const ADVANCES_TEAM_QUESTION = "advances_team";
// user_goalscorer answers are player ids; this sentinel means "никто не забьёт".
// Провайдерские id всегда числовые, так что коллизии с реальным игроком нет.
export const USER_GOALSCORER_NONE_ANSWER = "__none__";

// Ответы на «минуту первого гола» — интервалы основного времени.
// Границу интервала задаёт именно поле `time` провайдера, без addedTime: гол на 45+2
// приходит как time=45, на 90+4 — как time=90, то есть базовая минута уже указывает на
// нужный тайм. addedTime участвует только в сортировке, чтобы отличить 45 от 45+2.
// Всё, что позже 90-й, — дополнительное время, и оно не засчитывается: results хранит
// счёт основного времени (strict-90min), и вопросы о голах обязаны отвечать по той же
// границе, иначе ответ разойдётся с видимым в игре счётом.
export const FIRST_GOAL_MINUTE_BANDS = [
  { key: "1_30", label: "1–30", maxMinute: 30 },
  { key: "31_60", label: "31–60", maxMinute: 60 },
  { key: "61_90", label: "61–90", maxMinute: 90 },
] as const;
export const FIRST_GOAL_MINUTE_NONE_ANSWER = "none";

export function firstGoalMinuteBandKey(minute: any): string | null {
  const value = Number(minute);
  if (!Number.isFinite(value) || value <= 0) return null;
  for (const band of FIRST_GOAL_MINUTE_BANDS) {
    if (value <= band.maxMinute) return band.key;
  }
  return FIRST_GOAL_MINUTE_NONE_ANSWER;
}
type BonusRuleMetric =
  | "goals"
  | "corners"
  | "yellow_cards"
  | "red_cards"
  | "shots"
  | "shots_on_target"
  | "possession"
  | "fouls";

// Метрики вопроса «у кого больше»: у каждой свой матчер по имени показателя в дереве
// footapi7 /statistics. Имена проверяются по уже склеенной строке name+title+key, поэтому
// матчеры обязаны быть узкими: «shots» без границы слова совпал бы и с «Shots on target»,
// и вопрос про удары резолвился бы по ударам в створ.
const STAT_LEADER_METRICS: Record<string, { label: string; comparativeLabel: string; test: (joinedName: string) => boolean }> = {
  corners: { label: "угловых", comparativeLabel: "больше угловых", test: (n) => /corner|углов/.test(n) },
  shots: { label: "ударов", comparativeLabel: "больше ударов", test: (n) => /total shots|shots total|всего ударов/.test(n) },
  shots_on_target: { label: "ударов в створ", comparativeLabel: "больше ударов в створ", test: (n) => /shots on target|on target|в створ/.test(n) },
  possession: { label: "владения мячом", comparativeLabel: "больше владел мячом", test: (n) => /ball possession|possession|владение/.test(n) },
  fouls: { label: "фолов", comparativeLabel: "больше фолов", test: (n) => /\bfouls\b|фол/.test(n) },
};

const DEFAULT_STAT_LEADER_METRIC = "corners";

function normalizeStatLeaderMetric(value: any): string {
  const normalized = String(value || "").trim().toLowerCase();
  return normalized in STAT_LEADER_METRICS ? normalized : DEFAULT_STAT_LEADER_METRIC;
}

