type LeagueMembershipIntervalRow = {
  leagueId: string;
  userId: number;
  role: 'owner' | 'member';
  joinedAt: string | null;
  leftAt: string | null;
};

function parseStoredDateTimeMs(value: unknown): number | null {
  if (value === null || value === undefined) return null;
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  const raw = String(value).trim();
  if (!raw) return null;
  if (/^\d+$/.test(raw)) {
    const num = Number(raw);
    return Number.isFinite(num) ? num : null;
  }
  const normalized = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(raw)
    ? raw.replace(' ', 'T') + 'Z'
    : raw;
  const ms = Date.parse(normalized);
  return Number.isFinite(ms) ? ms : null;
}

function getDayBoundaryMs(day: string) {
  const startMs = Date.parse(`${day}T00:00:00Z`);
  const endMs = Date.parse(`${day}T23:59:59.999Z`);
  return { startMs, endMs };
}

function isAchievementRowInSeason(
  row: any,
  seasonId: number,
  seasonStart: string,
  seasonEnd?: string | null
): boolean {
  const periodKey = String(row?.period_key || '').trim();
  if (periodKey === seasonPeriodKey(seasonId)) return true;

  if (periodKey.startsWith('day:')) {
    const day = periodKey.slice(4, 14);
    if (/^\d{4}-\d{2}-\d{2}$/.test(day)) {
      return day >= seasonStart && (!seasonEnd || day <= seasonEnd);
    }
  }

  const parsedEventMs = parseStoredDateTimeMs(row?.earned_at ?? row?.unlocked_at);
  if (!Number.isFinite(parsedEventMs)) return false;
  const eventMs = parsedEventMs as number;

  const seasonStartMs = Date.parse(`${seasonStart}T00:00:00Z`);
  if (!Number.isFinite(seasonStartMs) || eventMs < seasonStartMs) return false;

  if (!seasonEnd) return true;

  const seasonEndMs = Date.parse(`${seasonEnd}T23:59:59.999Z`);
  if (!Number.isFinite(seasonEndMs)) return true;

  // Allow a small grace window for delayed finalization/unlock operations right after season end.
  const graceEndMs = seasonEndMs + 7 * 24 * 60 * 60 * 1000;
  return eventMs <= graceEndMs;
}

function buildSeasonalAchievementProgressMap(
  rows: any[],
  seasonId: number,
  seasonStart: string,
  seasonEnd?: string | null
) {
  const map = new Map<string, { unlocked: boolean; progress: number }>();
  for (const row of rows) {
    if (!isAchievementRowInSeason(row, seasonId, seasonStart, seasonEnd)) continue;
    const key = `${String(row?.achievement_id || '')}:${String(row?.scope_target_id || '')}`;
    const current = map.get(key) ?? { unlocked: false, progress: 0 };
    current.unlocked = current.unlocked || String(row?.state || '') === 'confirmed' || !!row?.unlocked_at;
    current.progress = Math.max(current.progress, Number(row?.progress || 0));
    map.set(key, current);
  }
  return map;
}

type LeagueSeasonMembershipWindow = {
  startDay: string;
  endDay: string | null;
  joinedAtMs: number;
  leftAtMs: number | null;
};

async function listUserLeagueSeasonMembershipWindows(
  env: Env,
  userId: number,
  leagueId: string,
  seasonStart: string,
  referenceDay?: string
): Promise<LeagueSeasonMembershipWindow[]> {
  const schema = await getSeasonSchemaSupport(env);
  const sql = schema.leagueMembershipHistory
    ? `
      SELECT joined_at, left_at
      FROM league_members_history
      WHERE user_id = ? AND league_id = ?
    `
    : `
      SELECT joined_at, NULL as left_at
      FROM league_members
      WHERE user_id = ? AND league_id = ?
    `;

  const res = await env.DB.prepare(sql).bind(userId, leagueId).all();
  const rows = (res.results || []) as any[];
  if (!rows.length) return [];

  const seasonStartDay = seasonStart.slice(0, 10);
  const seasonStartMs = Date.parse(`${seasonStartDay}T00:00:00Z`);
  const refEndMs = referenceDay
    ? Date.parse(`${referenceDay}T23:59:59.999Z`)
    : Number.POSITIVE_INFINITY;

  const windows: LeagueSeasonMembershipWindow[] = [];
  for (const row of rows) {
    const joinedAtMs = parseStoredDateTimeMs(row?.joined_at) ?? seasonStartMs;
    const leftAtMsRaw = parseStoredDateTimeMs(row?.left_at);
    const startMs = Math.max(joinedAtMs, seasonStartMs);
    const endMs = Math.min(leftAtMsRaw ?? Number.POSITIVE_INFINITY, refEndMs);
    if (!Number.isFinite(startMs) || endMs < startMs) continue;

    const startDay = new Date(startMs).toISOString().slice(0, 10);
    const endDay =
      Number.isFinite(endMs) && endMs !== Number.POSITIVE_INFINITY
        ? new Date(endMs).toISOString().slice(0, 10)
        : null;

    windows.push({
      startDay,
      endDay,
      joinedAtMs,
      leftAtMs: leftAtMsRaw ?? null,
    });
  }

  return windows;
}

function isDayWithinMembershipWindows(day: string, windows: LeagueSeasonMembershipWindow[]): boolean {
  return windows.some((window) => day >= window.startDay && (!window.endDay || day <= window.endDay));
}

function getLeagueNotDeletedCondition(schema: SeasonSchemaSupport, alias?: string | null) {
  const prefix = alias ? `${alias}.` : '';
  return schema.leaguesDeletedAt ? `${prefix}deleted_at IS NULL` : '1=1';
}

