// --- DB-backed banned words cache ---
type BannedWordsCache = { ruRoots: string[]; enRoots: string[]; allowlist: Set<string>; ts: number };
let _bannedWordsCache: BannedWordsCache | null = null;
const BANNED_WORDS_CACHE_TTL = 60_000; // 60s

async function loadBannedWords(env: Env): Promise<BannedWordsCache> {
  if (_bannedWordsCache && Date.now() - _bannedWordsCache.ts < BANNED_WORDS_CACHE_TTL) return _bannedWordsCache;
  try {
    const res = await env.DB.prepare('SELECT word, lang FROM banned_words').all<{ word: string; lang: string }>();
    const rows = res.results || [];
    const ruRoots: string[] = []; const enRoots: string[] = []; const allowlist = new Set<string>();
    for (const r of rows) {
      if (r.lang === 'ru') ruRoots.push(r.word);
      else if (r.lang === 'en') enRoots.push(r.word);
      else if (r.lang === 'allowlist') allowlist.add(r.word);
    }
    _bannedWordsCache = { ruRoots, enRoots, allowlist, ts: Date.now() };
    return _bannedWordsCache;
  } catch {
    return { ruRoots: FALLBACK_RU_ROOTS, enRoots: FALLBACK_EN_ROOTS, allowlist: FALLBACK_SAFE_ALLOWLIST, ts: Date.now() };
  }
}

function invalidateBannedWordsCache() { _bannedWordsCache = null; }

