async function getDisplaySeason(env: Env): Promise<SeasonRecord | null> {
  const active = await getActiveSeason(env);
  if (active) return active;
  const finalizing = await getFinalizingSeason(env);
  if (finalizing) return finalizing;
  const finished = await getLatestFinishedSeason(env);
  if (finished) return finished;
  return null;
}

async function getUpcomingSeasons(env: Env): Promise<SeasonRecord[]> {
  const schema = await getSeasonSchemaSupport(env);
  if (!schema.seasonsTable) return [];
  try {
    const res = await env.DB.prepare(`
      SELECT *
      FROM seasons
      WHERE status = 'upcoming'
      ORDER BY starts_at ASC, id ASC
    `).all();
    return ((res.results || []) as any[]).map(mapSeasonRow);
  } catch (_) {
    return [];
  }
}

async function getSeasonForTimestamp(env: Env, iso: string): Promise<SeasonRecord | null> {
  const schema = await getSeasonSchemaSupport(env);
  if (!schema.seasonsTable) return null;
  try {
    const row = await env.DB.prepare(`
      SELECT *
      FROM seasons
      WHERE starts_at <= ? AND ends_at >= ?
      ORDER BY starts_at DESC, id DESC
      LIMIT 1
    `).bind(iso, iso).first() as any;
    return row ? mapSeasonRow(row) : null;
  } catch (_) {
    return null;
  }
}

async function getSeasonForDay(env: Env, day: string): Promise<SeasonRecord | null> {
  const season = await getSeasonForTimestamp(env, `${day}T23:59:59Z`);
  if (season) return season;
  if (new Date(`${day}T23:59:59Z`).getTime() < SEASON_1_END_UTC) {
    return getArchivedSeasonOneRecord();
  }
  const legacy = await getLegacyConfiguredSeason(env);
  const ts = new Date(`${day}T23:59:59Z`).getTime();
  if (legacy) {
    const startsAt = new Date(legacy.starts_at).getTime();
    const endsAt = new Date(legacy.ends_at).getTime();
    if (Number.isFinite(startsAt) && Number.isFinite(endsAt) && ts >= startsAt && ts <= endsAt) {
      return legacy;
    }
  }
  return null;
}

async function getSeasonPeriodForDay(env: Env, day: string): Promise<string> {
  const season = await getSeasonForDay(env, day);
  if (season) return seasonPeriodKey(season.id);

  const legacy = await getLegacySeasonConfig(env);
  const ts = new Date(`${day}T23:59:59Z`).getTime();
  if (ts < SEASON_1_END_UTC) return 'season:1';
  if (ts >= new Date(legacy.start).getTime() && ts <= new Date(legacy.end).getTime()) {
    return seasonPeriodKey(legacy.number);
  }
  return seasonPeriodKey(legacy.number);
}

// Season context changes only via admin mutations, yet it is re-read by several
// builders on EVERY /bootstrap and quest read. Short TTL caches remove that
// repeated D1 work; bustSeasonContextCache() keeps admin changes visible
// immediately (all season writes call it, directly or via syncLegacySeasonSetting).
const SEASON_CONTEXT_TTL_MS = 30_000;
let __seasonConfigCache: { at: number; value: SeasonConfig } | null = null;
let __displaySeasonPayloadCache: { at: number; value: any } | null = null;
function bustSeasonContextCache(): void {
  __seasonConfigCache = null;
  __displaySeasonPayloadCache = null;
}

async function getSeasonConfig(env: Env): Promise<SeasonConfig> {
  if (__seasonConfigCache && Date.now() - __seasonConfigCache.at < SEASON_CONTEXT_TTL_MS) {
    return __seasonConfigCache.value;
  }
  const season = await getDisplaySeason(env);
  let value: SeasonConfig;
  if (season) {
    value = {
      number: season.id,
      start: season.starts_at,
      end: season.ends_at,
      name: season.name,
      status: season.status,
      seasonId: season.id,
    };
  } else {
    const legacy = await getLegacySeasonConfig(env);
    value = {
      number: legacy.number,
      start: legacy.start,
      end: legacy.end,
      name: legacy.name || defaultSeasonName(legacy.number),
      status: legacy.status || 'active',
      seasonId: legacy.number,
    };
  }
  __seasonConfigCache = { at: Date.now(), value };
  return value;
}

async function getSeasonIdForDayOrDisplay(env: Env, day: string): Promise<number> {
  const season = await getSeasonForDay(env, day);
  if (season) return season.id;
  return getCurrentSeasonNumber(env);
}

// economy-v1.md §2/§0.3: последняя неделя сезона — недельный потолок обмена снят
// (разовая полная конвертация остатка звёзд по 20⭐=1⚽); за 14 дней до конца показываем
// баннер сгорания. capLifted=true в последние 7 дней сезона.
// Сколько дней осталось до конца сезона — справочно (витрина обмена показывает это
// в ответе). Раньше отсюда же росла механика сгорания звёзд: за 14 дней баннер, за 7 —
// снятый потолок обмена. Звёзды переносятся в новый сезон (carryOverSeasonStars),
// поэтому оба окна убраны, а сам счётчик дней остался.
async function getSeasonDaysUntilEnd(env: Env): Promise<number | null> {
  const cfg = await getSeasonConfig(env);
  const end = cfg.end ? String(cfg.end) : null;
  if (!end) return null;
  const endMs = Date.parse(end.length <= 10 ? `${end}T23:59:59.999Z` : end);
  if (!Number.isFinite(endMs)) return null;
  return Math.ceil((endMs - Date.now()) / 86400000);
}

type LeaderboardPeriodKind = 'all' | 'day' | 'week' | 'season';

interface LeaderboardSeasonOption {
  id: number;
  name: string;
  slug: string | null;
  status: SeasonStatus;
  startsAt: string;
  endsAt: string;
  finalizedAt: string | null;
  archivedAt: string | null;
  isCurrent: boolean;
}

interface LeaderboardResolution {
  requestedPeriod: string;
  normalizedPeriod: LeaderboardPeriodKind;
  resolvedPeriod: string;
  anchorDay: string | null;
  seasonId: number | null;
  season: SeasonRecord | null;
  progressSeasonNumber: number;
  useSnapshots: boolean;
}

function isFrozenSeasonStatus(status?: SeasonStatus | null): boolean {
  return status === 'finished' || status === 'archived';
}

function parseSeasonIdInput(value: unknown): number | null {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0) return null;
  return parsed;
}

function normalizeLeaderboardAnchorDay(value: unknown): string | null {
  const raw = String(value || '').trim();
  if (!raw) return null;
  const day = getUtcDayFromIso(raw);
  return /^\d{4}-\d{2}-\d{2}$/.test(day) ? day : null;
}

function mapLeaderboardSeasonOption(season: SeasonRecord, currentSeasonId: number | null): LeaderboardSeasonOption {
  return {
    id: season.id,
    name: season.name,
    slug: season.slug,
    status: season.status,
    startsAt: season.starts_at,
    endsAt: season.ends_at,
    finalizedAt: season.finalized_at,
    archivedAt: season.archived_at,
    isCurrent: season.id === currentSeasonId,
  };
}

async function getLeaderboardSeasonSelectorPayload(env: Env) {
  const displaySeason = await getDisplaySeason(env);
  const rawSeasons = await listSeasons(env);
  const deduped = new Map<number, SeasonRecord>();

  for (const season of rawSeasons) {
    if (season.status === 'upcoming') continue;
    if (!deduped.has(season.id)) deduped.set(season.id, season);
  }

  if (displaySeason && displaySeason.status !== 'upcoming' && !deduped.has(displaySeason.id)) {
    deduped.set(displaySeason.id, displaySeason);
  }

  const seasons = [...deduped.values()]
    .sort((a, b) =>
      seasonStatusPriority(a.status) - seasonStatusPriority(b.status)
      || new Date(b.starts_at).getTime() - new Date(a.starts_at).getTime()
      || b.id - a.id
    )
    .map((season) => mapLeaderboardSeasonOption(season, displaySeason?.id ?? null));

  return {
    seasons,
    defaultSeasonId: displaySeason?.id ?? seasons[0]?.id ?? null,
    displaySeasonId: displaySeason?.id ?? null,
    activeSeasonId: (await getActiveSeason(env))?.id ?? null,
  };
}

async function resolveLeaderboardPeriod(
  env: Env,
  requestedPeriod?: string | null,
  explicitSeasonId?: unknown,
  explicitDay?: unknown
): Promise<LeaderboardResolution> {
  let rawPeriod = String(requestedPeriod || 'season').trim() || 'season';
  let seasonId = parseSeasonIdInput(explicitSeasonId);
  let anchorDay = normalizeLeaderboardAnchorDay(explicitDay);

  if (rawPeriod.startsWith('season:')) {
    seasonId = seasonId ?? parseSeasonIdInput(rawPeriod.slice(7));
    rawPeriod = 'season';
  } else if (rawPeriod.startsWith('month:')) {
    // Leaderboards no longer use month-based periods.
    rawPeriod = 'season';
  } else if (rawPeriod === 'currentSeason') {
    rawPeriod = 'season';
  }

  if (rawPeriod === 'season') {
    const season = seasonId ? await getSeasonById(env, seasonId) : await getDisplaySeason(env);
    if (seasonId && !season) throw new Error("SEASON_NOT_FOUND");
    if (!season) {
      const fallbackSeasonNumber = await getCurrentSeasonNumber(env);
      return {
        requestedPeriod: 'season',
        normalizedPeriod: 'all',
        resolvedPeriod: 'all',
        anchorDay: null,
        seasonId: null,
        season: null,
        progressSeasonNumber: fallbackSeasonNumber,
        useSnapshots: false,
      };
    }
    return {
      requestedPeriod: 'season',
      normalizedPeriod: 'season',
      resolvedPeriod: seasonPeriodKey(season.id),
      anchorDay: null,
      seasonId: season.id,
      season,
      progressSeasonNumber: season.id,
      useSnapshots: isFrozenSeasonStatus(season.status),
    };
  }

  if (rawPeriod.startsWith('day:')) {
    anchorDay = anchorDay || rawPeriod.slice(4, 14);
    // Reject malformed day keys instead of computing (and caching) garbage:
    // every distinct value becomes a standings-cache key, so unvalidated input
    // would let a client fragment the cache at will.
    if (!/^\d{4}-\d{2}-\d{2}$/.test(anchorDay)) throw new Error("BAD_PERIOD");

    // If no one has points for the requested day, fall back to the previous day
    const hasPoints = await env.DB.prepare(
      `SELECT 1 FROM user_day_stats WHERE day = ? AND points > 0 LIMIT 1`
    ).bind(anchorDay).first();
    if (!hasPoints) {
      const d = new Date(anchorDay + 'T12:00:00Z');
      d.setUTCDate(d.getUTCDate() - 1);
      anchorDay = d.toISOString().slice(0, 10);
    }

    return {
      requestedPeriod: rawPeriod,
      normalizedPeriod: 'day',
      resolvedPeriod: `day:${anchorDay}`,
      anchorDay,
      seasonId: null,
      season: null,
      progressSeasonNumber: await getCurrentSeasonNumber(env),
      useSnapshots: false,
    };
  }

  if (rawPeriod.startsWith('week:')) {
    // Same guard as day: only well-formed ISO week keys may become cache keys.
    if (!/^\d{4}-W\d{2}$/.test(rawPeriod.slice(5))) throw new Error("BAD_PERIOD");
    return {
      requestedPeriod: rawPeriod,
      normalizedPeriod: 'week',
      resolvedPeriod: rawPeriod,
      anchorDay,
      seasonId: null,
      season: null,
      progressSeasonNumber: await getCurrentSeasonNumber(env),
      useSnapshots: false,
    };
  }

  return {
    requestedPeriod: 'all',
    normalizedPeriod: 'all',
    resolvedPeriod: 'all',
    anchorDay: null,
    seasonId: null,
    season: null,
    progressSeasonNumber: await getCurrentSeasonNumber(env),
    useSnapshots: false,
  };
}

// Raw global-standing rows (userId + points, pre-identity) are IDENTICAL for
// every viewer — only the identity hydration is viewer-dependent (league-mates
// see telegram identity, others do not), and that stays per-request. Computing
// these rows is the most expensive read in the app (full picks scan for the
// all/season periods), so cache them briefly; ≤20s staleness is on the same
// order as a page refresh after a score recalc.
const GLOBAL_STANDINGS_TTL_MS = 20_000;
// Second layer behind the in-isolate map: the edge cache survives isolate churn
// and is shared across isolates, so the expensive picks recompute runs at most
// once per TTL per colo regardless of traffic. Same staleness class as the
// 45s edge cache already used for the public top-league boards.
const GLOBAL_STANDINGS_EDGE_TTL_SEC = 45;
const __globalStandingsCache = new Map<string, { at: number; rows: SeasonStandingRow[] }>();

function standingsEdgeCacheKey(key: string): Request {
  // Synthetic internal URL — never routed; only a cache-key namespace.
  return new Request(`https://edge-cache.internal/global-standings/${encodeURIComponent(key)}`, { method: "GET" });
}

async function withStandingsCache(key: string, compute: () => Promise<SeasonStandingRow[]>): Promise<SeasonStandingRow[]> {
  const hit = __globalStandingsCache.get(key);
  if (hit && Date.now() - hit.at < GLOBAL_STANDINGS_TTL_MS) return hit.rows;

  const rememberInIsolate = (rows: SeasonStandingRow[]) => {
    if (__globalStandingsCache.size >= 64) __globalStandingsCache.clear();
    __globalStandingsCache.set(key, { at: Date.now(), rows });
    return rows;
  };

  // Cache API is absent in unit tests and must never break the leaderboard:
  // every edge-cache step is best-effort.
  const cache = typeof caches !== "undefined" ? (caches as any).default : null;
  if (cache) {
    try {
      const cached = await cache.match(standingsEdgeCacheKey(key));
      if (cached) return rememberInIsolate(await cached.json() as SeasonStandingRow[]);
    } catch {}
  }

  const rows = await compute();
  rememberInIsolate(rows);
  if (cache) {
    try {
      await cache.put(standingsEdgeCacheKey(key), new Response(JSON.stringify(rows), {
        headers: {
          "Content-Type": "application/json",
          "Cache-Control": `public, max-age=${GLOBAL_STANDINGS_EDGE_TTL_SEC}`,
        },
      }));
    } catch {}
  }
  return rows;
}

type LeaderboardViewerStanding = { rank: number; points: number; totalPlayers: number } | null;
type GlobalLeaderboardResult = { leaderboard: any[]; me: LeaderboardViewerStanding };

async function queryGlobalLeaderboardRows(env: Env, scope: LeaderboardResolution, viewerId: number | null): Promise<GlobalLeaderboardResult> {
  if (scope.normalizedPeriod === 'season' && scope.seasonId) {
    return queryDerivedGlobalSeasonLeaderboardRows(env, scope.seasonId, scope.progressSeasonNumber, viewerId);
  }

  if (scope.normalizedPeriod === 'all') {
    const rows = await withStandingsCache('all', () => collectAllTimeSeasonScopedStandingRows(env));
    return hydrateSeasonUserLeaderboardRows(env, rows, scope.progressSeasonNumber, viewerId);
  }

  if (scope.normalizedPeriod === 'day' || scope.normalizedPeriod === 'week') {
    const rows = await withStandingsCache(
      `${scope.resolvedPeriod}|${scope.anchorDay ?? '-'}`,
      () => collectGlobalPeriodStandingRows(env, scope)
    );
    return hydrateSeasonUserLeaderboardRows(env, rows, scope.progressSeasonNumber, viewerId, 'participation');
  }

  const userSchema = await getUserProfileSchemaSupport(env);
  const res = await env.DB.prepare(`
    SELECT u.id, u.username, u.first_name, u.photo_url, s.points
    FROM scores_agg s
    JOIN users u ON u.id = s.user_id
    WHERE s.period = ?
      AND s.points > 0
      AND ${notBannedSqlCondition(userSchema, 'u')}
    ORDER BY s.points DESC, u.id ASC
    LIMIT 50
  `).bind(scope.resolvedPeriod).all();

  const rows = (res.results || []) as any[];
  const publicMap = await buildPublicUserIdentityMap(env, viewerId, rows.map((row) => Number(row.id)));
  const leaderboard = rows.flatMap((row) => {
    const identity = publicMap.get(Number(row.id));
    if (!identity) return [];
    return [{
      id: identity.telegramId,
      profile_key: identity.profileKey,
      display_name: identity.displayName,
      username: identity.displayName,
      first_name: null,
      photo_url: identity.avatarUrl,
      points: row.points,
    }];
  });
  return { leaderboard, me: null };
}

// Public top-league / top-channel leaderboards. These carry no viewer identity
// (identical output for everyone) and hit D1 hard, so they are edge-cached for a
// short TTL: repeated/abusive polling is served from cache instead of the DB.
async function serveTopLeagueLeaderboard(
  req: Request,
  url: URL,
  path: string,
  env: Env,
  headersCors: Record<string, string>,
  leagueType: 'private' | 'channel'
): Promise<Response> {
  const TOP_LEADERBOARD_CACHE_TTL_SEC = 45;
  const period = url.searchParams.get("period") ?? "";
  const seasonId = url.searchParams.get("seasonId") ?? "";
  const day = url.searchParams.get("day") ?? "";

  // Normalized cache key: only the params that change the result, so query-string
  // noise cannot fragment the cache or bypass it.
  const cache = (caches as any).default;
  const cacheKey = new Request(
    `${url.origin}${path}?period=${encodeURIComponent(period)}&seasonId=${encodeURIComponent(seasonId)}&day=${encodeURIComponent(day)}`,
    { method: "GET" }
  );
  const cached = await cache.match(cacheKey);
  if (cached) return cached;

  try {
    const scope = await resolveLeaderboardPeriod(
      env,
      url.searchParams.get("period"),
      url.searchParams.get("seasonId"),
      url.searchParams.get("day")
    );
    const leaderboard = await queryTopLeagueLeaderboardRows(env, scope, leagueType);

    const res = json({
      ok: true,
      period: scope.requestedPeriod,
      resolvedPeriod: scope.resolvedPeriod,
      periodKind: scope.normalizedPeriod,
      seasonId: scope.seasonId,
      season: scope.season ? {
        id: scope.season.id,
        name: scope.season.name,
        status: scope.season.status,
        startsAt: scope.season.starts_at,
        endsAt: scope.season.ends_at,
        finalizedAt: scope.season.finalized_at,
      } : null,
      leaderboard,
    }, 200, { ...headersCors, "Cache-Control": `public, max-age=${TOP_LEADERBOARD_CACHE_TTL_SEC}` });

    await cache.put(cacheKey, res.clone());
    return res;
  } catch (e: any) {
    // Errors are never cached (no-store default), so a transient failure won't stick.
    // Internal/runtime details are masked; business codes pass through unchanged.
    return handleRouteError(e);
  }
}

async function queryLeagueLeaderboardRows(env: Env, leagueId: string, scope: LeaderboardResolution, viewerId: number | null): Promise<LeagueSeasonLeaderboardResult> {
  if (scope.normalizedPeriod === 'season' && scope.seasonId) {
    const availability = await getLeagueSeasonAvailability(env, scope.seasonId, leagueId);
    if (!availability.existed) {
      return { rows: [], emptyReason: 'LEAGUE_NOT_IN_SEASON' };
    }

    return queryDerivedLeagueSeasonLeaderboardRows(env, scope.seasonId, leagueId, scope.progressSeasonNumber, viewerId);
  }

  const aggregateRows = await listLeaguePeriodAggregateRows(env, [leagueId], scope.resolvedPeriod, {
    anchorDay: scope.anchorDay,
    includeZeroRows: true,
  });
  if (!aggregateRows.length) {
    return { rows: [], emptyReason: null };
  }

  const rankedAggregates = [...aggregateRows].sort(sortLeagueAggregateRows).slice(0, 50);
  const aggregateUserIds = rankedAggregates.map((row) => row.userId);
  const aggregatePlaceholders = aggregateUserIds.map(() => '?').join(', ');
  const memberUserSchema = await getUserProfileSchemaSupport(env);
  const memberRes = await env.DB.prepare(`
    SELECT u.id, u.username, u.first_name, u.photo_url
    FROM users u
    WHERE u.id IN (${aggregatePlaceholders})
      AND ${notBannedSqlCondition(memberUserSchema, 'u')}
  `).bind(...aggregateUserIds).all();

  const memberMap = new Map<number, any>();
  for (const row of ((memberRes.results || []) as any[])) {
    memberMap.set(Number(row.id), row);
  }

  const rows = rankedAggregates.flatMap((aggregate) => {
    const member = memberMap.get(aggregate.userId);
    if (!member) return [];
    return [{
      ...member,
      points: aggregate.points,
      exact_count: aggregate.exactCount,
      joker_points: aggregate.jokerPoints,
      earliest_pick_time: aggregate.earliestPickTime,
    }];
  });
  const publicMap = await buildPublicUserIdentityMap(env, viewerId, rows.map((row) => Number(row.id)));
  return {
    rows: rows.flatMap((row) => {
      const identity = publicMap.get(Number(row.id));
      if (!identity) return [];
      return [{
        id: identity.telegramId,
        profile_key: identity.profileKey,
        display_name: identity.displayName,
        username: identity.displayName,
        first_name: null,
        photo_url: identity.avatarUrl,
        points: row.points,
      }];
    }),
    emptyReason: null,
  };
}

async function queryTopLeagueLeaderboardRows(
  env: Env,
  scope: LeaderboardResolution,
  leagueType: 'private' | 'channel'
) {
  const schema = await getSeasonSchemaSupport(env);
  const nameExpr = leagueType === 'channel'
    ? `COALESCE(NULLIF(TRIM(l.telegram_chat_title), ''), NULLIF(TRIM(l.name), ''), NULLIF(TRIM(l.telegram_chat_username), ''))`
    : `COALESCE(NULLIF(TRIM(l.name), ''), NULLIF(TRIM(l.telegram_chat_title), ''))`;

  if (scope.normalizedPeriod === 'season' && scope.seasonId) {
    return queryDerivedTopLeagueSeasonLeaderboardRows(env, scope.seasonId!, leagueType);
  }

  const leagueRes = await env.DB.prepare(`
    SELECT
      l.id,
      ${nameExpr} as name,
      l.type,
      ${getPublicLeagueAvatarSqlExpr('l')} as avatar_url,
      l.avatar_type,
      l.telegram_chat_title,
      l.telegram_chat_username
    FROM leagues l
    WHERE l.type = ?
      AND ${getLeagueNotDeletedCondition(schema, 'l')}
  `).bind(leagueType).all();

  const leagueRows = (leagueRes.results || []) as any[];
  if (!leagueRows.length) return [];

  const leagueIds = leagueRows.map((row) => String(row.id));
  const placeholders = leagueIds.map(() => '?').join(', ');
  const memberRes = await env.DB.prepare(`
    SELECT league_id, COUNT(*) AS members_count
    FROM league_members
    WHERE league_id IN (${placeholders})
    GROUP BY league_id
  `).bind(...leagueIds).all();

  const currentMemberCounts = new Map<string, number>();
  for (const row of ((memberRes.results || []) as any[])) {
    currentMemberCounts.set(String(row.league_id), Number(row.members_count || 0));
  }

  const aggregateRows = await listLeaguePeriodAggregateRows(env, leagueIds, scope.resolvedPeriod, {
    anchorDay: scope.anchorDay,
    includeZeroRows: false,
  });
  const byLeague = new Map<string, LeaguePeriodAggregateRow[]>();
  for (const row of aggregateRows) {
    if (!byLeague.has(row.leagueId)) byLeague.set(row.leagueId, []);
    byLeague.get(row.leagueId)!.push(row);
  }

  return leagueRows
    .flatMap((row: any) => {
      const leagueId = String(row.id);
      const ranked = [...(byLeague.get(leagueId) || [])].sort(sortLeagueAggregateRows);
      const score = ranked.slice(0, 5).reduce((sum, item) => sum + item.points, 0);
      const name = safeLeagueDisplayTitle(row.name, leagueType === 'channel' ? 'Канал' : 'Лига');
      if (!name || score <= 0) return [];
      return [{
        ...row,
        name,
        score,
        members_count: currentMemberCounts.get(leagueId) ?? 0,
      }];
    })
    .sort((a, b) =>
      Number(b.score || 0) - Number(a.score || 0) ||
      Number(b.members_count || 0) - Number(a.members_count || 0) ||
      String(a.name || '').localeCompare(String(b.name || ''))
    )
    .slice(0, 20);
}

// Helper to get week key (ISO week)
export function getWeekKey(day: string): string {
  const d = new Date(day);
  d.setUTCHours(0, 0, 0, 0);
  d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  const weekNo = Math.ceil((((d.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
  return `${d.getUTCFullYear()}-W${String(weekNo).padStart(2, '0')}`;
}

// Helper to check if a week has ended (current time is past the week)
function isWeekEnded(weekKey: string): boolean {
  // weekKey format: "2026-W05"
  const [year, weekPart] = weekKey.split('-W');
  const weekNum = parseInt(weekPart);

  // Calculate the Monday of that week
  const jan4 = new Date(Date.UTC(parseInt(year), 0, 4));
  const dayOfWeek = jan4.getUTCDay() || 7;
  const monday = new Date(jan4);
  monday.setUTCDate(jan4.getUTCDate() - dayOfWeek + 1 + (weekNum - 1) * 7);

  // Week ends at Sunday 23:59:59 UTC
  const sunday = new Date(monday);
  sunday.setUTCDate(monday.getUTCDate() + 6);
  sunday.setUTCHours(23, 59, 59, 999);

  return Date.now() > sunday.getTime();
}

// Helper to check if a month has ended
function isMonthEnded(monthKey: string): boolean {
  // monthKey format: "2026-02"
  const [year, month] = monthKey.split('-').map(Number);
  // First day of NEXT month
  const nextMonth = new Date(Date.UTC(year, month, 1, 0, 0, 0));
  return Date.now() >= nextMonth.getTime();
}

const WEEKLY_FINALIZATION_CUTOFF_HOURS = 12;

type WeeklyQuestDefinitionRow = {
  taskKey: string;
  scope: 'global' | 'league';
  emoji: string;
  title: string;
  description: string;
  rewardStars: number;
  threshold: number;
  progressKind: 'boolean' | 'counter' | 'streak' | 'best';
  phase: 'pick_saved' | 'scores_updated';
  rarity: 'common' | 'rare' | 'epic';
  rankingBased: boolean;
  sortOrder: number;
};

type WeeklyQuestResponseRow = {
  id: string;
  scope: 'global' | 'league';
  rarity: 'common' | 'rare' | 'epic';
  emoji: string;
  title: string;
  description: string;
  threshold: number;
  stars_reward: number;
  reward_balls: number;
  unlocked: boolean;
  progress: number;
  finalized: boolean;
  ranking_based: boolean;
  claim_mode: 'auto';
  period_key: string;
  scope_id?: string;
  scope_name?: string | null;
  status_note?: string | null;
  unlocked_at?: number | null;
};

type WeeklyGlobalProgress = {
  activeDaysPicked: number;
  activeDaysWithPoints: number;
  exactHits: number;
};

type WeeklyLeagueStandingRow = {
  leagueId: string;
  userId: number;
  finalRank: number;
  finalPoints: number;
  exactHits: number;
  jokerPoints: number;
  matchesPredicted: number;
};

type WeeklyScope = {
  weekKey: string;
  seasonId: number;
};

function getUtcDayFromIso(value: string): string {
  return String(value || '').slice(0, 10);
}

function getWeekWindowUtc(weekKey: string) {
  const [yearRaw, weekRaw] = weekKey.split('-W');
  const year = Number(yearRaw);
  const weekNum = Number(weekRaw);
  const jan4 = new Date(Date.UTC(year, 0, 4));
  const dayOfWeek = jan4.getUTCDay() || 7;
  const monday = new Date(jan4);
  monday.setUTCDate(jan4.getUTCDate() - dayOfWeek + 1 + (weekNum - 1) * 7);
  monday.setUTCHours(0, 0, 0, 0);

  const sunday = new Date(monday);
  sunday.setUTCDate(monday.getUTCDate() + 6);
  sunday.setUTCHours(23, 59, 59, 999);

  const cutoff = new Date(sunday);
  cutoff.setUTCHours(cutoff.getUTCHours() + WEEKLY_FINALIZATION_CUTOFF_HOURS);

  return {
    weekKey,
    startMs: monday.getTime(),
    endMs: sunday.getTime(),
    startIso: monday.toISOString(),
    endIso: sunday.toISOString(),
    resetAtIso: new Date(sunday.getTime() + 1).toISOString(),
    cutoffMs: cutoff.getTime(),
  };
}

function getWeekKeyFromStartTime(startTime: string): string {
  return getWeekKey(getUtcDayFromIso(startTime));
}

function getWeeklyInstanceKey(weekKey: string) {
  return `week:${weekKey}`;
}

function getWeeklyLeagueInstanceKey(weekKey: string, leagueId: string) {
  return `week:${weekKey}:league:${leagueId}`;
}

// ========== STARS & QUESTS ==========
// The seasonal "level" mechanic was removed (Stage 1). `user_season_progress.stars`
// remains the authoritative seasonal balance and feeds the season progress + star
// exchange. The legacy `level` / `gold_avatar_frame` columns and the `season_levels`
// table are no longer read or written by active runtime (kept in D1 for Stage 2 cleanup).

async function getCurrentSeasonNumber(env: Env): Promise<number> {
  const cfg = await getSeasonConfig(env);
  return cfg.number;
}


async function syncLegacySeasonSetting(env: Env, season?: SeasonRecord | null): Promise<void> {
  // Called after every season lifecycle transition — bust the season caches so
  // admin changes are visible immediately despite the read-path TTL.
  bustSeasonContextCache();
  const target = season || await getDisplaySeason(env);
  if (!target) return;
  const value = JSON.stringify({ number: target.id, start: target.starts_at, end: target.ends_at });
  await env.DB.prepare(`
    INSERT INTO app_settings (key, value_json, updated_at, updated_by)
    VALUES ('season', ?, datetime('now'), 0)
    ON CONFLICT(key) DO UPDATE SET
      value_json = excluded.value_json,
      updated_at = excluded.updated_at,
      updated_by = excluded.updated_by
  `).bind(value).run();
}

async function getGlobalMatchMode(env: Env): Promise<MatchMode> {
  try {
    const row = await env.DB.prepare(`SELECT value_json FROM app_settings WHERE key = 'match_mode' LIMIT 1`).first() as any;
    if (!row?.value_json) return 'club';
    const parsed = JSON.parse(String(row.value_json));
    return normalizeMatchMode(parsed?.mode);
  } catch (_) {
    return 'club';
  }
}

async function setGlobalMatchMode(env: Env, mode: MatchMode, updatedBy: number): Promise<void> {
  const value = JSON.stringify({ mode: normalizeMatchMode(mode) });
  await env.DB.prepare(`
    INSERT INTO app_settings (key, value_json, updated_at, updated_by)
    VALUES ('match_mode', ?, datetime('now'), ?)
    ON CONFLICT(key) DO UPDATE SET
      value_json = excluded.value_json,
      updated_at = excluded.updated_at,
      updated_by = excluded.updated_by
  `).bind(value, updatedBy).run();
}

async function getPublishedDayMatchMode(env: Env, day: string): Promise<MatchMode | null> {
  const schema = await getSeasonSchemaSupport(env);
  const rows = await env.DB.prepare(`
    SELECT competition, is_pick${schema.matchesCompetitionType ? ', competition_type' : ''}${schema.matchesMatchType ? ', match_type' : ''}
    FROM matches
    WHERE day = ? AND is_pick = 1
    ORDER BY start_time
    LIMIT 3
  `).bind(day).all();

  const picks = (rows.results || []) as any[];
  if (picks.length === 0) return null;
  return picks.some((row) => getMatchCompetitionType(row) === 'national_team') ? 'national_teams' : 'club';
}

async function getEffectiveMatchModeForDay(env: Env, day: string): Promise<EffectiveMatchMode> {
  const globalMode = await getGlobalMatchMode(env);
  const publishedMode = await getPublishedDayMatchMode(env, day);
  if (publishedMode) {
    return { mode: publishedMode, globalMode, source: 'published_day' };
  }
  return { mode: globalMode, globalMode, source: 'global' };
}

async function awardStars(env: Env, userId: number, amount: number, seasonNumber: number): Promise<{ totalStars: number }> {
  if (amount <= 0) return { totalStars: 0 };

  // Upsert stars (level mechanic removed — `stars` is the authoritative seasonal balance)
  await env.DB.prepare(`
    INSERT INTO user_season_progress (user_id, season_number, stars)
    VALUES (?, ?, ?)
    ON CONFLICT(user_id, season_number) DO UPDATE SET stars = stars + excluded.stars
  `).bind(userId, seasonNumber, amount).run();

  // Read current
  const row = await env.DB.prepare(
    `SELECT stars FROM user_season_progress WHERE user_id = ? AND season_number = ?`
  ).bind(userId, seasonNumber).first() as any;

  return { totalStars: row?.stars ?? 0 };
}

// ========== NEW TASKS CATALOG ARCHITECTURE ==========

// Cached tasks catalog (read once per request lifecycle)
let _tasksCatalogCache: any[] | null = null;
async function getTasksCatalog(env: Env): Promise<any[]> {
  if (_tasksCatalogCache) return _tasksCatalogCache;
  const res = await env.DB.prepare(`SELECT * FROM tasks_catalog ORDER BY sort_order`).all();
  _tasksCatalogCache = (res.results || []) as any[];
  return _tasksCatalogCache;
}

type TaskCatalogRow = any;

function buildTaskCatalogMap(rows: TaskCatalogRow[]): Map<string, TaskCatalogRow> {
  return new Map(rows.map((row) => [String(row.task_key), row]));
}

function resolveQuestCopy(
  key: string,
  title: string,
  description: string,
  catalogRow?: TaskCatalogRow | null
) {
  const normalized = getQuestCopy(key, title, description);
  return {
    title: catalogRow?.title ? String(catalogRow.title) : normalized.title,
    description: catalogRow?.description ? String(catalogRow.description) : normalized.description,
  };
}

function mergeAchievementDefinitionWithCatalog(def: any, catalogRow?: TaskCatalogRow | null) {
  const copy = resolveQuestCopy(String(def.id || ''), String(def.title || ''), String(def.description || ''), catalogRow);
  return {
    ...def,
    ...copy,
    emoji: catalogRow?.emoji ? String(catalogRow.emoji) : def.emoji,
    rarity: catalogRow?.rarity ? String(catalogRow.rarity) : def.rarity,
    stars_reward: catalogRow?.reward_stars !== undefined ? Number(catalogRow.reward_stars || 0) : Number(def.stars_reward || 0),
    threshold: catalogRow?.progress_target !== undefined && catalogRow?.progress_target !== null
      ? Number(catalogRow.progress_target || 0)
      : Number(def.threshold || 0),
    sort_order: catalogRow?.sort_order !== undefined ? Number(catalogRow.sort_order || 0) : Number(def.sort_order || 0),
    phase: catalogRow?.phase ? String(catalogRow.phase) : def.phase,
  };
}

async function listAchievementDefinitionsWithCatalogOverrides(env: Env): Promise<any[]> {
  const [defsRes, taskRows, schema] = await Promise.all([
    env.DB.prepare(`SELECT * FROM achievements`).all(),
    getTasksCatalog(env),
    getQuestSchemaSupport(env),
  ]);
  const taskMap = buildTaskCatalogMap(taskRows);
  return ((defsRes.results || []) as any[])
    .map((def) => mergeAchievementDefinitionWithCatalog(def, taskMap.get(String(def.id || ''))))
    .filter((def) => !schema.taskIsEnabled || Number(taskMap.get(String(def.id || ''))?.is_enabled ?? 1) === 1)
    .sort((a, b) =>
      Number(a.sort_order ?? 1000) - Number(b.sort_order ?? 1000)
      || String(a.scope || '').localeCompare(String(b.scope || ''))
      || String(a.id || '').localeCompare(String(b.id || ''))
    );
}

function buildAchievementDefinitionMap(defs: any[]): Map<string, any> {
  return new Map(defs.map((def: any) => [String(def.id || ''), def]));
}

function buildTaskAwardMap(rows: any[], field: 'stars' | 'balls'): Map<string, number> {
  return new Map(
    (rows || []).map((row: any) => [
      `${String(row.task_key || '')}:${String(row.instance_key || '')}`,
      Number(row?.[field] || 0),
    ])
  );
}

async function getTaskAwardMaps(env: Env, userId: number, seasonId: number) {
  const [starsRes, ballsRes] = await Promise.all([
    env.DB.prepare(`
      SELECT task_key, instance_key, stars
      FROM stars_ledger
      WHERE user_id = ? AND season_id = ?
    `).bind(userId, seasonId).all(),
    env.DB.prepare(`
      SELECT task_key, instance_key, balls
      FROM balls_ledger
      WHERE user_id = ? AND season_id = ?
    `).bind(userId, seasonId).all(),
  ]);

  return {
    stars: buildTaskAwardMap((starsRes.results || []) as any[], 'stars'),
    balls: buildTaskAwardMap((ballsRes.results || []) as any[], 'balls'),
  };
}

async function listDailyQuestDefinitions(env: Env): Promise<any[]> {
  const [taskRows, schema] = await Promise.all([getTasksCatalog(env), getQuestSchemaSupport(env)]);
  const taskMap = buildTaskCatalogMap(taskRows);
  return DAILY_QUESTS
    .map((quest) => {
      const catalogRow = taskMap.get(String(quest.id));
      const copy = resolveQuestCopy(String(quest.id), String(quest.title), String(quest.description), catalogRow);
      return {
        ...quest,
        ...copy,
        emoji: catalogRow?.emoji ? String(catalogRow.emoji) : quest.emoji,
        stars: catalogRow?.reward_stars !== undefined ? Number(catalogRow.reward_stars || 0) : Number(quest.stars || 0),
        phase: catalogRow?.phase ? String(catalogRow.phase) : quest.phase,
        league: catalogRow?.league_only !== undefined ? Number(catalogRow.league_only) === 1 : quest.league,
        rarity: catalogRow?.rarity ? String(catalogRow.rarity) : 'common',
        sort_order: catalogRow?.sort_order !== undefined ? Number(catalogRow.sort_order || 0) : 100,
      };
    })
    .filter((quest) => !schema.taskIsEnabled || Number(taskMap.get(String(quest.id))?.is_enabled ?? 1) === 1)
    .sort((a, b) => Number(a.sort_order || 100) - Number(b.sort_order || 100) || String(a.id).localeCompare(String(b.id)));
}

// Check if a day is an approved matchday (has approved picks)

// Idempotent star award via ledger (prevents duplicate awards)
async function awardStarsViaLedger(
  env: Env, userId: number, seasonId: number,
  taskKey: string, instanceKey: string, stars: number,
  source: string = 'seasonal_task',
  metadataJson?: string | null
): Promise<{ awarded: boolean; totalStars: number }> {
  if (stars <= 0) return { awarded: false, totalStars: 0 };

  const now = Date.now();
  // INSERT OR IGNORE — if (user_id, season_id, task_key, instance_key) already exists, nothing happens
  const ledgerResult = await env.DB.prepare(`
    INSERT OR IGNORE INTO stars_ledger (user_id, season_id, source, task_key, instance_key, stars, created_at, metadata_json)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
  `).bind(userId, seasonId, source, taskKey, instanceKey, stars, now, metadataJson ?? null).run();

  // If no row was inserted (duplicate), skip star award
  if (!ledgerResult.meta.changes || ledgerResult.meta.changes === 0) {
    // Already awarded — read current star total for return
    const row = await env.DB.prepare(
      `SELECT stars FROM user_season_progress WHERE user_id = ? AND season_number = ?`
    ).bind(userId, seasonId).first() as any;
    return { awarded: false, totalStars: Number(row?.stars || 0) };
  }

  // Actually award the stars (increment)
  const result = await awardStars(env, userId, stars, seasonId);
  return { awarded: true, ...result };
}

// Mark a task as completed in user_task_progress (idempotent)
async function markTaskCompleted(
  env: Env, userId: number, seasonId: number,
  taskKey: string, instanceKey: string, progress: number = 1
): Promise<boolean> {
  const now = Date.now();
  const res = await env.DB.prepare(`
    INSERT INTO user_task_progress (user_id, season_id, task_key, instance_key, progress, completed_at, reward_granted)
    VALUES (?, ?, ?, ?, ?, ?, 0)
    ON CONFLICT(user_id, season_id, task_key, instance_key) DO UPDATE SET
      progress = MAX(user_task_progress.progress, excluded.progress),
      completed_at = COALESCE(user_task_progress.completed_at, excluded.completed_at)
  `).bind(userId, seasonId, taskKey, instanceKey, progress, now).run();
  return (res.meta.changes ?? 0) > 0;
}

// Mark task reward as granted + shown_at
async function markTaskRewardGranted(
  env: Env, userId: number, seasonId: number,
  taskKey: string, instanceKey: string
): Promise<void> {
  await env.DB.prepare(`
    UPDATE user_task_progress SET reward_granted = 1
    WHERE user_id = ? AND season_id = ? AND task_key = ? AND instance_key = ?
  `).bind(userId, seasonId, taskKey, instanceKey).run();
}

async function upsertTaskProgress(
  env: Env,
  userId: number,
  seasonId: number,
  taskKey: string,
  instanceKey: string,
  progress: number,
  opts?: { completed?: boolean; rewardGranted?: boolean }
): Promise<void> {
  const now = Date.now();
  const completedAt = opts?.completed ? now : null;
  const rewardGranted = opts?.rewardGranted ? 1 : 0;
  await env.DB.prepare(`
    INSERT INTO user_task_progress (user_id, season_id, task_key, instance_key, progress, completed_at, reward_granted)
    VALUES (?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(user_id, season_id, task_key, instance_key) DO UPDATE SET
      progress = excluded.progress,
      completed_at = CASE
        WHEN excluded.completed_at IS NOT NULL THEN COALESCE(user_task_progress.completed_at, excluded.completed_at)
        ELSE NULL
      END,
      reward_granted = CASE
        WHEN excluded.reward_granted = 1 THEN 1
        ELSE CASE WHEN excluded.completed_at IS NULL THEN 0 ELSE user_task_progress.reward_granted END
      END
  `).bind(userId, seasonId, taskKey, instanceKey, progress, completedAt, rewardGranted).run();
}

async function revokeStarsForTask(
  env: Env,
  userId: number,
  seasonId: number,
  taskKey: string,
  instanceKey: string,
  stars: number
): Promise<void> {
  if (stars <= 0) return;
  const delRes = await env.DB.prepare(`
    DELETE FROM stars_ledger
    WHERE user_id = ? AND season_id = ? AND task_key = ? AND instance_key = ?
  `).bind(userId, seasonId, taskKey, instanceKey).run();

  if ((delRes.meta.changes ?? 0) > 0) {
    await env.DB.prepare(`
      UPDATE user_season_progress
      SET stars = MAX(0, stars - ?)
      WHERE user_id = ? AND season_number = ?
    `).bind(stars, userId, seasonId).run();
  }

  await env.DB.prepare(`
    UPDATE user_task_progress
    SET reward_granted = 0,
        completed_at = NULL
    WHERE user_id = ? AND season_id = ? AND task_key = ? AND instance_key = ?
  `).bind(userId, seasonId, taskKey, instanceKey).run();
}

// ========== END NEW TASKS CATALOG ARCHITECTURE ==========

// Award balls to a user (idempotent via balls_ledger unique index)
async function awardBalls(
  env: Env, userId: number, amount: number,
  seasonId?: number, taskKey?: string, instanceKey?: string, source?: string
): Promise<void> {
  if (amount <= 0) return;
  const sn = seasonId ?? await getCurrentSeasonNumber(env);
  const tk = taskKey ?? 'unknown';
  const ik = instanceKey ?? 'season';
  const src = source ?? 'task_reward';
  // One atomic batch, same shape as the shop purchase: the ledger row is the anchor and
  // carries idempotency via the unique index (user_id, season_id, task_key, instance_key),
  // and the balance update commits or rolls back with it. This used to be two separate
  // statements — a crash in between left the ledger row written and the balls never
  // credited, which INSERT OR IGNORE then made unrecoverable on retry.
  // A plain INSERT (not OR IGNORE) is deliberate: a duplicate must throw so the whole
  // batch rolls back instead of silently crediting the balance twice.
  try {
    await env.DB.batch([
      env.DB.prepare(
        `INSERT INTO balls_ledger (user_id, season_id, task_key, instance_key, balls, source, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?)`
      ).bind(userId, sn, tk, ik, amount, src, Date.now()),
      env.DB.prepare(
        `UPDATE users SET balls = balls + ? WHERE id = ?`
      ).bind(amount, userId),
    ]);
  } catch (e: any) {
    // Already granted (or a concurrent request won the race) → the batch rolled back, nothing
    // was credited twice. Same silent no-op the previous OR IGNORE produced.
    if (/UNIQUE constraint failed: balls_ledger\./i.test(String(e?.message || e))) return;
    throw e;
  }
}

// Read a user's current lucky-token (Жетон) balance. Reuses the existing
// `fortune_spins` table as the single source of truth; missing row ⇒ 0.
async function getLuckyTokenBalance(env: Env, userId: number): Promise<number> {
  const row = await env.DB.prepare(
    `SELECT quantity FROM fortune_spins WHERE user_id = ?`
  ).bind(userId).first() as any;
  return Math.max(0, Number(row?.quantity || 0));
}

// Credit lucky tokens to a user + record history idempotently.
// The ledger row (UNIQUE ref_id) is the idempotency guard: the balance is only
// incremented when the ledger insert actually happened (mirrors awardBalls()).
// Returns the resulting balance.
async function grantLuckyTokens(
  env: Env, userId: number, amount: number,
  op: LuckyTokenOp, ref: string, now: number,
  comment?: string | null, adminUserId?: number | null,
): Promise<number> {
  const amt = Math.floor(Number(amount) || 0);
  if (amt <= 0) return getLuckyTokenBalance(env, userId);
  const before = await getLuckyTokenBalance(env, userId);
  // Atomic batch (see awardBalls): the ledger row is the anchor — UNIQUE(ref_id) makes a
  // replay throw and roll the whole batch back — and the balance credit commits with it.
  // Previously these were two statements, so a crash in between wrote history without ever
  // crediting the tokens, and the replay was swallowed by OR IGNORE.
  try {
    await env.DB.batch([
      env.DB.prepare(
        `INSERT INTO lucky_token_transactions
           (user_id, amount, balance_before, balance_after, operation_type, comment, admin_user_id, ref_id, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`
      ).bind(userId, amt, before, before + amt, op, comment ?? null, adminUserId ?? null, ref, now),
      env.DB.prepare(
        `INSERT INTO fortune_spins (user_id, quantity) VALUES (?, ?)
         ON CONFLICT(user_id) DO UPDATE SET quantity = quantity + excluded.quantity`
      ).bind(userId, amt),
    ]);
    return before + amt;
  } catch (e: any) {
    if (/UNIQUE constraint failed: lucky_token_transactions\.ref_id/i.test(String(e?.message || e))) {
      return getLuckyTokenBalance(env, userId); // duplicate ref ⇒ already granted
    }
    throw e;
  }
}

// Debit lucky tokens atomically (never below zero). Records history. Returns the
// resulting balance, or null if the user did not have enough tokens.
async function spendLuckyTokens(
  env: Env, userId: number, amount: number,
  op: LuckyTokenOp, ref: string, now: number,
  comment?: string | null, adminUserId?: number | null,
): Promise<number | null> {
  const amt = Math.floor(Number(amount) || 0);
  if (amt <= 0) return getLuckyTokenBalance(env, userId);
  // Atomic conditional debit — cannot go below zero.
  const dec = await env.DB.prepare(
    `UPDATE fortune_spins SET quantity = quantity - ? WHERE user_id = ? AND quantity >= ? RETURNING quantity`
  ).bind(amt, userId, amt).first() as any;
  if (!dec) return null;
  const after = Math.max(0, Number(dec.quantity));
  await env.DB.prepare(
    `INSERT OR IGNORE INTO lucky_token_transactions
       (user_id, amount, balance_before, balance_after, operation_type, comment, admin_user_id, ref_id, created_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`
  ).bind(userId, -amt, after + amt, after, op, comment ?? null, adminUserId ?? null, ref, now).run();
  return after;
}

// Grant a case reward to a user

// Get updated user state after case open
async function getCaseUserState(env: Env, userId: number) {
  const sn = await getCurrentSeasonNumber(env);
  const [userRow, casesRes, boostsRes, starRow] = await Promise.all([
    env.DB.prepare(`SELECT balls, extra_league_slots FROM users WHERE id = ?`).bind(userId).first() as Promise<any>,
    env.DB.prepare(`SELECT case_type, quantity FROM user_cases WHERE user_id = ?`).bind(userId).all(),
    env.DB.prepare(
      `SELECT boost_type, COUNT(*) as cnt FROM user_boosts WHERE user_id = ? AND status = 'available' GROUP BY boost_type`
    ).bind(userId).all(),
    env.DB.prepare(
      `SELECT stars FROM user_season_progress WHERE user_id = ? AND season_number = ?`
    ).bind(userId, sn).first() as Promise<any>,
  ]);
  const freeCases = ((casesRes.results || []) as any[]).find(r => r.case_type === 'daily_free')?.quantity ?? 0;
  const boosts: Record<string, number> = {};
  for (const r of (boostsRes.results || []) as any[]) {
    boosts[r.boost_type] = Number(r.cnt);
  }
  return {
    balance: userRow?.balls ?? 0,
    freeCases,
    extraLeagueSlots: userRow?.extra_league_slots ?? 0,
    boosts,
    stars: starRow?.stars ?? 0,
  };
}

function nowUnixSeconds() {
  return Math.floor(Date.now() / 1000);
}


function parseJsonSafe<T = any>(value: unknown, fallback: T): T {
  if (!value || typeof value !== "string") return fallback;
  try {
    return JSON.parse(value) as T;
  } catch {
    return fallback;
  }
}

