// ── E6: eurocup knockout (playoff) foundation helpers (no scoring) ───────────

async function listEurocupKnockoutMatches(env: Env, tournamentId: number): Promise<any[]> {
  const res = await env.DB.prepare(`
    SELECT * FROM season_prediction_eurocup_knockout_matches
    WHERE tournament_id = ?
  `).bind(tournamentId).all();
  return sortKnockoutMatches((res.results || []) as any[]);
}

async function ensureEurocupDownstreamKnockoutMatches(env: Env, tournamentId: number, code: string, adminId: number): Promise<number> {
  const rows = await listEurocupKnockoutMatches(env, tournamentId);
  const updates = eurocupDownstreamKnockoutPairUpdates(rows, eurocupKnockoutBracketSources(code));
  if (updates.length === 0) return 0;
  const now = nowUnixSeconds();
  let changed = 0;
  for (const u of updates) {
    const result = await env.DB.prepare(`
      UPDATE season_prediction_eurocup_knockout_matches
      SET team_a_id = ?, team_b_id = ?,
          team_a_source = ?, team_b_source = ?,
          winner_team_id = NULL,
          status = CASE WHEN status IN ('confirmed','completed') AND winner_team_id IS NOT NULL THEN status ELSE 'confirmed' END,
          confirmed_at = CASE WHEN confirmed_at IS NULL THEN ? ELSE confirmed_at END,
          confirmed_by_admin_id = CASE WHEN confirmed_by_admin_id IS NULL THEN ? ELSE confirmed_by_admin_id END,
          updated_at = ?
      WHERE tournament_id = ?
        AND match_key = ?
        AND NOT (status IN ('confirmed','completed') AND winner_team_id IS NOT NULL)
    `).bind(
      u.team_a_id, u.team_b_id,
      u.team_a_source, u.team_b_source,
      now, adminId,
      now, tournamentId, u.match_key,
    ).run();
    changed += Number(result.meta?.changes || 0);
  }
  return changed;
}

function serializeEurocupKnockoutMatch(row: any) {
  return {
    match_key: row.match_key,
    stage: row.stage,
    match_order: Number(row.match_order || 0),
    team_a_id: row.team_a_id ?? null,
    team_b_id: row.team_b_id ?? null,
    team_a_source: row.team_a_source ?? null,
    team_b_source: row.team_b_source ?? null,
    winner_team_id: row.winner_team_id ?? null,
    status: row.status,
    source: row.source,
    known: isKnockoutMatchKnown(row),
  };
}

