// Ordered official league-stage zone ids (only meaningful once confirmed).
function eurocupOfficialZones(official: any | null): {
  confirmed: boolean;
  top8: string[];
  zone_9_24: string[];
  eliminated: string[];
} {
  const confirmed = !!official && ["confirmed", "published"].includes(String(official.status));
  const orderedRaw = official ? parseJsonSafe(official.team_ids_snapshot_json, []) : [];
  const ordered = Array.isArray(orderedRaw) ? orderedRaw.map((x: any) => String(x)) : [];
  if (!confirmed || ordered.length < 36) {
    return { confirmed, top8: [], zone_9_24: [], eliminated: [] };
  }
  return {
    confirmed: true,
    top8: ordered.slice(0, 8),
    zone_9_24: ordered.slice(8, 24),
    eliminated: ordered.slice(24, 36),
  };
}

// Build the KnownMatch[] used to validate user picks (both teams + confirmed/completed).
function eurocupKnownKnockoutMatches(matchRows: any[]): KnownMatch[] {
  return matchRows
    .filter((m) => isKnockoutMatchKnown(m))
    .map((m) => ({
      match_key: String(m.match_key),
      stage: m.stage,
      team_a_id: String(m.team_a_id),
      team_b_id: String(m.team_b_id),
    }));
}

// ── Stage E8: full eurocup recalc (league stage + play-off ties + bracket) ────
// Pure-logic-driven, NO rewards/economy/claim writes. League official table must
// be confirmed (league scoring needs it); play-off/bracket scoring is progressive
// and uses whatever official knockout results are already confirmed.
const EUROCUP_FULL_RESULT_BRACKET_STATUSES = new Set(["submitted", "locked", "completed"]);
const EUROCUP_RECALC_STAGES = new Set<EurocupPlayoffScopeStage>(["league", "ties", "r16", "qf", "sf", "final", "full"]);

function normalizeEurocupRecalcStage(raw: unknown): EurocupPlayoffScopeStage {
  const stage = String(raw || "full").trim().toLowerCase() as EurocupPlayoffScopeStage;
  if (!EUROCUP_RECALC_STAGES.has(stage)) throw new Error("INVALID_EUROCUP_RECALC_STAGE");
  return stage;
}

async function recalcEurocupFull(env: Env, code: string, adminId: number, triggerReason: string, scopeStage: EurocupPlayoffScopeStage = "full"): Promise<{
  ok: boolean;
  error?: string;
  formula_version: string;
  stage: EurocupPlayoffScopeStage;
  processed: number;
  skipped: number;
  failed: number;
  avg_score: number;
  max_score: number;
  max_possible_points: number;
  recalc_id: number;
  rewards_triggered: false;
}> {
  const season = await getSeasonPredictionSeason(env);
  const tournament = await getSeasonPredictionTournament(env, season.id, code);
  const official = await getSeasonPredictionOfficialResult(env, Number(tournament.id));
  if (!official || !["confirmed", "published"].includes(String(official.status))) {
    return { ok: false, error: "OFFICIAL_RESULTS_REQUIRED", formula_version: EUROCUPS_FULL_FORMULA_VERSION, stage: scopeStage, processed: 0, skipped: 0, failed: 0, avg_score: 0, max_score: 0, max_possible_points: 0, recalc_id: 0, rewards_triggered: false };
  }
  const teams = await listSeasonPredictionTeams(env, Number(tournament.id));
  if (!teams.length) throw new Error("TEAMS_NOT_CONFIGURED");
  const allowedIds = teams.map((t: any) => String(t.team_id || t.id));
  const snapshotIds = parseJsonSafe(official.team_ids_snapshot_json, []) as string[];
  const officialOrderedIds = Array.isArray(snapshotIds) && snapshotIds.length === EUROCUP_TEAM_COUNT
    ? snapshotIds.map(String)
    : validateEurocupOfficialTable(parseJsonSafe(official.table_json, {}), allowedIds);
  const nameById = new Map(teams.map((t: any) => [String(t.team_id || t.id), String(t.team_name || t.short_name || "")]));
  const teamName = (id: string) => nameById.get(id) || null;

  // Official knockout matches (ties + bracket) drive the progressive max.
  const knockoutRows = await listEurocupKnockoutMatches(env, Number(tournament.id));
  const officialMatches: KnockoutMatchRow[] = (knockoutRows || []).map((m: any) => ({
    match_key: String(m.match_key),
    stage: String(m.stage),
    match_order: Number(m.match_order || 0),
    team_a_id: m.team_a_id ?? null,
    team_b_id: m.team_b_id ?? null,
    winner_team_id: m.winner_team_id ?? null,
    status: m.status,
  }));
  if (scopeStage !== "full" && scopeStage !== "league") {
    const readiness = eurocupRecalcStageReadiness(officialMatches, scopeStage);
    if (!readiness.ready) {
      return {
        ok: false,
        error: "EUROCUP_RECALC_STAGE_RESULTS_REQUIRED",
        formula_version: EUROCUPS_FULL_FORMULA_VERSION,
        stage: scopeStage,
        processed: 0,
        skipped: 0,
        failed: 0,
        avg_score: 0,
        max_score: 0,
        max_possible_points: 0,
        recalc_id: 0,
        rewards_triggered: false,
      };
    }
  }

  // User knockout brackets (ties + bracket picks live together in picks_json).
  const bracketRes = await env.DB.prepare(`
    SELECT user_id, picks_json, status FROM season_prediction_eurocup_knockout_brackets
    WHERE tournament_id = ?
  `).bind(Number(tournament.id)).all();
  const bracketByUser = new Map<number, { picks: any; status: string }>();
  for (const b of (bracketRes.results || []) as any[]) {
    bracketByUser.set(Number(b.user_id), { picks: parseJsonSafe(b.picks_json, {}), status: String(b.status || "draft") });
  }

  const now = nowUnixSeconds();
  const logInsert = await env.DB.prepare(`
    INSERT INTO season_prediction_recalc_log (
      season_prediction_tournament_id, triggered_by_admin_id, trigger_reason, status,
      formula_version, formula_config_json, started_at
    ) VALUES (?, ?, ?, 'running', ?, ?, ?)
  `).bind(
    Number(tournament.id), Number(adminId), String(triggerReason || `eurocups_full:${scopeStage}`),
    EUROCUPS_FULL_FORMULA_VERSION, JSON.stringify({ league: EUROCUPS_FORMULA_VERSION, playoff: EUROCUPS_FULL_FORMULA_VERSION, scope_stage: scopeStage }), now,
  ).run();
  const recalcId = Number(logInsert.meta?.last_row_id || 0);

  try {
    const entriesRes = await env.DB.prepare(`
      SELECT * FROM season_prediction_user_entries
      WHERE season_prediction_season_id = ? AND tournament_code = ?
        AND status IN ('submitted','locked','scoring','completed')
    `).bind(Number(season.id), code).all();
    const entries = (entriesRes.results || []) as any[];

    let processed = 0;
    let skipped = 0;
    let failed = 0;
    let sumPoints = 0;
    let maxPoints = 0;
    let maxPossiblePoints = 0;
    const scoredAt = nowUnixSeconds();

    for (const entry of entries) {
      try {
        const userTable = parseJsonSafe(entry.table_json, null);
        if (!userTable) { skipped += 1; continue; }
        const league = scoreSeasonPredictionEurocupLeagueStageEntry({ userTable, officialOrderedIds, teamName });
        const userBracket = bracketByUser.get(Number(entry.user_id));
        const bracketSubmitted = !!userBracket && EUROCUP_FULL_RESULT_BRACKET_STATUSES.has(userBracket.status);
        const pb = scoreEurocupPlayoffBracket({
          officialMatches,
          picks: (userBracket?.picks || {}) as any,
          bracketSubmitted,
          scopeStage,
        });
        const full = combineEurocupFullScore(
          { total_points: league.total_points, max_possible_points: league.max_possible_points, breakdown: league.breakdown },
          pb,
        );
        await env.DB.prepare(`
          INSERT INTO season_prediction_user_scores (
            user_id, season_prediction_season_id, season_prediction_tournament_id, tournament_code, user_entry_id,
            total_points, max_possible_points, points_pct, breakdown_json, scored_at, scored_by_recalc_id, created_at, updated_at
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
          ON CONFLICT(user_id, season_prediction_tournament_id) DO UPDATE SET
            user_entry_id = excluded.user_entry_id,
            total_points = excluded.total_points,
            max_possible_points = excluded.max_possible_points,
            points_pct = excluded.points_pct,
            breakdown_json = excluded.breakdown_json,
            scored_at = excluded.scored_at,
            scored_by_recalc_id = excluded.scored_by_recalc_id,
            updated_at = excluded.updated_at
        `).bind(
          Number(entry.user_id), Number(season.id), Number(tournament.id), code, Number(entry.id),
          full.total_points, full.max_possible_points, full.points_pct, JSON.stringify(full.breakdown),
          scoredAt, recalcId, scoredAt, scoredAt,
        ).run();
        processed += 1;
        sumPoints += full.total_points;
        if (full.total_points > maxPoints) maxPoints = full.total_points;
        if (full.max_possible_points > maxPossiblePoints) maxPossiblePoints = full.max_possible_points;
      } catch {
        failed += 1;
      }
    }

    const avgPoints = processed > 0 ? Math.round((sumPoints / processed) * 100) / 100 : 0;
    await env.DB.prepare(`
      UPDATE season_prediction_recalc_log
      SET status = 'completed', entries_processed = ?, entries_skipped = ?, entries_failed = ?,
          avg_points = ?, max_points = ?, finished_at = ?
      WHERE id = ?
    `).bind(processed, skipped, failed, avgPoints, maxPoints, nowUnixSeconds(), recalcId).run();

    await writeAudit(env, "RECALCULATE_SEASON_PREDICTION_EUROCUP_FULL_SCORES", { code, recalcId, processed, skipped, failed }, Number(adminId));
    // NOTE: E8 — no rewards, no economy, no claim writes.
    return {
      ok: true,
      formula_version: EUROCUPS_FULL_FORMULA_VERSION,
      stage: scopeStage,
      processed, skipped, failed,
      avg_score: avgPoints, max_score: maxPoints, max_possible_points: maxPossiblePoints,
      recalc_id: recalcId,
      rewards_triggered: false,
    };
  } catch (runErr: any) {
    await env.DB.prepare(`
      UPDATE season_prediction_recalc_log SET status = 'failed', error_message = ?, finished_at = ? WHERE id = ?
    `).bind(String(runErr?.message || runErr), nowUnixSeconds(), recalcId).run();
    throw runErr;
  }
}

function serializeSeasonPredictionOfficialAward(row: any) {
  return {
    id: row.id,
    season_prediction_tournament_id: row.season_prediction_tournament_id,
    award_type: row.award_type,
    award_option_id: row.award_option_id ?? null,
    player_id: row.player_id ?? null,
    player_name: row.player_name,
    team_id: row.team_id ?? null,
    team_name: row.team_name ?? null,
    status: row.status,
    source: row.source,
    confirmed_at: row.confirmed_at ?? null,
    confirmed_by_admin_id: row.confirmed_by_admin_id ?? null,
    notes: row.notes ?? null,
  };
}

function normalizeOfficialAwardInput(raw: any) {
  let awardType: ReturnType<typeof normalizeSeasonPredictionOfficialAwardType>;
  try {
    awardType = normalizeSeasonPredictionOfficialAwardType(raw?.award_type || "");
  } catch {
    throw new Error("INVALID_OFFICIAL_AWARD_TYPE");
  }
  const playerName = String(raw?.player_name || "").trim();
  if (!playerName) throw new Error("OFFICIAL_AWARD_PLAYER_REQUIRED");
  const optionalString = (value: unknown) => {
    if (value === null || value === undefined || value === "") return null;
    return String(value).trim() || null;
  };
  const optionId = raw?.award_option_id;
  return {
    award_type: awardType,
    award_option_id: optionId === null || optionId === undefined || optionId === "" ? null : Number(optionId),
    player_id: optionalString(raw?.player_id),
    player_name: playerName,
    team_id: optionalString(raw?.team_id),
    team_name: optionalString(raw?.team_name),
  };
}

// Validates a confirmed official final table against the configured team list.
function validateOfficialTableForConfirm(tableJson: any, teams: any[], teamCount: number) {
  const officialIds = teams.map((team) => String(team.team_id || team.id));
  const officialSet = new Set(officialIds);
  const pickedIds = extractSeasonPredictionTableIds(tableJson);
  if (pickedIds.length !== teamCount) throw new Error("OFFICIAL_TABLE_INCOMPLETE");
  const pickedSet = new Set(pickedIds);
  if (pickedSet.size !== pickedIds.length) throw new Error("OFFICIAL_TABLE_HAS_DUPLICATES");
  for (const id of pickedIds) {
    if (!officialSet.has(id)) throw new Error("OFFICIAL_TABLE_HAS_UNKNOWN_TEAM");
  }
  return pickedIds;
}

