// Valid case codes for reward rules = active shop_cases (+ canonical season codes).
async function getSeasonRewardValidCaseTypes(env: Env): Promise<Set<string>> {
  const set = new Set<string>(["premium", "daily_free"]);
  try {
    const res = await env.DB.prepare(`SELECT code FROM shop_cases WHERE is_active = 1`).all();
    for (const r of ((res.results || []) as any[])) set.add(String(r.code));
  } catch {
    // shop_cases may be missing in some envs — canonical codes still apply.
  }
  return set;
}

