function serializeWeeklyChallenge(row: WeeklyChallengeRow | null, extras?: { matchCount?: number; questionCount?: number }) {
  if (!row) return null;
  return {
    id: row.id,
    season_prediction_season_id: row.season_prediction_season_id,
    code: row.code,
    title: row.title,
    description: row.description ?? null,
    status: row.status,
    open_at: row.open_at ?? null,
    deadline_at: row.deadline_at ?? null,
    close_at: row.close_at ?? null,
    sort_order: Number(row.sort_order || 0),
    task_schema_version: Number(row.task_schema_version || 1),
    bonus_question_key: normalizeWeeklyBonusQuestionKey(row.bonus_question_key) || null,
    settings: parseJsonSafe(row.settings_json, {}),
    // W-Builder: additive — competition mode lives in settings_json (legacy → "unspecified").
    competition_mode: resolveWeeklyCompetitionMode(parseJsonSafe(row.settings_json, {})),
    match_count: extras?.matchCount ?? null,
    question_count: extras?.questionCount ?? null,
    created_at: row.created_at ?? null,
    updated_at: row.updated_at ?? null,
  };
}

function serializeWeeklyChallengeMatch(row: any) {
  return {
    id: row.id,
    weekly_challenge_id: row.weekly_challenge_id,
    match_id: row.match_id ?? null,
    provider: row.provider ?? null,
    provider_match_id: row.provider_match_id ?? null,
    tournament_code: row.tournament_code ?? null,
    home_team_name: row.home_team_name,
    away_team_name: row.away_team_name,
    kickoff_at: row.kickoff_at ?? null,
    status: row.status ?? null,
    score_home: row.score_home ?? null,
    score_away: row.score_away ?? null,
    sort_order: Number(row.sort_order || 0),
    metadata: row.metadata ?? parseJsonSafe(row.metadata_json, {}),
  };
}

// `revealOfficial` is set by callers only once intake is closed (deadline passed /
// challenge locked). It lets a user self-check each answer as soon as its official
// result is CONFIRMED — before the final recalc ("предварительно"). Unconfirmed
// answers stay hidden (official_status='pending', no option id), so nothing leaks
// while the challenge is still open.
function serializeWeeklyChallengeQuestion(row: any, opts?: { revealOfficial?: boolean }) {
  const rawStatus = String(row.status || "active");
  let officialStatus: "pending" | "confirmed" | "void" = "pending";
  let officialAnswerOptionId: string | null = null;
  let officialAnswerOptionIds: string[] = [];
  if (opts?.revealOfficial) {
    const rawOfficial = String(row.official_status || "pending");
    if (rawStatus === "void" || rawOfficial === "void") {
      officialStatus = "void";
    } else if (rawOfficial === "confirmed") {
      officialStatus = "confirmed";
      officialAnswerOptionId = row.official_answer_option_id == null || row.official_answer_option_id === ""
        ? null
        : String(row.official_answer_option_id);
      const many = weeklyOfficialOptionIdsFromRow(row);
      officialAnswerOptionIds = many ?? (officialAnswerOptionId == null ? [] : [officialAnswerOptionId]);
    }
  }
  return {
    id: row.id,
    weekly_challenge_id: row.weekly_challenge_id,
    question_key: row.question_key,
    title: row.title,
    description: row.description ?? null,
    question_type: row.question_type || "single_select",
    options: row.options ?? parseJsonSafe(row.options_json, []),
    config: row.config ?? parseJsonSafe(row.config_json, {}),
    status: row.status,
    sort_order: Number(row.sort_order || 0),
    // W-Builder: additive — surfaced for the builder + generic renderer (legacy → null).
    template_key: (() => {
      const cfg = row.config ?? parseJsonSafe(row.config_json, {});
      const tk = cfg && typeof cfg === "object" ? String((cfg as any).template_key || "").trim() : "";
      return tk && getWeeklyTemplate(tk) ? tk : null;
    })(),
    display_category: weeklyQuestionDisplayCategory(String(row.question_key)),
    // Post-deadline self-check fields (see revealOfficial note above).
    official_status: officialStatus,
    official_answer_option_id: officialAnswerOptionId,
    // Full accepted set — single-answer questions repeat the one id here.
    official_answer_option_ids: officialAnswerOptionIds,
  };
}

// W1: map a question row to the pure scoring engine input shape.
function weeklyQuestionToScoringInput(q: any): WeeklyQuestionInput {
  return {
    id: Number(q.id),
    question_key: String(q.question_key),
    title: String(q.title || ""),
    status: String(q.status || "active"),
    options: Array.isArray(q.options) ? q.options : parseJsonSafe(q.options_json, []),
    official_status: String(q.official_status || "pending"),
    official_answer_option_id: q.official_answer_option_id == null || q.official_answer_option_id === "" ? null : String(q.official_answer_option_id),
    official_answer_option_ids: weeklyOfficialOptionIdsFromRow(q),
    allow_multi_correct: weeklyTemplateAllowsMultiCorrect(weeklyTemplateKeyFromRow(q)),
    official_note: q.official_note ?? null,
  };
}

// template_key lives inside config_json; both the row shape (config vs config_json)
// and legacy rows without a template are handled here so callers stay short.
function weeklyTemplateKeyFromRow(q: any): string | null {
  const cfg = q?.config ?? parseJsonSafe(q?.config_json, {});
  const tk = cfg && typeof cfg === "object" ? String((cfg as any).template_key || "").trim() : "";
  return tk && getWeeklyTemplate(tk) ? tk : null;
}

// Multi-answer ids are stored as a JSON array; NULL/garbage means "legacy single".
function weeklyOfficialOptionIdsFromRow(q: any): string[] | null {
  const raw = q?.official_answer_option_ids;
  if (raw == null || raw === "") return null;
  const parsed = Array.isArray(raw) ? raw : parseJsonSafe(raw, null);
  if (!Array.isArray(parsed)) return null;
  const ids = parsed.map((v: unknown) => (v == null ? "" : String(v))).filter((v: string) => v !== "");
  return ids.length > 0 ? ids : null;
}

// W1: admin view of a question's official-answer settings.
function serializeWeeklyOfficialAnswer(q: any) {
  return {
    question_id: Number(q.id),
    question_key: q.question_key,
    title: q.title,
    status: q.status,
    options: Array.isArray(q.options) ? q.options : parseJsonSafe(q.options_json, []),
    official_status: String(q.official_status || "pending"),
    official_answer_option_id: q.official_answer_option_id ?? null,
    official_answer_option_ids: weeklyOfficialOptionIdsFromRow(q),
    official_note: q.official_note ?? null,
    official_confirmed_at: q.official_confirmed_at ?? null,
    // W-Builder: additive context for the official-answers UI.
    config: Array.isArray(q.config) ? q.config : parseJsonSafe(q.config_json, q.config ?? {}),
    template_key: weeklyTemplateKeyFromRow(q),
    // Drives the multi-select in the official-answers UI (open to every template).
    allow_multi_correct: weeklyTemplateAllowsMultiCorrect(weeklyTemplateKeyFromRow(q)),
    display_category: weeklyQuestionDisplayCategory(String(q.question_key)),
  };
}

// W1: focused public weekly-challenge score shape (no other users' data).
function serializeWeeklyChallengeScore(row: any | null) {
  if (!row) return null;
  return {
    total_points: Number(row.total_points || 0),
    max_possible_points: Number(row.max_possible_points || 0),
    points_pct: Number(row.points_pct || 0),
    correct_answers: Number(row.correct_answers || 0),
    wrong_answers: Number(row.wrong_answers || 0),
    void_questions: Number(row.void_questions || 0),
    unanswered_questions: Number(row.unanswered_questions || 0),
    formula_version: row.formula_version || WEEKLY_CHALLENGE_FORMULA_VERSION,
    breakdown_json: parseJsonSafe(row.breakdown_json, {}),
    scored_at: row.scored_at ?? null,
  };
}

async function getWeeklyChallengeScore(env: Env, userId: number, challengeId: number): Promise<any | null> {
  return await env.DB.prepare(`
    SELECT * FROM season_prediction_weekly_challenge_scores
    WHERE user_id = ? AND weekly_challenge_id = ?
    LIMIT 1
  `).bind(userId, challengeId).first() as any;
}

// W2: all reward_ledger unique_keys already granted to this user for weekly tasks.
// Range scan (not LIKE) so underscores in the key are literal — avoids the D1
// "pattern too complex" error.
async function listWeeklyTaskClaimedKeys(env: Env, userId: number): Promise<string[]> {
  const res = await env.DB.prepare(`
    SELECT unique_key FROM reward_ledger
    WHERE user_id = ? AND status = 'granted'
      AND unique_key >= 'weekly_challenge_task:' AND unique_key < 'weekly_challenge_task;'
  `).bind(userId).all();
  return ((res.results || []) as any[]).map((r) => String(r.unique_key));
}

async function listWeeklyTaskClaimSnapshots(env: Env, userId: number): Promise<WeeklyTaskBuilderInput["claimedTaskSnapshots"]> {
  const res = await env.DB.prepare(`
    SELECT weekly_challenge_id, task_key, reward_snapshot_json
    FROM weekly_challenge_task_claims
    WHERE user_id = ? AND status = 'completed'
  `).bind(userId).all();
  const snapshots: NonNullable<WeeklyTaskBuilderInput["claimedTaskSnapshots"]> = {};
  for (const row of ((res.results || []) as any[])) {
    const challengeId = Number(row.weekly_challenge_id || 0);
    const taskKey = String(row.task_key || "");
    if (!challengeId || !taskKey) continue;
    const base = `weekly_challenge_task:${challengeId}:${taskKey}:${userId}`;
    const parsed = parseJsonSafe(row.reward_snapshot_json, {}) as any;
    const reward = parsed?.reward && typeof parsed.reward === "object"
      ? {
        stars: Number(parsed.reward.stars || 0),
        balls: Number(parsed.reward.balls || 0),
        case_type: parsed.reward.case_type == null ? null : String(parsed.reward.case_type),
        case_count: Number(parsed.reward.case_count || 0),
      }
      : null;
    snapshots[base] = {
      reward,
      tier: parsed?.tier == null ? null : String(parsed.tier),
      task_schema_version: parsed?.task_schema_version == null ? null : Number(parsed.task_schema_version),
      component_keys: Array.isArray(parsed?.component_keys) ? parsed.component_keys.map((key: unknown) => String(key)) : [],
    };
  }
  return snapshots;
}

async function loadWeeklyChallengeTasksInputForChallenge(
  env: Env,
  userId: number,
  challenge: WeeklyChallengeRow,
  season: SeasonPredictionSeasonRow,
): Promise<WeeklyTaskBuilderInput> {
  const seasonId = Number(season.id);
  let entry: WeeklyTaskBuilderInput["entry"] = null;
  let activeQuestionKeys: string[] = [];
  let score: WeeklyTaskBuilderInput["score"] = null;
  let questionResults: WeeklyTaskBuilderInput["questionResults"] = {};
  let resultsStale = false;

  const [entryRow, questions, scoreRow, recalcState] = await Promise.all([
    getWeeklyChallengeEntry(env, userId, Number(challenge.id)),
    listWeeklyChallengeQuestions(env, Number(challenge.id)),
    getWeeklyChallengeScore(env, userId, Number(challenge.id)),
    getWeeklyChallengeRecalcState(env, challenge),
  ]);
  if (entryRow) {
    entry = { status: String(entryRow.status), answers: parseJsonSafe(entryRow.answers_json, {}), submitted_at: entryRow.submitted_at ?? null };
  }
  activeQuestionKeys = questions
    .filter((q) => String(q.status || "active") === "active")
    .map((q) => String(q.question_key));
  if (scoreRow) {
    score = {
      total_points: Number(scoreRow.total_points || 0),
      max_possible_points: Number(scoreRow.max_possible_points || 0),
      correct_answers: Number(scoreRow.correct_answers || 0),
    };
    const breakdown = parseJsonSafe(scoreRow.breakdown_json, {});
    const qs = Array.isArray((breakdown as any)?.questions) ? (breakdown as any).questions : [];
    questionResults = Object.fromEntries(qs.map((q: any) => [
      String(q.question_key || ""),
      {
        status: String(q.status || "pending_official"),
        points: Number(q.points || 0),
        title: q.title ?? null,
      },
    ]).filter(([key]: [string, any]) => !!key)) as WeeklyTaskBuilderInput["questionResults"];
  }
  // W5: a personal score is stale if official answers changed after the last recalc.
  resultsStale = !!scoreRow && weeklyChallengeResultsAreStale({
    officialUpdatedAt: recalcState.officialUpdatedAt,
    lastRecalcAt: recalcState.lastRecalcAt,
    hasScores: true,
  });

  const [seasonEntries, claimedUniqueKeys, claimedTaskSnapshots] = await Promise.all([
    listWeeklyChallengeEntriesForSeason(env, userId, seasonId),
    listWeeklyTaskClaimedKeys(env, userId),
    listWeeklyTaskClaimSnapshots(env, userId),
  ]);
  const seasonSubmittedCount = seasonEntries.filter((e) =>
    SEASON_PREDICTION_SUBMITTED_STATUSES.has(String(e.status)),
  ).length;

  return {
    userId,
    seasonId,
    challenge: {
      id: Number(challenge.id),
      title: String(challenge.title),
      status: String(challenge.status),
      deadline_at: challenge.deadline_at ?? null,
      task_schema_version: Number(challenge.task_schema_version || 1),
      bonus_question_key: normalizeWeeklyBonusQuestionKey(challenge.bonus_question_key),
    },
    entry,
    activeQuestionKeys,
    score,
    questionResults,
    resultsStale,
    seasonSubmittedCount,
    claimedUniqueKeys,
    claimedTaskSnapshots,
    // Per-challenge editable reward config (V2); malformed/absent → defaults.
    rewardConfig: parseWeeklyTaskRewardsFromSettings(parseJsonSafe(challenge.settings_json, {})).config,
  };
}

// W2: assemble the pure task-builder input for a user (active challenge surface).
// `publicCache` routes the shared season/challenge lookups through the 60s
// spPublicCached used by the home-screen surfaces. Only the read-only GET
// (badge) path passes it; claim flows keep fresh reads so reward validation
// never runs on stale config.
async function loadWeeklyChallengeTasksInput(env: Env, userId: number, opts?: { publicCache?: boolean }): Promise<WeeklyTaskBuilderInput> {
  const season = opts?.publicCache
    ? await spPublicCached("season", () => getSeasonPredictionSeason(env))
    : await getSeasonPredictionSeason(env);
  const seasonId = Number(season.id);
  const challenge = opts?.publicCache
    ? await spPublicCached(`wc:active:${seasonId}`, () => getActiveWeeklyChallenge(env, seasonId))
    : await getActiveWeeklyChallenge(env, seasonId);
  if (!challenge) {
    const [seasonEntries, claimedUniqueKeys, claimedTaskSnapshots] = await Promise.all([
      listWeeklyChallengeEntriesForSeason(env, userId, seasonId),
      listWeeklyTaskClaimedKeys(env, userId),
      listWeeklyTaskClaimSnapshots(env, userId),
    ]);
    const seasonSubmittedCount = seasonEntries.filter((e) =>
      SEASON_PREDICTION_SUBMITTED_STATUSES.has(String(e.status)),
    ).length;
    return {
      userId,
      seasonId,
      challenge: null,
      entry: null,
      activeQuestionKeys: [],
      score: null,
      resultsStale: false,
      seasonSubmittedCount,
      claimedUniqueKeys,
      claimedTaskSnapshots,
    };
  }
  return loadWeeklyChallengeTasksInputForChallenge(env, userId, challenge, season);
}

async function loadWeeklyChallengeTasksInputById(env: Env, userId: number, challengeId: number): Promise<WeeklyTaskBuilderInput | null> {
  const season = await getSeasonPredictionSeason(env);
  const challenge = await getWeeklyChallenge(env, Number(season.id), challengeId);
  if (!challenge || String(challenge.status) === "draft") return null;
  return loadWeeklyChallengeTasksInputForChallenge(env, userId, challenge, season);
}

// W2: grant a weekly-task reward idempotently via the shared reward_ledger.
// Each reward component gets a stable, score-independent unique_key suffix.
// Context is also written to metadata_json for ledger-level traceability (the
// dedup itself relies only on unique_key, so metadata is purely informational).
async function grantWeeklyChallengeTaskReward(
  env: Env,
  userId: number,
  taskKey: string,
  base: string,
  reward: WeeklyTaskReward,
  challengeId: number | null,
  snapshot?: Record<string, unknown>,
): Promise<{ stars: number; balls: number; case_type: string | null; case_count: number; lucky_tokens: number; boost_type: string | null; boost_count: number }> {
  const seasonId = await getCurrentSeasonNumber(env);
  const granted = await claimWeeklyChallengeTaskReward({
    db: env.DB,
    userId,
    seasonId,
    taskKey,
    base,
    reward,
    challengeId,
    snapshot,
    nowSeconds: nowUnixSeconds(),
    nowMs: Date.now(),
  });
  return { stars: granted.stars, balls: granted.balls, case_type: granted.case_type, case_count: granted.case_count, lucky_tokens: granted.lucky_tokens, boost_type: granted.boost_type, boost_count: granted.boost_count };
}

function serializeWeeklyChallengeEntry(row: any | null) {
  if (!row) return null;
  return {
    id: row.id,
    user_id: row.user_id,
    weekly_challenge_id: row.weekly_challenge_id,
    status: row.status,
    answers: parseJsonSafe(row.answers_json, {}),
    submitted_at: row.submitted_at ?? null,
    last_submitted_at: row.last_submitted_at ?? null,
    locked_at: row.locked_at ?? null,
    created_at: row.created_at ?? null,
    updated_at: row.updated_at ?? null,
  };
}

type SeasonPredictionTaskStatus = "available" | "in_progress" | "completed" | "future" | "failed";

type SeasonPredictionTaskPayload = {
  id: string;
  section: string;
  subsection: string;
  title: string;
  description: string;
  status: SeasonPredictionTaskStatus;
  progress: { current: number; target: number };
  // E10.2: reward + claim_status are filled by a final enrichment pass from the
  // admin-managed reward config. null/not_claimable for non-reward-bearing tasks.
  reward: TaskRewardPayload | null;
  claim_status?: SeasonTaskClaimStatus;
  future_reason?: string;
  badge?: string;
  phase?: string; // "league" | "ties" | "bracket" | "result" — in-card grouping
};

type SeasonPredictionTaskSubsectionPayload = {
  id: string;
  title: string;
  tasks: SeasonPredictionTaskPayload[];
  progress: { current: number; target: number };
};

const SEASON_PREDICTION_SUBMITTED_STATUSES = new Set(["submitted", "locked", "scoring", "completed"]);
const SEASON_PREDICTION_TOP_LEAGUE_LABELS: Record<string, string> = {
  PL: "АПЛ",
  PD: "Ла Лига",
  SA: "Серия А",
  BL1: "Бундеслига",
  FL1: "Лига 1",
};
const SEASON_PREDICTION_EUROPE_LABELS: Record<string, string> = {
  UCL: "Лига чемпионов",
  UEL: "Лига Европы",
  UECL: "Лига конференций",
};

function clampProgress(current: number, target: number): { current: number; target: number } {
  return { current: Math.max(0, Math.min(current, target)), target };
}

function getSeasonPredictionTaskStatus(current: number, target: number, future = false): SeasonPredictionTaskStatus {
  if (future) return "future";
  if (target > 0 && current >= target) return "completed";
  if (current > 0) return "in_progress";
  return "available";
}

function makeSeasonPredictionTask(
  section: string,
  subsection: string,
  id: string,
  title: string,
  description: string,
  current: number,
  target = 1,
  future = false,
  futureReason = "После подсчёта результатов",
): SeasonPredictionTaskPayload {
  const progress = future ? { current: 0, target } : clampProgress(current, target);
  const task: SeasonPredictionTaskPayload = {
    id,
    section,
    subsection,
    title,
    description,
    status: getSeasonPredictionTaskStatus(progress.current, progress.target, future),
    progress,
    reward: null,
  };
  if (future) task.future_reason = futureReason;
  return task;
}

function summarizeSeasonPredictionTasks(tasks: SeasonPredictionTaskPayload[]): { current: number; target: number } {
  const active = tasks.filter((task) => task.status !== "future");
  return {
    current: active.filter((task) => task.status === "completed").length,
    target: active.length,
  };
}

function hasSeasonPredictionAward(awards: any, key: string): boolean {
  if (!awards || typeof awards !== "object" || Array.isArray(awards)) return false;
  const value = awards[key] ?? (key === "top_assistant" ? awards.top_assister : undefined);
  return !!value && typeof value === "object";
}

function countSeasonPredictionAwards(awards: any): number {
  return ["top_scorer", "top_assistant", "golden_glove"].filter((key) => hasSeasonPredictionAward(awards, key)).length;
}

function getEuropeanLeagueStagePayload(entry: SeasonPredictionEntryRow | null): any {
  const table: any = parseJsonSafe(entry?.table_json, null);
  if (!table || typeof table !== "object" || Array.isArray(table)) return {};
  return table.league_stage && typeof table.league_stage === "object" ? table.league_stage : table;
}

async function listWeeklyChallengeEntriesForSeason(env: Env, userId: number, seasonId: number): Promise<any[]> {
  const res = await env.DB.prepare(`
    SELECT e.*,
           c.id AS challenge_id,
           c.status AS challenge_status,
           (
             SELECT COUNT(*)
             FROM season_prediction_weekly_challenge_questions q
             WHERE q.weekly_challenge_id = c.id AND q.status = 'active'
           ) AS active_question_count
    FROM season_prediction_weekly_challenge_entries e
    JOIN season_prediction_weekly_challenges c ON c.id = e.weekly_challenge_id
    WHERE e.user_id = ? AND c.season_prediction_season_id = ?
    ORDER BY c.id DESC
  `).bind(userId, seasonId).all();
  return (res.results || []) as any[];
}

// `publicCache`: see loadWeeklyChallengeTasksInput — GET-only; claim flows
// validate against fresh season/tournament config.
async function buildSeasonPredictionTasksResponse(env: Env, userId: number, opts?: { publicCache?: boolean }) {
  const season = opts?.publicCache
    ? await spPublicCached("season", () => getSeasonPredictionSeason(env))
    : await getSeasonPredictionSeason(env);
  const [tournaments, entries, weeklyEntries] = await Promise.all([
    opts?.publicCache
      ? spPublicCached(`tournaments:${season.id}:all`, () => listAllSeasonPredictionTournaments(env, Number(season.id)))
      : listAllSeasonPredictionTournaments(env, Number(season.id)),
    listSeasonPredictionEntries(env, userId, Number(season.id)),
    listWeeklyChallengeEntriesForSeason(env, userId, Number(season.id)),
  ]);
  const tournamentMap = new Map(tournaments.map((t) => [String(t.tournament_code), t]));
  const entryMap = new Map(entries.map((entry) => [String(entry.tournament_code), entry]));
  const topCodes = Array.from(SEASON_PREDICTION_TOP_LEAGUES);
  const europeCodes = Array.from(SEASON_PREDICTION_EUROPEAN_CUPS);
  const isSubmitted = (entry: SeasonPredictionEntryRow | null | undefined) => !!entry && SEASON_PREDICTION_SUBMITTED_STATUSES.has(String(entry.status));
  const tableCount = (entry: SeasonPredictionEntryRow | null | undefined) => extractSeasonPredictionTableIds(parseJsonSafe(entry?.table_json, null)).length;
  const leagueTarget = (code: string) => {
    const tournament = tournamentMap.get(code);
    return Number(tournament?.configured_team_count || tournament?.team_count || 0);
  };
  const awardsCount = (code: string) => countSeasonPredictionAwards(parseJsonSafe(entryMap.get(code)?.awards_json, null));
  const isLeagueComplete = (code: string) => isSubmitted(entryMap.get(code)) && awardsCount(code) >= 3;
  const submittedTopCount = topCodes.filter((code) => isSubmitted(entryMap.get(code))).length;
  const topAwardsAllCount = topCodes.filter((code) => awardsCount(code) >= 3).length;
  const topCompleteCount = topCodes.filter((code) => isLeagueComplete(code)).length;

  // ── Top-5 after-results scoring (drives the "Итог сезона" tasks) ──────────────
  // A league is "revealed" once its official results are scored (a score row exists).
  // Before that the tasks stay `future` ("Скоро"); after, completion is derived from
  // the same score columns the leaderboard uses. Rewards are configured in admin.
  const topScoreEntries = await Promise.all(topCodes.map(async (code) => {
    const tournament = tournamentMap.get(code);
    const score = tournament ? await getSeasonPredictionUserScore(env, userId, Number(tournament.id)) : null;
    return [code, score] as const;
  }));
  const topScoreMap = new Map(topScoreEntries);
  const topScored = (code: string) => !!topScoreMap.get(code);
  const topChampionHit = (code: string) => Number((topScoreMap.get(code) as any)?.champion_correct || 0) >= 1;
  const topExactPositions = (code: string) => Number((topScoreMap.get(code) as any)?.exact_positions || 0);
  const topAwardsHitCount = (code: string) => Number((topScoreMap.get(code) as any)?.awards_correct || 0);
  // Zone tasks complete on the "full zone" flag: every team of that official zone was
  // placed by the user inside the same zone (order within the zone does not matter).
  const topZoneFull = (code: string, col: string) => Number((topScoreMap.get(code) as any)?.[col] || 0) === 1;
  const topScoredCount = topCodes.filter(topScored).length;
  const topChampionsMultiCount = topCodes.filter(topChampionHit).length;
  const topAwardsMultiCount = topCodes.filter((code) => topAwardsHitCount(code) >= 1).length;

  const hasAnyWeeklyEntry = weeklyEntries.length > 0;
  const weeklyAllAnswered = weeklyEntries.some((entry) => {
    const activeCount = Number(entry.active_question_count || 0);
    const answers: Record<string, unknown> = parseJsonSafe(entry.answers_json, {});
    return activeCount > 0 && Object.keys(answers || {}).filter((key) => answers[key]).length >= activeCount;
  });
  const weeklySubmitted = weeklyEntries.some((entry) => SEASON_PREDICTION_SUBMITTED_STATUSES.has(String(entry.status)));

  const europeEntry = (code: string) => entryMap.get(code) || null;
  const europeTop8Count = (code: string) => normalizeStringIdList(getEuropeanLeagueStagePayload(europeEntry(code)).top8_team_ids).length;
  const europeZoneCount = (code: string) => normalizeStringIdList(getEuropeanLeagueStagePayload(europeEntry(code)).zone_9_24_team_ids).length;
  const europeSubmittedCount = europeCodes.filter((code) => isSubmitted(europeEntry(code))).length;
  const europeTop8FullCount = europeCodes.filter((code) => europeTop8Count(code) >= SEASON_PREDICTION_EUROPEAN_LEAGUE_STAGE_TOP8).length;
  const europeZoneFullCount = europeCodes.filter((code) => europeZoneCount(code) >= SEASON_PREDICTION_EUROPEAN_LEAGUE_STAGE_ZONE_9_24).length;

  const subsections: SeasonPredictionTaskSubsectionPayload[] = [];
  const addSubsection = (section: string, id: string, title: string, tasks: SeasonPredictionTaskPayload[]) => {
    subsections.push({ id, title, tasks, progress: summarizeSeasonPredictionTasks(tasks) });
  };

  addSubsection("start", "start", "Старт сезона", [
    makeSeasonPredictionTask("start", "start", "start_first_prediction", "Первый прогноз сезона", "Подтверди любой прогноз сезона: лигу, еврокубок или Вызов недели.", submittedTopCount + europeSubmittedCount + (weeklySubmitted ? 1 : 0), 1),
    makeSeasonPredictionTask("start", "start", "start_first_table", "Первая таблица", "Сохрани или подтверди таблицу любой топ-5 лиги.", topCodes.filter((code) => tableCount(entryMap.get(code)) > 0).length, 1),
    makeSeasonPredictionTask("start", "start", "start_individual_pick", "Индивидуальный выбор", "Выбери хотя бы одну индивидуальную награду в любой топ-5 лиге.", topCodes.filter((code) => awardsCount(code) > 0).length, 1),
    makeSeasonPredictionTask("start", "start", "start_full_league", "Полный прогноз лиги", "Подтверди таблицу и выбери все 3 индивидуальные награды в одной лиге.", topCompleteCount, 1),
    makeSeasonPredictionTask("start", "start", "start_big_start", "Большой старт", "Подтверди прогнозы по 3 лигам топ-5.", submittedTopCount, 3),
  ]);

  addSubsection("top5", "all", "Все топ-5", [
    makeSeasonPredictionTask("top5", "all", "top5_submit_2", "Подтвердить прогнозы по 2 лигам", "Подтверди сезонные прогнозы по любым двум лигам топ-5.", submittedTopCount, 2),
    makeSeasonPredictionTask("top5", "all", "top5_submit_3", "Подтвердить прогнозы по 3 лигам", "Подтверди сезонные прогнозы по любым трём лигам топ-5.", submittedTopCount, 3),
    makeSeasonPredictionTask("top5", "all", "top5_submit_5", "Подтвердить прогнозы по всем 5 лигам", "Закрой прогнозы по всей пятёрке лиг.", submittedTopCount, 5),
    makeSeasonPredictionTask("top5", "all", "top5_awards_all", "Выбрать индивидуальные награды во всех 5 лигах", "Заполни бомбардира, ассистента и вратаря во всех топ-5 лигах.", topAwardsAllCount, 5),
    makeSeasonPredictionTask("top5", "all", "top5_complete_all", "Завершить все топ-5 прогнозы полностью", "Подтверди таблицы и все индивидуальные награды во всех топ-5 лигах.", topCompleteCount, 5),
    makeSeasonPredictionTask("top5", "all", "top5_champions_multi", "Угадать чемпионов нескольких лиг", "Итог сезона: угадать чемпионов минимум в 2 лигах топ-5.", topChampionsMultiCount, 2, topScoredCount === 0),
    makeSeasonPredictionTask("top5", "all", "top5_awards_multi", "Угадать индивидуальные награды в разных лигах", "Итог сезона: угадать индивидуальные награды минимум в 2 лигах топ-5.", topAwardsMultiCount, 2, topScoredCount === 0),
  ]);

  for (const code of topCodes) {
    const label = SEASON_PREDICTION_TOP_LEAGUE_LABELS[code] || code;
    addSubsection("top5", code, label, [
      makeSeasonPredictionTask("top5", code, `top5_${code}_fill_table`, `Заполнить таблицу ${label}`, `Расставь полный список команд в таблице ${label}.`, tableCount(entryMap.get(code)), Math.max(leagueTarget(code), 1)),
      makeSeasonPredictionTask("top5", code, `top5_${code}_submit_prediction`, `Подтвердить прогноз ${label}`, `Подтверди сезонный прогноз по ${label}.`, isSubmitted(entryMap.get(code)) ? 1 : 0, 1),
      makeSeasonPredictionTask("top5", code, `top5_${code}_pick_awards`, "Выбрать индивидуальные награды", "Заполни лучшего бомбардира, ассистента и вратаря.", awardsCount(code), 3),
      makeSeasonPredictionTask("top5", code, `top5_${code}_complete`, `Завершить прогноз ${label} полностью`, "Подтверди таблицу и все 3 индивидуальные награды.", isLeagueComplete(code) ? 1 : 0, 1),
      makeSeasonPredictionTask("top5", code, `top5_${code}_champion`, "Угадать чемпиона", `Итог сезона: угадать чемпиона ${label}.`, topChampionHit(code) ? 1 : 0, 1, !topScored(code)),
      makeSeasonPredictionTask("top5", code, `top5_${code}_ucl_zone`, "Угадать зону Лиги чемпионов", `Итог сезона: расставить все команды зоны Лиги чемпионов ${label} в эту зону.`, topZoneFull(code, "ucl_zone_full") ? 1 : 0, 1, !topScored(code)),
      makeSeasonPredictionTask("top5", code, `top5_${code}_uel_zone`, "Угадать зону Лиги Европы", `Итог сезона: расставить все команды зоны Лиги Европы ${label} в эту зону.`, topZoneFull(code, "europa_zone_full") ? 1 : 0, 1, !topScored(code)),
      makeSeasonPredictionTask("top5", code, `top5_${code}_uecl_zone`, "Угадать зону Лиги конференций", `Итог сезона: расставить все команды зоны Лиги конференций ${label} в эту зону.`, topZoneFull(code, "conference_zone_full") ? 1 : 0, 1, !topScored(code)),
      makeSeasonPredictionTask("top5", code, `top5_${code}_relegation_zone`, "Угадать зону вылета", `Итог сезона: расставить все команды зоны вылета ${label} в эту зону.`, topZoneFull(code, "relegation_zone_full") ? 1 : 0, 1, !topScored(code)),
      makeSeasonPredictionTask("top5", code, `top5_${code}_full_table`, "Угадать всю таблицу точно", `Итог сезона: угадать точные позиции всех команд ${label}.`, topExactPositions(code), Math.max(1, leagueTarget(code)), !topScored(code)),
      makeSeasonPredictionTask("top5", code, `top5_${code}_awards_hit`, "Угадать индивидуальные награды", `Итог сезона: угадать хотя бы одну индивидуальную награду ${label}.`, topAwardsHitCount(code), 1, !topScored(code)),
    ]);
  }

  addSubsection("weekly", "weekly", "Вызов недели", [
    makeSeasonPredictionTask("weekly", "weekly", "weekly_participate", "Участвовать в Вызове недели", "Сохрани черновик или подтверди Вызов недели.", hasAnyWeeklyEntry ? 1 : 0, 1),
    makeSeasonPredictionTask("weekly", "weekly", "weekly_answer_all_5", "Ответить на все 5 вопросов", "Заполни ответы на все активные вопросы текущего вызова.", weeklyAllAnswered ? 1 : 0, 1),
    makeSeasonPredictionTask("weekly", "weekly", "weekly_submit", "Подтвердить Вызов недели", "Подтверди ответы Вызова недели.", weeklySubmitted ? 1 : 0, 1),
    makeSeasonPredictionTask("weekly", "weekly", "weekly_streak_3", "Серия из 3 недель подряд", "Будет засчитано, когда наберётся история недель.", 0, 3, true, "После накопления недельной истории"),
    makeSeasonPredictionTask("weekly", "weekly", "weekly_5_weeks", "Участвовать 5 недель за сезон", "Будет засчитано по истории недельных вызовов.", 0, 5, true, "После накопления недельной истории"),
    makeSeasonPredictionTask("weekly", "weekly", "weekly_future_score_3", "Угадать 3 из 5", "Будет засчитано после подведения итогов Вызова недели.", 0, 1, true),
    makeSeasonPredictionTask("weekly", "weekly", "weekly_future_score_5", "Угадать 5 из 5", "Будет засчитано после подведения итогов Вызова недели.", 0, 1, true),
  ]);

  // ── E10.1 data: per-cup play-off bracket + score (Стыки/Сетка/Результаты) ────
  // Progress-tracking tasks (reward: null), same as the league-stage eurocup tasks
  // — no reward_ledger / claim / dedup. Routed into the TOURNAMENT subsections
  // (Все / ЛЧ / ЛЕ / ЛК) and tagged with a phase for in-card grouping, so the top
  // chips stay tournament-only (no Стыки/Сетка/Результаты chips).
  const EUROCUP_TASK_SHORTS: Record<string, string> = { UCL: "ЛЧ", UEL: "ЛЕ", UECL: "ЛК" };
  const countStagePicks = (picks: unknown, stage: string): number => {
    const obj = picks && typeof picks === "object" && !Array.isArray(picks) ? (picks as Record<string, unknown>)[stage] : null;
    if (!obj || typeof obj !== "object" || Array.isArray(obj)) return 0;
    return Object.values(obj as Record<string, unknown>).filter((v) => v != null && v !== "").length;
  };
  // One query for the whole section: which cups have a confirmed play-off draw.
  // Until an admin confirms the pairs, every ties/bracket/result task renders as
  // «Скоро» instead of sitting on the league-stage screen as actionable.
  const openKnockoutCodes = new Set<string>();
  if (europeCodes.length) {
    const drawRes = await env.DB.prepare(`
      SELECT DISTINCT tournament_code FROM season_prediction_eurocup_knockout_matches
      WHERE status IN ('confirmed','completed')
    `).all();
    for (const row of (drawRes.results || []) as any[]) openKnockoutCodes.add(String(row.tournament_code));
  }
  const knockoutCups: EurocupCupTaskInput[] = [];
  // League-stage result figures per cup, harvested from the same score rows the
  // knockout tasks need — the league result tasks below are built in a separate
  // loop and would otherwise re-read every row.
  const leagueResults = new Map<string, EurocupLeagueStageResult | null>();
  for (const code of europeCodes) {
    const tournament = tournamentMap.get(code);
    if (!tournament) continue;
    const [bracketRow, scoreRow] = await Promise.all([
      getEurocupKnockoutBracket(env, userId, Number(tournament.id)),
      getSeasonPredictionUserScore(env, userId, Number(tournament.id)),
    ]);
    const picks = parseJsonSafe(bracketRow?.picks_json, {});
    const bracketPicked = ["round_of_16", "quarter_final", "semi_final", "final"].reduce((n, s) => n + countStagePicks(picks, s), 0);
    knockoutCups.push({
      code: code as EurocupCupCode,
      label: SEASON_PREDICTION_EUROPE_LABELS[code] || code,
      short: EUROCUP_TASK_SHORTS[code] || code,
      tiesPicked: countStagePicks(picks, "knockout_playoffs"),
      bracketPicked,
      championPicked: !!(picks && typeof picks === "object" && (picks as Record<string, unknown>).champion_team_id) || countStagePicks(picks, "final") > 0,
      bracketSubmitted: !!bracketRow && SEASON_PREDICTION_SUBMITTED_STATUSES.has(String(bracketRow.status)),
      result: scoreRow ? parseEurocupResultFromBreakdown(parseJsonSafe(scoreRow.breakdown_json, {}), Number(scoreRow.total_points || 0)) : null,
      knockoutOpen: openKnockoutCodes.has(code),
    });
    leagueResults.set(code, scoreRow
      ? parseEurocupLeagueStageResult(parseJsonSafe(scoreRow.breakdown_json, {}), Number(scoreRow.total_points || 0))
      : null);
  }
  const leagueResult = (code: string) => leagueResults.get(code) || null;
  const cupsWithLeaguePoints = (min: number) =>
    europeCodes.filter((code) => (leagueResult(code)?.points ?? 0) >= min).length;
  const cupsWithFullTop8 = () =>
    europeCodes.filter((code) => (leagueResult(code)?.top8_correct ?? 0) >= SEASON_PREDICTION_EUROPEAN_LEAGUE_STAGE_TOP8).length;
  // "Not scored yet" for the whole phase: no cup has official results, so the
  // aggregates read as pending instead of as already-failed.
  const noLeagueResultsYet = europeCodes.every((code) => !leagueResult(code));
  const knockoutViews = buildEurocupKnockoutTaskViews(knockoutCups);
  const toEurocupTaskPayload = (v: (typeof knockoutViews)[number]): SeasonPredictionTaskPayload => {
    const subsection = v.cup === "aggregate" ? "all" : v.cup;
    const payload: SeasonPredictionTaskPayload = {
      id: v.id, section: "europe", subsection, title: v.title, description: v.description,
      status: v.status, progress: { current: v.current, target: v.target }, reward: null,
      badge: v.badge, phase: v.badge,
    };
    if (v.future_reason) payload.future_reason = v.future_reason;
    return payload;
  };
  const knockoutFor = (target: EurocupCupCode | "aggregate") => knockoutViews.filter((v) => v.cup === target).map(toEurocupTaskPayload);
  const withLeaguePhase = (tasks: SeasonPredictionTaskPayload[]): SeasonPredictionTaskPayload[] => tasks.map((t) => ({ ...t, phase: "league" }));

  addSubsection("europe", "all", "Все еврокубки", [
    ...withLeaguePhase([
      makeSeasonPredictionTask("europe", "all", "europe_submit_any", "Подтвердить прогноз любого еврокубка", "Подтверди прогноз стадии лиги хотя бы одного еврокубка.", europeSubmittedCount, 1),
      makeSeasonPredictionTask("europe", "all", "europe_submit_2", "Подтвердить прогнозы по 2 еврокубкам", "Подтверди прогнозы по двум еврокубкам.", europeSubmittedCount, 2),
      makeSeasonPredictionTask("europe", "all", "europe_submit_3", "Подтвердить прогнозы по всем 3 еврокубкам", "Подтверди ЛЧ, ЛЕ и ЛК.", europeSubmittedCount, 3),
      makeSeasonPredictionTask("europe", "all", "europe_top8_all", "Заполнить топ-8 во всех еврокубках", "Выбери топ-8 в каждом еврокубке.", europeTop8FullCount, 3),
      makeSeasonPredictionTask("europe", "all", "europe_zone_all", "Заполнить 9–24 во всех еврокубках", "Заполни зону 9–24 в каждом еврокубке.", europeZoneFullCount, 3),
      makeSeasonPredictionTask("europe", "all", "europe_res_points_50_all", "Набрать 50+ очков во всех еврокубках", "Набери минимум 50 очков за стадию лиги в каждом из трёх еврокубков.", cupsWithLeaguePoints(50), 3, noLeagueResultsYet),
      makeSeasonPredictionTask("europe", "all", "europe_res_points_75_all", "Набрать 75+ очков во всех еврокубках", "Набери минимум 75 очков за стадию лиги в каждом из трёх еврокубков.", cupsWithLeaguePoints(75), 3, noLeagueResultsYet),
      makeSeasonPredictionTask("europe", "all", "europe_res_top8_any", "Угадать весь топ-8 в любом еврокубке", "Угадай все 8 команд верхней зоны хотя бы в одном еврокубке.", cupsWithFullTop8(), 1, noLeagueResultsYet),
    ]),
    ...knockoutFor("aggregate"),
  ]);

  for (const code of europeCodes) {
    const label = SEASON_PREDICTION_EUROPE_LABELS[code] || code;
    addSubsection("europe", code, label, [
      ...withLeaguePhase([
        makeSeasonPredictionTask("europe", code, `europe_${code}_start`, "Начать прогноз стадии лиги", `Сохрани черновик прогноза для турнира: ${label}.`, europeEntry(code) ? 1 : 0, 1),
        makeSeasonPredictionTask("europe", code, `europe_${code}_top8`, "Заполнить Топ-8", "Выбери 8 команд, которые попадут в верхнюю зону.", europeTop8Count(code), SEASON_PREDICTION_EUROPEAN_LEAGUE_STAGE_TOP8),
        makeSeasonPredictionTask("europe", code, `europe_${code}_zone_9_24`, "Заполнить зону 9–24", "Выбери 16 команд зоны стыков.", europeZoneCount(code), SEASON_PREDICTION_EUROPEAN_LEAGUE_STAGE_ZONE_9_24),
        makeSeasonPredictionTask("europe", code, `europe_${code}_submit`, "Подтвердить прогноз стадии лиги", "Подтверди прогноз стадии лиги.", isSubmitted(europeEntry(code)) ? 1 : 0, 1),
        makeSeasonPredictionTask("europe", code, `europe_${code}_res_points_50`, "Набрать 50+ очков", "Набери минимум 50 очков из 100 за стадию лиги.", leagueResult(code)?.points ?? 0, 50, !leagueResult(code)),
        makeSeasonPredictionTask("europe", code, `europe_${code}_res_points_75`, "Набрать 75+ очков", "Набери минимум 75 очков из 100 за стадию лиги.", leagueResult(code)?.points ?? 0, 75, !leagueResult(code)),
        makeSeasonPredictionTask("europe", code, `europe_${code}_res_top24_20`, "Угадать 20 из 24 участников плей-офф", "Угадай минимум 20 из 24 команд, прошедших в плей-офф.", leagueResult(code)?.top24_correct ?? 0, 20, !leagueResult(code)),
        makeSeasonPredictionTask("europe", code, `europe_${code}_res_top24_all`, "Угадать всех участников плей-офф", "Угадай все 24 команды, прошедшие в плей-офф (в любой из двух зон).", leagueResult(code)?.top24_correct ?? 0, SEASON_PREDICTION_EUROPEAN_LEAGUE_STAGE_TOP24, !leagueResult(code)),
        makeSeasonPredictionTask("europe", code, `europe_${code}_res_top8_6`, "Угадать 6 из 8 в топ-8", "Угадай минимум 6 из 8 команд верхней зоны.", leagueResult(code)?.top8_correct ?? 0, 6, !leagueResult(code)),
        makeSeasonPredictionTask("europe", code, `europe_${code}_res_top8_all`, "Угадать весь топ-8", "Угадай все 8 команд, напрямую вышедших в 1/8 финала.", leagueResult(code)?.top8_correct ?? 0, SEASON_PREDICTION_EUROPEAN_LEAGUE_STAGE_TOP8, !leagueResult(code)),
      ]),
      ...knockoutFor(code as EurocupCupCode),
    ]);
  }

  // ── «Золотой мяч» · только результаты ────────────────────────────────────────
  // За заполнение бюллетеня заданий нет намеренно: он предзаполнен и
  // подтверждается одним нажатием, награда за это была бы раздачей из воздуха.
  // До подтверждения официального итога всё висит как future («Скоро») — строка
  // очков появляется только после админского пересчёта.
  const ballonDorTournament = tournamentMap.get(SEASON_PREDICTION_BALLON_DOR_CODE) || null;
  if (ballonDorTournament && await isBallonDorVisibleForUser(env, userId)) {
    const bdScore = await getSeasonPredictionUserScore(env, userId, Number(ballonDorTournament.id));
    const bdScored = !!bdScore;
    // Флаги тиров лежат в breakdown_json: под них нет отдельных колонок, а
    // champion_correct переиспользован под обладателя (тот же смысл «угадал первого»).
    const bdBreakdown = parseJsonSafe((bdScore as any)?.breakdown_json, {} as Record<string, unknown>);
    const bdFlag = (key: string) => (Number((bdBreakdown as any)?.[key] || 0) >= 1 ? 1 : 0);
    const bdNomineeCount = Math.max(1, Number(ballonDorTournament.team_count || BALLON_DOR_NOMINEE_COUNT));
    // Считаем расставленных, а не подтверждение: черновик — это уже работа, а
    // отдельного задания «подтвердить» нет намеренно (один тап поверх готового
    // бюллетеня снова стал бы наградой из воздуха).
    const bdPlaced = extractBallonDorRankingIds(parseJsonSafe(entryMap.get(SEASON_PREDICTION_BALLON_DOR_CODE)?.table_json, null)).length;
    addSubsection("ballon_dor", "ballon_dor", "Золотой мяч", [
      makeSeasonPredictionTask("ballon_dor", "ballon_dor", "ballon_dor_fill", "Расставить всех номинантов",
        "Разложи все 30 номинантов по местам — с 1-го по 30-е.",
        bdPlaced, bdNomineeCount),
      makeSeasonPredictionTask("ballon_dor", "ballon_dor", "ballon_dor_winner", "Угадать обладателя Золотого мяча",
        "Итог: угадать, кто выиграл Золотой мяч.",
        Number((bdScore as any)?.champion_correct || 0) >= 1 ? 1 : 0, 1, !bdScored),
      makeSeasonPredictionTask("ballon_dor", "ballon_dor", "ballon_dor_top3_names", "Угадать топ-3 по именам",
        "Итог: все три призёра стоят в твоей тройке — порядок внутри неё не важен.",
        bdFlag("top3_names_correct"), 1, !bdScored),
      makeSeasonPredictionTask("ballon_dor", "ballon_dor", "ballon_dor_top5_exact", "Угадать топ-5 точно по местам",
        "Итог: первые пять мест совпали одно в одно.",
        bdFlag("top5_exact"), 1, !bdScored),
      makeSeasonPredictionTask("ballon_dor", "ballon_dor", "ballon_dor_top10_exact", "Угадать топ-10 точно по местам",
        "Итог: первые десять мест совпали одно в одно.",
        bdFlag("top10_exact"), 1, !bdScored),
      makeSeasonPredictionTask("ballon_dor", "ballon_dor", "ballon_dor_top30_exact", "Угадать все 30 мест точно",
        "Итог: весь список совпал одно в одно.",
        Number((bdScore as any)?.exact_positions || 0), bdNomineeCount, !bdScored),
      // Пороги очков стоят между вехами: «75+» было бы пересказом точного топ-5.
      makeSeasonPredictionTask("ballon_dor", "ballon_dor", "ballon_dor_points_30", "Набрать 30+ очков",
        "Итог: 30 очков за прогноз. Берётся и обладателем с тройкой, и десятком угаданных мест.",
        Number((bdScore as any)?.total_points || 0), 30, !bdScored),
      makeSeasonPredictionTask("ballon_dor", "ballon_dor", "ballon_dor_points_50", "Набрать 50+ очков",
        "Итог: 50 очков за прогноз.",
        Number((bdScore as any)?.total_points || 0), 50, !bdScored),
      // Отдельная ось — точность по всей тридцатке, без оглядки на бонусы.
      makeSeasonPredictionTask("ballon_dor", "ballon_dor", "ballon_dor_exact_5", "Угадать 5+ мест",
        "Итог: пять номинантов оказались ровно на тех местах, куда ты их поставил.",
        Number((bdScore as any)?.exact_positions || 0), 5, !bdScored),
      makeSeasonPredictionTask("ballon_dor", "ballon_dor", "ballon_dor_exact_10", "Угадать 10+ мест",
        "Итог: десять номинантов на своих местах.",
        Number((bdScore as any)?.exact_positions || 0), 10, !bdScored),
    ]);
  }

  const sectionDefs = [
    { id: "start", title: "Старт сезона" },
    { id: "top5", title: "Топ-5 лиг" },
    { id: "weekly", title: "Вызов недели" },
    { id: "europe", title: "Еврокубки" },
    { id: "ballon_dor", title: "Золотой мяч" },
  ];
  const sections = sectionDefs.map((section) => {
    const items = subsections.filter((subsection) => subsection.tasks.some((task) => task.section === section.id));
    const tasks = items.flatMap((subsection) => subsection.tasks);
    return {
      ...section,
      subsections: items,
      progress: summarizeSeasonPredictionTasks(tasks),
    };
  });
  const allTasks = sections.flatMap((section) => section.subsections.flatMap((subsection) => subsection.tasks));

  // ── E10.2: enrich every task with reward + claim_status from the admin config ──
  // Reward = stored config ?? code default. A task is claimable only when its reward
  // is active (enabled & non-zero) AND status === "completed" AND not yet claimed.
  // Non-catalog tasks (start / weekly / future placeholders) stay reward:null.
  const [taskRewardConfig, claimedTaskKeys] = await Promise.all([
    getSeasonTaskRewardConfigMap(env),
    listSeasonTaskClaimedKeys(env, userId, Number(season.id)),
  ]);
  let claimableCount = 0;
  for (const task of allTasks) {
    const entry = getTaskRewardCatalogEntry(task.id);
    if (!entry) {
      task.reward = null;
      task.claim_status = "not_claimable";
      continue;
    }
    const eff = effectiveTaskReward(taskRewardConfig.get(task.id) || null, entry.default);
    const active = rewardIsActive(eff);
    const claimed = claimedTaskKeys.has(task.id);
    task.reward = rewardForPayload(eff);
    task.claim_status = taskClaimStatus(task.status, active, claimed);
    const override = taskRewardConfig.get(task.id)?.title_override;
    if (override) task.title = override;
    if (task.claim_status === "claimable") claimableCount += 1;
  }

  return {
    ok: true,
    season: serializeSeasonPredictionSeason(season),
    sections,
    progress: summarizeSeasonPredictionTasks(allTasks),
    claimable_count: claimableCount,
    // Per-level claimable breakdown (section / subsection / phase) for granular badges.
    summaries: buildSeasonTaskClaimableSummary(allTasks),
  };
}

function isWeeklyChallengeLocked(season: SeasonPredictionSeasonRow, challenge: WeeklyChallengeRow, entry?: any | null): boolean {
  if (entry && ["locked", "scoring", "completed"].includes(String(entry.status))) return true;
  if (["locked", "scoring", "completed", "archived"].includes(String(season.status))) return true;
  if (["locked", "scoring", "completed", "archived"].includes(String(challenge.status))) return true;
  if (challenge.status === "draft") return true; // not yet opened to users
  const deadline = Number(challenge.deadline_at || season.deadline_at || 0);
  return deadline > 0 && nowUnixSeconds() >= deadline;
}

function validateWeeklyChallengeQuestionInput(raw: any, index: number) {
  const key = String(raw?.question_key || "").trim();
  if (!WEEKLY_CHALLENGE_QUESTION_KEYS.includes(key as any)) {
    throw new Error("INVALID_WEEKLY_QUESTION_KEY");
  }
  const title = String(raw?.title || "").trim();
  if (!title) throw new Error("WEEKLY_QUESTION_TITLE_REQUIRED");
  const description = raw?.description == null || raw?.description === "" ? null : String(raw.description).trim();
  const questionType = String(raw?.question_type || "single_select").trim() || "single_select";
  const status = String(raw?.status || "active").trim() || "active";
  if (!WEEKLY_CHALLENGE_QUESTION_STATUSES.has(status)) throw new Error("INVALID_WEEKLY_QUESTION_STATUS");
  const optionsRaw = normalizeJsonPayload(raw?.options_json ?? raw?.options, [], "INVALID_WEEKLY_QUESTION_OPTIONS");
  if (!Array.isArray(optionsRaw)) throw new Error("INVALID_WEEKLY_QUESTION_OPTIONS");
  const seenIds = new Set<string>();
  const options = optionsRaw.map((option: any, i: number) => {
    const id = String(option?.id || "").trim();
    const label = String(option?.label || "").trim();
    if (!id) throw new Error("WEEKLY_QUESTION_OPTION_ID_REQUIRED");
    if (!label) throw new Error("WEEKLY_QUESTION_OPTION_LABEL_REQUIRED");
    if (seenIds.has(id)) throw new Error("WEEKLY_QUESTION_OPTION_DUPLICATE_ID");
    seenIds.add(id);
    // Preserve every key admin passes through (icons, refs, extra fields).
    return { ...option, id, label, sort_order: i + 1 };
  });
  if (status === "active" && options.length < 2) throw new Error("WEEKLY_QUESTION_NEEDS_AT_LEAST_TWO_OPTIONS");
  const config = normalizeNullableJsonObject(raw?.config_json ?? raw?.config, {}, "INVALID_WEEKLY_QUESTION_CONFIG");
  const templateKey = (config && typeof config === "object") ? String((config as any).template_key || "").trim() : "";
  // Key-specific shape sanity checks (only when active so a draft can be partial).
  if (status === "active") {
    // upset_count is template-aware exempt from the no_upset fallback requirement; all
    // other upset templates (and legacy custom upset questions) still require it.
    if (key === "upset_of_week" && templateKey !== "upset_count" && !seenIds.has("no_upset")) {
      throw new Error("WEEKLY_UPSET_REQUIRES_NO_UPSET_OPTION");
    }
    if (key === "duel_of_week") {
      for (const required of ["player_a", "player_b", "equal"]) {
        if (!seenIds.has(required)) throw new Error("WEEKLY_DUEL_REQUIRES_PLAYER_A_PLAYER_B_EQUAL");
      }
    }
  }
  return {
    question_key: key,
    title,
    description,
    question_type: questionType,
    options_json: JSON.stringify(options),
    config_json: JSON.stringify(config || {}),
    status,
    sort_order: Number(raw?.sort_order) > 0 ? Math.floor(Number(raw.sort_order)) : index + 1,
  };
}

function normalizeWeeklyChallengeMatchInput(raw: any, index: number) {
  const homeName = String(raw?.home_team_name || raw?.homeTeamName || "").trim();
  const awayName = String(raw?.away_team_name || raw?.awayTeamName || "").trim();
  if (!homeName) throw new Error("WEEKLY_MATCH_HOME_NAME_REQUIRED");
  if (!awayName) throw new Error("WEEKLY_MATCH_AWAY_NAME_REQUIRED");
  const optionalString = (value: unknown) => {
    if (value === null || value === undefined || value === "") return null;
    return String(value).trim() || null;
  };
  const optionalInt = (value: unknown) => {
    if (value === null || value === undefined || value === "") return null;
    const n = Number(value);
    return Number.isFinite(n) ? Math.floor(n) : null;
  };
  return {
    match_id: optionalString(raw?.match_id),
    provider: optionalString(raw?.provider),
    provider_match_id: optionalString(raw?.provider_match_id),
    tournament_code: optionalString(raw?.tournament_code),
    home_team_name: homeName,
    away_team_name: awayName,
    kickoff_at: normalizeOptionalUnixSeconds(raw?.kickoff_at),
    status: optionalString(raw?.status),
    score_home: optionalInt(raw?.score_home),
    score_away: optionalInt(raw?.score_away),
    metadata_json: JSON.stringify(normalizeNullableJsonObject(raw?.metadata_json ?? raw?.metadata ?? {}, {}, "INVALID_WEEKLY_MATCH_METADATA") || {}),
    sort_order: Number(raw?.sort_order) > 0 ? Math.floor(Number(raw.sort_order)) : index + 1,
  };
}

function validateWeeklyChallengeAnswers(answers: any, questions: any[], requireAll: boolean): { sanitized: Record<string, string>; missing: string[] } {
  const sanitized: Record<string, string> = {};
  const missing: string[] = [];
  const raw = (answers && typeof answers === "object" && !Array.isArray(answers)) ? answers as Record<string, unknown> : {};
  for (const question of questions) {
    const key = String(question.question_key);
    const status = String(question.status || "active");
    if (status !== "active") continue;
    const value = raw[key];
    if (value === null || value === undefined || value === "") {
      if (requireAll) missing.push(key);
      continue;
    }
    const stringValue = String(value);
    const allowed = (question.options || []).map((option: any) => String(option?.id || ""));
    if (!allowed.includes(stringValue)) {
      throw new Error(`WEEKLY_ANSWER_INVALID_FOR_${key.toUpperCase()}`);
    }
    sanitized[key] = stringValue;
  }
  if (requireAll && missing.length > 0) throw new Error("WEEKLY_ANSWERS_INCOMPLETE");
  return { sanitized, missing };
}

function normalizeWeeklyChallengeStatus(value: unknown, fallback: string): string {
  const status = String(value || fallback || "").trim();
  if (!WEEKLY_CHALLENGE_STATUSES.has(status)) throw new Error("INVALID_WEEKLY_CHALLENGE_STATUS");
  return status;
}

async function countWeeklyChallengeEntriesByStatus(env: Env, challengeId: number, statuses: string[]): Promise<number> {
  if (!statuses.length) return 0;
  const placeholders = statuses.map(() => "?").join(",");
  const row = await env.DB.prepare(`
    SELECT COUNT(*) AS c
    FROM season_prediction_weekly_challenge_entries
    WHERE weekly_challenge_id = ? AND status IN (${placeholders})
  `).bind(challengeId, ...statuses).first() as any;
  return Number(row?.c || 0);
}

// W2: how much of a challenge's question structure is safe to edit, based on real
// user interaction. Drafts already hold option ids, so they lock structure too.
async function getWeeklyChallengeQuestionEditState(env: Env, challengeId: number): Promise<{
  state: "unused" | "has_drafts" | "has_submissions" | "has_scores";
  drafts: number; submitted: number; scores: number; entries: number; structural_locked: boolean;
}> {
  const [drafts, submitted, scoresRow] = await Promise.all([
    countWeeklyChallengeEntriesByStatus(env, challengeId, ["draft"]),
    countWeeklyChallengeEntriesByStatus(env, challengeId, ["submitted", "locked", "scoring", "completed"]),
    env.DB.prepare(`SELECT COUNT(*) AS c FROM season_prediction_weekly_challenge_scores WHERE weekly_challenge_id = ?`).bind(challengeId).first() as Promise<any>,
  ]);
  const scores = Number(scoresRow?.c || 0);
  const state = resolveWeeklyEditState({ drafts, submitted, scores });
  return { state, drafts, submitted, scores, entries: drafts + submitted, structural_locked: !weeklyEditStateAllowsStructural(state) };
}

// Allowed case types for weekly rewards = the weekly default ("basic") + the canonical
// season case types (premium/daily_free + active shop_cases). "basic" stays first.
async function getWeeklyRewardAllowedCaseTypes(env: Env): Promise<Set<string>> {
  const set = new Set<string>([WEEKLY_DEFAULT_CASE_TYPE]);
  try {
    for (const c of await getSeasonRewardValidCaseTypes(env)) set.add(c);
  } catch {
    // fall back to the weekly default only
  }
  return set;
}

// Count a challenge's user/financial dependencies (for safe-delete eligibility).
async function getWeeklyChallengeDeletionCounts(env: Env, challengeId: number): Promise<WeeklyChallengeDeletionCounts> {
  const [entries, claimsRow, scoresRow, rewardsRow] = await Promise.all([
    countWeeklyChallengeEntriesByStatus(env, challengeId, ["draft", "submitted", "locked", "scoring", "completed"]),
    env.DB.prepare(`SELECT COUNT(*) AS c FROM weekly_challenge_task_claims WHERE weekly_challenge_id = ?`).bind(challengeId).first() as Promise<any>,
    env.DB.prepare(`SELECT COUNT(*) AS c FROM season_prediction_weekly_challenge_scores WHERE weekly_challenge_id = ?`).bind(challengeId).first() as Promise<any>,
    env.DB.prepare(`SELECT COUNT(*) AS c FROM reward_ledger WHERE source_type = 'weekly_challenge_task' AND status = 'granted' AND unique_key LIKE ?`).bind(`weekly_challenge_task:${challengeId}:%`).first() as Promise<any>,
  ]);
  return { entries, claims: Number(claimsRow?.c || 0), scores: Number(scoresRow?.c || 0), rewards: Number(rewardsRow?.c || 0) };
}

// Reward editing is allowed only while the challenge is an untouched draft: status
// 'draft', no entries, no claims. Anything else locks rewards (snapshot stays source of truth).
async function getWeeklyTaskRewardsLockState(env: Env, challenge: WeeklyChallengeRow): Promise<{ locked: boolean; reason: string | null; entries: number; claims: number }> {
  const [entries, claimsRow] = await Promise.all([
    countWeeklyChallengeEntriesByStatus(env, Number(challenge.id), ["draft", "submitted", "locked", "scoring", "completed"]),
    env.DB.prepare(`SELECT COUNT(*) AS c FROM weekly_challenge_task_claims WHERE weekly_challenge_id = ?`).bind(Number(challenge.id)).first() as Promise<any>,
  ]);
  const claims = Number(claimsRow?.c || 0);
  const notDraft = String(challenge.status) !== "draft";
  const locked = notDraft || entries > 0 || claims > 0;
  const reason = !locked ? null
    : notDraft ? "Вызов опубликован — награды изменить нельзя."
      : entries > 0 ? "Есть ответы игроков — награды изменить нельзя."
        : "Есть полученные награды — изменить нельзя.";
  return { locked, reason, entries, claims };
}

// W2: map a stored DB question row to the pure structure-compare shape.
function weeklyRowToStructure(row: any): WeeklyQuestionStructure {
  return {
    question_key: String(row.question_key),
    question_type: String(row.question_type || "single_select"),
    status: String(row.status || "active"),
    title: String(row.title || ""),
    description: row.description == null ? null : String(row.description),
    sort_order: Number(row.sort_order || 0),
    options: parseJsonSafe(row.options_json, []),
    config: parseJsonSafe(row.config_json, {}),
  };
}

// W4: recalc/stale state for a challenge. `weekly_official_updated_at` is stamped
// into settings_json by the official-answers PUT; the last completed recalc's
// finished_at comes from the shared recalc log.
async function getWeeklyChallengeRecalcState(env: Env, challenge: WeeklyChallengeRow): Promise<{
  lastRecalcAt: number | null;
  officialUpdatedAt: number | null;
  hasScores: boolean;
  scoresCount: number;
  resultsStale: boolean;
}> {
  const [lastRecalc, scoresRow] = await Promise.all([
    env.DB.prepare(`SELECT finished_at FROM season_prediction_recalc_log WHERE trigger_reason = ? AND status = 'completed' ORDER BY id DESC LIMIT 1`).bind(`weekly:${challenge.id}`).first() as Promise<any>,
    env.DB.prepare(`SELECT COUNT(*) AS c FROM season_prediction_weekly_challenge_scores WHERE weekly_challenge_id = ?`).bind(challenge.id).first() as Promise<any>,
  ]);
  const settings = parseJsonSafe(challenge.settings_json, {}) as any || {};
  const officialUpdatedAt = Number(settings?.weekly_official_updated_at) || null;
  const lastRecalcAt = lastRecalc?.finished_at == null ? null : Number(lastRecalc.finished_at);
  const scoresCount = Number(scoresRow?.c || 0);
  const hasScores = scoresCount > 0;
  return {
    lastRecalcAt,
    officialUpdatedAt,
    hasScores,
    scoresCount,
    resultsStale: weeklyChallengeResultsAreStale({ officialUpdatedAt, lastRecalcAt, hasScores }),
  };
}

// W2: map a sanitized PUT payload (options_json/config_json are strings) to the shape.
function weeklyPayloadToStructure(q: any): WeeklyQuestionStructure {
  return {
    question_key: String(q.question_key),
    question_type: String(q.question_type || "single_select"),
    status: String(q.status || "active"),
    title: String(q.title || ""),
    description: q.description == null ? null : String(q.description),
    sort_order: Number(q.sort_order || 0),
    options: parseJsonSafe(q.options_json, []),
    config: parseJsonSafe(q.config_json, {}),
  };
}

async function getWeeklyChallengeReadiness(env: Env, challengeId: number): Promise<{ matchCount: number; activeQuestionKeys: Set<string>; missingQuestionKeys: string[] }> {
  const [matches, questions] = await Promise.all([
    env.DB.prepare(`SELECT COUNT(*) AS c FROM season_prediction_weekly_challenge_matches WHERE weekly_challenge_id = ?`).bind(challengeId).first() as Promise<any>,
    env.DB.prepare(`
      SELECT question_key
      FROM season_prediction_weekly_challenge_questions
      WHERE weekly_challenge_id = ? AND status = 'active'
    `).bind(challengeId).all() as Promise<any>,
  ]);
  const activeQuestionKeys = new Set(((questions.results || []) as any[]).map((row) => String(row.question_key || "")));
  return {
    matchCount: Number(matches?.c || 0),
    activeQuestionKeys,
    missingQuestionKeys: WEEKLY_CHALLENGE_QUESTION_KEYS.filter((key) => !activeQuestionKeys.has(key)),
  };
}

// Returns another challenge in the same season that is already 'active' (excluding
// the given id), or null. Used to enforce a single active weekly challenge.
async function findOtherActiveWeeklyChallenge(env: Env, seasonId: number, excludeId: number): Promise<WeeklyChallengeRow | null> {
  const row = await env.DB.prepare(`
    SELECT * FROM season_prediction_weekly_challenges
    WHERE season_prediction_season_id = ? AND status = 'active' AND id != ?
    ORDER BY sort_order DESC, id DESC
    LIMIT 1
  `).bind(seasonId, excludeId).first() as any;
  return row || null;
}

// W1: full activation readiness. Pool non-empty, all 5 fixed question keys active
// with >=2 options + required special options, every question match_ref present in
// the pool, and the deadline (if set) has not already passed. Throws coded errors.
// The "single active challenge" guard is enforced by the caller (so it can return
// the offending challenge's id/code/title in the response).
async function assertWeeklyChallengeCanBeActive(env: Env, challenge: WeeklyChallengeRow): Promise<void> {
  const challengeId = Number(challenge.id);
  const readiness = await getWeeklyChallengeReadiness(env, challengeId);
  if (readiness.matchCount <= 0) throw new Error("WEEKLY_CHALLENGE_ACTIVE_REQUIRES_MATCH_POOL");
  if (readiness.missingQuestionKeys.length > 0) {
    throw new Error(`WEEKLY_CHALLENGE_ACTIVE_REQUIRES_5_ACTIVE_QUESTIONS:${readiness.missingQuestionKeys.join(",")}`);
  }

  const [matches, questions] = await Promise.all([
    listWeeklyChallengeMatches(env, challengeId),
    listWeeklyChallengeQuestions(env, challengeId),
  ]);
  const parsedQuestions = questions.map((q: any) => ({
    question_key: String(q.question_key),
    status: String(q.status || "active"),
    options: parseJsonSafe(q.options_json, []) as Array<{ id?: unknown; match_ref?: unknown }>,
    config: parseJsonSafe(q.config_json, {}),
  }));

  validateWeeklyActivationQuestions(parsedQuestions);

  const poolRefs = buildWeeklyPoolRefSet(matches);
  const badRef = findWeeklyQuestionMatchRefNotInPool(parsedQuestions, poolRefs);
  if (badRef) throw new Error(`WEEKLY_QUESTION_MATCH_NOT_IN_POOL:${badRef.question_key}`);

  if (Number(challenge.task_schema_version || 1) >= WEEKLY_CHALLENGE_TASK_SCHEMA_V2) {
    const bonusKey = normalizeWeeklyBonusQuestionKey(challenge.bonus_question_key);
    if (!bonusKey) throw new Error("WEEKLY_V2_BONUS_QUESTION_REQUIRED");
    const fullKey = weeklyBonusQuestionFullKey(bonusKey);
    if (!fullKey || !readiness.activeQuestionKeys.has(fullKey)) {
      throw new Error("WEEKLY_V2_BONUS_QUESTION_INVALID");
    }
  }

  const deadline = Number(challenge.deadline_at || 0);
  if (deadline > 0 && nowUnixSeconds() >= deadline) throw new Error("WEEKLY_CHALLENGE_DEADLINE_PASSED");
}

