function normalizeOptionalUnixSeconds(value: unknown): number | null {
  if (value === undefined || value === null || value === "") return null;
  if (typeof value === "number" && Number.isFinite(value)) return Math.floor(value);
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed) return null;
    if (/^\d+$/.test(trimmed)) return Number(trimmed);
    const parsed = Date.parse(trimmed);
    if (Number.isFinite(parsed)) return Math.floor(parsed / 1000);
  }
  throw new Error("INVALID_TIMESTAMP");
}

function normalizeJsonPayload(value: unknown, fallback: unknown, errorCode: string): unknown {
  if (value === undefined) return fallback;
  if (value === null) return null;
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed) return fallback;
    try {
      return JSON.parse(trimmed);
    } catch {
      throw new Error(errorCode);
    }
  }
  if (typeof value === "object") return value;
  throw new Error(errorCode);
}

function normalizeNullableJsonObject(value: unknown, fallback: unknown, errorCode: string): unknown {
  const normalized = normalizeJsonPayload(value, fallback, errorCode);
  if (normalized === null) return null;
  if (typeof normalized !== "object" || Array.isArray(normalized)) throw new Error(errorCode);
  return normalized;
}

function validateSeasonPredictionZones(zones: unknown, teamCount: number) {
  if (typeof zones !== "object" || zones === null || Array.isArray(zones)) throw new Error("INVALID_ZONES_JSON");
  const used = new Map<number, string>();
  for (const [zoneKey, rawValue] of Object.entries(zones as Record<string, unknown>)) {
    if (rawValue === null) continue;
    if (!Array.isArray(rawValue) || rawValue.length !== 2) throw new Error("INVALID_ZONE_RANGE");
    const from = Number(rawValue[0]);
    const to = Number(rawValue[1]);
    if (!Number.isInteger(from) || !Number.isInteger(to) || from < 1 || to < from || to > teamCount) {
      throw new Error("ZONE_OUT_OF_RANGE");
    }
    if (zoneKey === "champion") continue;
    for (let place = from; place <= to; place += 1) {
      const existing = used.get(place);
      if (existing && existing !== zoneKey) throw new Error("ZONE_CONFLICT");
      used.set(place, zoneKey);
    }
  }
}

function normalizeSeasonPredictionTeamInput(raw: any, index: number) {
  const teamName = String(raw?.team_name || raw?.teamName || "").trim();
  if (!teamName) throw new Error("TEAM_NAME_REQUIRED");
  return {
    team_id: raw?.team_id === undefined || raw?.team_id === null || raw?.team_id === "" ? null : String(raw.team_id).trim(),
    team_name: teamName,
    short_name: raw?.short_name === undefined || raw?.short_name === null || raw?.short_name === "" ? null : String(raw.short_name).trim(),
    crest_url: raw?.crest_url === undefined || raw?.crest_url === null || raw?.crest_url === "" ? null : String(raw.crest_url).trim(),
    provider: raw?.provider === undefined || raw?.provider === null || raw?.provider === "" ? null : String(raw.provider).trim(),
    provider_team_id: raw?.provider_team_id === undefined || raw?.provider_team_id === null || raw?.provider_team_id === "" ? null : String(raw.provider_team_id).trim(),
    sort_order: index + 1,
    metadata_json: JSON.stringify(normalizeNullableJsonObject(raw?.metadata_json ?? raw?.metadata ?? {}, {}, "INVALID_TEAM_METADATA") || {}),
  };
}

function getSeasonPredictionTeamSortName(raw: any): string {
  return String(raw?.team_name || raw?.teamName || raw?.short_name || raw?.shortName || raw?.team_id || raw?.teamId || raw?.id || "");
}

function sortSeasonPredictionTeamInputsAlphabetically<T>(teams: T[]): T[] {
  return [...teams].sort((a: any, b: any) => {
    const byName = getSeasonPredictionTeamSortName(a).localeCompare(getSeasonPredictionTeamSortName(b), ["ru", "en"], { sensitivity: "base", numeric: true });
    if (byName !== 0) return byName;
    return String(a?.team_id || a?.teamId || a?.id || "").localeCompare(String(b?.team_id || b?.teamId || b?.id || ""));
  });
}

async function countSeasonPredictionEntries(env: Env, seasonId: number, code: string, statuses: string[]): Promise<number> {
  const placeholders = statuses.map(() => "?").join(",");
  const row = await env.DB.prepare(`
    SELECT COUNT(*) AS c
    FROM season_prediction_user_entries
    WHERE season_prediction_season_id = ? AND tournament_code = ? AND status IN (${placeholders})
  `).bind(seasonId, code, ...statuses).first() as any;
  return Number(row?.c || 0);
}

function resolveAllSportsTournamentId(
  tournament: SeasonPredictionTournamentRow,
  override: string | null,
): number | null {
  const tryParseId = (raw: unknown): number | null => {
    if (typeof raw === "number" && Number.isFinite(raw) && raw > 0) return Math.floor(raw);
    if (typeof raw === "string") {
      const trimmed = raw.trim().replace(/^as:/i, "");
      if (/^\d+$/.test(trimmed)) {
        const n = Number(trimmed);
        return Number.isFinite(n) && n > 0 ? n : null;
      }
    }
    return null;
  };
  const fromOverride = tryParseId(override);
  if (fromOverride) return fromOverride;
  const settings = parseJsonSafe(tournament.settings_json, {} as Record<string, unknown>);
  const fromSettings = tryParseId((settings as Record<string, unknown>).allsports_tournament_id);
  if (fromSettings) return fromSettings;
  const fromStatic = SEASON_PREDICTION_ALLSPORTS_TOURNAMENT_IDS[String(tournament.tournament_code)];
  return fromStatic || null;
}

function resolveFootballDataCompetitionCode(
  tournament: SeasonPredictionTournamentRow,
  override: string | null,
): string | null {
  const sanitize = (raw: unknown): string | null => {
    if (typeof raw !== "string") return null;
    const trimmed = raw.trim().toUpperCase().replace(/^FD:/, "");
    return /^[A-Z0-9_-]{2,10}$/.test(trimmed) ? trimmed : null;
  };
  const fromOverride = sanitize(override);
  if (fromOverride) return fromOverride;
  const settings = parseJsonSafe(tournament.settings_json, {} as Record<string, unknown>);
  const fromSettings = sanitize((settings as Record<string, unknown>).competition_code);
  if (fromSettings) return fromSettings;
  // Back-compat for top-5: tournament_code already equals the Football-Data
  // competition code (PL, PD, SA, BL1, FL1). European cups must come via
  // override or settings_json because their tournament_code (UCL/UEL/UECL)
  // does not match Football-Data's codes for all editions.
  if (tournament.tournament_type === "european") return null;
  return sanitize(tournament.tournament_code);
}

async function previewSeasonPredictionTeamsFromProvider(
  env: Env,
  tournament: SeasonPredictionTournamentRow,
  provider: "football-data" | "allsports",
  season: string | null,
  providerCompetitionId: string | null = null,
): Promise<{ teams: SeasonPredictionImportTeam[]; warnings: string[] }> {
  const warnings: string[] = [];
  const code = String(tournament.tournament_code);
  if (provider === "allsports") {
    const tournamentId = resolveAllSportsTournamentId(tournament, providerCompetitionId);
    if (!tournamentId) {
      return {
        teams: [],
        warnings: [
          `Для ${code} не задан AllSports unique tournament id. Укажите числовой ID в поле "Provider competition ID" или сохраните его в settings_json.allsports_tournament_id.`,
        ],
      };
    }
    const resolved = await resolveAllSportsSeasonId(env, code, season, warnings);
    if (!resolved.seasonId) {
      warnings.push("Сезон пока недоступен у AllSports. Попробуйте другой год или подождите открытия сезона у провайдера.");
      return { teams: [], warnings };
    }
    let standingsPayload: any;
    let standingsPath: string;
    try {
      const got = await fetchFirstAllSportsJson(env, [
        `/api/tournament/${tournamentId}/season/${resolved.seasonId}/standings`,
        `/api/tournament/${tournamentId}/season/${resolved.seasonId}/standings/total`,
        `/api/unique-tournament/${tournamentId}/season/${resolved.seasonId}/standings/total`,
        `/api/unique-tournament/${tournamentId}/season/${resolved.seasonId}/standings`,
      ]);
      standingsPayload = got.payload;
      standingsPath = got.path;
    } catch (e: any) {
      const message = String(e?.message || e);
      if (message.includes("ALLSPORTS_HTTP_404")) {
        warnings.push(`AllSports не вернул standings для unique_tournament_id=${tournamentId} в сезоне ${resolved.seasonLabel || resolved.seasonId}. Проверьте ID или сезон, либо используйте ручной ввод.`);
        return { teams: [], warnings };
      }
      throw e;
    }
    const standings = pickAllSportsArray(standingsPayload, ["standings", "data"]);
    const rows = standings.flatMap((standing: any) => Array.isArray(standing?.rows) ? standing.rows : []);
    const seen = new Set<string>();
    const teams = rows.map((row: any) => row?.team).filter(Boolean).filter((team: any) => {
      const id = String(team?.id || team?.name || "");
      if (!id || seen.has(id)) return false;
      seen.add(id);
      return true;
    });
    const normalized = teams.map((team: any) => ({
      team_name: String(team?.name || team?.shortName || team?.nameCode || "").trim(),
      short_name: team?.nameCode ? String(team.nameCode).trim() : (team?.shortName ? String(team.shortName).trim() : null),
      crest_url: team?.id ? toFrontApiPath(`/proxy/team/${team.id}/image`) : null,
      team_id: team?.id ? `as:${team.id}` : null,
      provider: "allsports",
      provider_team_id: team?.id ? String(team.id) : null,
      metadata_json: {
        source: "allsports",
        unique_tournament_id: tournamentId,
        season_id: resolved.seasonId,
        season_label: resolved.seasonLabel,
        standings_endpoint: standingsPath,
        country: team?.country?.name || null,
      },
    })).filter((team: SeasonPredictionImportTeam) => team.team_name);
    if (normalized.length !== Number(tournament.team_count)) {
      warnings.push(`AllSports вернул ${normalized.length} команд, ожидается ${tournament.team_count}. Сохранение без force будет запрещено.`);
    }
    return { teams: normalized, warnings };
  }
  if (!env.FOOTBALL_DATA_TOKEN) throw new Error("FOOTBALL_DATA_TOKEN_NOT_CONFIGURED");
  const competitionCode = resolveFootballDataCompetitionCode(tournament, providerCompetitionId);
  if (!competitionCode) {
    return {
      teams: [],
      warnings: [
        `Для ${code} не задан Football-Data competition code. Укажите его в поле "Provider competition ID" (например, CL/EL/UECL) или сохраните в settings_json.competition_code.`,
      ],
    };
  }
  const buildUrl = (seasonValue: string | null) => {
    const url = new URL(`https://api.football-data.org/v4/competitions/${encodeURIComponent(competitionCode)}/teams`);
    if (seasonValue) url.searchParams.set("season", seasonValue);
    return url.toString();
  };
  let usedSeason = season;
  let res = await fetch(buildUrl(usedSeason), {
    headers: { "X-Auth-Token": env.FOOTBALL_DATA_TOKEN },
  });
  if (res.status === 404 && usedSeason) {
    warnings.push(`Football-Data не нашел сезон ${usedSeason} для ${competitionCode}. Загружен preview без параметра season, проверьте актуальность состава перед сохранением.`);
    usedSeason = null;
    res = await fetch(buildUrl(null), {
      headers: { "X-Auth-Token": env.FOOTBALL_DATA_TOKEN },
    });
  }
  if (!res.ok) {
    if (res.status === 429) throw new Error("FOOTBALL_DATA_RATE_LIMITED");
    // Treat upstream "competition not available" responses as graceful warnings —
    // free tier or unsupported tournaments must not 500 the admin UI.
    if (res.status === 404) {
      warnings.push(`Football-Data не возвращает команды для ${competitionCode}. Турнир может быть недоступен на текущем тарифе или код не поддерживается провайдером.`);
      return { teams: [], warnings };
    }
    if (res.status === 403) {
      warnings.push(`Football-Data: доступ к ${competitionCode} запрещён (403). Возможно, тариф не покрывает этот турнир.`);
      return { teams: [], warnings };
    }
    const text = await res.text().catch(() => "");
    throw new Error(`FOOTBALL_DATA_TEAMS_HTTP_${res.status}:${text.slice(0, 120)}`);
  }
  const payload = await res.json<any>();
  const teams = Array.isArray(payload?.teams) ? payload.teams : [];
  const normalized = teams.map((team: any) => ({
    team_name: String(team?.name || team?.shortName || team?.tla || "").trim(),
    short_name: team?.tla ? String(team.tla).trim() : (team?.shortName ? String(team.shortName).trim() : null),
    crest_url: team?.crest ? String(team.crest).trim() : null,
    team_id: team?.id ? `fd:${team.id}` : null,
    provider: "football-data",
    provider_team_id: team?.id ? String(team.id) : null,
    metadata_json: {
      source: "football-data",
      competition_code: competitionCode,
      season: usedSeason,
      venue: team?.venue || null,
      founded: team?.founded || null,
    },
  })).filter((team: SeasonPredictionImportTeam) => team.team_name);
  if (normalized.length !== Number(tournament.team_count)) {
    warnings.push(`Football-Data вернул ${normalized.length} команд, ожидается ${tournament.team_count}. Сохранение без force будет запрещено.`);
  }
  return { teams: normalized, warnings };
}

async function previewSeasonPredictionAwardOptionsFromProvider(
  env: Env,
  tournament: SeasonPredictionTournamentRow,
  provider: "football-data" | "allsports",
  season: string | null,
  awardType: string,
  limit: number
): Promise<{ options: SeasonPredictionImportAwardOption[]; warnings: string[] }> {
  const warnings: string[] = [];
  const normalizedAwardType = normalizeSeasonPredictionAwardType(awardType);
  const statsAwardType = normalizeSeasonPredictionAwardTypeForClient(awardType);
  if (provider === "allsports") {
    const tournamentId = SEASON_PREDICTION_ALLSPORTS_TOURNAMENT_IDS[String(tournament.tournament_code)];
    if (!tournamentId) return { options: [], warnings: [`Для ${tournament.tournament_code} не задан AllSports unique tournament id.`] };
    const resolved = await resolveAllSportsSeasonId(env, String(tournament.tournament_code), season, warnings);
    if (!resolved.seasonId) return { options: [], warnings };
    const statKey = statsAwardType === "top_scorer" ? "goals" : statsAwardType === "top_assistant" ? "assists" : "cleanSheet";
    // cleanSheet is credited to every player who was on the pitch for a shutout, not
    // just the keeper — without the position filter the golden glove list came back
    // full of centre-backs. `saves` is requested alongside purely as a safety net in
    // case the provider ever ignores `filters` (outfielders always have 0 saves).
    const isGoalkeeperAward = statKey === "cleanSheet";
    const cappedLimit = Math.max(1, Math.min(100, limit || 30));
    const query = [
      `limit=${cappedLimit}`,
      `order=-${statKey}`,
      "accumulation=total",
      `fields=${isGoalkeeperAward ? `${statKey},saves` : statKey}`,
      ...(isGoalkeeperAward ? ["filters=position.in.G"] : []),
    ].join("&");
    warnings.push("AllSports import кандидатов наград использует экспериментальный season statistics endpoint. Проверьте preview перед сохранением.");
    try {
      const { payload, path } = await fetchFirstAllSportsJson(env, [
        `/api/tournament/${tournamentId}/season/${resolved.seasonId}/statistics?${query}`,
        `/api/unique-tournament/${tournamentId}/season/${resolved.seasonId}/statistics?${query}`,
      ]);
      const rawResults = pickAllSportsArray(payload, ["results", "statistics", "data"]);
      // Only drop outfielders when the provider actually answered with `saves` —
      // otherwise an unsupported field would wipe the whole list.
      const savesSupported = isGoalkeeperAward && rawResults.some((item: any) => Number(item?.saves) > 0);
      const results = savesSupported
        ? rawResults.filter((item: any) => Number(item?.saves) > 0)
        : rawResults;
      const options = results.map((item: any) => {
        const player = item?.player || item;
        const team = item?.team || player?.team || {};
        return {
          award_type: normalizedAwardType,
          player_name: String(player?.name || player?.shortName || "").trim(),
          team_name: team?.name ? String(team.name).trim() : null,
          player_id: player?.id ? `as:${player.id}` : null,
          team_id: team?.id ? `as:${team.id}` : null,
          metadata_json: {
            source: "allsports",
            unique_tournament_id: tournamentId,
            season_id: resolved.seasonId,
            season_label: resolved.seasonLabel,
            statistics_endpoint: path,
            stat_key: statKey,
            value: item?.[statKey] ?? item?.statistics?.[statKey] ?? null,
          },
        };
      })
        .filter((option: SeasonPredictionImportAwardOption) => option.player_name)
        // Sort locally too: a silently ignored `order` param would otherwise look
        // like a legitimate, correctly ranked list.
        .sort((a: any, b: any) => Number(b.metadata_json?.value ?? 0) - Number(a.metadata_json?.value ?? 0))
        .slice(0, cappedLimit);
      if (!options.length) {
        warnings.push(`AllSports не вернул кандидатов по выбранной награде (сезон ${resolved.seasonLabel || resolved.seasonId}). Если сезон ещё не начался, статистики нет — укажите предыдущий сезон.`);
      }
      return { options, warnings };
    } catch (e: any) {
      return {
        options: [],
        warnings: [`AllSports не отдал статистику для ${normalizedAwardType}: ${e?.message || String(e)}. Используйте ручной ввод или Football-Data для бомбардиров.`],
      };
    }
  }
  if (normalizedAwardType !== "top_scorer") {
    return {
      options: [],
      warnings: ["Football-Data в текущей интеграции надежно поддерживает импорт бомбардиров. Ассисты и золотая перчатка требуют ручной настройки или отдельного источника."],
    };
  }
  if (!env.FOOTBALL_DATA_TOKEN) throw new Error("FOOTBALL_DATA_TOKEN_NOT_CONFIGURED");
  const code = String(tournament.tournament_code);
  const buildUrl = (seasonValue: string | null) => {
    const url = new URL(`https://api.football-data.org/v4/competitions/${encodeURIComponent(code)}/scorers`);
    if (seasonValue) url.searchParams.set("season", seasonValue);
    url.searchParams.set("limit", String(Math.max(1, Math.min(100, limit || 30))));
    return url.toString();
  };
  let usedSeason = season;
  let res = await fetch(buildUrl(usedSeason), {
    headers: { "X-Auth-Token": env.FOOTBALL_DATA_TOKEN },
  });
  if (res.status === 404 && usedSeason) {
    warnings.push(`Football-Data не нашел сезон ${usedSeason}. Загружен preview бомбардиров без параметра season, проверьте актуальность перед сохранением.`);
    usedSeason = null;
    res = await fetch(buildUrl(null), {
      headers: { "X-Auth-Token": env.FOOTBALL_DATA_TOKEN },
    });
  }
  if (!res.ok) {
    const text = await res.text().catch(() => "");
    if (res.status === 429) throw new Error("FOOTBALL_DATA_RATE_LIMITED");
    throw new Error(`FOOTBALL_DATA_SCORERS_HTTP_${res.status}:${text.slice(0, 120)}`);
  }
  const payload = await res.json<any>();
  const scorers = Array.isArray(payload?.scorers) ? payload.scorers : [];
  const options = scorers.map((item: any) => ({
    award_type: "top_scorer",
    player_name: String(item?.player?.name || "").trim(),
    team_name: item?.team?.name ? String(item.team.name).trim() : null,
    player_id: item?.player?.id ? `fd:${item.player.id}` : null,
    team_id: item?.team?.id ? `fd:${item.team.id}` : null,
    metadata_json: {
      source: "football-data",
      competition_code: code,
      season: usedSeason,
      goals: item?.goals ?? null,
      assists: item?.assists ?? null,
      penalties: item?.penalties ?? null,
    },
  })).filter((option: SeasonPredictionImportAwardOption) => option.player_name);
  if (!options.length) warnings.push("Football-Data не вернул кандидатов. Проверьте сезон или доступность данных.");
  return { options, warnings };
}

function normalizeSeasonPredictionAwardInput(raw: any, index: number) {
  const awardType = normalizeSeasonPredictionAwardType(raw?.award_type || raw?.awardType || "");
  const playerName = String(raw?.player_name || raw?.playerName || "").trim();
  if (!playerName) throw new Error("PLAYER_NAME_REQUIRED");
  return {
    award_type: awardType,
    player_id: raw?.player_id === undefined || raw?.player_id === null || raw?.player_id === "" ? null : String(raw.player_id).trim(),
    player_name: playerName,
    team_id: raw?.team_id === undefined || raw?.team_id === null || raw?.team_id === "" ? null : String(raw.team_id).trim(),
    team_name: raw?.team_name === undefined || raw?.team_name === null || raw?.team_name === "" ? null : String(raw.team_name).trim(),
    sort_order: Number.isInteger(Number(raw?.sort_order)) && Number(raw.sort_order) > 0 ? Number(raw.sort_order) : index + 1,
    metadata_json: JSON.stringify(normalizeNullableJsonObject(raw?.metadata_json ?? raw?.metadata ?? {}, {}, "INVALID_AWARD_METADATA") || {}),
  };
}

// Whitelist the ONLY award fields the scorer (computeAwardsCorrect / buildAwardsBreakdown)
// and the read-time backfill ever read. Everything else in the incoming pick is dropped, so
// a hand-crafted request cannot smuggle arbitrary/oversized keys into the stored awards_json.
function pickSeasonPredictionAwardFields(value: any, awardType: string): Record<string, any> | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const out: Record<string, any> = { award_type: awardType };
  const playerId = value.player_id;
  if (playerId !== undefined && playerId !== null && playerId !== "") out.player_id = String(playerId).slice(0, 128);
  const awardOptionId = value.award_option_id;
  if (awardOptionId !== undefined && awardOptionId !== null && awardOptionId !== "") {
    const n = Number(awardOptionId);
    if (Number.isFinite(n)) out.award_option_id = n;
  }
  if (value.player_name != null) out.player_name = String(value.player_name).slice(0, 200);
  if (value.team_name != null) out.team_name = String(value.team_name).slice(0, 200);
  return out;
}

const SEASON_PREDICTION_AWARD_KEYS = ["top_scorer", "top_assister", "golden_glove"] as const;

function normalizeSeasonPredictionAwardsJsonInput(value: any) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return value ?? null;
  const out: Record<string, any> = {};
  for (const key of SEASON_PREDICTION_AWARD_KEYS) {
    // Canonical key is `top_assister`; tolerate the legacy `top_assistant` alias on input.
    const raw = key === "top_assister" ? (value.top_assister ?? value.top_assistant) : value[key];
    const norm = pickSeasonPredictionAwardFields(raw, key);
    if (norm) out[key] = norm;
  }
  return out;
}

async function validateSeasonPredictionAwardsJson(env: Env, tournament: SeasonPredictionTournamentRow, awardsJson: any): Promise<void> {
  if (!awardsJson || typeof awardsJson !== "object" || Array.isArray(awardsJson)) return;
  const playersCount = await countSeasonPredictionResetRows(env, `
    SELECT COUNT(*) AS count FROM season_prediction_tournament_players
    WHERE season_prediction_tournament_id = ? AND is_active = 1
  `, Number(tournament.id)).catch((e) => {
    if (isSeasonPredictionPlayersTableMissing(e)) return 0;
    throw e;
  });
  for (const key of ["top_scorer", "top_assister", "golden_glove"]) {
    const pick = awardsJson[key] ?? (key === "top_assister" ? awardsJson.top_assistant : undefined);
    if (!pick || typeof pick !== "object" || Array.isArray(pick)) continue;
    const awardType = normalizeSeasonPredictionAwardType(key);
    const playerId = pick.player_id === undefined || pick.player_id === null || pick.player_id === "" ? null : String(pick.player_id);
    const awardOptionId = pick.award_option_id === undefined || pick.award_option_id === null || pick.award_option_id === "" ? null : Number(pick.award_option_id);
    if (playersCount > 0 && playerId) {
      const row = await env.DB.prepare(`
        SELECT * FROM season_prediction_tournament_players
        WHERE season_prediction_tournament_id = ?
          AND is_active = 1
          AND (player_id = ? OR provider_player_id = ?)
        LIMIT 1
      `).bind(Number(tournament.id), playerId, playerId).first() as any;
      if (!row) throw new Error("PLAYER_NOT_FOUND");
      if (!isEligibleForAward(awardType, row)) throw new Error("PLAYER_NOT_ELIGIBLE_FOR_AWARD");
      continue;
    }
    if (awardOptionId && Number.isFinite(awardOptionId)) {
      const row = await env.DB.prepare(`
        SELECT * FROM season_prediction_award_options
        WHERE season_prediction_tournament_id = ? AND id = ?
        LIMIT 1
      `).bind(Number(tournament.id), awardOptionId).first() as any;
      if (!row) throw new Error("AWARD_OPTION_NOT_FOUND");
      if (normalizeSeasonPredictionAwardType(row.award_type) !== awardType) throw new Error("AWARD_OPTION_TYPE_MISMATCH");
    }
  }
}

// ─── Auto-submit of season-prediction drafts after the deadline ──────────────
// A draft never scores — every recalc selects `status IN ('submitted','locked',…)` — so a
// user who filled the table but never pressed "Подтвердить" used to lose the whole season.
// This sweep promotes the LAST SAVED draft to 'submitted' once the deadline has passed,
// and ONLY when that draft passes exactly the same validation the manual submit route runs.
// An incomplete draft is deliberately left as a draft: a partial eurocup table would throw
// inside the scorer and land as a `failed` entry, and completing it for the user would mean
// inventing a prediction they never made.
//
// Idempotent by construction: every UPDATE is guarded by the current draft status, so a
// repeated tick (or an overlapping one) is a no-op. Writing after the deadline is safe here
// because the user can no longer change anything — the draft is already frozen.
type SeasonPredictionAutoSubmitStats = {
  tournaments: number;
  tables: number;
  awards: number;
  brackets: number;
  skipped_invalid: number;
};

// Past these tournament/season statuses the sweep stays out: results are being scored or
// the tournament is closed, so flipping a stale draft in could disturb a finished payout.
const SEASON_PREDICTION_AUTOSUBMIT_BLOCKING_STATUSES = new Set(["scoring", "completed", "archived"]);

// Exported for unit tests: the deadline boundary decides whether a season is saved or lost.
export function seasonPredictionAutoSubmitWindowOpen(deadline: number, now: number, graceSeconds: number): boolean {
  return deadline > 0 && now >= deadline && now - deadline <= graceSeconds;
}

async function runSeasonPredictionAutoSubmit(
  env: Env,
  opts: { trigger: string; now?: number; maxEntries?: number; graceHours?: number },
): Promise<SeasonPredictionAutoSubmitStats> {
  const stats: SeasonPredictionAutoSubmitStats = { tournaments: 0, tables: 0, awards: 0, brackets: 0, skipped_invalid: 0 };
  const now = Number(opts.now || nowUnixSeconds());
  const graceSeconds = Math.max(1, Number(opts.graceHours || 168)) * 3600;
  const maxEntries = Math.max(1, Number(opts.maxEntries || 300));
  let budget = maxEntries;

  const season = await getSeasonPredictionSeason(env);
  if (SEASON_PREDICTION_AUTOSUBMIT_BLOCKING_STATUSES.has(String(season.status))) return stats;
  const tournaments = await listAllSeasonPredictionTournaments(env, Number(season.id));

  for (const tournament of tournaments) {
    if (budget <= 0) break;
    if (SEASON_PREDICTION_AUTOSUBMIT_BLOCKING_STATUSES.has(String(tournament.status))) continue;
    if (String(tournament.status) === "soon" || String(tournament.status) === "draft") continue;

    const code = String(tournament.tournament_code);
    const isEuropean = String(tournament.tournament_type) === "european";
    const tableDeadline = Number(tournament.deadline_at || season.deadline_at || 0);
    const awardsDeadline = Number(tournament.awards_deadline_at || tournament.deadline_at || season.deadline_at || 0);
    const tableDue = seasonPredictionAutoSubmitWindowOpen(tableDeadline, now, graceSeconds);
    // Awards live on the top-league screen only, and behind their own window.
    const awardsDue = !isEuropean && seasonPredictionAutoSubmitWindowOpen(awardsDeadline, now, graceSeconds);
    if (!tableDue && !awardsDue) continue;
    stats.tournaments += 1;

    const teams = await listSeasonPredictionTeams(env, Number(tournament.id));

    // ── 1. Table drafts ──────────────────────────────────────────────────────
    if (tableDue && budget > 0) {
      const res = await env.DB.prepare(`
        SELECT id, table_json FROM season_prediction_user_entries
        WHERE season_prediction_season_id = ? AND tournament_code = ? AND status = 'draft'
        ORDER BY id ASC LIMIT ?
      `).bind(Number(season.id), code, budget).all();
      const rows = (res.results || []) as any[];
      budget -= rows.length;
      const stmts: D1PreparedStatement[] = [];
      for (const row of rows) {
        try {
          const stored = parseJsonSafe(row.table_json, null);
          if (isEuropean) {
            validateEuropeanLeagueStageSubmit(sanitizeEuropeanLeagueStageDraft(stored, teams), teams);
          } else {
            validateSeasonPredictionSubmit(stored, teams);
          }
        } catch {
          stats.skipped_invalid += 1;
          continue;
        }
        stmts.push(env.DB.prepare(`
          UPDATE season_prediction_user_entries
          SET status = 'submitted',
              submitted_at = COALESCE(submitted_at, ?),
              last_submitted_at = ?,
              updated_at = ?
          WHERE id = ? AND status = 'draft'
        `).bind(now, now, now, Number(row.id)));
      }
      if (stmts.length) {
        await env.DB.batch(stmts);
        stats.tables += stmts.length;
      }
    }

    // ── 2. Awards drafts (own window, own status) ────────────────────────────
    if (awardsDue && budget > 0) {
      const res = await env.DB.prepare(`
        SELECT id, awards_json FROM season_prediction_user_entries
        WHERE season_prediction_season_id = ? AND tournament_code = ?
          AND COALESCE(NULLIF(TRIM(awards_status), ''), 'draft') = 'draft'
          AND awards_json IS NOT NULL
        ORDER BY id ASC LIMIT ?
      `).bind(Number(season.id), code, budget).all();
      const rows = (res.results || []) as any[];
      budget -= rows.length;
      const stmts: D1PreparedStatement[] = [];
      for (const row of rows) {
        try {
          const awardsJson = normalizeSeasonPredictionAwardsJsonInput(parseJsonSafe(row.awards_json, null));
          // Same bar as the manual route: at least one pick, and every pick still valid.
          if (countSeasonPredictionAwards(awardsJson) === 0) { stats.skipped_invalid += 1; continue; }
          await validateSeasonPredictionAwardsJson(env, tournament, awardsJson);
          stmts.push(env.DB.prepare(`
            UPDATE season_prediction_user_entries
            SET awards_status = 'submitted',
                awards_submitted_at = COALESCE(awards_submitted_at, ?),
                awards_last_submitted_at = ?,
                updated_at = ?
            WHERE id = ? AND COALESCE(NULLIF(TRIM(awards_status), ''), 'draft') = 'draft'
          `).bind(now, now, now, Number(row.id)));
        } catch {
          stats.skipped_invalid += 1;
        }
      }
      if (stmts.length) {
        await env.DB.batch(stmts);
        stats.awards += stmts.length;
      }
    }

    // ── 3. Eurocup knockout brackets ─────────────────────────────────────────
    // Same deadline as the league stage, but an extra gate: once official results are
    // confirmed the bracket is frozen and must never be flipped in retroactively.
    if (isEuropean && tableDue && budget > 0) {
      const matchRows = await listEurocupKnockoutMatches(env, Number(tournament.id));
      const adminKnown = eurocupKnownKnockoutMatches(matchRows);
      if (adminKnown.length > 0 && !eurocupBracketResultsConfirmed(matchRows)) {
        const allTeamIds = new Set<string>(teams.map((t: any) => String(t.team_id || t.id)));
        const sources = eurocupKnockoutBracketSources(code);
        const r16Known = adminKnown.filter((m) => m.stage === "round_of_16");
        const playoffKnown = adminKnown.filter((m) => m.stage === "knockout_playoffs");
        const res = await env.DB.prepare(`
          SELECT id, picks_json FROM season_prediction_eurocup_knockout_brackets
          WHERE tournament_id = ? AND status = 'draft'
          ORDER BY id ASC LIMIT ?
        `).bind(Number(tournament.id), budget).all();
        const rows = (res.results || []) as any[];
        budget -= rows.length;
        const stmts: D1PreparedStatement[] = [];
        for (const row of rows) {
          try {
            const picks = parseJsonSafe(row.picks_json, {});
            const known = [...playoffKnown, ...deriveUserBracketMatches(r16Known, picks, sources)];
            const validated = validateUserKnockoutPicks(picks, known, allTeamIds, true);
            const picksJson = JSON.stringify({ ...validated.picks, champion_team_id: validated.champion_team_id });
            stmts.push(env.DB.prepare(`
              UPDATE season_prediction_eurocup_knockout_brackets
              SET status = 'submitted',
                  picks_json = ?,
                  submitted_at = COALESCE(submitted_at, ?),
                  last_submitted_at = ?,
                  updated_at = ?
              WHERE id = ? AND status = 'draft'
            `).bind(picksJson, now, now, now, Number(row.id)));
          } catch {
            stats.skipped_invalid += 1;
          }
        }
        if (stmts.length) {
          await env.DB.batch(stmts);
          stats.brackets += stmts.length;
        }
      }
    }
  }

  logEvent({
    operation: "season_prediction_autosubmit",
    trigger: opts.trigger,
    run_id: makeRunId(),
    status: "ok",
    tournaments: stats.tournaments,
    tables: stats.tables,
    awards: stats.awards,
    brackets: stats.brackets,
    skipped_invalid: stats.skipped_invalid,
  });
  return stats;
}

async function buildAdminSeasonPredictionsConfig(env: Env) {
  const season = await getSeasonPredictionSeason(env);
  const tournaments = await listAllSeasonPredictionTournaments(env, season.id);
  const hydrated = [];
  for (const tournament of tournaments) {
    hydrated.push({
      ...serializeSeasonPredictionTournament(tournament),
      teams: await listSeasonPredictionTeams(env, tournament.id),
      award_options: await listSeasonPredictionAwardOptions(env, tournament.id),
    });
  }
  return {
    season: serializeSeasonPredictionSeason(season),
    tournaments: hydrated,
  };
}


// Shared atomic reward-delivery primitive: delivery is a single ATOMIC db.batch
// (credit + resource ledger + reward_ledger) via the shared rewardComponentStatements builder.
// The reward_ledger row is granted IFF the credit applied in the same transaction; replays are
// no-ops via the NOT EXISTS guard + UNIQUE(unique_key). Returns true only when THIS call newly
// granted the component (preserves the prior "newly granted" semantics used by admin/finalize
// counters). Used by manual admin grants, weekly-challenge tasks and season-prediction tasks.
// Exported for integration tests. (The reward_ledger CHECK constraint still permits the legacy
// bracket_quest / bracket_final_reward source_types for historical rows; they are no longer
// produced by active runtime after the World Cup bracket removal.)
export async function grantReward(
  env: Env,
  userId: number,
  sourceType: "manual_admin" | "weekly_challenge_task" | "season_prediction_task",
  sourceId: string,
  uniqueKey: string,
  rewardType: "stars" | "balls" | "case" | "lucky_token",
  amount: number,
  caseType?: string,
  grantedBy?: number | null,
  metadata?: any
) {
  if (amount <= 0) return false;
  if (rewardType === "case" && !caseType) return false;
  const creditSeason = await getCurrentSeasonNumber(env);
  const stmts = rewardComponentStatements(env, {
    userId, sourceType, sourceId, uniqueKey, rewardType, amount,
    caseType: caseType ?? null, grantedBy: grantedBy ?? null,
    metaJson: JSON.stringify(metadata || {}),
    creditSeason, nowMs: Date.now(), nowSec: nowUnixSeconds(),
  });
  if (stmts.length === 0) return false;
  const res = await env.DB.batch(stmts);
  // The reward_ledger INSERT is the last statement; changes>0 ⇒ this call newly delivered it.
  const newlyGranted = (res[res.length - 1]?.meta?.changes ?? 0) > 0;
  return newlyGranted;
}

// Stage 5 + 5.1: fully idempotent shop purchase (extracted from POST /shop/buy so it is
// unit-testable with the REAL code, like grantSeasonTaskReward). Charges balls and grants the item
// EXACTLY ONCE per operationId.
//
// Stage 5.1 — SINGLE ATOMIC BATCH (no orphan claim): the operation row (purchase_history with
// UNIQUE operation_id) is written INSIDE the same db.batch as the charge, grant and deduct. So a
// committed purchase_history row ALWAYS means a fully delivered purchase — there is no separate
// pre-claim that can survive without the economics.
//   * truthful: op row ⇔ (ball charge + item grant + deduct), all in one transaction;
//   * concurrency/replay: the second request's purchase_history INSERT hits UNIQUE(operation_id),
//     which rolls the WHOLE batch back (no double charge/grant), and we replay the stored result;
//   * concurrent drain: every economic statement is gated on the PRE-deduct `balls >= cost`
//     (deduct is last), so a balance drained below cost makes ALL of them no-op together —
//     never an item without a charge nor a charge without an item;
//   * request snapshot: a replay with a DIFFERENT user_id or item_type for the same operation_id
//     is a conflict (409 SHOP_OPERATION_CONFLICT), never a second purchase.
// Prices/items are read from shop_boosts — nothing here changes any economic value.
export type ShopPurchaseResult =
  | { ok: true; duplicate?: boolean; balance: number; extraLeagueSlots: number }
  | { ok: false; error: string; balance?: number };

const SHOP_OP_CONFLICT = "SHOP_OPERATION_CONFLICT";

// Client-supplied idempotency keys (operationId / openId / spinId / idempotency_key) end up in
// UNIQUE-indexed columns (purchase_history, case_opens, fortune_spin_opens, star_exchange_ledger,
// ball_transactions.open_id). Cap the format so an arbitrary client payload can't bloat those
// indexes. The frontend sends crypto.randomUUID(); tests use short slugs — both fit.
export function isValidClientOpKey(key: string): boolean {
  return key.length > 0 && key.length <= 64 && /^[A-Za-z0-9:._-]+$/.test(key);
}

// economy-v1.md §0.1: макс накопленных ваучеров доп. лиги (extra_league_slots).
// При переполнении случайный дроп слота конвертируется в 3⚽ (§9/§12/§13),
// а покупка слота за мячи блокируется.
const MAX_EXTRA_LEAGUE_SLOTS = 5;
const EXTRA_LEAGUE_OVERFLOW_BALLS = 3;

// If a rolled reward is an extra-league slot but the user is already at the slot
// cap, convert it to 3⚽ (economy-v1.md §9/§12/§13). Applied before the receipt is
// written so case_opens / fortune_spin_opens record the actual reward granted.
async function resolveExtraLeagueOverflow(env: Env, userId: number, reward: CaseReward): Promise<CaseReward> {
  if (canonicalRewardType(reward.type) !== "extra_league") return reward;
  const r = await env.DB.prepare(`SELECT extra_league_slots FROM users WHERE id = ?`).bind(userId).first() as any;
  if (Number(r?.extra_league_slots ?? 0) < MAX_EXTRA_LEAGUE_SLOTS) return reward;
  return { type: "balls", amount: EXTRA_LEAGUE_OVERFLOW_BALLS * Math.max(1, Number(reward.amount) || 1), code: null };
}

export async function executeShopPurchase(
  env: Env, userId: number, itemType: string, operationId: string,
): Promise<ShopPurchaseResult> {
  if (!operationId) return { ok: false, error: "OPERATION_ID_REQUIRED" };
  if (!isValidClientOpKey(operationId)) return { ok: false, error: "INVALID_OPERATION_ID" };
  const opKey = `shop:${operationId}`;
  const readState = async () => {
    const r = await env.DB.prepare(`SELECT balls, extra_league_slots FROM users WHERE id = ?`).bind(userId).first() as any;
    return { balance: Number(r?.balls ?? 0), extraLeagueSlots: Number(r?.extra_league_slots ?? 0) };
  };
  // A committed op row == a completed purchase. Same request ⇒ replay; different user/item ⇒ conflict.
  const replayOrConflict = (row: any): ShopPurchaseResult | null => {
    if (!row) return null;
    if (Number(row.user_id) !== userId || String(row.item_type) !== itemType) return { ok: false, error: SHOP_OP_CONFLICT };
    return null; // caller appends current state for the duplicate-success reply
  };

  // Replay / conflict against the committed operation.
  const existingOp = await env.DB.prepare(`SELECT user_id, item_type FROM purchase_history WHERE operation_id = ?`).bind(opKey).first() as any;
  if (existingOp) {
    const conflict = replayOrConflict(existingOp);
    if (conflict) return conflict;
    return { ok: true, duplicate: true, ...(await readState()) };
  }

  const item = await env.DB.prepare(`SELECT * FROM shop_boosts WHERE code = ? AND is_active = 1`).bind(itemType).first() as any;
  if (!item) return { ok: false, error: "Unknown or inactive item" };
  const cost = Number(item.price_balls);
  const now = Date.now();

  // economy-v1.md §0.1: нельзя покупать слот доп. лиги сверх потолка накопления.
  if (itemType === "extra_league") {
    const slots = (await readState()).extraLeagueSlots;
    if (slots >= MAX_EXTRA_LEAGUE_SLOTS) return { ok: false, error: "MAX_LEAGUE_SLOTS", balance: (await readState()).balance };
  }

  const pre = await env.DB.prepare(`SELECT balls FROM users WHERE id = ?`).bind(userId).first() as any;
  const preBalance = Number(pre?.balls ?? 0);
  if (preBalance < cost) return { ok: false, error: "Insufficient balls", balance: preBalance };

  // One atomic batch (a single D1 transaction, so no other request interleaves mid-batch). The
  // purchase_history INSERT (UNIQUE operation_id) is the anchor and carries the FULL gate — the
  // pre-deduct balance and, for extra_league, the slot cap. Every other statement is gated on the
  // anchor row existing, so they all commit or all no-op together, and no gate is re-evaluated
  // against state the batch itself already mutated. A concurrent/replayed duplicate makes the
  // anchor violate UNIQUE, which throws and rolls back the entire batch.
  let gate = `(SELECT balls FROM users WHERE id = ?) >= ?`;
  const gateBinds: unknown[] = [userId, cost];
  if (itemType === "extra_league") {
    // The slot cap is part of the atomic gate — concurrent purchases can't overshoot it.
    gate += ` AND (SELECT extra_league_slots FROM users WHERE id = ?) < ?`;
    gateBinds.push(userId, MAX_EXTRA_LEAGUE_SLOTS);
  }
  const anchored = `EXISTS (SELECT 1 FROM purchase_history WHERE operation_id = ?)`;
  const grantStmt = itemType === 'extra_league'
    ? env.DB.prepare(`UPDATE users SET extra_league_slots = extra_league_slots + 1 WHERE id = ? AND ${anchored}`).bind(userId, opKey)
    : env.DB.prepare(`INSERT INTO user_boosts (user_id, boost_type, status, purchased_at) SELECT ?, ?, 'available', ? WHERE ${anchored}`).bind(userId, itemType, now, opKey);
  try {
    const batchRes = await env.DB.batch([
      env.DB.prepare(`INSERT INTO purchase_history (user_id, item_type, balls_cost, created_at, operation_id)
                      SELECT ?, ?, ?, ?, ? WHERE ${gate}`).bind(userId, itemType, cost, now, opKey, ...gateBinds),
      env.DB.prepare(`INSERT INTO ball_transactions (user_id, amount, balance_before, balance_after, operation_type, comment, open_id, created_at)
                      SELECT ?, ?, ?, ?, 'purchase', ?, ?, ? WHERE ${anchored}`)
        .bind(userId, -cost, preBalance, preBalance - cost, `Куплен предмет: ${item.title}`, opKey, now, opKey),
      grantStmt,
      env.DB.prepare(`UPDATE users SET balls = balls - ? WHERE id = ? AND ${anchored}`).bind(cost, userId, opKey),
    ]);
    const claimed = (batchRes[0]?.meta?.changes ?? 0) > 0;
    if (!claimed) {
      // The gate closed between the pre-read and the batch (balance drained or, for
      // extra_league, the slot cap was reached concurrently) → nothing was inserted, charged,
      // granted or deducted. No op row left behind.
      const state = await readState();
      if (itemType === "extra_league" && state.extraLeagueSlots >= MAX_EXTRA_LEAGUE_SLOTS) {
        return { ok: false, error: "MAX_LEAGUE_SLOTS", balance: state.balance };
      }
      return { ok: false, error: "Insufficient balls (race)", balance: state.balance };
    }
    return { ok: true, ...(await readState()) };
  } catch (e: any) {
    // A concurrent request committed the same operation_id first → UNIQUE rolled this batch back.
    if (String(e?.message || e).includes("UNIQUE constraint failed: purchase_history.operation_id")) {
      const dup = await env.DB.prepare(`SELECT user_id, item_type FROM purchase_history WHERE operation_id = ?`).bind(opKey).first() as any;
      const conflict = replayOrConflict(dup);
      if (conflict) return conflict;
      return { ok: true, duplicate: true, ...(await readState()) };
    }
    throw e;
  }
}

// ── Stage 5.2: atomic, idempotent case open ──────────────────────────────────────────────────
export type CaseReward = { type: string; amount: number; code?: string | null };
export type CaseOpenResult =
  | { ok: true; duplicate?: boolean; reward: CaseReward; state: Awaited<ReturnType<typeof getCaseUserState>> }
  | { ok: false; error: string };

// Build the reward-credit statements for ONE case reward, each gated on `condSql` (the resource
// availability of the open — inventory quantity / daily-case / balance). The statements run inside
// the SAME atomic batch as the case_opens receipt + the consume, so they are rolled back together
// on any failure or on a duplicate open_id (UNIQUE). condBinds are appended to every statement.
function caseRewardStmts(
  env: Env,
  p: { userId: number; openId: string; reward: CaseReward; creditSeason: number; now: number },
  condSql: string,
  condBinds: unknown[],
): D1PreparedStatement[] {
  const { userId, openId, reward, creditSeason, now } = p;
  const type = canonicalRewardType(reward.type);
  const amount = Number(reward.amount) || 0;
  if (type === "lucky_token") {
    const amt = Math.max(1, amount);
    const ref = `${openId}:lucky_token`;
    return [
      env.DB.prepare(`INSERT OR IGNORE INTO lucky_token_transactions (user_id, amount, balance_before, balance_after, operation_type, comment, admin_user_id, ref_id, created_at)
          SELECT ?, ?, COALESCE((SELECT quantity FROM fortune_spins WHERE user_id = ?), 0), COALESCE((SELECT quantity FROM fortune_spins WHERE user_id = ?), 0) + ?, ?, ?, NULL, ?, ?
          WHERE ${condSql}`).bind(userId, amt, userId, userId, amt, LUCKY_TOKEN_OPS.caseDrop, "Кейс", ref, now, ...condBinds),
      env.DB.prepare(`INSERT OR IGNORE INTO fortune_spins (user_id, quantity) VALUES (?, 0)`).bind(userId),
      env.DB.prepare(`UPDATE fortune_spins SET quantity = quantity + ? WHERE user_id = ? AND ${condSql}`).bind(amt, userId, ...condBinds),
    ];
  }
  if (type === "stars") {
    return [
      env.DB.prepare(`INSERT INTO user_season_progress (user_id, season_number, stars) VALUES (?, ?, 0) ON CONFLICT(user_id, season_number) DO NOTHING`).bind(userId, creditSeason),
      env.DB.prepare(`UPDATE user_season_progress SET stars = stars + ? WHERE user_id = ? AND season_number = ? AND ${condSql}`).bind(amount, userId, creditSeason, ...condBinds),
      env.DB.prepare(`INSERT OR IGNORE INTO stars_ledger (user_id, season_id, source, task_key, instance_key, stars, created_at) SELECT ?, ?, ?, ?, ?, ?, ? WHERE ${condSql}`).bind(userId, creditSeason, "case_reward", "case_open", openId, amount, now, ...condBinds),
    ];
  }
  if (type === "balls") {
    return [env.DB.prepare(`UPDATE users SET balls = balls + ? WHERE id = ? AND ${condSql}`).bind(amount, userId, ...condBinds)];
  }
  if (type === "extra_joker" || type === "double_chance") {
    // amount>1 (e.g. Premium «Extra Joker ×2», economy-v1.md §12) grants N boosts;
    // amount<=1 is the historical single-boost behavior (one INSERT).
    const n = Math.max(1, amount);
    const stmts: D1PreparedStatement[] = [];
    for (let i = 0; i < n; i++) {
      stmts.push(env.DB.prepare(`INSERT INTO user_boosts (user_id, boost_type, status, purchased_at) SELECT ?, ?, 'available', ? WHERE ${condSql}`).bind(userId, type, now, ...condBinds));
    }
    return stmts;
  }
  if (type === "extra_joker_double_chance") {
    // economy-v1.md §12 combo reward: one Extra Joker + one Double Chance.
    return [
      env.DB.prepare(`INSERT INTO user_boosts (user_id, boost_type, status, purchased_at) SELECT ?, 'extra_joker', 'available', ? WHERE ${condSql}`).bind(userId, now, ...condBinds),
      env.DB.prepare(`INSERT INTO user_boosts (user_id, boost_type, status, purchased_at) SELECT ?, 'double_chance', 'available', ? WHERE ${condSql}`).bind(userId, now, ...condBinds),
    ];
  }
  if (type === "extra_league") {
    return [env.DB.prepare(`UPDATE users SET extra_league_slots = extra_league_slots + ? WHERE id = ? AND ${condSql}`).bind(Math.max(1, amount), userId, ...condBinds)];
  }
  if (type === "case") {
    const nested = String(reward.code || "daily_free");
    return [
      env.DB.prepare(`INSERT OR IGNORE INTO user_cases (user_id, case_type, quantity) VALUES (?, ?, 0)`).bind(userId, nested),
      env.DB.prepare(`UPDATE user_cases SET quantity = quantity + ? WHERE user_id = ? AND case_type = ? AND ${condSql}`).bind(Math.max(1, amount), userId, nested, ...condBinds),
    ];
  }
  return [];
}

// One atomic open attempt for a given resource mode. Returns true iff the case_opens receipt was
// inserted (i.e. the open happened). The receipt INSERT is the FIRST statement and the anchor:
// a concurrent duplicate open_id makes it violate UNIQUE → the whole batch rolls back (caller
// replays); a closed resource gate makes it (and everything else) a no-op together.
async function runCaseOpenAttempt(
  env: Env,
  p: { userId: number; caseType: string; openId: string; reward: CaseReward; creditSeason: number; now: number; ballsSpent: number },
  consume: { condSql: string; condBinds: unknown[]; pre: D1PreparedStatement[]; post: D1PreparedStatement[] },
): Promise<boolean> {
  const { userId, caseType, openId, reward, creditSeason, now, ballsSpent } = p;
  const stmts: D1PreparedStatement[] = [
    // Anchor + receipt (UNIQUE open_id), gated on the resource being available.
    env.DB.prepare(`INSERT INTO case_opens (open_id, user_id, case_type, reward_type, reward_amount, reward_code, balls_spent, created_at)
        SELECT ?, ?, ?, ?, ?, ?, ?, ? WHERE ${consume.condSql}`)
      .bind(openId, userId, caseType, canonicalRewardType(reward.type), Number(reward.amount) || 0, reward.code ?? null, ballsSpent, now, ...consume.condBinds),
    ...consume.pre, // paid: ball_transactions + purchase_history (gated)
    ...caseRewardStmts(env, { userId, openId, reward, creditSeason, now }, consume.condSql, consume.condBinds),
    ...consume.post, // the actual consume (decrement / opened_at / deduct), LAST so gates read pre-consume state
  ];
  const res = await env.DB.batch(stmts);
  return (res[0]?.meta?.changes ?? 0) > 0;
}

// Atomic, idempotent case open (extracted from POST /cases/open for real-code testing). Charges
// (inventory / daily-case / balls) and grants the reward EXACTLY ONCE per openId, all in one
// db.batch. rollFn() is called once for a fresh open; a committed open_id replays its stored
// reward; a different user/case for the same openId is a 409 conflict. No economic value changes.
export async function executeCaseOpen(
  env: Env,
  args: { userId: number; caseType: string; openId: string; cost: number; inventoryBacked: boolean; rollFn: () => CaseReward; currency?: "balls" | "stars" },
): Promise<CaseOpenResult> {
  const { userId, caseType, openId, cost, inventoryBacked, rollFn } = args;
  const currency = args.currency ?? "balls";
  if (!openId) return { ok: false, error: "Missing openId" };
  if (!isValidClientOpKey(openId)) return { ok: false, error: "INVALID_OPEN_ID" };

  const storedReward = (row: any): CaseReward => ({ type: String(row.reward_type), amount: Number(row.reward_amount), code: row.reward_code ?? null });
  const existing = await env.DB.prepare(`SELECT user_id, case_type, reward_type, reward_amount, reward_code FROM case_opens WHERE open_id = ?`).bind(openId).first() as any;
  if (existing) {
    if (Number(existing.user_id) !== userId || String(existing.case_type) !== caseType) return { ok: false, error: "CASE_OPEN_OPERATION_CONFLICT" };
    return { ok: true, duplicate: true, reward: storedReward(existing), state: await getCaseUserState(env, userId) };
  }

  const creditSeason = await getCurrentSeasonNumber(env);
  const now = Date.now();
  const reward = await resolveExtraLeagueOverflow(env, userId, rollFn());

  // Resource modes to try, in order. daily_free → inventory then daily fallback; premium →
  // inventory then paid; a zero-cost non-inventory case → a single free attempt.
  const day = new Date().toISOString().slice(0, 10);
  type Attempt = { ballsSpent: number; consume: { condSql: string; condBinds: unknown[]; pre: D1PreparedStatement[]; post: D1PreparedStatement[] } };
  const attempts: Attempt[] = [];
  if (inventoryBacked) {
    attempts.push({
      ballsSpent: 0,
      consume: {
        condSql: `(SELECT quantity FROM user_cases WHERE user_id = ? AND case_type = ?) > 0`,
        condBinds: [userId, caseType],
        pre: [],
        post: [env.DB.prepare(`UPDATE user_cases SET quantity = quantity - 1 WHERE user_id = ? AND case_type = ? AND quantity > 0`).bind(userId, caseType)],
      },
    });
  }
  if (caseType === "daily_free") {
    attempts.push({
      ballsSpent: 0,
      consume: {
        condSql: `(SELECT COUNT(*) FROM daily_cases WHERE user_id = ? AND day = ? AND earned = 1 AND opened_at IS NULL) > 0`,
        condBinds: [userId, day],
        pre: [],
        post: [env.DB.prepare(`UPDATE daily_cases SET opened_at = ? WHERE user_id = ? AND day = ? AND earned = 1 AND opened_at IS NULL`).bind(now, userId, day)],
      },
    });
  }
  if (cost > 0 && currency === "stars") {
    // §0.4: покупка кейса за звёзды. Списываем из user_season_progress текущего сезона,
    // мимо недельного потолка обмена. star_purchase_ledger даёт идемпотентный аудит.
    const gate = `(SELECT stars FROM user_season_progress WHERE user_id = ? AND season_number = ?) >= ?`;
    attempts.push({
      ballsSpent: 0,
      consume: {
        condSql: gate,
        condBinds: [userId, creditSeason, cost],
        pre: [
          env.DB.prepare(`INSERT OR IGNORE INTO star_purchase_ledger (user_id, season_number, item_type, stars_spent, idempotency_key, created_at)
              SELECT ?, ?, ?, ?, ?, ? WHERE ${gate}`).bind(userId, creditSeason, `case_${caseType}`, cost, openId, now, userId, creditSeason, cost),
        ],
        post: [env.DB.prepare(`UPDATE user_season_progress SET stars = stars - ? WHERE user_id = ? AND season_number = ? AND stars >= ?`).bind(cost, userId, creditSeason, cost)],
      },
    });
  } else if (cost > 0) {
    const gate = `(SELECT balls FROM users WHERE id = ?) >= ?`;
    attempts.push({
      ballsSpent: cost,
      consume: {
        condSql: gate,
        condBinds: [userId, cost],
        pre: [
          env.DB.prepare(`INSERT INTO ball_transactions (user_id, amount, balance_before, balance_after, operation_type, comment, open_id, created_at)
              SELECT ?, ?, (SELECT balls FROM users WHERE id = ?), (SELECT balls FROM users WHERE id = ?) - ?, 'case_open', ?, ?, ? WHERE ${gate}`)
            .bind(userId, -cost, userId, userId, cost, `Кейс: ${caseType}`, openId, now, userId, cost),
          env.DB.prepare(`INSERT OR IGNORE INTO purchase_history (user_id, item_type, balls_cost, created_at, operation_id)
              SELECT ?, ?, ?, ?, ? WHERE ${gate}`).bind(userId, `case_${caseType}`, cost, now, `case:${openId}`, userId, cost),
        ],
        post: [env.DB.prepare(`UPDATE users SET balls = balls - ? WHERE id = ? AND balls >= ?`).bind(cost, userId, cost)],
      },
    });
  }
  if (attempts.length === 0) {
    // Zero-cost, non-inventory case: there is no consumable resource to gate on, so an open here
    // would be infinitely repeatable with fresh openIds (free farm). Refuse instead — every
    // legitimate case is inventory-backed, daily-gated or paid.
    return { ok: false, error: "CASE_NOT_OPENABLE" };
  }

  for (const attempt of attempts) {
    try {
      const anchored = await runCaseOpenAttempt(env, { userId, caseType, openId, reward, creditSeason, now, ballsSpent: attempt.ballsSpent }, attempt.consume);
      if (anchored) {
        return { ok: true, reward, state: await getCaseUserState(env, userId) };
      }
    } catch (e: any) {
      if (String(e?.message || e).includes("UNIQUE constraint failed: case_opens.open_id")) {
        const dup = await env.DB.prepare(`SELECT user_id, case_type, reward_type, reward_amount, reward_code FROM case_opens WHERE open_id = ?`).bind(openId).first() as any;
        if (dup) {
          if (Number(dup.user_id) !== userId || String(dup.case_type) !== caseType) return { ok: false, error: "CASE_OPEN_OPERATION_CONFLICT" };
          return { ok: true, duplicate: true, reward: storedReward(dup), state: await getCaseUserState(env, userId) };
        }
      }
      throw e;
    }
  }

  // No attempt anchored. Either a concurrent winner committed the same open_id, or the resource is
  // genuinely unavailable.
  const committed = await env.DB.prepare(`SELECT user_id, case_type, reward_type, reward_amount, reward_code FROM case_opens WHERE open_id = ?`).bind(openId).first() as any;
  if (committed) {
    if (Number(committed.user_id) !== userId || String(committed.case_type) !== caseType) return { ok: false, error: "CASE_OPEN_OPERATION_CONFLICT" };
    return { ok: true, duplicate: true, reward: storedReward(committed), state: await getCaseUserState(env, userId) };
  }
  // A paid attempt existed (cost>0) but no inventory/daily and balance was insufficient.
  return { ok: false, error: cost > 0 ? "INSUFFICIENT_BALLS" : "NO_FREE_CASE" };
}

// ── Stage 5.3: atomic, idempotent fortune ("Фартовый мяч") spin ───────────────────────────────
export type FortuneSpinResult =
  | { ok: true; duplicate?: boolean; sectorIndex: number; reward: CaseReward; paymentMethod: "balls" | "lucky_token" | "stars" }
  | { ok: false; error: string };

// Charges (balls or one lucky token) and grants the rolled reward EXACTLY ONCE per spin_id, all in
// one db.batch. The fortune_spin_opens row (UNIQUE spin_id) is the anchor: a committed row ⇔ a
// fully completed spin (charge + grant). A concurrent duplicate makes the anchor INSERT violate
// UNIQUE → whole batch rolls back → replay. A closed resource gate makes every statement a no-op
// together. Wheel price / token cost / sectors are read by the caller — nothing here changes any
// economic value.
export async function executeFortuneSpin(
  env: Env,
  args: {
    userId: number; spinId: string; paymentMethod: "balls" | "lucky_token" | "stars";
    cost: number; tokenCost: number; starsCost?: number; allowBalls: boolean; allowToken: boolean; allowStars?: boolean;
    sectors: any[];
    rollFn: () => { sectorId: number; index: number; rewardType: string; amount: number; rewardCode: string | null };
  },
): Promise<FortuneSpinResult> {
  const { userId, spinId, paymentMethod, cost, tokenCost, allowBalls, allowToken, sectors } = args;
  const starsCost = Number(args.starsCost ?? 0);
  const allowStars = args.allowStars ?? false;
  if (!spinId) return { ok: false, error: "Missing spinId" };
  if (!isValidClientOpKey(spinId)) return { ok: false, error: "INVALID_SPIN_ID" };
  const indexOf = (sectorId: any) => { const i = sectors.findIndex((s) => Number(s.id) === Number(sectorId)); return i >= 0 ? i : 0; };
  const storedReward = (row: any): CaseReward => ({ type: String(row.reward_type), amount: Number(row.reward_amount), code: row.reward_code ?? null });
  const replayOrConflict = (row: any): FortuneSpinResult => {
    // Receipt encodes the method: free_spin=1 → token; balls_spent>0 → balls; else → stars.
    const storedPM: "balls" | "lucky_token" | "stars" = Number(row.free_spin) === 1 ? "lucky_token" : (Number(row.balls_spent) > 0 ? "balls" : "stars");
    if (Number(row.user_id) !== userId || storedPM !== paymentMethod) return { ok: false, error: "FORTUNE_SPIN_OPERATION_CONFLICT" };
    return { ok: true, duplicate: true, sectorIndex: indexOf(row.sector_id), reward: storedReward(row), paymentMethod: storedPM };
  };

  const existing = await env.DB.prepare(`SELECT user_id, balls_spent, free_spin, sector_id, reward_type, reward_amount, reward_code FROM fortune_spin_opens WHERE spin_id = ?`).bind(spinId).first() as any;
  if (existing) return replayOrConflict(existing);

  const creditSeason = await getCurrentSeasonNumber(env);
  const now = Date.now();
  const roll = args.rollFn();
  // §0.1 overflow: a slot drop past the cap becomes 3⚽; the receipt below records
  // the resolved reward (reward.*), while sector_id still points at the rolled sector.
  const reward = await resolveExtraLeagueOverflow(env, userId, { type: roll.rewardType, amount: roll.amount, code: roll.rewardCode });

  let condSql: string; let condBinds: unknown[]; let pre: D1PreparedStatement[]; let post: D1PreparedStatement[];
  let ballsSpent = 0; let freeSpin = 0;
  if (paymentMethod === "balls") {
    if (!allowBalls) return { ok: false, error: "BALLS_PAYMENT_DISABLED" };
    if (cost <= 0) return { ok: false, error: "BALLS_PRICE_NOT_SET" };
    ballsSpent = cost;
    condSql = `(SELECT balls FROM users WHERE id = ?) >= ?`; condBinds = [userId, cost];
    pre = [env.DB.prepare(`INSERT OR IGNORE INTO ball_transactions (user_id, amount, balance_before, balance_after, operation_type, comment, open_id, created_at)
        SELECT ?, ?, (SELECT balls FROM users WHERE id = ?), (SELECT balls FROM users WHERE id = ?) - ?, 'fortune_spin', 'Фартовый мяч', ?, ? WHERE ${condSql}`)
      .bind(userId, -cost, userId, userId, cost, spinId, now, userId, cost)];
    post = [env.DB.prepare(`UPDATE users SET balls = balls - ? WHERE id = ? AND balls >= ?`).bind(cost, userId, cost)];
  } else if (paymentMethod === "lucky_token") {
    if (!allowToken) return { ok: false, error: "TOKEN_PAYMENT_DISABLED" };
    freeSpin = 1;
    condSql = `(SELECT quantity FROM fortune_spins WHERE user_id = ?) >= ?`; condBinds = [userId, tokenCost];
    pre = [
      env.DB.prepare(`INSERT OR IGNORE INTO lucky_token_transactions (user_id, amount, balance_before, balance_after, operation_type, comment, admin_user_id, ref_id, created_at)
          SELECT ?, ?, COALESCE((SELECT quantity FROM fortune_spins WHERE user_id = ?), 0), COALESCE((SELECT quantity FROM fortune_spins WHERE user_id = ?), 0) - ?, ?, ?, NULL, ?, ? WHERE ${condSql}`)
        .bind(userId, -tokenCost, userId, userId, tokenCost, LUCKY_TOKEN_OPS.spin, "Фартовый мяч", spinId, now, userId, tokenCost),
    ];
    post = [env.DB.prepare(`UPDATE fortune_spins SET quantity = quantity - ? WHERE user_id = ? AND quantity >= ?`).bind(tokenCost, userId, tokenCost)];
  } else {
    // §0.4: спин за звёзды. Списываем из user_season_progress текущего сезона, мимо
    // недельного потолка обмена. balls_spent=0 & free_spin=0 в чеке ⇒ метод 'stars'.
    if (!allowStars) return { ok: false, error: "STARS_PAYMENT_DISABLED" };
    if (starsCost <= 0) return { ok: false, error: "STARS_PRICE_NOT_SET" };
    condSql = `(SELECT stars FROM user_season_progress WHERE user_id = ? AND season_number = ?) >= ?`; condBinds = [userId, creditSeason, starsCost];
    pre = [
      env.DB.prepare(`INSERT OR IGNORE INTO star_purchase_ledger (user_id, season_number, item_type, stars_spent, idempotency_key, created_at)
          SELECT ?, ?, ?, ?, ?, ? WHERE ${condSql}`).bind(userId, creditSeason, "fortune_spin", starsCost, spinId, now, userId, creditSeason, starsCost),
    ];
    post = [env.DB.prepare(`UPDATE user_season_progress SET stars = stars - ? WHERE user_id = ? AND season_number = ? AND stars >= ?`).bind(starsCost, userId, creditSeason, starsCost)];
  }

  const anchor = env.DB.prepare(`INSERT INTO fortune_spin_opens (spin_id, user_id, sector_id, reward_type, reward_amount, reward_code, balls_spent, free_spin, created_at)
      SELECT ?, ?, ?, ?, ?, ?, ?, ?, ? WHERE ${condSql}`)
    .bind(spinId, userId, roll.sectorId, reward.type, reward.amount, reward.code, ballsSpent, freeSpin, now, ...condBinds);

  try {
    const batchRes = await env.DB.batch([
      anchor,
      ...pre,
      ...caseRewardStmts(env, { userId, openId: spinId, reward, creditSeason, now }, condSql, condBinds),
      ...post,
    ]);
    const anchored = (batchRes[0]?.meta?.changes ?? 0) > 0;
    if (!anchored) {
      const committed = await env.DB.prepare(`SELECT user_id, balls_spent, free_spin, sector_id, reward_type, reward_amount, reward_code FROM fortune_spin_opens WHERE spin_id = ?`).bind(spinId).first() as any;
      if (committed) return replayOrConflict(committed);
      return { ok: false, error: paymentMethod === "balls" ? "INSUFFICIENT_BALLS" : paymentMethod === "stars" ? "INSUFFICIENT_STARS" : "INSUFFICIENT_LUCKY_TOKENS" };
    }
    return { ok: true, sectorIndex: roll.index, reward, paymentMethod };
  } catch (e: any) {
    if (String(e?.message || e).includes("UNIQUE constraint failed: fortune_spin_opens.spin_id")) {
      const committed = await env.DB.prepare(`SELECT user_id, balls_spent, free_spin, sector_id, reward_type, reward_amount, reward_code FROM fortune_spin_opens WHERE spin_id = ?`).bind(spinId).first() as any;
      if (committed) return replayOrConflict(committed);
    }
    throw e;
  }
}


function parseCaseRewardMeta(metaJson: unknown): any | null {
  if (!metaJson || metaJson === "null") return null;
  try {
    const parsed = typeof metaJson === "string" ? JSON.parse(metaJson) : metaJson;
    return parsed && typeof parsed === "object" ? parsed : null;
  } catch {
    return null;
  }
}

function getEffectiveDiscreteAmounts(entry: any): Array<{ amount: number; weight: number }> {
  const meta = parseCaseRewardMeta(entry?.meta_json);
  const raw = Array.isArray(meta?.discrete_amounts) ? meta.discrete_amounts : [];
  const min = entry?.min_amount != null ? Number(entry.min_amount) : null;
  const max = entry?.max_amount != null ? Number(entry.max_amount) : null;
  return raw
    .map((item: any) => ({
      amount: Number(item?.amount),
      weight: Number(item?.weight),
    }))
    .filter((item: any) => Number.isFinite(item.amount) && Number.isFinite(item.weight) && item.weight > 0)
    .filter((item: any) => (
      min == null || max == null
        ? true
        : item.amount >= min && item.amount <= max
    ));
}

// Every reward type caseRewardStmts() can actually deliver. A type outside this set would commit
// the receipt + charge but grant NOTHING (caseRewardStmts returns []) — so an admin typo must be
// rejected at save time, not silently swallowed at open time.
const GRANTABLE_CASE_REWARD_TYPES = new Set([
  "stars", "balls", "extra_joker", "double_chance", "extra_joker_double_chance",
  "extra_league", "case", "lucky_token",
]);

function normalizeCaseRewardConfig(raw: any): any {
  const chancePercent = Number(raw?.chance_percent);
  const fixedAmount = raw?.fixed_amount == null || raw.fixed_amount === "" ? null : Number(raw.fixed_amount);
  const minAmount = raw?.min_amount == null || raw.min_amount === "" ? null : Number(raw.min_amount);
  const maxAmount = raw?.max_amount == null || raw.max_amount === "" ? null : Number(raw.max_amount);
  const isActive = raw?.is_active ? 1 : 0;
  const rewardType = String(raw?.reward_type ?? "").toLowerCase();
  const rewardCode = raw?.reward_code ?? null;

  if (!GRANTABLE_CASE_REWARD_TYPES.has(canonicalRewardType(rewardType))) {
    throw new Error(`Unknown reward type: ${rewardType || "(empty)"}`);
  }
  if (!Number.isFinite(chancePercent)) throw new Error("Invalid reward probability");
  if (fixedAmount != null && (!Number.isFinite(fixedAmount) || fixedAmount < 0)) throw new Error("Invalid fixed amount");
  if (minAmount != null && (!Number.isFinite(minAmount) || minAmount < 0)) throw new Error("Invalid min amount");
  if (maxAmount != null && (!Number.isFinite(maxAmount) || maxAmount < 0)) throw new Error("Invalid max amount");

  let meta = parseCaseRewardMeta(raw?.meta_json);
  if (fixedAmount != null) {
    meta = null;
  } else if (minAmount != null && maxAmount != null && minAmount < maxAmount) {
    if (meta?.discrete_amounts) {
      const filtered = getEffectiveDiscreteAmounts({ min_amount: minAmount, max_amount: maxAmount, meta_json: meta });
      const nextMeta = { ...meta, discrete_amounts: filtered };
      if (filtered.length === 0) delete nextMeta.discrete_amounts;
      meta = Object.keys(nextMeta).length > 0 ? nextMeta : null;
    }
  } else if (meta?.discrete_amounts) {
    const nextMeta = { ...meta };
    delete nextMeta.discrete_amounts;
    meta = Object.keys(nextMeta).length > 0 ? nextMeta : null;
  }

  return {
    reward_type: rewardType,
    reward_code: rewardCode,
    chance_percent: chancePercent,
    min_amount: minAmount,
    max_amount: maxAmount,
    fixed_amount: fixedAmount,
    is_active: isActive,
    meta_json: meta ? JSON.stringify(meta) : null,
  };
}

async function transferDailyCaseToInventory(
  env: Env,
  userId: number,
  day: string,
  opts?: { allowCreateIfMissing?: boolean; earnedAt?: number | null; comment?: string; now?: number }
): Promise<boolean> {
  const now = opts?.now ?? Date.now();
  const comment = opts?.comment ?? 'daily_case_autotransfer';
  const existing = await env.DB.prepare(
    `SELECT earned, earned_at FROM daily_cases WHERE user_id = ? AND day = ?`
  ).bind(userId, day).first() as any;

  let promoted = false;
  if (!existing) {
    if (!opts?.allowCreateIfMissing) return false;
    const insRes = await env.DB.prepare(`
      INSERT OR IGNORE INTO daily_cases (user_id, day, earned, earned_at)
      VALUES (?, ?, 2, ?)
    `).bind(userId, day, opts?.earnedAt ?? now).run();
    promoted = (insRes.meta.changes ?? 0) > 0;
  } else if (Number(existing.earned) === 1) {
    const updRes = await env.DB.prepare(`
      UPDATE daily_cases
      SET earned = 2
      WHERE user_id = ? AND day = ? AND earned = 1
    `).bind(userId, day).run();
    promoted = (updRes.meta.changes ?? 0) > 0;
  } else {
    return false;
  }

  if (!promoted) return false;

  const beforeRow = await env.DB.prepare(
    `SELECT quantity FROM user_cases WHERE user_id = ? AND case_type = 'daily_free'`
  ).bind(userId).first() as any;
  const qtBefore = Number(beforeRow?.quantity ?? 0);

  await env.DB.prepare(`
    INSERT INTO user_cases (user_id, case_type, quantity)
    VALUES (?, 'daily_free', 1)
    ON CONFLICT(user_id, case_type) DO UPDATE SET quantity = quantity + 1
  `).bind(userId).run();

  const afterRow = await env.DB.prepare(
    `SELECT quantity FROM user_cases WHERE user_id = ? AND case_type = 'daily_free'`
  ).bind(userId).first() as any;
  const qtAfter = Number(afterRow?.quantity ?? (qtBefore + 1));

  await env.DB.prepare(`
    INSERT INTO case_transactions (user_id, case_type, amount, quantity_before, quantity_after, operation_type, comment, created_at)
    VALUES (?, 'daily_free', 1, ?, ?, 'earn', ?, ?)
  `).bind(userId, qtBefore, qtAfter, comment, now).run();

  return true;
}

// Stable, deterministic idempotency key for a partner case reward. Bound ONLY to the immutable
// partner_claim id (no Telegram id / username / time / randomness). One claim → one key forever;
// retries rebuild the exact same key; the suffix scopes it to the case-reward operation so it can
// never collide with another operation kind for the same claim.
function buildPartnerCaseRewardIdempotencyKey(claimId: number): string {
  return `partner_claim:${claimId}:case_reward`;
}

interface GrantCaseResult { quantityAfter: number; granted: boolean; alreadyGranted: boolean }

// Grant a case into a user's inventory.
//
// Without `idempotencyKey` (shop / tasks / daily / weekly / season / admin call sites): behaves
// exactly as before — increment user_cases + write an 'earn' case_transactions receipt (key NULL).
//
// With `idempotencyKey` (partner case reward): CRASH-SAFE + IDEMPOTENT. The inventory increment and
// the receipt are committed in ONE atomic db.batch, and the receipt carries the unique key. A
// replay (same key) is a no-op: user_cases is NOT incremented again and no second receipt is
// written — the UNIQUE(idempotency_key) index is the authoritative DB-level guard (no check-then-
// insert race). Returns granted=true on a fresh grant, alreadyGranted=true on a safe replay. A
// matching receipt for a DIFFERENT user is a controlled integrity error (never a silent no-op).
async function grantCaseToInventory(
  env: Env,
  userId: number,
  caseType: string,
  opts?: { amount?: number; comment?: string; now?: number; idempotencyKey?: string }
): Promise<GrantCaseResult> {
  const now = opts?.now ?? Date.now();
  const amount = Math.max(1, Number(opts?.amount ?? 1));
  const comment = opts?.comment ?? 'task_case_reward';
  const key = opts?.idempotencyKey;

  if (!key) {
    // ── Legacy path (unchanged behavior for all non-idempotent call sites) ──
    const beforeRow = await env.DB.prepare(
      `SELECT quantity FROM user_cases WHERE user_id = ? AND case_type = ?`
    ).bind(userId, caseType).first() as any;
    const quantityBefore = Number(beforeRow?.quantity ?? 0);

    await env.DB.prepare(`
      INSERT INTO user_cases (user_id, case_type, quantity)
      VALUES (?, ?, ?)
      ON CONFLICT(user_id, case_type) DO UPDATE SET quantity = quantity + excluded.quantity
    `).bind(userId, caseType, amount).run();

    const afterRow = await env.DB.prepare(
      `SELECT quantity FROM user_cases WHERE user_id = ? AND case_type = ?`
    ).bind(userId, caseType).first() as any;
    const quantityAfter = Number(afterRow?.quantity ?? (quantityBefore + amount));

    await env.DB.prepare(`
      INSERT INTO case_transactions (user_id, case_type, amount, quantity_before, quantity_after, operation_type, comment, created_at)
      VALUES (?, ?, ?, ?, ?, 'earn', ?, ?)
    `).bind(userId, caseType, amount, quantityBefore, quantityAfter, comment, now).run();

    return { quantityAfter, granted: true, alreadyGranted: false };
  }

  // ── Idempotent + atomic path (partner case reward) ──
  // All three statements run in ONE transaction (db.batch). Both the increment (stmt 2) and the
  // receipt insert (stmt 3) are gated on "no receipt yet for this key", so they either BOTH apply
  // (fresh grant) or BOTH skip (replay) — inventory and receipt can never diverge. stmt 3 is the
  // anchor: changes>0 ⇒ this call newly granted.
  const batch = await env.DB.batch([
    // 1. ensure the inventory row exists (no-op if present) so stmt 2's UPDATE can apply
    env.DB.prepare(`INSERT OR IGNORE INTO user_cases (user_id, case_type, quantity) VALUES (?, ?, 0)`)
      .bind(userId, caseType),
    // 2. increment ONLY if this key was never granted
    env.DB.prepare(`UPDATE user_cases SET quantity = quantity + ?
       WHERE user_id = ? AND case_type = ?
         AND NOT EXISTS (SELECT 1 FROM case_transactions WHERE idempotency_key = ?)`)
      .bind(amount, userId, caseType, key),
    // 3. write the receipt ONLY if this key was never granted (UNIQUE(idempotency_key) backstop)
    env.DB.prepare(`INSERT INTO case_transactions
        (user_id, case_type, amount, quantity_before, quantity_after, operation_type, comment, created_at, idempotency_key)
       SELECT ?, ?, ?,
         (SELECT quantity FROM user_cases WHERE user_id = ? AND case_type = ?) - ?,
         (SELECT quantity FROM user_cases WHERE user_id = ? AND case_type = ?),
         'earn', ?, ?, ?
       WHERE NOT EXISTS (SELECT 1 FROM case_transactions WHERE idempotency_key = ?)`)
      .bind(userId, caseType, amount, userId, caseType, amount, userId, caseType, comment, now, key, key),
  ]);

  const granted = Number(batch?.[2]?.meta?.changes ?? 0) > 0;
  const qRow = await env.DB.prepare(`SELECT quantity FROM user_cases WHERE user_id = ? AND case_type = ?`)
    .bind(userId, caseType).first() as any;
  const quantityAfter = Number(qRow?.quantity ?? 0);

  if (!granted) {
    // Safe replay ONLY if the existing receipt fully matches what this call would have written.
    // A key bound to a claim must resolve to exactly the same user / case_type / amount / earn
    // operation; any divergence is corruption (e.g. a mutated campaign, a poisoned key) and must
    // surface as a controlled integrity error — never a silent "alreadyGranted" no-op.
    const existing = await env.DB.prepare(
      `SELECT user_id, case_type, amount, operation_type, idempotency_key FROM case_transactions WHERE idempotency_key = ?`
    ).bind(key).first() as any;
    if (!existing) throw new Error("CASE_IDEMPOTENCY_RECEIPT_INVALID");
    if (Number(existing.user_id) !== userId) throw new Error("CASE_IDEMPOTENCY_KEY_USER_MISMATCH");
    if (String(existing.case_type) !== caseType) throw new Error("CASE_IDEMPOTENCY_KEY_CASE_TYPE_MISMATCH");
    if (Number(existing.amount) !== amount) throw new Error("CASE_IDEMPOTENCY_KEY_AMOUNT_MISMATCH");
    if (String(existing.operation_type) !== "earn") throw new Error("CASE_IDEMPOTENCY_KEY_OPERATION_MISMATCH");
    if (String(existing.idempotency_key) !== key) throw new Error("CASE_IDEMPOTENCY_RECEIPT_INVALID");
  }

  return { quantityAfter, granted, alreadyGranted: !granted };
}

// =======================
// Referral program (docs/referral-v1.md)
// =======================
// Zero hot-path cost by design: attach happens once via POST /referral/claim
// (only for users arriving through a ref_/src_ deep link), activation is a
// single PK read inside the already-heavy pick-save flow, and every grant goes
// through the existing idempotent ledgers (case_transactions idempotency_key /
// lucky_token_transactions ref_id), so replays and races can never double-pay.

const REFERRAL_ATTACH_WINDOW_MS = 48 * 3600_000; // only "new" users can be attributed
const REFERRAL_CAP_WINDOW_MS = 24 * 3600_000;    // rolling window for the inviter daily cap

let referralConfigCache: { value: ReferralConfig; expiresAt: number } | null = null;

export function resetReferralConfigCache() { referralConfigCache = null; }

async function getReferralConfig(env: Env): Promise<ReferralConfig> {
  if (referralConfigCache && referralConfigCache.expiresAt > Date.now()) return referralConfigCache.value;
  let config = REFERRAL_CONFIG_DEFAULTS;
  try {
    const row = await env.DB.prepare(`SELECT value FROM app_config WHERE key = ?`)
      .bind(REFERRAL_CONFIG_KEY).first() as any;
    if (row?.value) {
      const parsed = parseReferralConfig(JSON.parse(String(row.value)));
      if (parsed) config = parsed;
    }
  } catch { /* missing table/row or corrupt JSON → defaults */ }
  referralConfigCache = { value: config, expiresAt: Date.now() + 60_000 };
  return config;
}

// Single dispatcher for all referral payouts. Idempotency key doubles as the
// audit trail id in the respective ledger; a replayed key is a silent no-op.
async function grantReferralItemReward(
  env: Env, userId: number, reward: ReferralReward, idemKey: string, comment: string
): Promise<boolean> {
  if (reward.type === "none" || reward.amount <= 0) return false;
  if (reward.type === "lucky_token") {
    const before = await getLuckyTokenBalance(env, userId);
    const after = await grantLuckyTokens(env, userId, reward.amount, LUCKY_TOKEN_OPS.referral, idemKey, Date.now(), comment);
    return after > before;
  }
  const caseType = reward.type === "premium_case" ? "premium" : "daily_free";
  const res = await grantCaseToInventory(env, userId, caseType, {
    amount: reward.amount, comment, idempotencyKey: idemKey,
  });
  return res.granted;
}

// Called after a successful pick/joker save (best-effort, never blocks the save).
// Returns invitee-toast info when THIS call performed the activation.
export async function processReferralActivation(
  env: Env, ctx: ExecutionContext, userId: number, inviteeName: string
): Promise<{ granted: boolean; label: string } | null> {
  const me = await env.DB.prepare(
    `SELECT referred_by, referral_activated_at FROM users WHERE id = ?`
  ).bind(userId).first() as any;
  if (!me || me.referred_by == null) return null;
  const inviterId = Number(me.referred_by);
  if (!Number.isSafeInteger(inviterId) || inviterId <= 0 || inviterId === userId) return null;

  const config = await getReferralConfig(env);
  if (!config.enabled) return null;

  // Attach-time ban check only covers bans that predate the attach — re-check
  // here so a later-banned inviter stops earning. The invitee still activates
  // and gets the welcome reward (they did nothing wrong); the inviter's
  // referral_rewarded_at slots stay NULL, so the pending sweep pays them out
  // later only if the ban is ever lifted.
  const inviterRow = await env.DB.prepare(
    `SELECT is_banned FROM users WHERE id = ?`
  ).bind(inviterId).first() as any;
  const inviterBanned = !inviterRow || Number(inviterRow.is_banned || 0) === 1;

  const now = Date.now();
  let inviteeToast: { granted: boolean; label: string } | null = null;

  // 1. Activation flip — the WHERE guard makes exactly one request the winner.
  if (me.referral_activated_at == null) {
    const flip = await env.DB.prepare(
      `UPDATE users SET referral_activated_at = ? WHERE id = ? AND referral_activated_at IS NULL`
    ).bind(now, userId).run();
    if ((flip.meta.changes ?? 0) > 0) {
      const granted = await grantReferralItemReward(
        env, userId, config.invitee_reward, `referral_welcome:${userId}`, "referral_invitee_reward"
      );
      if (granted) inviteeToast = { granted, label: referralRewardLabel(config.invitee_reward) };
    }
  }

  if (inviterBanned) return inviteeToast;

  // 2. Sweep the inviter's pending per-friend rewards up to the rolling daily cap.
  //    Runs on every activation event of any friend, so deferred rewards catch up.
  const rewardedRecently = await env.DB.prepare(
    `SELECT COUNT(*) AS n FROM users WHERE referred_by = ? AND referral_rewarded_at >= ?`
  ).bind(inviterId, now - REFERRAL_CAP_WINDOW_MS).first() as any;
  let budget = Math.max(0, config.daily_cap - Number(rewardedRecently?.n || 0));

  let newlyRewarded = 0;
  if (budget > 0) {
    const pending = await env.DB.prepare(
      `SELECT id FROM users
       WHERE referred_by = ? AND referral_activated_at IS NOT NULL AND referral_rewarded_at IS NULL
       ORDER BY referral_activated_at ASC LIMIT ?`
    ).bind(inviterId, budget).all();
    for (const row of (pending.results || []) as any[]) {
      const friendId = Number(row.id);
      // Claim the slot first; only the claiming request pays out (idempotent anyway).
      const claim = await env.DB.prepare(
        `UPDATE users SET referral_rewarded_at = ? WHERE id = ? AND referral_rewarded_at IS NULL`
      ).bind(now, friendId).run();
      if ((claim.meta.changes ?? 0) === 0) continue;
      await grantReferralItemReward(
        env, inviterId, config.per_friend_reward, `referral_friend:${friendId}`, "referral_per_friend_reward"
      );
      newlyRewarded += 1;
    }
  }

  // 3. Milestones — computed from the activated count, granted lazily and
  //    idempotently, so a config edit or a missed run self-heals later.
  const activatedRow = await env.DB.prepare(
    `SELECT COUNT(*) AS n FROM users WHERE referred_by = ? AND referral_activated_at IS NOT NULL`
  ).bind(inviterId).first() as any;
  const activatedCount = Number(activatedRow?.n || 0);
  for (const m of config.milestones) {
    if (m.count <= activatedCount) {
      await grantReferralItemReward(
        env, inviterId, m.reward, `referral_milestone:${inviterId}:${m.count}`, `referral_milestone_${m.count}`
      );
    }
  }

  // 4. Notify the inviter (plain text — no parse_mode, so no escaping pitfalls).
  if (newlyRewarded > 0 && env.TELEGRAM_BOT_TOKEN) {
    const label = referralRewardLabel(config.per_friend_reward);
    const name = String(inviteeName || "Твой друг").slice(0, 64);
    ctx.waitUntil(
      telegramBotApi(env, "sendMessage", {
        chat_id: inviterId,
        text: `🎁 ${name} сделал первый прогноз по твоему приглашению — тебе начислено: ${label}. Друзей активировано: ${activatedCount}.`,
      }).catch(() => {})
    );
  }

  return inviteeToast;
}

let starShopTablesAvailableCache: { value: boolean; expiresAt: number } | null = null;
let starExchangeTablesAvailableCache: { value: boolean; expiresAt: number } | null = null;

async function hasStarExchangeTables(env: Env): Promise<boolean> {
  if (starExchangeTablesAvailableCache && starExchangeTablesAvailableCache.expiresAt > Date.now()) {
    return starExchangeTablesAvailableCache.value;
  }
  const [cfg, tiers, ledger] = await Promise.all([
    hasTable(env, "economy_star_exchange_config"),
    hasTable(env, "economy_star_exchange_tiers"),
    hasTable(env, "star_exchange_ledger"),
  ]);
  const value = cfg && tiers && ledger;
  starExchangeTablesAvailableCache = { value, expiresAt: Date.now() + SCHEMA_SUPPORT_TTL_MS };
  return value;
}

async function getWeeklyExchangeUsed(env: Env, userId: number, weekKey: string): Promise<number> {
  const row = await env.DB.prepare(
    `SELECT COALESCE(SUM(stars_spent), 0) AS used FROM star_exchange_ledger WHERE user_id = ? AND week_key = ?`
  ).bind(userId, weekKey).first() as any;
  return Number(row?.used ?? 0);
}

async function hasStarShopTables(env: Env): Promise<boolean> {
  if (starShopTablesAvailableCache && starShopTablesAvailableCache.expiresAt > Date.now()) {
    return starShopTablesAvailableCache.value;
  }
  const [packs, orders, events] = await Promise.all([
    hasTable(env, "shop_star_packs"),
    hasTable(env, "telegram_star_orders"),
    hasTable(env, "telegram_star_order_events"),
  ]);
  const value = packs && orders && events;
  starShopTablesAvailableCache = { value, expiresAt: Date.now() + SCHEMA_SUPPORT_TTL_MS };
  return value;
}

function getStarPackTotalBalls(pack: { balls_amount: number; bonus_balls: number }): number {
  return Math.max(0, Number(pack.balls_amount || 0)) + Math.max(0, Number(pack.bonus_balls || 0));
}

function normalizeStarPackAdminInput(raw: any): Omit<ShopStarPackRow, "id" | "created_at" | "updated_at"> {
  const code = String(raw?.code ?? "").trim().toLowerCase();
  const title = String(raw?.title ?? "").trim();
  if (!code) throw new Error("STAR_PACK_CODE_REQUIRED");
  if (!title) throw new Error("STAR_PACK_TITLE_REQUIRED");

  const description = raw?.description == null ? null : String(raw.description).trim();
  const emoji = raw?.emoji == null ? null : String(raw.emoji).trim();
  const badgeText = raw?.badge_text == null ? null : String(raw.badge_text).trim();
  const ballsAmount = Math.max(0, Number(raw?.balls_amount ?? 0));
  const bonusBalls = Math.max(0, Number(raw?.bonus_balls ?? 0));
  const priceXtr = Math.max(1, Number(raw?.price_xtr ?? 0));
  const sortOrder = Number.isFinite(Number(raw?.sort_order)) ? Number(raw.sort_order) : 0;
  const isActive = raw?.is_active ? 1 : 0;

  if (!Number.isFinite(ballsAmount) || ballsAmount <= 0) throw new Error("STAR_PACK_BALLS_REQUIRED");
  if (!Number.isFinite(bonusBalls)) throw new Error("STAR_PACK_BONUS_INVALID");
  if (!Number.isFinite(priceXtr) || priceXtr <= 0) throw new Error("STAR_PACK_PRICE_REQUIRED");
  if (!Number.isFinite(sortOrder)) throw new Error("STAR_PACK_SORT_INVALID");

  return {
    code,
    title,
    description,
    emoji,
    balls_amount: ballsAmount,
    bonus_balls: bonusBalls,
    price_xtr: priceXtr,
    badge_text: badgeText,
    is_active: isActive,
    sort_order: sortOrder,
  };
}

async function listActiveStarPacks(env: Env): Promise<any[]> {
  if (!(await hasStarShopTables(env))) return [];
  const res = await env.DB.prepare(`
    SELECT id, code, title, description, emoji, balls_amount, bonus_balls, price_xtr, badge_text, sort_order
    FROM shop_star_packs
    WHERE is_active = 1
    ORDER BY sort_order ASC, id ASC
  `).all();
  return ((res.results || []) as any[]).map((row) => ({
    ...row,
    balls_amount: Number(row.balls_amount || 0),
    bonus_balls: Number(row.bonus_balls || 0),
    price_xtr: Number(row.price_xtr || 0),
    total_balls: Math.max(0, Number(row.balls_amount || 0)) + Math.max(0, Number(row.bonus_balls || 0)),
  }));
}

async function getStarPackByCode(env: Env, code: string, opts?: { activeOnly?: boolean }): Promise<ShopStarPackRow | null> {
  if (!(await hasStarShopTables(env))) return null;
  const activeOnly = opts?.activeOnly !== false;
  const row = await env.DB.prepare(`
    SELECT *
    FROM shop_star_packs
    WHERE code = ?
      ${activeOnly ? "AND is_active = 1" : ""}
    LIMIT 1
  `).bind(code).first() as any;
  return row ? ({
    ...row,
    id: Number(row.id),
    balls_amount: Number(row.balls_amount || 0),
    bonus_balls: Number(row.bonus_balls || 0),
    price_xtr: Number(row.price_xtr || 0),
    is_active: Number(row.is_active || 0),
    sort_order: Number(row.sort_order || 0),
    created_at: Number(row.created_at || 0),
    updated_at: Number(row.updated_at || 0),
  }) : null;
}

async function findReusableStarOrder(env: Env, userId: number, packCode: string): Promise<any | null> {
  if (!(await hasStarShopTables(env))) return null;
  const minCreatedAt = Date.now() - 15 * 60 * 1000;
  const row = await env.DB.prepare(`
    SELECT order_id, invoice_link, status, total_balls, price_xtr
    FROM telegram_star_orders
    WHERE user_id = ?
      AND pack_code = ?
      AND status IN ('pending', 'invoice_created', 'pre_checkout_approved')
      AND created_at >= ?
    ORDER BY created_at DESC
    LIMIT 1
  `).bind(userId, packCode, minCreatedAt).first() as any;
  return row || null;
}

async function createStarOrder(env: Env, userId: number, pack: ShopStarPackRow): Promise<any> {
  if (!(await hasStarShopTables(env))) {
    throw new Error("STAR_SHOP_NOT_READY");
  }
  const now = Date.now();
  const orderId = crypto.randomUUID();
  const invoicePayload = `stars_pack:${orderId}`;
  const totalBalls = getStarPackTotalBalls(pack);

  await env.DB.prepare(`
    INSERT INTO telegram_star_orders (
      order_id, user_id, pack_code, pack_title, invoice_payload, price_xtr,
      balls_amount, bonus_balls, total_balls, status, created_at, updated_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?)
  `).bind(
    orderId,
    userId,
    pack.code,
    pack.title,
    invoicePayload,
    Number(pack.price_xtr || 0),
    Number(pack.balls_amount || 0),
    Number(pack.bonus_balls || 0),
    totalBalls,
    now,
    now
  ).run();

  return {
    orderId,
    invoicePayload,
    totalBalls,
    priceXtr: Number(pack.price_xtr || 0),
    packTitle: pack.title,
  };
}

async function logStarOrderEvent(env: Env, orderId: string, eventType: string, payload?: unknown): Promise<void> {
  if (!(await hasStarShopTables(env))) return;
  await env.DB.prepare(`
    INSERT INTO telegram_star_order_events (order_id, event_type, payload_json, created_at)
    VALUES (?, ?, ?, ?)
  `).bind(orderId, eventType, payload == null ? null : JSON.stringify(payload), Date.now()).run();
}

async function markStarOrderInvoiceCreated(env: Env, orderId: string, invoiceLink: string): Promise<void> {
  if (!(await hasStarShopTables(env))) return;
  await env.DB.prepare(`
    UPDATE telegram_star_orders
    SET invoice_link = ?, status = 'invoice_created', updated_at = ?, last_error = NULL
    WHERE order_id = ?
  `).bind(invoiceLink, Date.now(), orderId).run();
  await logStarOrderEvent(env, orderId, "invoice_created", { invoice_link: invoiceLink });
}

async function markStarOrderFailed(env: Env, orderId: string, reason: string): Promise<void> {
  if (!(await hasStarShopTables(env))) return;
  await env.DB.prepare(`
    UPDATE telegram_star_orders
    SET status = 'failed', last_error = ?, updated_at = ?
    WHERE order_id = ?
  `).bind(reason, Date.now(), orderId).run();
  await logStarOrderEvent(env, orderId, "invoice_failed", { reason });
}

async function getStarOrderForUser(env: Env, userId: number, orderId: string): Promise<any | null> {
  if (!(await hasStarShopTables(env))) return null;
  const row = await env.DB.prepare(`
    SELECT order_id, pack_code, pack_title, price_xtr, balls_amount, bonus_balls, total_balls,
           status, last_error, created_at, paid_at, credited_at, refunded_at
    FROM telegram_star_orders
    WHERE order_id = ? AND user_id = ?
    LIMIT 1
  `).bind(orderId, userId).first() as any;
  return row ? {
    ...row,
    price_xtr: Number(row.price_xtr || 0),
    balls_amount: Number(row.balls_amount || 0),
    bonus_balls: Number(row.bonus_balls || 0),
    total_balls: Number(row.total_balls || 0),
  } : null;
}

async function getStarOrderByIdForAdmin(env: Env, orderId: string): Promise<any | null> {
  if (!(await hasStarShopTables(env))) return null;
  const row = await env.DB.prepare(`
    SELECT o.*, u.username, u.first_name, u.last_name
    FROM telegram_star_orders o
    LEFT JOIN users u ON u.id = o.user_id
    WHERE o.order_id = ?
    LIMIT 1
  `).bind(orderId).first() as any;
  return row ? {
    ...row,
    user_id: Number(row.user_id || 0),
    price_xtr: Number(row.price_xtr || 0),
    balls_amount: Number(row.balls_amount || 0),
    bonus_balls: Number(row.bonus_balls || 0),
    total_balls: Number(row.total_balls || 0),
  } : null;
}

async function evaluateStarOrderRefundState(env: Env, order: any): Promise<StarOrderRefundState> {
  const totalBalls = Math.max(0, Number(order?.total_balls || 0));
  const userId = Number(order?.user_id || 0);
  const currentBalanceRow = await env.DB.prepare(`SELECT balls FROM users WHERE id = ?`).bind(userId).first() as any;
  const currentBalance = Math.max(0, Number(currentBalanceRow?.balls || 0));

  if (!order) {
    return { refundable: false, reason: "ORDER_NOT_FOUND", current_balance: currentBalance, total_balls: totalBalls, unspent_purchase_balls: 0 };
  }
  if (String(order.status || "") === "refunded" || Number(order.refunded_at || 0) > 0) {
    return { refundable: false, reason: "ALREADY_REFUNDED", current_balance: currentBalance, total_balls: totalBalls, unspent_purchase_balls: 0 };
  }
  if (String(order.status || "") !== "credited" || Number(order.credited_at || 0) <= 0) {
    return { refundable: false, reason: "ORDER_NOT_CREDITED", current_balance: currentBalance, total_balls: totalBalls, unspent_purchase_balls: 0 };
  }
  if (!String(order.telegram_payment_charge_id || "").trim()) {
    return { refundable: false, reason: "TELEGRAM_CHARGE_MISSING", current_balance: currentBalance, total_balls: totalBalls, unspent_purchase_balls: 0 };
  }
  if (totalBalls <= 0) {
    return { refundable: false, reason: "NO_BALLS_IN_ORDER", current_balance: currentBalance, total_balls: totalBalls, unspent_purchase_balls: 0 };
  }

  const purchaseTx = await env.DB.prepare(`
    SELECT id, amount, balance_before
    FROM ball_transactions
    WHERE user_id = ? AND open_id = ?
    LIMIT 1
  `).bind(userId, `stars_order:${String(order.order_id)}`).first() as any;

  if (!purchaseTx) {
    return { refundable: false, reason: "PURCHASE_LEDGER_MISSING", current_balance: currentBalance, total_balls: totalBalls, unspent_purchase_balls: 0 };
  }

  const spendTx = await env.DB.prepare(`
    SELECT id, amount, operation_type, open_id
    FROM ball_transactions
    WHERE user_id = ? AND id > ?
      AND amount < 0
      AND (open_id IS NULL OR open_id != ?)
    ORDER BY id ASC
    LIMIT 1
  `).bind(userId, Number(purchaseTx.id || 0), `stars_refund:${String(order.order_id)}`).first() as any;

  if (spendTx) {
    return {
      refundable: false,
      reason: "SPEND_AFTER_PURCHASE",
      current_balance: currentBalance,
      total_balls: totalBalls,
      unspent_purchase_balls: 0,
    };
  }

  if (currentBalance < totalBalls) {
    return {
      refundable: false,
      reason: "CURRENT_BALANCE_BELOW_PACK",
      current_balance: currentBalance,
      total_balls: totalBalls,
      unspent_purchase_balls: 0,
    };
  }

  return {
    refundable: true,
    reason: null,
    current_balance: currentBalance,
    total_balls: totalBalls,
    unspent_purchase_balls: totalBalls,
  };
}

async function listAdminStarOrders(env: Env, limit: number = 30): Promise<any[]> {
  if (!(await hasStarShopTables(env))) return [];
  const safeLimit = Math.max(1, Math.min(100, Number(limit || 30)));
  const res = await env.DB.prepare(`
    SELECT o.*, u.username, u.first_name, u.last_name
    FROM telegram_star_orders o
    LEFT JOIN users u ON u.id = o.user_id
    ORDER BY COALESCE(o.created_at, 0) DESC, o.order_id DESC
    LIMIT ?
  `).bind(safeLimit).all();

  const rows = (res.results || []) as any[];
  const decorated: any[] = [];
  for (const row of rows) {
    const normalized = {
      ...row,
      user_id: Number(row.user_id || 0),
      price_xtr: Number(row.price_xtr || 0),
      balls_amount: Number(row.balls_amount || 0),
      bonus_balls: Number(row.bonus_balls || 0),
      total_balls: Number(row.total_balls || 0),
    };
    const refundState = await evaluateStarOrderRefundState(env, normalized);
    decorated.push({
      ...normalized,
      refund_available: refundState.refundable,
      refund_reason: refundState.reason,
      current_balance: refundState.current_balance,
      unspent_purchase_balls: refundState.unspent_purchase_balls,
    });
  }
  return decorated;
}

async function tryGrantTaskCaseReward(
  env: Env,
  userId: number,
  seasonId: number,
  taskKey: string,
  instanceKey: string,
  progress: number,
  caseType: string,
  comment: string
): Promise<boolean> {
  const now = Date.now();
  await env.DB.prepare(`
    INSERT INTO user_task_progress (user_id, season_id, task_key, instance_key, progress, completed_at, reward_granted)
    VALUES (?, ?, ?, ?, ?, NULL, 0)
    ON CONFLICT(user_id, season_id, task_key, instance_key) DO NOTHING
  `).bind(userId, seasonId, taskKey, instanceKey, progress).run();

  const lockRes = await env.DB.prepare(`
    UPDATE user_task_progress
    SET progress = MAX(progress, ?),
        completed_at = COALESCE(completed_at, ?),
        reward_granted = 1
    WHERE user_id = ?
      AND season_id = ?
      AND task_key = ?
      AND instance_key = ?
      AND reward_granted = 0
  `).bind(progress, now, userId, seasonId, taskKey, instanceKey).run();

  if ((lockRes.meta.changes ?? 0) === 0) {
    return false;
  }

  try {
    await grantCaseToInventory(env, userId, caseType, { amount: 1, comment, now });
    return true;
  } catch (error) {
    await env.DB.prepare(`
      UPDATE user_task_progress
      SET reward_granted = 0
      WHERE user_id = ?
        AND season_id = ?
        AND task_key = ?
        AND instance_key = ?
    `).bind(userId, seasonId, taskKey, instanceKey).run();
    throw error;
  }
}

// Boost variant of tryGrantTaskCaseReward: same reward_granted 0→1 lock, so a replay
// (or a concurrent call) can never hand out a second boost. user_boosts stores ONE row
// per boost unit (status='available'); on insert failure the lock is released so a later
// call can retry. Mirrors the granting shape used by weeklyChallengeTaskClaims.ts.
async function tryGrantTaskBoostReward(
  env: Env,
  userId: number,
  seasonId: number,
  taskKey: string,
  instanceKey: string,
  progress: number,
  boostType: string
): Promise<boolean> {
  const now = Date.now();
  await env.DB.prepare(`
    INSERT INTO user_task_progress (user_id, season_id, task_key, instance_key, progress, completed_at, reward_granted)
    VALUES (?, ?, ?, ?, ?, NULL, 0)
    ON CONFLICT(user_id, season_id, task_key, instance_key) DO NOTHING
  `).bind(userId, seasonId, taskKey, instanceKey, progress).run();

  const lockRes = await env.DB.prepare(`
    UPDATE user_task_progress
    SET progress = MAX(progress, ?),
        completed_at = COALESCE(completed_at, ?),
        reward_granted = 1
    WHERE user_id = ?
      AND season_id = ?
      AND task_key = ?
      AND instance_key = ?
      AND reward_granted = 0
  `).bind(progress, now, userId, seasonId, taskKey, instanceKey).run();

  if ((lockRes.meta.changes ?? 0) === 0) {
    return false;
  }

  try {
    await env.DB.prepare(
      `INSERT INTO user_boosts (user_id, boost_type, status, purchased_at) VALUES (?, ?, 'available', ?)`
    ).bind(userId, boostType, now).run();
    return true;
  } catch (error) {
    await env.DB.prepare(`
      UPDATE user_task_progress
      SET reward_granted = 0
      WHERE user_id = ?
        AND season_id = ?
        AND task_key = ?
        AND instance_key = ?
    `).bind(userId, seasonId, taskKey, instanceKey).run();
    throw error;
  }
}

const PARTNER_TASK_TYPES = new Set<PartnerCampaignTaskType>([
  "telegram_channel_subscribe",
  "telegram_group_join",
  "telegram_bot_start",
  "external_callback_confirm",
  "miniapp_open_confirm",
]);

const PARTNER_REWARD_TYPES = new Set<PartnerRewardType>([
  "balls",
  "case",
]);

const PARTNER_ACTIVE_STATUSES = new Set<PartnerCampaignStatus>(["active"]);
const PARTNER_TELEGRAM_MEMBERSHIP_STATUSES = new Set(["member", "administrator", "creator", "restricted"]);

let partnerTablesAvailableCache: { value: boolean; expiresAt: number } | null = null;

async function hasPartnerTables(env: Env): Promise<boolean> {
  if (partnerTablesAvailableCache && partnerTablesAvailableCache.expiresAt > Date.now()) {
    return partnerTablesAvailableCache.value;
  }
  const [campaigns, claims, events, rewardLogs] = await Promise.all([
    hasTable(env, "partner_campaigns"),
    hasTable(env, "partner_claims"),
    hasTable(env, "partner_events"),
    hasTable(env, "partner_reward_logs"),
  ]);
  const value = campaigns && claims && events && rewardLogs;
  partnerTablesAvailableCache = { value, expiresAt: Date.now() + SCHEMA_SUPPORT_TTL_MS };
  return value;
}

function parsePartnerJson(value: unknown): any | null {
  if (value == null || value === "" || value === "null") return null;
  if (typeof value === "object") return value;
  try {
    return JSON.parse(String(value));
  } catch {
    return null;
  }
}

function cleanPartnerUsername(value: unknown): string {
  return String(value || "").trim().replace(/^@+/, "");
}

// Length-independent-branch comparison for partner callback secrets. Avoids a
// short-circuit timing oracle on `===`. (Length itself is not treated as secret.)
function timingSafeEqualStr(a: string, b: string): boolean {
  const enc = new TextEncoder();
  const ba = enc.encode(a);
  const bb = enc.encode(b);
  if (ba.length !== bb.length) return false;
  let diff = 0;
  for (let i = 0; i < ba.length; i++) diff |= ba[i] ^ bb[i];
  return diff === 0;
}

function parsePartnerTimestamp(value: unknown, fieldName: string): number | null {
  if (value == null || value === "") return null;
  if (typeof value === "number" && Number.isFinite(value)) return Math.trunc(value);
  const raw = String(value).trim();
  if (!raw) return null;
  if (/^\d+$/.test(raw)) return Number(raw);
  const parsed = Date.parse(raw);
  if (!Number.isFinite(parsed)) throw new Error(`INVALID_${fieldName.toUpperCase()}`);
  return parsed;
}

function buildPartnerRewardMeta(campaign: {
  reward_type: PartnerCampaignRow["reward_type"];
  reward_amount: PartnerCampaignRow["reward_amount"];
  reward_payload_json?: PartnerCampaignRow["reward_payload_json"];
}) {
  const payload = parsePartnerJson(campaign.reward_payload_json) || {};
  const amount = Math.max(0, Number(campaign.reward_amount || 0));
  const caseType = String(payload.caseType || payload.case_type || "").trim();
  const label = (() => {
    if (campaign.reward_type === "balls") return `${amount} мяч${amount === 1 ? "" : amount >= 2 && amount <= 4 ? "а" : "ей"}`;
    if (campaign.reward_type === "case") {
      const readable = caseType === "premium" ? "Премиум-кейс" : caseType === "daily_free" ? "Ежедневный кейс" : caseType ? `Кейс: ${caseType}` : "Кейс";
      return amount > 1 ? `${readable} x${amount}` : readable;
    }
    return String(payload.label || payload.title || "Награда");
  })();
  return { amount, payload, caseType, label };
}

function getPartnerHoldMessage(holdHours: number): string {
  if (holdHours <= 0) return "Награда будет начислена сразу после подтверждения.";
  return `Награда будет начислена после повторной проверки в течение ${holdHours} ч.`;
}

function appendQueryParams(url: string, params: Record<string, string>): string {
  const separator = url.includes("?") ? "&" : "?";
  const suffix = Object.entries(params)
    .filter(([, value]) => value)
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
    .join("&");
  return suffix ? `${url}${separator}${suffix}` : url;
}

function canOpenPartnerCampaign(campaign: PartnerCampaignRow, now: number) {
  if (Number(campaign.is_visible || 0) !== 1) {
    return { allowed: false, status: "unavailable" as PartnerUserStatus, reason: "Кампания сейчас скрыта." };
  }
  if (campaign.status === "paused" || campaign.status === "draft" || campaign.status === "archived") {
    return { allowed: false, status: "unavailable" as PartnerUserStatus, reason: "Кампания сейчас недоступна." };
  }
  if (campaign.status === "ended") {
    return { allowed: false, status: "expired" as PartnerUserStatus, reason: "Кампания завершена." };
  }
  if (campaign.starts_at && now < Number(campaign.starts_at)) {
    return { allowed: false, status: "unavailable" as PartnerUserStatus, reason: "Кампания ещё не началась." };
  }
  if (campaign.ends_at && now > Number(campaign.ends_at)) {
    return { allowed: false, status: "expired" as PartnerUserStatus, reason: "Срок выполнения кампании истёк." };
  }
  if (campaign.max_total_claims && Number(campaign.completed_claims_count || 0) >= Number(campaign.max_total_claims)) {
    return { allowed: false, status: "unavailable" as PartnerUserStatus, reason: "Лимит по кампании уже исчерпан." };
  }
  if (!PARTNER_ACTIVE_STATUSES.has(campaign.status)) {
    return { allowed: false, status: "unavailable" as PartnerUserStatus, reason: "Кампания недоступна." };
  }
  return { allowed: true, status: "available" as PartnerUserStatus, reason: "" };
}

function mapPartnerClaimToUserStatus(
  campaign: PartnerCampaignRow,
  claim: PartnerClaimRow | null,
  now: number
): PartnerUserStatus {
  if (claim?.status === "completed") return "completed";
  if (claim?.status === "pending_hold") return "pending_hold";
  if (claim?.status === "expired") return "expired";
  if (claim?.status === "revoked") {
    return campaign.ends_at && now > Number(campaign.ends_at) ? "expired" : "unavailable";
  }
  if (claim?.status === "started" || claim?.status === "verified" || claim?.status === "failed") {
    return "in_progress";
  }
  return canOpenPartnerCampaign(campaign, now).status;
}

async function insertPartnerEvent(
  env: Env,
  campaignId: number,
  userId: number,
  claimId: number | null,
  eventType: string,
  payload?: Record<string, unknown>
) {
  if (!(await hasPartnerTables(env))) return;
  await env.DB.prepare(`
    INSERT INTO partner_events (campaign_id, user_id, claim_id, event_type, payload_json, created_at)
    VALUES (?, ?, ?, ?, ?, ?)
  `).bind(
    campaignId,
    userId,
    claimId,
    eventType,
    payload ? JSON.stringify(payload) : null,
    Date.now()
  ).run();
}

async function getPartnerCampaignById(env: Env, campaignId: number): Promise<PartnerCampaignRow | null> {
  if (!(await hasPartnerTables(env))) return null;
  const row = await env.DB.prepare(`SELECT * FROM partner_campaigns WHERE id = ?`).bind(campaignId).first();
  return (row as PartnerCampaignRow | null) || null;
}

async function getPartnerClaim(env: Env, campaignId: number, userId: number): Promise<PartnerClaimRow | null> {
  if (!(await hasPartnerTables(env))) return null;
  const row = await env.DB.prepare(`
    SELECT * FROM partner_claims
    WHERE campaign_id = ? AND user_id = ?
  `).bind(campaignId, userId).first();
  return (row as PartnerClaimRow | null) || null;
}

async function ensurePartnerClaimStarted(env: Env, campaignId: number, userId: number): Promise<PartnerClaimRow> {
  const existing = await getPartnerClaim(env, campaignId, userId);
  if (existing) return existing;

  const now = Date.now();
  const verifyToken = crypto.randomUUID();
  await env.DB.prepare(`
    INSERT INTO partner_claims (
      campaign_id, user_id, verify_token, status, started_at, created_at, updated_at
    ) VALUES (?, ?, ?, 'started', ?, ?, ?)
  `).bind(campaignId, userId, verifyToken, now, now, now).run();

  const created = await getPartnerClaim(env, campaignId, userId);
  if (!created) throw new Error("PARTNER_CLAIM_CREATE_FAILED");
  return created;
}

async function updatePartnerClaimState(
  env: Env,
  claimId: number,
  patch: {
    status?: PartnerClaimStatus;
    verifiedAt?: number | null;
    holdUntil?: number | null;
    completedAt?: number | null;
    rewardGrantedAt?: number | null;
    failedReason?: string | null;
    verificationPayload?: Record<string, unknown> | null;
  }
) {
  const sets: string[] = ["updated_at = ?"];
  const values: any[] = [Date.now()];
  if (patch.status) {
    sets.push("status = ?");
    values.push(patch.status);
  }
  if (patch.verifiedAt !== undefined) {
    sets.push("verified_at = ?");
    values.push(patch.verifiedAt);
  }
  if (patch.holdUntil !== undefined) {
    sets.push("hold_until = ?");
    values.push(patch.holdUntil);
  }
  if (patch.completedAt !== undefined) {
    sets.push("completed_at = ?");
    values.push(patch.completedAt);
  }
  if (patch.rewardGrantedAt !== undefined) {
    sets.push("reward_granted_at = ?");
    values.push(patch.rewardGrantedAt);
  }
  if (patch.failedReason !== undefined) {
    sets.push("failed_reason = ?");
    values.push(patch.failedReason);
  }
  if (patch.verificationPayload !== undefined) {
    sets.push("verification_payload_json = ?");
    values.push(patch.verificationPayload ? JSON.stringify(patch.verificationPayload) : null);
  }
  values.push(claimId);
  await env.DB.prepare(`UPDATE partner_claims SET ${sets.join(", ")} WHERE id = ?`).bind(...values).run();
}

async function getPartnerCampaignStats(env: Env, campaignId: number) {
  const res = await env.DB.prepare(`
    SELECT status, COUNT(*) as cnt
    FROM partner_claims
    WHERE campaign_id = ?
    GROUP BY status
  `).bind(campaignId).all();
  const stats = {
    started: 0,
    pending_hold: 0,
    completed: 0,
    failed: 0,
    revoked: 0,
    expired: 0,
  };
  for (const row of (res.results || []) as any[]) {
    const key = String(row.status || "") as keyof typeof stats;
    if (key in stats) stats[key] = Number(row.cnt || 0);
  }
  return stats;
}

async function verifyTelegramMembershipForCampaign(
  env: Env,
  campaign: PartnerCampaignRow,
  userId: number
): Promise<{ verified: boolean; payload: Record<string, unknown>; fatalReason?: string }> {
  const chatId = String(campaign.telegram_chat_id || "").trim();
  if (!chatId) return { verified: false, payload: {}, fatalReason: "CHAT_ID_MISSING" };

  const res = await telegramBotApi(env, "getChatMember", { chat_id: chatId, user_id: userId });
  const description = String(res.body?.description || "");
  if (!res.ok) {
    if (description.includes("chat not found") || description.includes("have no rights")) {
      return {
        verified: false,
        payload: { telegram_status: null, description },
        fatalReason: "BOT_CANNOT_VERIFY_MEMBERSHIP",
      };
    }
    return {
      verified: false,
      payload: { telegram_status: null, description },
      fatalReason: "TELEGRAM_VERIFY_FAILED",
    };
  }

  const member = res.body?.result || {};
  const status = String(member.status || "").toLowerCase();
  const isMember =
    PARTNER_TELEGRAM_MEMBERSHIP_STATUSES.has(status)
    && !(status === "restricted" && member.is_member === false);
  return {
    verified: isMember,
    payload: {
      telegram_status: status || null,
      chat_id: chatId,
      checked_at: Date.now(),
    },
  };
}

async function verifyPartnerCampaignCompletion(
  env: Env,
  campaign: PartnerCampaignRow,
  claim: PartnerClaimRow,
  userId: number
): Promise<{ verified: boolean; payload: Record<string, unknown>; fatalReason?: string }> {
  if (campaign.task_type === "telegram_channel_subscribe" || campaign.task_type === "telegram_group_join") {
    return verifyTelegramMembershipForCampaign(env, campaign, userId);
  }

  if (campaign.task_type === "telegram_bot_start") {
    const row = await env.DB.prepare(`
      SELECT id, created_at
      FROM partner_events
      WHERE claim_id = ?
        AND campaign_id = ?
        AND user_id = ?
        AND event_type = 'partner_task_verified'
      ORDER BY created_at DESC
      LIMIT 1
    `).bind(claim.id, campaign.id, userId).first() as any;
    return {
      verified: !!row,
      payload: { event_id: row?.id ?? null, event_created_at: row?.created_at ?? null },
    };
  }

  if (campaign.task_type === "external_callback_confirm" || campaign.task_type === "miniapp_open_confirm") {
    const row = await env.DB.prepare(`
      SELECT id, created_at, payload_json
      FROM partner_events
      WHERE claim_id = ?
        AND campaign_id = ?
        AND user_id = ?
        AND event_type = 'partner_task_verified'
      ORDER BY created_at DESC
      LIMIT 1
    `).bind(claim.id, campaign.id, userId).first() as any;
    return {
      verified: !!row,
      payload: row?.payload_json ? (parsePartnerJson(row.payload_json) || {}) : {},
    };
  }

  return { verified: false, payload: {}, fatalReason: "UNSUPPORTED_PARTNER_TASK_TYPE" };
}

async function reservePartnerCampaignCompletion(env: Env, campaign: PartnerCampaignRow): Promise<boolean> {
  const hasLimit = Number(campaign.max_total_claims || 0) > 0;
  if (!hasLimit) return true;
  const res = await env.DB.prepare(`
    UPDATE partner_campaigns
    SET completed_claims_count = completed_claims_count + 1,
        updated_at = ?
    WHERE id = ?
      AND completed_claims_count < max_total_claims
  `).bind(Date.now(), campaign.id).run();
  return Number(res.meta.changes || 0) > 0;
}

async function rollbackPartnerCampaignCompletionReservation(env: Env, campaignId: number) {
  await env.DB.prepare(`
    UPDATE partner_campaigns
    SET completed_claims_count = CASE
      WHEN completed_claims_count > 0 THEN completed_claims_count - 1
      ELSE 0
    END,
        updated_at = ?
    WHERE id = ?
  `).bind(Date.now(), campaignId).run();
}

async function grantPartnerCampaignReward(
  env: Env,
  campaign: PartnerCampaignRow,
  claim: PartnerClaimRow
) {
  const reward = buildPartnerRewardMeta(campaign);
  const now = Date.now();
  const existingLog = await env.DB.prepare(`
    SELECT id, status
    FROM partner_reward_logs
    WHERE claim_id = ?
    LIMIT 1
  `).bind(claim.id).first() as any;

  if (existingLog?.status === "completed") {
    return false;
  }

  // A pending reward log (UNIQUE(claim_id)) is the authoritative reservation FACT + immutable reward
  // snapshot for a claim. Ownership of the campaign quota slot is decided ATOMICALLY by a conditional
  // transition: only the attempt whose INSERT-OR-IGNORE (no log) or `failed→pending` conditional
  // UPDATE reports meta.changes === 1 owns — and may reserve / later roll back — the slot. Losing
  // concurrent attempts piggy-back on the (already pending) log and deliver idempotently without ever
  // touching the counter. The reward snapshot is written ONLY on the first INSERT and is NEVER
  // rewritten on retry, so a campaign edit after a claim's log exists cannot change that claim's reward.
  let reservationCreatedByThisAttempt = false;

  if (existingLog?.status === "failed") {
    // Re-activate failed → pending. STATUS-ONLY: the original reward snapshot is preserved untouched.
    const react = await env.DB.prepare(
      `UPDATE partner_reward_logs SET status = 'pending' WHERE claim_id = ? AND status = 'failed'`
    ).bind(claim.id).run();
    reservationCreatedByThisAttempt = Number(react.meta.changes || 0) === 1;
  } else if (!existingLog) {
    const logInsert = await env.DB.prepare(`
      INSERT OR IGNORE INTO partner_reward_logs (
        claim_id, campaign_id, user_id, reward_type, reward_amount, reward_payload_json, status, created_at
      ) VALUES (?, ?, ?, ?, ?, ?, 'pending', ?)
    `).bind(
      claim.id,
      campaign.id,
      claim.user_id,
      campaign.reward_type,
      reward.amount,
      campaign.reward_payload_json || null,
      now
    ).run();
    reservationCreatedByThisAttempt = Number(logInsert.meta.changes || 0) === 1;
  }
  // else: existingLog.status === 'pending' → crash recovery; reservation already held by the owner.

  // AUTHORITATIVE, IMMUTABLE reward snapshot + current status (also resolves lost concurrent races).
  // Grant from the pending reward log, never from the (possibly-mutated) live campaign.
  const snap = await env.DB.prepare(`
    SELECT status, reward_type, reward_amount, reward_payload_json FROM partner_reward_logs WHERE claim_id = ?
  `).bind(claim.id).first() as any;
  if (!snap) throw new Error("PARTNER_REWARD_LOG_MISSING");
  if (snap.status === "completed") {
    // A concurrent attempt already completed delivery from the pending log. If we owned the slot it
    // correctly accounts for that single completion → nothing to roll back; just no-op.
    return false;
  }
  if (snap.status === "failed") {
    // We neither own the reactivation nor is the log pending → controlled retry conflict; never grant
    // on a failed snapshot.
    throw new Error("PARTNER_REWARD_RETRY_CONFLICT");
  }
  // snap.status === 'pending' — proceed (owner OR a loser/recovery piggy-backing on the pending log).
  const effectiveRewardType = String(snap.reward_type || "") as PartnerRewardType;
  const effectiveReward = buildPartnerRewardMeta({
    reward_type: effectiveRewardType,
    reward_amount: Number(snap.reward_amount || 0),
    reward_payload_json: snap.reward_payload_json ?? null,
  });
  const effectiveAmount = effectiveReward.amount;

  // Reserve a campaign slot ONLY when this attempt created the reservation. A crash-recovery
  // attempt reuses the already-counted slot → no double increment / no counter drift.
  if (reservationCreatedByThisAttempt) {
    const reserved = await reservePartnerCampaignCompletion(env, campaign);
    if (!reserved) {
      await env.DB.prepare(`UPDATE partner_reward_logs SET status = 'failed' WHERE claim_id = ?`).bind(claim.id).run();
      throw new Error("PARTNER_CAMPAIGN_LIMIT_REACHED");
    }
  }

  try {
    if (effectiveRewardType === "balls") {
      // Stage 8 — atomic + idempotent balls grant. The non-idempotent `balls += ?`
      // is committed in ONE transactional db.batch together with the ledger
      // transition, both guarded by `status='pending'`. So balls are applied iff the
      // ledger moves pending→completed, exactly once; a retry / concurrent run on an
      // already-completed ledger is a no-op (0 changes). Amount comes from the immutable snapshot.
      const ballsBatch = await env.DB.batch([
        env.DB.prepare(`UPDATE users SET balls = balls + ? WHERE id = ? AND EXISTS (SELECT 1 FROM partner_reward_logs WHERE claim_id = ? AND status = 'pending')`).bind(effectiveAmount, claim.user_id, claim.id),
        env.DB.prepare(`UPDATE partner_reward_logs SET status = 'completed' WHERE claim_id = ? AND status = 'pending'`).bind(claim.id),
        env.DB.prepare(`UPDATE partner_claims SET status = 'completed', completed_at = ?, reward_granted_at = ?, failed_reason = NULL, updated_at = ? WHERE id = ?`).bind(now, now, now, claim.id),
      ]);
      const granted = Number(ballsBatch?.[1]?.meta?.changes || 0) > 0;
      if (granted) {
        await insertPartnerEvent(env, campaign.id, claim.user_id, claim.id, "partner_task_rewarded", {
          rewardType: effectiveRewardType,
          rewardAmount: effectiveAmount,
        });
      }
      // NOTE: no rollback in the not-granted branch. In this model a slot is reserved by exactly ONE
      // owner per claim; if this attempt did not move the ledger pending→completed, a concurrent
      // attempt (the reservation owner OR a piggy-backing recovery worker) already did, so the single
      // reserved slot correctly accounts for that single completion. Releasing it here would drift the
      // counter to 0 for a real completion. Genuine non-delivery is handled by the catch (real error).
      return granted;
    } else if (effectiveRewardType === "case") {
      if (!effectiveReward.caseType) throw new Error("PARTNER_CASE_TYPE_REQUIRED");
      // Crash-safe idempotent grant: a stable claim-derived key makes a retry after a mid-flight
      // crash a no-op (alreadyGranted) instead of a second case. The shared completion below then
      // safely re-drives the reward log / claim to completed.
      await grantCaseToInventory(env, claim.user_id, effectiveReward.caseType, {
        amount: effectiveAmount || 1,
        comment: `partner_campaign:${campaign.id}:claim:${claim.id}`,
        now,
        idempotencyKey: buildPartnerCaseRewardIdempotencyKey(claim.id),
      });
    } else {
      throw new Error("PARTNER_REWARD_TYPE_NOT_ALLOWED");
    }

    await env.DB.prepare(`
      UPDATE partner_reward_logs
      SET status = 'completed'
      WHERE claim_id = ?
    `).bind(claim.id).run();

    await updatePartnerClaimState(env, claim.id, {
      status: "completed",
      completedAt: now,
      rewardGrantedAt: now,
      failedReason: null,
    });
    await insertPartnerEvent(env, campaign.id, claim.user_id, claim.id, "partner_task_rewarded", {
      rewardType: effectiveRewardType,
      rewardAmount: effectiveAmount,
    });
    return true;
  } catch (error) {
    // Only the attempt that created the reservation may release it — a recovery attempt that fails
    // must not decrement a slot owned by the original attempt.
    if (reservationCreatedByThisAttempt) {
      await rollbackPartnerCampaignCompletionReservation(env, campaign.id);
    }
    await env.DB.prepare(`
      UPDATE partner_reward_logs
      SET status = 'failed'
      WHERE claim_id = ?
    `).bind(claim.id).run();
    throw error;
  }
}

async function validatePartnerCampaignConfiguration(
  env: Env,
  campaign: Partial<PartnerCampaignRow>,
  opts?: { requireActivationReady?: boolean }
): Promise<{ ok: boolean; error?: string; payload?: Record<string, unknown>; normalizedUsername?: string | null }> {
  const taskType = String(campaign.task_type || "") as PartnerCampaignTaskType;
  const rewardType = String(campaign.reward_type || "") as PartnerRewardType;
  const payload = parsePartnerJson(campaign.reward_payload_json) || {};
  const requireActivationReady = !!opts?.requireActivationReady;

  if (!PARTNER_TASK_TYPES.has(taskType)) return { ok: false, error: "INVALID_PARTNER_TASK_TYPE" };
  if (!PARTNER_REWARD_TYPES.has(rewardType)) return { ok: false, error: "INVALID_PARTNER_REWARD_TYPE" };
  if (!String(campaign.title || "").trim()) return { ok: false, error: "PARTNER_TITLE_REQUIRED" };
  if (Number(campaign.max_claims_per_user || 1) !== 1) return { ok: false, error: "PARTNER_MAX_PER_USER_FIXED_TO_ONE" };
  if (rewardType === "balls" && Number(campaign.reward_amount || 0) <= 0) return { ok: false, error: "PARTNER_BALL_REWARD_REQUIRED" };
  if (rewardType === "case" && !String(payload.caseType || payload.case_type || "").trim()) return { ok: false, error: "PARTNER_CASE_TYPE_REQUIRED" };

  const deepLink = String(campaign.deep_link || "").trim();
  const normalizedUsername = cleanPartnerUsername(campaign.telegram_username);

  if (taskType === "telegram_channel_subscribe" || taskType === "telegram_group_join") {
    if (!String(campaign.telegram_chat_id || "").trim()) return { ok: false, error: "PARTNER_TELEGRAM_CHAT_ID_REQUIRED" };
    if (!deepLink && !normalizedUsername) return { ok: false, error: "PARTNER_TELEGRAM_LINK_REQUIRED" };
    if (requireActivationReady) {
      const botIdentity = await getTelegramBotIdentity(env);
      const chatCheck = await telegramBotApi(env, "getChat", { chat_id: campaign.telegram_chat_id });
      if (!chatCheck.ok) return { ok: false, error: "PARTNER_TELEGRAM_CHAT_UNAVAILABLE" };
      const accessCheck = await telegramBotApi(env, "getChatMember", { chat_id: campaign.telegram_chat_id, user_id: botIdentity.id });
      const status = String(accessCheck.body?.result?.status || "").toLowerCase();
      if (!accessCheck.ok || !["administrator", "creator"].includes(status)) {
        return { ok: false, error: "BOT_NOT_ADMIN_IN_PARTNER_CHAT" };
      }
      return {
        ok: true,
        normalizedUsername: normalizedUsername || cleanPartnerUsername(chatCheck.body?.result?.username),
        payload: {
          chatTitle: chatCheck.body?.result?.title || null,
          chatType: chatCheck.body?.result?.type || null,
          botStatus: status,
        },
      };
    }
    return { ok: true, normalizedUsername: normalizedUsername || null };
  }

  if (taskType === "telegram_bot_start") {
    const botUsername = cleanPartnerUsername(campaign.bot_username);
    if (!botUsername) return { ok: false, error: "PARTNER_BOT_USERNAME_REQUIRED" };
    if (requireActivationReady) {
      const botIdentity = await getTelegramBotIdentity(env);
      if (cleanPartnerUsername(botIdentity.username) !== botUsername) {
        return { ok: false, error: "PARTNER_BOT_START_REQUIRES_LOCAL_BOT" };
      }
      return { ok: true, payload: { botUsername } };
    }
    return { ok: true, payload: { botUsername } };
  }

  if (!deepLink) return { ok: false, error: "PARTNER_DEEP_LINK_REQUIRED" };
  if (requireActivationReady && !String(campaign.verification_secret || "").trim()) {
    return { ok: false, error: "PARTNER_CALLBACK_SECRET_REQUIRED" };
  }
  return { ok: true };
}

function normalizePartnerCampaignPayload(body: any, existing?: PartnerCampaignRow | null) {
  const taskType = String(body?.task_type ?? existing?.task_type ?? "").trim() as PartnerCampaignTaskType;
  const rewardType = String(body?.reward_type ?? existing?.reward_type ?? "").trim() as PartnerRewardType;
  const rawRewardPayload = body?.reward_payload ?? parsePartnerJson(body?.reward_payload_json) ?? parsePartnerJson(existing?.reward_payload_json) ?? null;
  const normalizedRewardPayload = rawRewardPayload ? JSON.stringify(rawRewardPayload) : null;
  const status = String(body?.status ?? existing?.status ?? "draft").trim() as PartnerCampaignStatus;
  const holdHours = Math.max(0, Number(body?.hold_hours ?? existing?.hold_hours ?? 24));
  const maxTotalClaimsRaw = body?.max_total_claims ?? existing?.max_total_claims ?? null;
  const maxClaimsPerUserRaw = body?.max_claims_per_user ?? existing?.max_claims_per_user ?? 1;

  const next: Partial<PartnerCampaignRow> = {
    title: String(body?.title ?? existing?.title ?? "").trim(),
    description: String(body?.description ?? existing?.description ?? "").trim(),
    sponsor_name: String(body?.sponsor_name ?? existing?.sponsor_name ?? "").trim(),
    badge_text: body?.badge_text != null ? String(body.badge_text).trim() : (existing?.badge_text ?? "Партнерское"),
    ad_badge_text: body?.ad_badge_text != null ? String(body.ad_badge_text).trim() : (existing?.ad_badge_text ?? "Реклама"),
    task_type: taskType,
    source_type: String(body?.source_type ?? existing?.source_type ?? "telegram").trim(),
    telegram_chat_id: body?.telegram_chat_id != null ? String(body.telegram_chat_id).trim() : (existing?.telegram_chat_id ?? null),
    telegram_username: body?.telegram_username != null ? cleanPartnerUsername(body.telegram_username) : (existing?.telegram_username ?? null),
    bot_username: body?.bot_username != null ? cleanPartnerUsername(body.bot_username) : (existing?.bot_username ?? null),
    deep_link: body?.deep_link != null ? String(body.deep_link).trim() : (existing?.deep_link ?? null),
    verification_secret: body?.verification_secret != null
      ? String(body.verification_secret).trim()
      : (existing?.verification_secret || (taskType === "external_callback_confirm" || taskType === "miniapp_open_confirm" ? crypto.randomUUID() : null)),
    reward_type: rewardType,
    reward_amount: Math.max(0, Number(body?.reward_amount ?? existing?.reward_amount ?? 0)),
    reward_payload_json: normalizedRewardPayload,
    hold_hours: holdHours,
    starts_at: body?.starts_at !== undefined ? parsePartnerTimestamp(body.starts_at, "starts_at") : (existing?.starts_at ?? null),
    ends_at: body?.ends_at !== undefined ? parsePartnerTimestamp(body.ends_at, "ends_at") : (existing?.ends_at ?? null),
    max_total_claims: maxTotalClaimsRaw == null || maxTotalClaimsRaw === "" ? null : Math.max(1, Number(maxTotalClaimsRaw)),
    max_claims_per_user: maxClaimsPerUserRaw == null || maxClaimsPerUserRaw === "" ? 1 : Math.max(1, Number(maxClaimsPerUserRaw)),
    status,
    is_visible: body?.is_visible != null ? (Number(body.is_visible) === 1 || body.is_visible === true ? 1 : 0) : Number(existing?.is_visible ?? 1),
    sort_order: Number(body?.sort_order ?? existing?.sort_order ?? 100),
  };

  if (next.starts_at && next.ends_at && Number(next.ends_at) <= Number(next.starts_at)) {
    throw new Error("PARTNER_END_BEFORE_START");
  }

  return next;
}

async function buildPartnerCampaignAdminRow(env: Env, campaign: PartnerCampaignRow) {
  const [stats, recentFailuresRes] = await Promise.all([
    getPartnerCampaignStats(env, Number(campaign.id)),
    env.DB.prepare(`
      SELECT failed_reason, updated_at
      FROM partner_claims
      WHERE campaign_id = ?
        AND failed_reason IS NOT NULL
      ORDER BY updated_at DESC
      LIMIT 5
    `).bind(campaign.id).all(),
  ]);

  return {
    ...campaign,
    reward_payload: parsePartnerJson(campaign.reward_payload_json) || null,
    validation_payload: parsePartnerJson(campaign.validation_payload_json) || null,
    stats,
    recent_errors: (recentFailuresRes.results || []) as any[],
  };
}

function resolvePartnerCampaignActionUrl(campaign: PartnerCampaignRow, claim: PartnerClaimRow): string {
  const username = cleanPartnerUsername(campaign.telegram_username);
  const botUsername = cleanPartnerUsername(campaign.bot_username);

  if (campaign.task_type === "telegram_channel_subscribe" || campaign.task_type === "telegram_group_join") {
    return String(campaign.deep_link || "").trim() || (username ? `https://t.me/${username}` : "");
  }

  if (campaign.task_type === "telegram_bot_start") {
    return botUsername ? `https://t.me/${botUsername}?start=partner_${claim.id}_${claim.verify_token}` : "";
  }

  const base = String(campaign.deep_link || "").trim();
  if (!base) return "";
  return appendQueryParams(base, {
    campaign_id: String(campaign.id),
    claim_id: String(claim.id),
    claim_token: claim.verify_token,
  });
}

function getPartnerStatusText(status: PartnerUserStatus, holdHours: number, failedReason?: string | null) {
  if (failedReason === "HOLD_RECHECK_FAILED") {
    return "Подписка не сохранилась до конца hold-периода. Награда по этой кампании больше недоступна.";
  }
  if (failedReason === "PARTNER_CLAIM_LOCKED") {
    return "Эта партнерская задача уже закрыта и больше не может быть подтверждена.";
  }
  switch (status) {
    case "available":
      return getPartnerHoldMessage(holdHours);
    case "in_progress":
      if (failedReason === "BOT_CANNOT_VERIFY_MEMBERSHIP" || failedReason === "TELEGRAM_VERIFY_FAILED") {
        return "Мы не смогли проверить выполнение. Проверьте, что бот всё ещё имеет доступ к партнёрскому чату.";
      }
      return "Сначала перейдите по ссылке, затем вернитесь и нажмите «Проверить».";
    case "pending_hold":
      return `Подписка подтверждена. Награда будет начислена после повторной проверки через ${holdHours} ч.`;
    case "completed":
      return "Награда уже начислена.";
    case "expired":
      return "Срок выполнения кампании истёк.";
    case "unavailable":
    default:
      return "Кампания сейчас недоступна.";
  }
}

async function buildPartnerCampaignCard(
  env: Env,
  campaign: PartnerCampaignRow,
  claim: PartnerClaimRow | null,
  userId: number
) {
  const now = Date.now();
  const uiStatus = mapPartnerClaimToUserStatus(campaign, claim, now);
  const availability = canOpenPartnerCampaign(campaign, now);
  const reward = buildPartnerRewardMeta(campaign);
  const actionUrl = claim ? resolvePartnerCampaignActionUrl(campaign, claim) : "";

  return {
    id: campaign.id,
    category: "partner",
    title: campaign.title,
    description: campaign.description,
    sponsorName: campaign.sponsor_name,
    taskType: campaign.task_type,
    badge: String(campaign.badge_text || "Партнерское").trim(),
    adBadge: String(campaign.ad_badge_text || "").trim(),
    reward: {
      type: campaign.reward_type,
      amount: reward.amount,
      label: reward.label,
      payload: reward.payload,
    },
    status: uiStatus,
    statusText: getPartnerStatusText(uiStatus, Number(campaign.hold_hours || 0), claim?.failed_reason || campaign.last_validation_error),
    holdHours: Number(campaign.hold_hours || 0),
    holdUntil: claim?.hold_until ?? null,
    actionUrl,
    startsAt: campaign.starts_at ?? null,
    endsAt: campaign.ends_at ?? null,
    claim: claim
      ? {
          id: claim.id,
          status: claim.status,
          startedAt: claim.started_at ?? null,
          verifiedAt: claim.verified_at ?? null,
          completedAt: claim.completed_at ?? null,
          failedReason: claim.failed_reason ?? null,
        }
      : null,
    isVisible: Number(campaign.is_visible || 0) === 1,
    isAvailable: availability.allowed,
    canVerify: !!claim && ["started", "failed", "verified", "pending_hold"].includes(claim.status),
    verificationError: claim?.failed_reason || campaign.last_validation_error || null,
    source: {
      telegramUsername: cleanPartnerUsername(campaign.telegram_username) || null,
      botUsername: cleanPartnerUsername(campaign.bot_username) || null,
      deepLink: campaign.deep_link || null,
    },
    impressionEvent: "partner_task_impression",
  };
}

/**
 * Партнёрское задание для плашки на главной: первое видимое и доступное этому
 * пользователю.
 *
 * Зачем отдельно от `GET /quests/partner`: тот роут на каждый вызов пишет
 * импрешен по всем кампаниям, и дёргать его с главной означало бы накручивать
 * статистику и писать в D1 на каждое открытие приложения. Здесь только чтение
 * и не больше пяти строк — выполненные и недоступные кампании отсеиваются, и
 * плашка сама исчезает у того, кто уже забрал награду.
 */
async function buildPartnerPromoPayload(env: Env, userId: number) {
  if (!(await hasPartnerTables(env))) return null;
  const res = await env.DB.prepare(`
    SELECT c.*, pc.id AS claim_id, pc.status AS claim_status, pc.hold_until AS claim_hold_until
    FROM partner_campaigns c
    LEFT JOIN partner_claims pc ON pc.campaign_id = c.id AND pc.user_id = ?
    WHERE c.is_visible = 1 AND c.status != 'archived'
    ORDER BY c.sort_order ASC, c.id ASC
    LIMIT 5
  `).bind(userId).all();

  const now = Date.now();
  for (const row of (res.results || []) as any[]) {
    const claim = row.claim_id
      ? ({ id: row.claim_id, status: row.claim_status, hold_until: row.claim_hold_until } as PartnerClaimRow)
      : null;
    const status = mapPartnerClaimToUserStatus(row as PartnerCampaignRow, claim, now);
    // Плашка зовёт начать задание, поэтому показываем только то, что ещё можно
    // выполнить: «на проверке» и «выполнено» звать уже некуда.
    if (status !== "available" && status !== "in_progress") continue;
    const reward = buildPartnerRewardMeta(row as PartnerCampaignRow);
    return {
      id: Number(row.id),
      title: String(row.title || ""),
      taskType: String(row.task_type || ""),
      status,
      reward: { type: String(row.reward_type || ""), amount: reward.amount, label: reward.label },
    };
  }
  return null;
}

async function completePartnerClaimAfterVerification(
  env: Env,
  campaign: PartnerCampaignRow,
  claim: PartnerClaimRow,
  payload: Record<string, unknown>,
  opts?: { verifiedAt?: number }
) {
  const now = Date.now();
  const verifiedAt = opts?.verifiedAt ?? now;
  const holdHours = Math.max(0, Number(campaign.hold_hours || 0));
  if (holdHours > 0) {
    const holdUntil = now + holdHours * 60 * 60 * 1000;
    await updatePartnerClaimState(env, claim.id, {
      status: "pending_hold",
      verifiedAt,
      holdUntil,
      failedReason: null,
      verificationPayload: payload,
    });
    await insertPartnerEvent(env, campaign.id, claim.user_id, claim.id, "partner_task_verified", payload);
    await insertPartnerEvent(env, campaign.id, claim.user_id, claim.id, "partner_task_pending_hold", {
      holdUntil,
      holdHours,
    });
    return { status: "pending_hold" as PartnerClaimStatus, holdUntil };
  }

  await updatePartnerClaimState(env, claim.id, {
    status: "verified",
    verifiedAt,
    failedReason: null,
    verificationPayload: payload,
  });
  await insertPartnerEvent(env, campaign.id, claim.user_id, claim.id, "partner_task_verified", payload);
  await grantPartnerCampaignReward(env, campaign, claim);
  await insertPartnerEvent(env, campaign.id, claim.user_id, claim.id, "partner_task_completed", {
    completedAt: Date.now(),
  });
  return { status: "completed" as PartnerClaimStatus, holdUntil: null };
}

async function processPendingPartnerClaim(
  env: Env,
  claim: PartnerClaimRow,
  campaign: PartnerCampaignRow
) {
  const verification = await verifyPartnerCampaignCompletion(env, campaign, claim, claim.user_id);
  if (verification.fatalReason) {
    await updatePartnerClaimState(env, claim.id, {
      status: "failed",
      failedReason: verification.fatalReason,
      verificationPayload: verification.payload,
    });
    await insertPartnerEvent(env, campaign.id, claim.user_id, claim.id, "partner_task_failed", {
      reason: verification.fatalReason,
    });
    return;
  }

  if (!verification.verified) {
    await updatePartnerClaimState(env, claim.id, {
      status: "revoked",
      failedReason: "HOLD_RECHECK_FAILED",
      verificationPayload: verification.payload,
    });
    await insertPartnerEvent(env, campaign.id, claim.user_id, claim.id, "partner_task_failed", {
      reason: "HOLD_RECHECK_FAILED",
    });
    return;
  }

  await updatePartnerClaimState(env, claim.id, {
    status: "verified",
    verifiedAt: Date.now(),
    failedReason: null,
    verificationPayload: verification.payload,
  });
  await grantPartnerCampaignReward(env, campaign, claim);
  await insertPartnerEvent(env, campaign.id, claim.user_id, claim.id, "partner_task_completed", {
    completedAt: Date.now(),
  });
}

async function processPendingPartnerClaims(env: Env) {
  const __t0 = Date.now(); const __runId = makeRunId(); let __status = "ok"; let __claims = 0;
  try {
  if (!(await hasPartnerTables(env))) return;
  const now = Date.now();
  const res = await env.DB.prepare(`
    SELECT
      pc.id as claim_id,
      pc.campaign_id,
      pc.user_id,
      pc.verify_token,
      pc.status as claim_status,
      pc.started_at as claim_started_at,
      pc.verified_at as claim_verified_at,
      pc.hold_until as claim_hold_until,
      pc.completed_at as claim_completed_at,
      pc.reward_granted_at as claim_reward_granted_at,
      pc.failed_reason as claim_failed_reason,
      pc.verification_payload_json as claim_verification_payload_json,
      pc.created_at as claim_created_at,
      pc.updated_at as claim_updated_at,
      c.*
    FROM partner_claims pc
    JOIN partner_campaigns c ON c.id = pc.campaign_id
    WHERE pc.status = 'pending_hold'
      AND pc.hold_until IS NOT NULL
      AND pc.hold_until <= ?
    ORDER BY pc.hold_until ASC
    LIMIT 100
  `).bind(now).all();

  __claims = (res.results || []).length;
  for (const row of (res.results || []) as any[]) {
    const claim: PartnerClaimRow = {
      id: Number(row.claim_id),
      campaign_id: Number(row.campaign_id),
      user_id: Number(row.user_id),
      verify_token: String(row.verify_token),
      status: String(row.claim_status) as PartnerClaimStatus,
      started_at: row.claim_started_at ?? null,
      verified_at: row.claim_verified_at ?? null,
      hold_until: row.claim_hold_until ?? null,
      completed_at: row.claim_completed_at ?? null,
      reward_granted_at: row.claim_reward_granted_at ?? null,
      failed_reason: row.claim_failed_reason ?? null,
      verification_payload_json: row.claim_verification_payload_json ?? null,
      created_at: Number(row.claim_created_at),
      updated_at: Number(row.claim_updated_at),
    };
    const campaign = row as PartnerCampaignRow;
    try {
      await processPendingPartnerClaim(env, claim, campaign);
    } catch (error: any) {
      console.error(`[PARTNER] pending claim ${claim.id} failed:`, error?.message || error);
      await updatePartnerClaimState(env, claim.id, {
        status: "failed",
        failedReason: error?.message || "PENDING_PARTNER_RECHECK_FAILED",
      });
      await insertPartnerEvent(env, campaign.id, claim.user_id, claim.id, "partner_task_failed", {
        reason: error?.message || "PENDING_PARTNER_RECHECK_FAILED",
      });
    }
  }
  } catch (__e) { __status = "error"; throw __e; } finally { logEvent({ operation: "processPendingPartnerClaims", trigger: "internal", run_id: __runId, status: __status, duration_ms: Date.now() - __t0, processed_users: __claims }); }
}

// ===========================================================================
// Stage 8 — Partner claims V2 (targeted processing + bounded hourly sweep).
//
// Reuses the existing idempotent processPendingPartnerClaim / grantPartnerCampaignReward.
// V2 only changes WHEN/HOW OFTEN claims are processed (not the rules/rewards). The
// frequent ~10 min cron no longer runs the heavy sweep unconditionally; an hourly
// keyset-paginated sweep is the insurance, and a single claim can be processed
// point-wise. Legacy sweep stays as a safety fallback (never removed).
// ===========================================================================

// Shared SELECT shape: a partner claim joined with its campaign.
const PARTNER_CLAIM_JOIN_COLS = `
      pc.id as claim_id, pc.campaign_id, pc.user_id, pc.verify_token,
      pc.status as claim_status, pc.started_at as claim_started_at,
      pc.verified_at as claim_verified_at, pc.hold_until as claim_hold_until,
      pc.completed_at as claim_completed_at, pc.reward_granted_at as claim_reward_granted_at,
      pc.failed_reason as claim_failed_reason, pc.verification_payload_json as claim_verification_payload_json,
      pc.created_at as claim_created_at, pc.updated_at as claim_updated_at, c.*`;

function mapJoinedPartnerRow(row: any): { claim: PartnerClaimRow; campaign: PartnerCampaignRow } {
  const claim: PartnerClaimRow = {
    id: Number(row.claim_id),
    campaign_id: Number(row.campaign_id),
    user_id: Number(row.user_id),
    verify_token: String(row.verify_token),
    status: String(row.claim_status) as PartnerClaimStatus,
    started_at: row.claim_started_at ?? null,
    verified_at: row.claim_verified_at ?? null,
    hold_until: row.claim_hold_until ?? null,
    completed_at: row.claim_completed_at ?? null,
    reward_granted_at: row.claim_reward_granted_at ?? null,
    failed_reason: row.claim_failed_reason ?? null,
    verification_payload_json: row.claim_verification_payload_json ?? null,
    created_at: Number(row.claim_created_at),
    updated_at: Number(row.claim_updated_at),
  };
  return { claim, campaign: row as PartnerCampaignRow };
}

async function loadPartnerClaimJoinedById(env: Env, claimId: number) {
  const row = await env.DB.prepare(`
    SELECT ${PARTNER_CLAIM_JOIN_COLS}
    FROM partner_claims pc JOIN partner_campaigns c ON c.id = pc.campaign_id
    WHERE pc.id = ?
    LIMIT 1
  `).bind(claimId).first() as any;
  return row ? mapJoinedPartnerRow(row) : null;
}

// Targeted single-claim processing. Idempotent + due-gated; never throws into the
// caller. A completed claim is a no-op; a not-yet-due hold is skipped (no work).
export async function processSinglePartnerClaim(env: Env, claimId: number, opts: { trigger: string }): Promise<{ ok: boolean; reason: string }> {
  const __t0 = Date.now(); const __runId = makeRunId();
  if (!(await hasPartnerTables(env))) return { ok: false, reason: "no_partner_tables" };
  const loaded = await loadPartnerClaimJoinedById(env, claimId);
  if (!loaded) return { ok: false, reason: "not_found" };
  const due = classifyPartnerClaimDue(loaded.claim, Date.now());
  // A `verified` claim is a grant that did not complete (e.g. partial failure mid-
  // grant). Resume it — grantPartnerCampaignReward is idempotent (atomic ledger).
  const resumeVerified = loaded.claim.status === "verified";
  if (due !== "due" && !resumeVerified) {
    logEvent({ operation: "partner_claim_targeted", trigger: opts.trigger, run_id: __runId, claim_id: claimId, status: "skipped", reason_code: due });
    return { ok: false, reason: due };
  }
  try {
    if (resumeVerified) {
      await grantPartnerCampaignReward(env, loaded.campaign, loaded.claim);
    } else {
      await processPendingPartnerClaim(env, loaded.claim, loaded.campaign);
    }
    logEvent({ operation: "partner_claim_targeted", trigger: opts.trigger, run_id: __runId, claim_id: claimId, status: "ok", duration_ms: Date.now() - __t0, reason_code: resumeVerified ? "resumed_verified" : "processed" });
    return { ok: true, reason: resumeVerified ? "resumed_verified" : "processed" };
  } catch (error: any) {
    await updatePartnerClaimState(env, claimId, { status: "failed", failedReason: error?.message || "TARGETED_PARTNER_FAILED" });
    await insertPartnerEvent(env, loaded.claim.campaign_id, loaded.claim.user_id, claimId, "partner_task_failed", { reason: error?.message || "TARGETED_PARTNER_FAILED" });
    logEvent({ operation: "partner_claim_targeted", trigger: opts.trigger, run_id: __runId, claim_id: claimId, status: "error", reason_code: "process_failed", error_code: String(error?.message || error).slice(0, 40) });
    return { ok: false, reason: "process_failed" };
  }
}

// Keyset page of DUE pending_hold claims with id > cursorId (ascending). No OFFSET,
// no full-history scan — uses idx_partner_claims_status_hold.
async function listDuePartnerClaimsPage(env: Env, cursorId: number, limit: number, now: number): Promise<any[]> {
  const res = await env.DB.prepare(`
    SELECT ${PARTNER_CLAIM_JOIN_COLS}
    FROM partner_claims pc JOIN partner_campaigns c ON c.id = pc.campaign_id
    WHERE pc.status = 'pending_hold' AND pc.hold_until IS NOT NULL AND pc.hold_until <= ?
      AND pc.id > ?
    ORDER BY pc.id ASC
    LIMIT ?
  `).bind(now, cursorId, limit).all();
  return (res.results || []) as any[];
}

// Hourly V2 sweep: bounded keyset pagination over due claims (insurance path).
export async function runPartnerClaimsSweepV2(env: Env, opts: { trigger: string }) {
  if (!(await hasPartnerTables(env))) return { ok: true, processed: 0, granted: 0, failed: 0, pages: 0, last_id: 0, has_more: false };
  const params = resolvePartnerParams(resolveEffectiveApiFlags(env));
  const now = Date.now();
  return runPartnerSweepCore(params, {
    trigger: opts.trigger,
    listDuePage: async (cursorId, limit) => {
      const rows = await listDuePartnerClaimsPage(env, cursorId, limit, now);
      return rows.map((row) => {
        const { claim } = mapJoinedPartnerRow(row);
        // Stash the full joined row for processOne via a side map on the claim id.
        partnerSweepRowCache.set(claim.id, row);
        return { id: claim.id, campaign_id: claim.campaign_id, user_id: claim.user_id, status: claim.status, hold_until: claim.hold_until } as PartnerSweepClaim;
      });
    },
    processOne: async (sweepClaim) => {
      const row = partnerSweepRowCache.get(sweepClaim.id);
      partnerSweepRowCache.delete(sweepClaim.id);
      if (!row) return { ok: false, reason: "row_missing" };
      const { claim, campaign } = mapJoinedPartnerRow(row);
      try {
        await processPendingPartnerClaim(env, claim, campaign);
        return { ok: true };
      } catch (error: any) {
        // Isolate a bad claim: mark failed (leaves the pending scan, retryable).
        await updatePartnerClaimState(env, claim.id, { status: "failed", failedReason: error?.message || "PARTNER_SWEEP_FAILED" });
        await insertPartnerEvent(env, campaign.id, claim.user_id, claim.id, "partner_task_failed", { reason: error?.message || "PARTNER_SWEEP_FAILED" });
        return { ok: false, reason: "process_failed" };
      }
    },
  });
}
// Per-invocation cache bridging listDuePage rows → processOne (avoids re-querying).
const partnerSweepRowCache = new Map<number, any>();

// Cheap existence check: a pending_hold claim overdue by more than staleMs (the
// hourly sweep should have handled it). Used only as the legacy-fallback trigger.
async function hasOverduePartnerClaims(env: Env, staleMs: number): Promise<boolean> {
  if (!(await hasPartnerTables(env))) return false;
  const threshold = Date.now() - Math.max(0, staleMs);
  const row = await env.DB.prepare(`
    SELECT 1 AS n FROM partner_claims
    WHERE status = 'pending_hold' AND hold_until IS NOT NULL AND hold_until <= ?
    LIMIT 1
  `).bind(threshold).first() as any;
  return !!row;
}

// Frequent (~10 min) cron gate: returns whether to run the legacy sweep now.
export async function partnerFrequentCronShouldRunLegacy(env: Env): Promise<boolean> {
  const flags = resolveEffectiveApiFlags(env);
  if (!flags.partnerClaimsV2) return true; // V2 off → legacy as today (default)
  const overdueMs = flags.partnerClaimsOverdueMinutes * 60_000;
  const overdueExists = flags.partnerClaimsLegacyCronFallback ? await hasOverduePartnerClaims(env, overdueMs) : false;
  const d = decidePartnerLegacyOnFrequentCron({ v2Enabled: true, fallbackEnabled: flags.partnerClaimsLegacyCronFallback, overdueExists });
  if (!d.runLegacy) logEvent({ operation: "partner_frequent_cron_skip", trigger: "cron", run_id: makeRunId(), reason_code: d.reason });
  return d.runLegacy;
}

async function getWeeklyBonusCaseState(
  env: Env,
  userId: number,
  scope: WeeklyScope
) {
  // Only the three canonical quests gate the case — a new global weekly quest must not
  // tighten it by accident (see WEEKLY_GLOBAL_CASE_REQUIRED_KEYS).
  const defs = (await listWeeklyQuestDefinitions(env))
    .filter((def) => def.scope === 'global' && (WEEKLY_GLOBAL_CASE_REQUIRED_KEYS as readonly string[]).includes(def.taskKey));
  const totalRequired = defs.length;
  const instanceKey = getWeeklyInstanceKey(scope.weekKey);

  if (!totalRequired) {
    const quantityRow = await env.DB.prepare(
      `SELECT quantity FROM user_cases WHERE user_id = ? AND case_type = ?`
    ).bind(userId, WEEKLY_GLOBAL_CASE_TYPE).first() as any;
    const quantity = Number(quantityRow?.quantity ?? 0);
    return {
      caseType: WEEKLY_GLOBAL_CASE_TYPE,
      totalRequired: 0,
      completedCount: 0,
      earned: quantity > 0,
      available: quantity > 0,
      quantity,
    };
  }

  const progressRes = await env.DB.prepare(`
    SELECT task_key, progress, completed_at, reward_granted
    FROM user_task_progress
    WHERE user_id = ?
      AND season_id = ?
      AND instance_key = ?
  `).bind(userId, scope.seasonId, instanceKey).all();
  const progressMap = new Map(
    (((progressRes.results || []) as any[]).map((row: any) => [String(row.task_key), row]))
  );

  // Same adaptive threshold as checkWeeklyQuests, otherwise a short week would count
  // a quest as completed there but not here (or vice versa).
  const potentialDayCount = countWeeklyPotentialDays(scope, await listActiveDaysForWeeklyScope(env, scope));

  let completedCount = 0;
  for (const def of defs) {
    const row = progressMap.get(def.taskKey) as any;
    const progress = Number(row?.progress || 0);
    const threshold = resolveWeeklyThreshold(def.taskKey, def.threshold, potentialDayCount);
    const completed = row?.reward_granted === 1 || !!row?.completed_at || progress >= threshold;
    if (completed) completedCount += 1;
  }

  // Halfway consolation: 2 of 3 → one Double Chance, granted once per week.
  if (completedCount >= WEEKLY_GLOBAL_BOOST_REQUIRED) {
    try {
      await tryGrantTaskBoostReward(
        env,
        userId,
        scope.seasonId,
        WEEKLY_GLOBAL_BOOST_TASK_KEY,
        instanceKey,
        completedCount,
        WEEKLY_GLOBAL_BOOST_TYPE
      );
    } catch (boostErr: any) {
      // Never block the case state (or the caller's quest run) on the boost grant.
      console.error(`[WQ] weekly boost grant failed userId=${userId} week=${scope.weekKey}:`, boostErr?.message || boostErr);
    }
  }

  const rewardRow = progressMap.get(WEEKLY_GLOBAL_CASE_TASK_KEY) as any;
  let earned = Number(rewardRow?.reward_granted || 0) === 1;

  if (!earned && completedCount >= totalRequired) {
    const granted = await tryGrantTaskCaseReward(
      env,
      userId,
      scope.seasonId,
      WEEKLY_GLOBAL_CASE_TASK_KEY,
      instanceKey,
      completedCount,
      WEEKLY_GLOBAL_CASE_TYPE,
      `weekly_global_case_reward:${scope.weekKey}`
    );
    earned = granted || earned;
  }

  const quantityRow = await env.DB.prepare(
    `SELECT quantity FROM user_cases WHERE user_id = ? AND case_type = ?`
  ).bind(userId, WEEKLY_GLOBAL_CASE_TYPE).first() as any;
  const quantity = Number(quantityRow?.quantity ?? 0);
  const available = earned && quantity > 0;

  return {
    caseType: WEEKLY_GLOBAL_CASE_TYPE,
    totalRequired,
    completedCount,
    earned,
    available,
    quantity: available ? quantity : 0,
  };
}

// Idempotent: re-derive the authoritative seasonal star total from the stars_ledger and
// persist it on user_season_progress. The seasonal "level" mechanic was removed (Stage 1),
// so only `stars` is recomputed here.
async function syncUserSeasonProgressFromLedger(
  env: Env,
  userId: number,
  seasonId: number
): Promise<{ stars: number }> {
  const ledgerRow = await env.DB.prepare(`
    SELECT COALESCE(SUM(stars), 0) AS total_stars
    FROM stars_ledger
    WHERE user_id = ? AND season_id = ?
  `).bind(userId, seasonId).first() as any;
  const stars = Number(ledgerRow?.total_stars || 0);

  await env.DB.prepare(`
    INSERT INTO user_season_progress (user_id, season_number, stars)
    VALUES (?, ?, ?)
    ON CONFLICT(user_id, season_number) DO UPDATE SET
      stars = excluded.stars
  `).bind(userId, seasonId, stars).run();

  return { stars };
}

async function revokeSeasonAchievementRows(
  env: Env,
  userId: number,
  achievementId: string,
  seasonId: number,
  progress: number,
  scopeTargetId?: string | null
) {
  const seasonKey = seasonPeriodKey(seasonId);
  const now = Date.now();
  if (scopeTargetId !== undefined && scopeTargetId !== null) {
    await env.DB.prepare(`
      UPDATE user_achievements
      SET
        state = 'revoked',
        unlocked_at = NULL,
        earned_at = NULL,
        shown_at = COALESCE(shown_at, ?),
        progress = ?
      WHERE user_id = ? AND achievement_id = ? AND scope_target_id = ? AND period_key = ?
    `).bind(now, progress, userId, achievementId, scopeTargetId, seasonKey).run();
    return;
  }

  await env.DB.prepare(`
    UPDATE user_achievements
    SET
      state = 'revoked',
      unlocked_at = NULL,
      earned_at = NULL,
      shown_at = COALESCE(shown_at, ?),
      progress = ?
    WHERE user_id = ? AND achievement_id = ? AND period_key = ?
  `).bind(now, progress, userId, achievementId, seasonKey).run();
}

async function revokeDisabledSeasonalTaskForUser(
  env: Env,
  userId: number,
  seasonId: number,
  taskKey: string
) {
  const seasonKey = seasonPeriodKey(seasonId);
  const now = Date.now();
  const [starRow, ballRow] = await Promise.all([
    env.DB.prepare(`
      SELECT COALESCE(SUM(stars), 0) AS total_stars
      FROM stars_ledger
      WHERE user_id = ? AND season_id = ? AND task_key = ?
    `).bind(userId, seasonId, taskKey).first() as Promise<any>,
    env.DB.prepare(`
      SELECT COALESCE(SUM(balls), 0) AS total_balls
      FROM balls_ledger
      WHERE user_id = ? AND season_id = ? AND task_key = ?
    `).bind(userId, seasonId, taskKey).first() as Promise<any>,
  ]);

  const totalBalls = Number(ballRow?.total_balls || 0);

  await Promise.all([
    env.DB.prepare(`
      DELETE FROM stars_ledger
      WHERE user_id = ? AND season_id = ? AND task_key = ?
    `).bind(userId, seasonId, taskKey).run(),
    env.DB.prepare(`
      DELETE FROM balls_ledger
      WHERE user_id = ? AND season_id = ? AND task_key = ?
    `).bind(userId, seasonId, taskKey).run(),
    env.DB.prepare(`
      DELETE FROM user_task_progress
      WHERE user_id = ? AND season_id = ? AND task_key = ?
    `).bind(userId, seasonId, taskKey).run(),
    env.DB.prepare(`
      UPDATE user_achievements
      SET
        state = 'revoked',
        unlocked_at = NULL,
        earned_at = NULL,
        shown_at = COALESCE(shown_at, ?),
        progress = 0
      WHERE user_id = ? AND achievement_id = ? AND period_key = ?
    `).bind(now, userId, taskKey, seasonKey).run(),
  ]);

  if (totalBalls > 0) {
    await env.DB.prepare(`
      UPDATE users
      SET balls = MAX(0, balls - ?)
      WHERE id = ?
    `).bind(totalBalls, userId).run();
  }
}

async function revokeDisabledSeasonalTasksForUser(
  env: Env,
  userId: number,
  seasonId: number,
  questSchema?: QuestSchemaSupport
) {
  const schema = questSchema ?? await getQuestSchemaSupport(env);
  if (!schema.taskIsEnabled) return;

  const disabledRes = await env.DB.prepare(`
    SELECT task_key
    FROM tasks_catalog
    WHERE task_type = 'seasonal'
      AND period_type = 'seasonal'
      AND COALESCE(is_enabled, 1) = 0
  `).all();

  const disabledKeys = ((disabledRes.results || []) as any[])
    .map((row: any) => String(row.task_key || '').trim())
    .filter(Boolean);

  for (const taskKey of disabledKeys) {
    await revokeDisabledSeasonalTaskForUser(env, userId, seasonId, taskKey);
  }
}

async function reconcileCurrentSeasonSeasonalStateForUser(
  env: Env,
  userId: number,
  seasonId: number,
  seasonStart: string,
  referenceDay?: string
) {
  // Seasonal achievements / tasks removed from runtime (Stage 1, 2026-06-26).
  // This batch reconciler is the second seasonal engine (alongside
  // checkAchievements); early-return makes it a no-op so no seasonal
  // unlocks/revokes or `seasonal_task` star/ball awards happen. Kept intact for
  // a possible Stage 2 drop or re-enable. See SEASONAL_TASKS_ENABLED in
  // checkAchievements.
  const SEASONAL_TASKS_ENABLED = false;
  if (!SEASONAL_TASKS_ENABLED) return;
  const defs = await listAchievementDefinitionsWithCatalogOverrides(env);
  const ballsRes = await env.DB.prepare(`
    SELECT task_key, reward_balls
    FROM tasks_catalog
    WHERE task_type = 'seasonal'
  `).all();
  const ballsMap = new Map(((ballsRes.results || []) as any[]).map((row: any) => [String(row.task_key), Number(row.reward_balls || 0)]));
  const questSchema = await getQuestSchemaSupport(env);
  await revokeDisabledSeasonalTasksForUser(env, userId, seasonId, questSchema);
  const skipMigratedWeeklyAchievements = questSchema.taskPeriodType;
  const currentLeagues = await getUserLeagues(env, userId);

  for (const def of defs) {
    const taskKey = String(def.id || '');
    if (!taskKey) continue;
    if (DAILY_ACHIEVEMENT_IDS.has(taskKey)) continue;
    if (skipMigratedWeeklyAchievements && WEEKLY_MIGRATED_ACHIEVEMENT_IDS.has(taskKey)) continue;
    const seasonKey = seasonPeriodKey(seasonId);
    const rewardBalls = ballsMap.get(taskKey) || 0;

    if (def.scope === 'global') {
      const effectiveSeasonStart = getEffectiveTaskSeasonStart(taskKey, seasonStart);
      const progress = def.condition_type
        ? await calculateAchievementProgress(userId, String(def.condition_type), Number(def.threshold || 0), '', env, referenceDay, effectiveSeasonStart)
        : 0;

      if (progress < Number(def.threshold || 0)) {
        await revokeStarsForTask(env, userId, seasonId, taskKey, 'season', Number(def.stars_reward || 0));
        await revokeBallsForTask(env, userId, seasonId, taskKey, 'season', ballsMap.get(taskKey) || 0);
        await env.DB.prepare(`
          DELETE FROM user_task_progress
          WHERE user_id = ? AND season_id = ? AND task_key = ? AND instance_key = 'season'
        `).bind(userId, seasonId, taskKey).run();
        await revokeSeasonAchievementRows(env, userId, taskKey, seasonId, progress, '');
      } else {
        await unlockAchievement(
          env,
          userId,
          taskKey,
          '',
          seasonKey,
          referenceDay || seasonStart.slice(0, 10),
          null
        );
        await markTaskCompleted(env, userId, seasonId, taskKey, 'season', progress);
        if (Number(def.stars_reward || 0) > 0) {
          await awardStarsViaLedger(env, userId, seasonId, taskKey, 'season', Number(def.stars_reward || 0), 'seasonal_task');
          await markTaskRewardGranted(env, userId, seasonId, taskKey, 'season');
        }
        if (rewardBalls > 0) {
          await awardBalls(env, userId, rewardBalls, seasonId, taskKey, 'season', 'task_reward');
        }
      }
      continue;
    }

    let hasQualifyingLeague = false;
    const qualifyingLeagueIds = new Set<string>();
    for (const league of currentLeagues) {
      const effectiveSeasonStart = getEffectiveTaskSeasonStart(taskKey, seasonStart);
      const progress = def.condition_type
        ? await calculateAchievementProgress(
            userId,
            String(def.condition_type),
            Number(def.threshold || 0),
            String(league.id),
            env,
            referenceDay,
            effectiveSeasonStart
          )
        : 0;
      if (progress >= Number(def.threshold || 0)) {
        hasQualifyingLeague = true;
        qualifyingLeagueIds.add(String(league.id));
      } else {
        await revokeSeasonAchievementRows(env, userId, taskKey, seasonId, progress, String(league.id));
      }
    }

    await env.DB.prepare(`
      UPDATE user_achievements
      SET
        state = 'revoked',
        unlocked_at = NULL,
        earned_at = NULL,
        shown_at = COALESCE(shown_at, ?),
        progress = 0
      WHERE user_id = ? AND achievement_id = ? AND period_key = ?
        ${qualifyingLeagueIds.size ? `AND scope_target_id NOT IN (${[...qualifyingLeagueIds].map(() => '?').join(', ')})` : ``}
    `).bind(
      Date.now(),
      userId,
      taskKey,
      seasonPeriodKey(seasonId),
      ...(qualifyingLeagueIds.size ? [...qualifyingLeagueIds] : [])
    ).run();

    if (hasQualifyingLeague) {
      for (const leagueId of qualifyingLeagueIds) {
        await unlockAchievement(env, userId, taskKey, leagueId, seasonKey, seasonStart.slice(0, 10), null);
      }

      await markTaskCompleted(env, userId, seasonId, taskKey, 'season', Number(def.threshold || 1));
      if (Number(def.stars_reward || 0) > 0) {
        await awardStarsViaLedger(env, userId, seasonId, taskKey, 'season', Number(def.stars_reward || 0), 'seasonal_task');
        await markTaskRewardGranted(env, userId, seasonId, taskKey, 'season');
      }
      if (rewardBalls > 0) {
        await awardBalls(env, userId, rewardBalls, seasonId, taskKey, 'season', 'task_reward');
      }
    }

    if (!hasQualifyingLeague) {
      await revokeStarsForTask(env, userId, seasonId, taskKey, 'season', Number(def.stars_reward || 0));
      await revokeBallsForTask(env, userId, seasonId, taskKey, 'season', ballsMap.get(taskKey) || 0);
      await env.DB.prepare(`
        DELETE FROM user_task_progress
        WHERE user_id = ? AND season_id = ? AND task_key = ? AND instance_key = 'season'
      `).bind(userId, seasonId, taskKey).run();
    }
  }

  await syncUserSeasonProgressFromLedger(env, userId, seasonId);
}

const DAILY_QUESTS = [
  { id: 'dq_full_day', emoji: '⏱️', title: 'Полные девяносто', description: 'Сделай прогнозы на все матчи дня до начала игр', stars: 1, phase: 'pick_saved' as const, league: false },
  { id: 'dq_early_start', emoji: '⏰', title: 'Ранний старт', description: 'Сделай прогноз минимум за 3 часа до начала матча', stars: 1, phase: 'pick_saved' as const, league: false },
  { id: 'dq_captain', emoji: '🃏', title: 'Капитанский выбор', description: 'Используй джокер в одном из матчей', stars: 1, phase: 'pick_saved' as const, league: false },
  { id: 'dq_read_game', emoji: '👀', title: 'Чтение игры', description: 'Угадай исход матча (двойной шанс не в счёт)', stars: 1, phase: 'scores_updated' as const, league: false },
  { id: 'dq_feel_score', emoji: '📊', title: 'Чувство счёта', description: 'Угадай разницу мячей', stars: 1, phase: 'scores_updated' as const, league: false },
  { id: 'dq_exact_score', emoji: '🎯', title: 'Точный выстрел', description: 'Угадай точный счёт в одном из матчей дня', stars: 2, phase: 'scores_updated' as const, league: false },
  { id: 'dq_joker_played', emoji: '🃏✅', title: 'Джокер сыграл', description: 'Набери очки в матче с джокером', stars: 1, phase: 'scores_updated' as const, league: false },
  // League daily quests (only shown if user is in a league)
  { id: 'dq_league_points', emoji: '🏆', title: 'День с очками', description: 'Набери хотя бы 1 очко за день в лиге', stars: 1, phase: 'scores_updated' as const, league: true },
  { id: 'dq_league_win', emoji: '👑', title: 'Победа дня', description: 'Займи 1 место в лиге по итогам дня', stars: 2, phase: 'scores_updated' as const, league: true },
];

// Achievement IDs that are daily quests (should not appear in seasonal tab)
const DAILY_ACHIEVEMENT_IDS = new Set([
  'global_full_day', 'global_early_start', 'global_first_joker',
  'global_read_game', 'global_goal_diff', 'global_joker_points',
  'league_day_points', 'league_win_day',
]);

const WEEKLY_MIGRATED_ACHIEVEMENT_IDS = new Set([
  'global_double_exact_week',
  'league_top3_week',
  'league_champion_week',
]);

const TASK_LIVE_FROM_DAY: Record<string, string> = {
  dq_exact_score: '2026-03-28',
  global_day20: '2026-03-28',
};

function isTaskActiveForDay(taskKey: string, day?: string): boolean {
  const liveFromDay = TASK_LIVE_FROM_DAY[String(taskKey || '')];
  if (!liveFromDay) return true;
  const effectiveDay = String(day || currentMatchdayKey() || '').slice(0, 10);
  if (!effectiveDay) return true;
  return effectiveDay >= liveFromDay;
}

function getEffectiveTaskSeasonStart(taskKey: string, seasonStart?: string): string {
  const base = seasonStart ? String(seasonStart).slice(0, 10) : '2000-01-01';
  const liveFromDay = TASK_LIVE_FROM_DAY[String(taskKey || '')];
  if (!liveFromDay) return base;
  return liveFromDay > base ? liveFromDay : base;
}

