const WEEKLY_GLOBAL_CASE_TASK_KEY = 'weekly_global_premium_case';
const WEEKLY_GLOBAL_CASE_TYPE = 'premium';

// The three global weekly quests that gate the Premium case. Kept as an explicit list
// instead of "every global weekly def": with defs.length any future global weekly quest
// would silently make the case harder to earn.
const WEEKLY_GLOBAL_CASE_REQUIRED_KEYS = [
  'weekly_active_days_3',
  'weekly_points_days_3',
  'global_double_exact_week',
] as const;

// Consolation reward at the halfway mark: 2 of 3 global weekly quests → one Double Chance.
// A boost is deliberate — it is not convertible back into balls, so it adds perceived value
// without emitting currency (see docs/weekly-tasks-plan-2026-07-22.md §2).
const WEEKLY_GLOBAL_BOOST_TASK_KEY = 'weekly_global_double_chance';
const WEEKLY_GLOBAL_BOOST_TYPE = 'double_chance';
const WEEKLY_GLOBAL_BOOST_REQUIRED = 2;

// "Do X in N game days" quests must never demand more days than the week actually has:
// during international breaks / season start a week can hold 1–2 game days, which used to
// make these quests (and with them the Premium case) physically unwinnable.
const WEEKLY_DAY_COUNT_TASK_KEYS = new Set<string>(['weekly_active_days_3', 'weekly_points_days_3']);

export function resolveWeeklyThreshold(taskKey: string, threshold: number, potentialDayCount: number): number {
  if (!WEEKLY_DAY_COUNT_TASK_KEYS.has(taskKey)) return threshold;
  if (!Number.isFinite(potentialDayCount) || potentialDayCount <= 0) return threshold;
  return Math.max(1, Math.min(threshold, Math.floor(potentialDayCount)));
}

// Days of the week that can still turn into game days: those that already carry picked
// matches, plus every calendar day of the week that has not finished yet. The second half
// matters because matches are ingested day by day — on Monday only today's day is picked,
// so counting just those collapses the target to 1, hands the reward out at 1/3 and lets
// revokeStarsForTask silently take it back once the rest of the week is ingested.
export function countWeeklyPotentialDays(scope: WeeklyScope, activeDays: string[], nowMs: number = Date.now()): number {
  const window = getWeekWindowUtc(scope.weekKey);
  const days = new Set<string>(activeDays);
  const DAY_MS = 24 * 60 * 60 * 1000;
  for (let ms = window.startMs; ms <= window.endMs; ms += DAY_MS) {
    if (ms + DAY_MS > nowMs) days.add(new Date(ms).toISOString().slice(0, 10));
  }
  return days.size;
}

