// Stage 4: single source of daily-quest CONDITIONS, shared by the legacy apply
// path (checkDailyQuests) and the read-only shadow evaluator. READ-ONLY: only
// SELECTs, never writes. Do not add a second set of conditions elsewhere.
interface DailyQuestCtx { totalMatches: number; dayStats: any; userLeagues: string[] }
export async function evaluateDailyQuestMet(env: Env, userId: number, day: string, quest: any, ctx: DailyQuestCtx): Promise<boolean> {
  const { totalMatches, dayStats, userLeagues } = ctx;
  let met = false;
  switch (quest.id) {
    case 'dq_full_day': {
      if (totalMatches > 0) {
        const distinctPicksRes = await env.DB.prepare(`
          SELECT COUNT(DISTINCT p.match_id) as cnt FROM picks p
          JOIN matches m ON p.match_id = m.match_id AND p.day = m.day
          WHERE p.user_id = ? AND m.matchday_key = ? AND m.is_pick = 1 AND CAST(p.updated_at AS INTEGER) <= CAST(strftime('%s', m.lock_time) * 1000 AS INTEGER)
        `).bind(userId, day).first() as any;
        met = (distinctPicksRes?.cnt ?? 0) >= totalMatches;
      }
      break;
    }
    case 'dq_early_start': {
      if (dayStats?.earliest_pick_time) {
        const matchRes = await env.DB.prepare(
          `SELECT MIN(start_time) as earliest FROM matches WHERE matchday_key = ? AND is_pick = 1`
        ).bind(day).first() as any;
        if (matchRes?.earliest) {
          const matchTime = new Date(matchRes.earliest).getTime();
          const diff = matchTime - dayStats.earliest_pick_time;
          met = diff >= 10800000;
        }
      }
      if (!met) {
        const picksWithMatches = await env.DB.prepare(`
          SELECT p.updated_at, m.start_time FROM picks p
          JOIN matches m ON p.match_id = m.match_id AND p.day = m.day
          WHERE p.user_id = ? AND m.matchday_key = ? AND m.is_pick = 1
        `).bind(userId, day).all();
        for (const row of ((picksWithMatches.results || []) as any[])) {
          const matchStart = new Date(row.start_time).getTime();
          const pickTime = Number(row.updated_at);
          if (matchStart - pickTime >= 10800000) { met = true; break; }
        }
      }
      break;
    }
    case 'dq_captain': {
      const jokerRes = await env.DB.prepare(`
        SELECT 1 FROM picks p
        JOIN matches m ON p.match_id = m.match_id AND p.day = m.day
        WHERE p.user_id = ? AND m.matchday_key = ? AND m.is_pick = 1 AND p.joker = 1
        LIMIT 1
      `).bind(userId, day).first();
      met = !!jokerRes;
      break;
    }
    case 'dq_read_game': {
      // "Угадайте исход матча" — counts a genuine outcome/diff/exact hit only.
      // A hit that exists solely because of a double_chance safety net (the user's
      // own pick missed the outcome) must NOT satisfy this quest. A genuine hit is
      // exactly sign(home-away) of the pick matching the result — this mirrors
      // calculateMatchPoints() base>0 and is independent of the double_chance variant.
      const readHit = await env.DB.prepare(`
        SELECT 1 FROM picks p
        JOIN results r ON p.match_id = r.match_id AND p.day = r.day
        JOIN matches m ON p.match_id = m.match_id AND p.day = m.day
        WHERE p.user_id = ? AND m.matchday_key = ? AND m.is_pick = 1
          AND (
            (p.home > p.away AND r.home > r.away)
            OR (p.home < p.away AND r.home < r.away)
            OR (p.home = p.away AND r.home = r.away)
          )
        LIMIT 1
      `).bind(userId, day).first();
      met = !!readHit;
      break;
    }
    case 'dq_feel_score': {
      met = (dayStats?.diff_count ?? 0) >= 1;
      break;
    }
    case 'dq_exact_score': {
      met = (dayStats?.exact_count ?? 0) >= 1;
      break;
    }
    case 'dq_joker_played': {
      met = (dayStats?.had_joker ?? 0) >= 1 && (dayStats?.joker_points ?? 0) > 0;
      break;
    }
    case 'dq_league_points':
      if (userLeagues.length > 0) met = (dayStats?.points ?? 0) > 0;
      break;
    case 'dq_league_win':
      if (userLeagues.length > 0) {
        const unfinishedRes = await env.DB.prepare(`SELECT COUNT(*) as c FROM matches WHERE matchday_key = ? AND is_pick = 1 AND status != 'FINISHED'`).bind(day).first() as any;
        if ((unfinishedRes?.c || 0) === 0 && (dayStats?.points || 0) > 0) {
          for (const lid of userLeagues) {
            const topRes = await env.DB.prepare(`
              SELECT user_id FROM league_day_stats
              WHERE league_id = ? AND day = ?
              ORDER BY points DESC LIMIT 1
            `).bind(lid, day).first() as any;
            if (!topRes || Number(topRes.user_id) !== userId) continue;
            const rankList = await computeLeagueLeaderboard(env, lid, `day:${day}`, { callsite: "quest", viewerId: userId, trigger: "daily_quest" });
            const rankRows = (rankList.results || []) as any[];
            if (!hasEnoughLeagueRankingParticipants(rankRows, 1)) continue;
            met = true;
            break;
          }
        }
      }
      break;
  }
  return met;
}

// Stage 4 — READ-ONLY shadow evaluator. Computes expected daily-quest state via
// the shared evaluateDailyQuestMet() and compares it with stored progress. It
// performs ONLY SELECTs — never INSERT/UPDATE/DELETE, never awards/grants/ledger.
export async function runDailyQuestShadow(
  env: Env,
  event: ReturnType<typeof buildQuestEvent>,
  leagueIds: string[]
): Promise<void> {
  const t0 = Date.now();
  const day = event.period_key;
  const phase = eventPhase(event.event_type);
  const base = {
    operation: "quest_event_shadow",
    event_type: event.event_type,
    event_id: event.event_id,
    period_key: day,
  } as const;
  if (phase === null) {
    logEvent({ ...base, result: "unsupported", reason_code: "no_quest_for_event", duration_ms: Date.now() - t0 });
    return;
  }
  try {
    const matchCountRow = await env.DB.prepare(`SELECT COUNT(*) as cnt FROM matches WHERE matchday_key = ? AND is_pick = 1`).bind(day).first() as any;
    const totalMatches = matchCountRow?.cnt ?? 0;
    const dayStats = await env.DB.prepare(`SELECT * FROM user_day_stats WHERE user_id = ? AND day = ?`).bind(event.user_id, day).first() as any;
    const storedRes = await env.DB.prepare(`SELECT quest_id, completed, stars_awarded FROM daily_quest_progress WHERE user_id = ? AND day = ?`).bind(event.user_id, day).all();
    const storedMap = new Map<string, { completed: number; stars: number }>();
    for (const r of (storedRes.results || []) as any[]) storedMap.set(String(r.quest_id), { completed: Number(r.completed), stars: Number(r.stars_awarded || 0) });

    const defs = await listDailyQuestDefinitions(env);
    let matched = 0, mismatched = 0;
    for (const quest of defs) {
      if (!isTaskActiveForDay(String(quest.id || ''), day)) continue;
      if (quest.phase === 'scores_updated' && phase !== 'scores_updated') continue; // mirror legacy phase gate
      const met = await evaluateDailyQuestMet(env, event.user_id, day, quest, { totalMatches, dayStats, userLeagues: leagueIds });
      const stored = storedMap.get(String(quest.id));
      const result = classifyQuestShadow({
        supported: true,
        hasStoredRow: !!stored,
        expectedCompleted: met,
        storedCompleted: !!stored && stored.completed === 1,
        expectedRewardEligible: met && Number(quest.stars || 0) > 0,
        storedRewarded: !!stored && stored.stars > 0,
      });
      if (result === "match") matched++;
      else { mismatched++; logEvent({ ...base, quest_id: quest.id, result, reason_code: "per_quest" }); }
    }
    logEvent({ ...base, result: mismatched > 0 ? "mismatch" : "match", reason_code: `matched=${matched},mismatched=${mismatched}`, duration_ms: Date.now() - t0 });
  } catch (e: any) {
    logEvent({ ...base, result: "error", error_code: String(e?.message || e).slice(0, 40), duration_ms: Date.now() - t0 });
  }
}

function questShadowFlags(env: Env): ShadowFlagState {
  const f = resolveEffectiveApiFlags(env);
  return { questEventSyncV2: f.questEventSyncV2, questEventSyncShadow: f.questEventSyncShadow };
}

// Stage 5: per-user rollout state for event-driven apply + read-reconcile skip.
function questApplyFlags(env: Env): ApplyFlagState {
  return {
    applyV2: resolveEffectiveApiFlags(env).questEventApplyV2,
    applyUserIds: parseUserIdAllowlist(env.QUEST_EVENT_APPLY_USER_IDS),
    skipReconcileUserIds: parseUserIdAllowlist(env.QUEST_READ_RECONCILE_SKIP_USER_IDS),
    skipAll: (env.QUEST_READ_RECONCILE_DISABLE_ALL || "").toLowerCase() === "true",
  };
}

// /quests/daily read-reconcile throttle: the catch-up net only needs to run once in
// a while per user+day, not on every tab open. Per-isolate memory — a fresh isolate
// simply reruns the reconcile, so correctness never depends on this cache.
// The resolved "current football day" is GLOBAL — it changes only when matches
// are ingested or the 00:00 UTC (03:00 MSK) day boundary passes, yet it was recomputed with a
// matches scan on every /quests/daily open. Cache briefly.
const DQ_DAY_TTL_MS = 60_000;
let __dqDayCache: { at: number; mdk: string; day: string } | null = null;

const DAILY_READ_RECONCILE_TTL_MS = 120_000;
const __dailyReconcileAt = new Map<string, number>();
function dailyReconcileRecentlyRan(userId: number, day: string): boolean {
  const at = __dailyReconcileAt.get(`${userId}:${day}`);
  return at !== undefined && Date.now() - at < DAILY_READ_RECONCILE_TTL_MS;
}
function markDailyReconcileRan(userId: number, day: string): void {
  if (__dailyReconcileAt.size > 20_000) __dailyReconcileAt.clear();
  __dailyReconcileAt.set(`${userId}:${day}`, Date.now());
}

// Gate + run shadow after a CONFIRMED successful action. Default flags => no-op.
async function maybeRunQuestShadow(env: Env, eventType: QuestEventType, userId: number, day: string, leagueIds: string[], matchId?: string | null): Promise<void> {
  const decision = shouldRunQuestShadow(questShadowFlags(env));
  if (!decision.run) {
    if (decision.warn) logEvent({ operation: "quest_event_shadow", event_type: eventType, result: "skipped", reason_code: decision.reason });
    return;
  }
  const event = buildQuestEvent(eventType, userId, day, { matchId: matchId ?? null });
  await runDailyQuestShadow(env, event, leagueIds);
}

// ── Stage 13 — SEASONAL quest/level shadow (compute + compare only, NO writes) ──

function seasonalShadowFlags(env: Env) {
  const f = resolveEffectiveApiFlags(env);
  return { seasonalEventSyncV2: f.seasonalEventSyncV2, seasonalEventSyncShadow: f.seasonalEventSyncShadow };
}

// ── Stage 14 — SEASONAL event-driven apply + read-only endpoints (allowlist only) ──

function seasonalApplyFlags(env: Env): ApplyFlagState {
  return {
    applyV2: resolveEffectiveApiFlags(env).seasonalEventApplyV2,
    applyUserIds: parseUserIdAllowlist(env.SEASONAL_EVENT_APPLY_USER_IDS),
    skipReconcileUserIds: parseUserIdAllowlist(env.SEASONAL_READ_RECONCILE_SKIP_USER_IDS),
  };
}

// Run the EXISTING seasonal reconcile after a confirmed event, but ONLY for users in
// the apply allowlist. Reuses reconcileCurrentSeasonSeasonalStateForUser (no rule
// copy; its existing idempotency prevents duplicate progress/rewards). Errors never
// bubble into the main action (best-effort, like the read-path reconcile).
async function maybeRunSeasonalApply(env: Env, userId: number): Promise<void> {
  if (!isQuestApplyUser(userId, seasonalApplyFlags(env))) return;
  const t0 = Date.now();
  try {
    const seasonNumber = await getCurrentSeasonNumber(env);
    const seasonCfg = await getSeasonConfig(env);
    await reconcileCurrentSeasonSeasonalStateForUser(env, userId, seasonNumber, seasonCfg.start, todayKeyUTC());
    logEvent({ operation: "seasonal_event_apply", user_id: userId, season_id: seasonNumber, status: "ok", duration_ms: Date.now() - t0 });
  } catch (e: any) {
    logEvent({ operation: "seasonal_event_apply", user_id: userId, status: "error", error_code: String(e?.message || e).slice(0, 40), duration_ms: Date.now() - t0 });
  }
}

// Gate + run seasonal shadow after a CONFIRMED action that can move seasonal progress.
// Default flags => no-op. NEVER writes; failures never bubble into the main action.
async function maybeRunSeasonalShadow(env: Env, eventType: SeasonalEventType, userId: number): Promise<void> {
  const decision = shouldRunSeasonalShadow(seasonalShadowFlags(env));
  if (!decision.run) {
    if (decision.warn) logEvent({ operation: "seasonal_event_shadow", event_type: eventType, result: "skipped", reason_code: decision.reason });
    return;
  }
  try {
    await runSeasonalShadow(env, eventType, userId);
  } catch (e: any) {
    logEvent({ operation: "seasonal_event_shadow", event_type: eventType, user_id: userId, result: "error", error_code: String(e?.message || e).slice(0, 40) });
  }
}

// Read-only: recompute expected seasonal-quest state and compare with stored.
// Reuses calculateAchievementProgress (the same evaluator legacy reconcile uses).
// Emits one aggregate diagnostic + per-mismatch lines.
export async function runSeasonalShadow(env: Env, eventType: SeasonalEventType, userId: number): Promise<{ matched: number; mismatched: number }> {
  const t0 = Date.now();
  const seasonNumber = await getCurrentSeasonNumber(env);
  const seasonCfg = await getSeasonConfig(env);
  const seasonKey = seasonPeriodKey(seasonNumber);
  const event = buildSeasonalEvent(eventType, userId, seasonKey);
  const base = { operation: "seasonal_event_shadow", event_type: eventType, event_id: event.event_id, user_id: userId, season_key: seasonKey } as const;

  const defs = await listAchievementDefinitionsWithCatalogOverrides(env);
  const ballsRes = await env.DB.prepare(`SELECT task_key, reward_balls FROM tasks_catalog WHERE task_type = 'seasonal'`).all();
  const ballsMap = new Map(((ballsRes.results || []) as any[]).map((r: any) => [String(r.task_key), Number(r.reward_balls || 0)]));
  const questSchema = await getQuestSchemaSupport(env);
  const skipMigratedWeekly = questSchema.taskPeriodType;
  const currentLeagues = await getUserLeagues(env, userId);

  // Stored seasonal task progress (instance_key='season').
  const storedRes = await env.DB.prepare(
    `SELECT task_key, progress, completed_at, reward_granted FROM user_task_progress WHERE user_id = ? AND season_id = ? AND instance_key = 'season'`
  ).bind(userId, seasonNumber).all();
  const storedMap = new Map<string, { progress: number; completed: boolean; rewarded: boolean }>();
  for (const r of (storedRes.results || []) as any[]) {
    storedMap.set(String(r.task_key), { progress: Number(r.progress || 0), completed: r.completed_at != null, rewarded: Number(r.reward_granted || 0) === 1 });
  }

  let matched = 0, mismatched = 0;
  for (const def of defs) {
    const taskKey = String(def.id || '');
    if (!taskKey || DAILY_ACHIEVEMENT_IDS.has(taskKey)) continue;
    if (skipMigratedWeekly && WEEKLY_MIGRATED_ACHIEVEMENT_IDS.has(taskKey)) continue;

    const threshold = Number(def.threshold || 0);
    const starsReward = Number(def.stars_reward || 0);
    const rewardBalls = ballsMap.get(taskKey) || 0;
    const effectiveSeasonStart = getEffectiveTaskSeasonStart(taskKey, seasonCfg.start);

    let expectedProgress = 0;
    if (def.condition_type) {
      if (def.scope === 'global') {
        expectedProgress = await calculateAchievementProgress(userId, String(def.condition_type), threshold, '', env, undefined, effectiveSeasonStart);
      } else {
        for (const league of currentLeagues) {
          const p = await calculateAchievementProgress(userId, String(def.condition_type), threshold, String(league.id), env, undefined, effectiveSeasonStart);
          if (p > expectedProgress) expectedProgress = p;
        }
      }
    }
    const expectedCompleted = !!def.condition_type && expectedProgress >= threshold;
    const expectedRewardEligible = expectedCompleted && (starsReward > 0 || rewardBalls > 0);
    const stored = storedMap.get(taskKey);

    const result = classifySeasonalShadow({
      supported: !!def.condition_type,
      hasStoredRow: !!stored,
      expectedProgress,
      storedProgress: stored?.progress ?? 0,
      expectedCompleted,
      storedCompleted: !!stored?.completed,
      expectedRewardEligible,
      storedRewarded: !!stored?.rewarded,
    });
    if (result === "match" || result === "unsupported") matched++;
    else { mismatched++; logEvent({ ...base, quest_id: taskKey, result, reason_code: "per_quest", expected_progress: expectedProgress, stored_progress: stored?.progress ?? 0 }); }
  }

  logEvent({ ...base, result: mismatched > 0 ? "mismatch" : "match", reason_code: `matched=${matched},mismatched=${mismatched}`, duration_ms: Date.now() - t0 });
  return { matched, mismatched };
}

export async function checkDailyQuests(
  env: Env, userId: number, day: string, phase: 'pick_saved' | 'scores_updated', leagueIds?: string[]
): Promise<{ completed: string[]; caseEarned: boolean }> {
  const __t0 = Date.now(); const __runId = makeRunId(); let __status = "ok";
  try {
  console.log(`[DQ] checkDailyQuests userId=${userId} day=${day} phase=${phase} leagueIds=${(leagueIds || []).join(',')}`);
  const seasonNumber = await getSeasonIdForDayOrDisplay(env, day);
  const completed: string[] = [];
  let caseEarned = false;

  // Count total approved matches for this matchday_key
  const matchCountRow = await env.DB.prepare(
    `SELECT COUNT(*) as cnt FROM matches WHERE matchday_key = ? AND is_pick = 1`
  ).bind(day).first() as any;
  const totalMatches = matchCountRow?.cnt ?? 0;

  // Get user day stats
  const dayStats = await env.DB.prepare(
    `SELECT * FROM user_day_stats WHERE user_id = ? AND day = ?`
  ).bind(userId, day).first() as any;

  // Get already completed quests for this day
  const existingRes = await env.DB.prepare(
    `SELECT quest_id FROM daily_quest_progress WHERE user_id = ? AND day = ? AND completed = 1`
  ).bind(userId, day).all();
  const alreadyCompleted = new Set((existingRes.results || []).map((r: any) => r.quest_id));

  const userLeagues = leagueIds || [];
  const dailyQuestDefs = await listDailyQuestDefinitions(env);

  for (const quest of dailyQuestDefs) {
    if (!isTaskActiveForDay(String(quest.id || ''), day)) continue;
    if (quest.phase === 'scores_updated' && phase !== 'scores_updated') continue;

    // Skip league quests evaluation entirely if user is not in any league, but wait: 
    // what if they WERE in a league and completed it, and now aren't? We should evaluate `met` based on `userLeagues.length > 0`.

    const isCurrentlyCompleted = alreadyCompleted.has(quest.id);
    const met = await evaluateDailyQuestMet(env, userId, day, quest, { totalMatches, dayStats, userLeagues });

    if (met && !isCurrentlyCompleted) {
      const now = Date.now();
      const instanceKey = `matchday:${day}`;

      await env.DB.prepare(`
        INSERT INTO daily_quest_progress (user_id, day, quest_id, completed, stars_awarded, completed_at)
        VALUES (?, ?, ?, 1, ?, ?)
        ON CONFLICT(user_id, day, quest_id) DO UPDATE SET completed = 1, stars_awarded = excluded.stars_awarded, completed_at = excluded.completed_at
      `).bind(userId, day, quest.id, quest.stars, now).run();

      await markTaskCompleted(env, userId, seasonNumber, quest.id, instanceKey);

      const result = await awardStarsViaLedger(env, userId, seasonNumber, quest.id, instanceKey, quest.stars, 'daily_task');
      if (result.awarded) {
        await markTaskRewardGranted(env, userId, seasonNumber, quest.id, instanceKey);
      }
      completed.push(quest.id);
      alreadyCompleted.add(quest.id);
      console.log(`[DQ] COMPLETED quest=${quest.id} userId=${userId} day=${day} stars=${quest.stars}`);

    } else if (!met && isCurrentlyCompleted) {
      console.log(`[DQ] REVOKING quest=${quest.id} userId=${userId} day=${day} (Match result adjusted)`);
      const instanceKey = `matchday:${day}`;

      // Remove progress state
      await env.DB.prepare(`DELETE FROM daily_quest_progress WHERE user_id = ? AND day = ? AND quest_id = ?`)
        .bind(userId, day, quest.id).run();
      await env.DB.prepare(`DELETE FROM user_task_progress WHERE user_id = ? AND season_id = ? AND task_key = ? AND instance_key = ?`)
        .bind(userId, seasonNumber, quest.id, instanceKey).run();

      // Revoke stars from ledger idempotently
      const ledgerRes = await env.DB.prepare(`
        DELETE FROM stars_ledger WHERE user_id = ? AND season_id = ? AND task_key = ? AND instance_key = ?
      `).bind(userId, seasonNumber, quest.id, instanceKey).run();

      if (ledgerRes.meta.changes && ledgerRes.meta.changes > 0) {
        await env.DB.prepare(`UPDATE user_season_progress SET stars = MAX(0, stars - ?) WHERE user_id = ? AND season_number = ?`)
          .bind(quest.stars, userId, seasonNumber).run();
      }

      alreadyCompleted.delete(quest.id);
    }
  }

  // Check case logic
  const nonLeagueCompletedCount = Array.from(alreadyCompleted).filter(id => {
    const q = dailyQuestDefs.find(x => x.id === id);
    return q && q.league === false;
  }).length;

  if (nonLeagueCompletedCount >= 4) {
    const caseRow = await env.DB.prepare(
      `SELECT earned FROM daily_cases WHERE user_id = ? AND day = ?`
    ).bind(userId, day).first() as any;
    if (!caseRow) {
      const now = Date.now();
      const insRes = await env.DB.prepare(`
        INSERT INTO daily_cases (user_id, day, earned, earned_at)
        VALUES (?, ?, 1, ?)
        ON CONFLICT(user_id, day) DO NOTHING
      `).bind(userId, day, now).run();
      caseEarned = (insRes.meta.changes ?? 0) > 0;
    }
  } else {
    // Revocation of the daily case if quests drop below 4
    const caseRow = await env.DB.prepare(
      `SELECT earned FROM daily_cases WHERE user_id = ? AND day = ?`
    ).bind(userId, day).first() as any;

    if (caseRow) {
      if (caseRow.earned === 1) {
        // Not transferred/opened yet, safe to fully delete
        await env.DB.prepare(`DELETE FROM daily_cases WHERE user_id = ? AND day = ?`).bind(userId, day).run();
      } else if (caseRow.earned === 2) {
        // Was already auto-transferred into user_cases inventory. We must revert the transfer idempotently.
        await env.DB.prepare(`DELETE FROM daily_cases WHERE user_id = ? AND day = ?`).bind(userId, day).run();

        const qtBeforeRes = await env.DB.prepare(`SELECT quantity FROM user_cases WHERE user_id = ? AND case_type = 'daily_free'`).bind(userId).first() as any;
        const qtBefore = qtBeforeRes?.quantity ?? 0;

        if (qtBefore > 0) {
          const qtAfter = qtBefore - 1;
          await env.DB.prepare(`UPDATE user_cases SET quantity = ? WHERE user_id = ? AND case_type = 'daily_free'`).bind(qtAfter, userId).run();
          await env.DB.prepare(`
            INSERT INTO case_transactions (user_id, case_type, amount, quantity_before, quantity_after, operation_type, comment, created_at)
            VALUES (?, 'daily_free', -1, ?, ?, 'spend', 'daily_case_quest_revoke', ?)
          `).bind(userId, qtBefore, qtAfter, Date.now()).run();
        }
      }
    }
  }

  return { completed, caseEarned };
  } catch (__e) { __status = "error"; throw __e; } finally { logEvent({ operation: "checkDailyQuests", trigger: phase, run_id: __runId, status: __status, duration_ms: Date.now() - __t0, processed_users: 1 }); }
}

async function listWeeklyQuestDefinitions(env: Env): Promise<WeeklyQuestDefinitionRow[]> {
  const schema = await getQuestSchemaSupport(env);
  if (!schema.taskPeriodType) return WEEKLY_QUESTS_FALLBACK;
  const rankingExpr = schema.taskRankingBased ? 'COALESCE(ranking_based, 0)' : '0';
  const enabledWhere = schema.taskIsEnabled ? `AND COALESCE(is_enabled, 1) = 1` : '';
  const res = await env.DB.prepare(`
    SELECT
      task_key,
      scope,
      emoji,
      title,
      description,
      reward_stars,
      COALESCE(progress_target, 1) AS progress_target,
      progress_kind,
      phase,
      rarity,
      ${rankingExpr} AS ranking_based,
      sort_order
    FROM tasks_catalog
    WHERE period_type = 'weekly'
      ${enabledWhere}
    ORDER BY sort_order ASC, task_key ASC
  `).all();

  return ((res.results || []) as any[]).map((row) => ({
    taskKey: String(row.task_key),
    scope: row.scope === 'league' ? 'league' : 'global',
    emoji: String(row.emoji || ''),
    title: String(row.title || ''),
    description: String(row.description || ''),
    rewardStars: Number(row.reward_stars || 0),
    threshold: Number(row.progress_target || 1),
    progressKind: (row.progress_kind || 'counter') as WeeklyQuestDefinitionRow['progressKind'],
    phase: row.phase === 'scores_updated' ? 'scores_updated' : 'pick_saved',
    rarity: (row.rarity || 'common') as WeeklyQuestDefinitionRow['rarity'],
    rankingBased: Number(row.ranking_based || 0) === 1,
    sortOrder: Number(row.sort_order || 100),
  }));
}

async function getCurrentWeeklyScope(env: Env): Promise<WeeklyScope> {
  const weekKey = getWeekKey(todayKeyUTC());
  const weekWindow = getWeekWindowUtc(weekKey);
  const schema = await getSeasonSchemaSupport(env);
  const displaySeason = await getDisplaySeason(env);
  const fallbackSeasonId = displaySeason?.id ?? await getCurrentSeasonNumber(env);

  if (!schema.matchesSeasonId) {
    return { weekKey, seasonId: fallbackSeasonId };
  }

  const matchRow = await env.DB.prepare(`
    SELECT COALESCE(season_id, ?) AS season_id
    FROM matches
    WHERE is_pick = 1
      AND start_time >= ?
      AND start_time <= ?
    ORDER BY start_time DESC, match_id DESC
    LIMIT 1
  `).bind(fallbackSeasonId, weekWindow.startIso, weekWindow.endIso).first() as any;

  return {
    weekKey,
    seasonId: Number(matchRow?.season_id || fallbackSeasonId),
  };
}

async function getWeeklyScopesForDay(env: Env, day: string): Promise<WeeklyScope[]> {
  const schema = await getSeasonSchemaSupport(env);
  const displaySeason = await getDisplaySeason(env);
  const fallbackSeasonId = displaySeason?.id ?? await getCurrentSeasonNumber(env);
  const selectSeason = schema.matchesSeasonId ? `COALESCE(season_id, ${fallbackSeasonId})` : `${fallbackSeasonId}`;
  const res = await env.DB.prepare(`
    SELECT DISTINCT ${selectSeason} AS season_id, start_time
    FROM matches
    WHERE day = ?
      AND is_pick = 1
  `).bind(day).all();

  const map = new Map<string, WeeklyScope>();
  for (const row of ((res.results || []) as any[])) {
    const weekKey = getWeekKeyFromStartTime(String(row.start_time));
    const seasonId = Number(row.season_id || fallbackSeasonId);
    map.set(`${seasonId}:${weekKey}`, { weekKey, seasonId });
  }
  return [...map.values()];
}

async function getWeeklyScopeForMatch(env: Env, matchId: string): Promise<WeeklyScope | null> {
  const schema = await getSeasonSchemaSupport(env);
  const displaySeason = await getDisplaySeason(env);
  const fallbackSeasonId = displaySeason?.id ?? await getCurrentSeasonNumber(env);
  const selectSeason = schema.matchesSeasonId ? `COALESCE(season_id, ${fallbackSeasonId})` : `${fallbackSeasonId}`;
  const row = await env.DB.prepare(`
    SELECT start_time, ${selectSeason} AS season_id
    FROM matches
    WHERE match_id = ?
    LIMIT 1
  `).bind(matchId).first() as any;
  if (!row?.start_time) return null;
  return {
    weekKey: getWeekKeyFromStartTime(String(row.start_time)),
    seasonId: Number(row.season_id || fallbackSeasonId),
  };
}

async function listActiveDaysForWeeklyScope(env: Env, scope: WeeklyScope): Promise<string[]> {
  const schema = await getSeasonSchemaSupport(env);
  const window = getWeekWindowUtc(scope.weekKey);
  const query = schema.matchesSeasonId
    ? env.DB.prepare(`
        SELECT DISTINCT substr(start_time, 1, 10) AS utc_day
        FROM matches
        WHERE is_pick = 1
          AND start_time >= ?
          AND start_time <= ?
          AND COALESCE(season_id, ?) = ?
        ORDER BY utc_day ASC
      `).bind(window.startIso, window.endIso, scope.seasonId, scope.seasonId)
    : env.DB.prepare(`
        SELECT DISTINCT substr(start_time, 1, 10) AS utc_day
        FROM matches
        WHERE is_pick = 1
          AND start_time >= ?
          AND start_time <= ?
        ORDER BY utc_day ASC
      `).bind(window.startIso, window.endIso);
  const res = await query.all();
  return ((res.results || []) as any[]).map((row) => String(row.utc_day));
}

async function computeWeeklyGlobalProgress(
  env: Env,
  userId: number,
  scope: WeeklyScope
): Promise<WeeklyGlobalProgress> {
  const schema = await getSeasonSchemaSupport(env);
  const window = getWeekWindowUtc(scope.weekKey);
  const query = schema.matchesSeasonId
    ? env.DB.prepare(`
        SELECT
          p.home AS pick_home,
          p.away AS pick_away,
          p.joker,
          p.double_chance,
          pba.answer AS advances_answer,
          m.start_time,
          r.home AS result_home,
          r.away AS result_away,
          COALESCE(mbq.is_enabled, 0) AS bonus_enabled,
          COALESCE(mbq.points_award, 1) AS bonus_points_award,
          mbq.correct_answer AS bonus_correct_answer,
          mbq.resolved_at AS bonus_resolved_at
        FROM picks p
        JOIN matches m ON m.day = p.day AND m.match_id = p.match_id
        LEFT JOIN results r ON r.day = p.day AND r.match_id = p.match_id
        LEFT JOIN pick_bonus_answers pba
          ON pba.day = p.day
         AND pba.match_id = p.match_id
         AND pba.user_id = p.user_id
         AND pba.question_type = '${ADVANCES_TEAM_QUESTION}'
        LEFT JOIN match_bonus_questions mbq
          ON mbq.day = p.day
         AND mbq.match_id = p.match_id
         AND mbq.question_type = '${ADVANCES_TEAM_QUESTION}'
        WHERE p.user_id = ?
          AND m.is_pick = 1
          AND m.start_time >= ?
          AND m.start_time <= ?
          AND COALESCE(p.season_id, m.season_id, ?) = ?
      `).bind(userId, window.startIso, window.endIso, scope.seasonId, scope.seasonId)
    : env.DB.prepare(`
        SELECT
          p.home AS pick_home,
          p.away AS pick_away,
          p.joker,
          p.double_chance,
          pba.answer AS advances_answer,
          m.start_time,
          r.home AS result_home,
          r.away AS result_away,
          COALESCE(mbq.is_enabled, 0) AS bonus_enabled,
          COALESCE(mbq.points_award, 1) AS bonus_points_award,
          mbq.correct_answer AS bonus_correct_answer,
          mbq.resolved_at AS bonus_resolved_at
        FROM picks p
        JOIN matches m ON m.day = p.day AND m.match_id = p.match_id
        LEFT JOIN results r ON r.day = p.day AND r.match_id = p.match_id
        LEFT JOIN pick_bonus_answers pba
          ON pba.day = p.day
         AND pba.match_id = p.match_id
         AND pba.user_id = p.user_id
         AND pba.question_type = '${ADVANCES_TEAM_QUESTION}'
        LEFT JOIN match_bonus_questions mbq
          ON mbq.day = p.day
         AND mbq.match_id = p.match_id
         AND mbq.question_type = '${ADVANCES_TEAM_QUESTION}'
        WHERE p.user_id = ?
          AND m.is_pick = 1
          AND m.start_time >= ?
          AND m.start_time <= ?
      `).bind(userId, window.startIso, window.endIso);
  const res = await query.all();

  const pickedDays = new Set<string>();
  const pointsByDay = new Map<string, number>();
  let exactHits = 0;

  for (const row of ((res.results || []) as any[])) {
    const utcDay = getUtcDayFromIso(String(row.start_time));
    pickedDays.add(utcDay);
    if (row.result_home === null || row.result_away === null) continue;
    const baseCalc = calculateMatchPoints(
      row.pick_home,
      row.pick_away,
      row.result_home,
      row.result_away,
      row.joker,
      row.double_chance
    );
    const calc = applyMatchBonusPoints(baseCalc, row.advances_answer, getMatchBonusQuestionFromJoinedRow(row));
    if (calc.reason === 'exact') exactHits += 1;
    pointsByDay.set(utcDay, (pointsByDay.get(utcDay) ?? 0) + calc.total);
  }

  let activeDaysWithPoints = 0;
  for (const total of pointsByDay.values()) {
    if (total > 0) activeDaysWithPoints += 1;
  }

  return {
    activeDaysPicked: pickedDays.size,
    activeDaysWithPoints,
    exactHits,
  };
}

async function collectWeeklyLeagueStandingRows(env: Env, scope: WeeklyScope): Promise<WeeklyLeagueStandingRow[]> {
  const schema = await getSeasonSchemaSupport(env);
  const window = getWeekWindowUtc(scope.weekKey);
  const leagueMetas = await listLeagueMetadataRows(env);
  const eligibleLeagueIds = new Set(
    leagueMetas
      .filter((league) => leagueExistsDuringWindow(league, window.startMs, window.endMs))
      .map((league) => league.id)
  );
  if (!eligibleLeagueIds.size) return [];

  const memberships = await listLeagueMembershipIntervals(env);
  const metaMap = new Map<string, LeagueMetadataRow>(leagueMetas.map((league) => [league.id, league]));
  const intervalsByUser = new Map<number, Array<{ leagueId: string; startMs: number; endMs: number }>>();

  for (const membership of memberships) {
    if (!eligibleLeagueIds.has(membership.leagueId)) continue;
    const league = metaMap.get(membership.leagueId);
    if (!league) continue;
    const joinedAtMs = parseStoredDateTimeMs(membership.joinedAt) ?? parseStoredDateTimeMs(league.created_at) ?? Number.NEGATIVE_INFINITY;
    const leftAtMs = parseStoredDateTimeMs(membership.leftAt);
    const leagueCreatedAtMs = parseStoredDateTimeMs(league.created_at) ?? Number.NEGATIVE_INFINITY;
    const leagueDeletedAtMs = parseStoredDateTimeMs(league.deleted_at);
    const startMs = Math.max(joinedAtMs, leagueCreatedAtMs, window.startMs);
    const endMs = Math.min(
      leftAtMs ?? Number.POSITIVE_INFINITY,
      leagueDeletedAtMs ?? Number.POSITIVE_INFINITY,
      window.endMs
    );
    if (endMs < startMs) continue;
    if (!intervalsByUser.has(membership.userId)) intervalsByUser.set(membership.userId, []);
    intervalsByUser.get(membership.userId)!.push({ leagueId: membership.leagueId, startMs, endMs });
  }

  if (!intervalsByUser.size) return [];

  const query = schema.matchesSeasonId
    ? env.DB.prepare(`
        SELECT
          p.user_id,
          p.home AS pick_home,
          p.away AS pick_away,
          p.joker,
          p.double_chance,
          pba.answer AS advances_answer,
          p.match_id,
          m.start_time,
          r.home AS result_home,
          r.away AS result_away,
          COALESCE(mbq.is_enabled, 0) AS bonus_enabled,
          COALESCE(mbq.points_award, 1) AS bonus_points_award,
          mbq.correct_answer AS bonus_correct_answer,
          mbq.resolved_at AS bonus_resolved_at
        FROM picks p
        JOIN matches m ON m.day = p.day AND m.match_id = p.match_id
        LEFT JOIN results r ON r.day = p.day AND r.match_id = p.match_id
        LEFT JOIN pick_bonus_answers pba
          ON pba.day = p.day
         AND pba.match_id = p.match_id
         AND pba.user_id = p.user_id
         AND pba.question_type = '${ADVANCES_TEAM_QUESTION}'
        LEFT JOIN match_bonus_questions mbq
          ON mbq.day = p.day
         AND mbq.match_id = p.match_id
         AND mbq.question_type = '${ADVANCES_TEAM_QUESTION}'
        WHERE m.is_pick = 1
          AND m.start_time >= ?
          AND m.start_time <= ?
          AND COALESCE(p.season_id, m.season_id, ?) = ?
        ORDER BY p.user_id, m.start_time, p.match_id
      `).bind(window.startIso, window.endIso, scope.seasonId, scope.seasonId)
    : env.DB.prepare(`
        SELECT
          p.user_id,
          p.home AS pick_home,
          p.away AS pick_away,
          p.joker,
          p.double_chance,
          pba.answer AS advances_answer,
          p.match_id,
          m.start_time,
          r.home AS result_home,
          r.away AS result_away,
          COALESCE(mbq.is_enabled, 0) AS bonus_enabled,
          COALESCE(mbq.points_award, 1) AS bonus_points_award,
          mbq.correct_answer AS bonus_correct_answer,
          mbq.resolved_at AS bonus_resolved_at
        FROM picks p
        JOIN matches m ON m.day = p.day AND m.match_id = p.match_id
        LEFT JOIN results r ON r.day = p.day AND r.match_id = p.match_id
        LEFT JOIN pick_bonus_answers pba
          ON pba.day = p.day
         AND pba.match_id = p.match_id
         AND pba.user_id = p.user_id
         AND pba.question_type = '${ADVANCES_TEAM_QUESTION}'
        LEFT JOIN match_bonus_questions mbq
          ON mbq.day = p.day
         AND mbq.match_id = p.match_id
         AND mbq.question_type = '${ADVANCES_TEAM_QUESTION}'
        WHERE m.is_pick = 1
          AND m.start_time >= ?
          AND m.start_time <= ?
        ORDER BY p.user_id, m.start_time, p.match_id
      `).bind(window.startIso, window.endIso);
  const rowsRes = await query.all();

  const standingMap = new Map<string, WeeklyLeagueStandingRow>();
  const seenMembershipMatches = new Set<string>();

  const ensure = (leagueId: string, userId: number) => {
    const key = `${leagueId}:${userId}`;
    if (!standingMap.has(key)) {
      standingMap.set(key, {
        leagueId,
        userId,
        finalRank: 0,
        finalPoints: 0,
        exactHits: 0,
        jokerPoints: 0,
        matchesPredicted: 0,
      });
    }
    return standingMap.get(key)!;
  };

  for (const row of ((rowsRes.results || []) as any[])) {
    const userId = Number(row.user_id);
    const intervals = intervalsByUser.get(userId);
    if (!intervals?.length) continue;
    const matchMs = parseStoredDateTimeMs(row.start_time);
    if (matchMs === null) continue;

    for (const interval of intervals) {
      if (matchMs < interval.startMs || matchMs > interval.endMs) continue;
      const membershipMatchKey = `${interval.leagueId}:${userId}:${row.match_id}`;
      if (seenMembershipMatches.has(membershipMatchKey)) continue;
      seenMembershipMatches.add(membershipMatchKey);

      const item = ensure(interval.leagueId, userId);
      item.matchesPredicted += 1;

      if (row.result_home === null || row.result_away === null) continue;
      const baseCalc = calculateMatchPoints(
        row.pick_home,
        row.pick_away,
        row.result_home,
        row.result_away,
        row.joker,
        row.double_chance
      );
      const calc = applyMatchBonusPoints(baseCalc, row.advances_answer, getMatchBonusQuestionFromJoinedRow(row));
      item.finalPoints += calc.total;
      if (calc.reason === 'exact') item.exactHits += 1;
      if (Number(row.joker) === 1) item.jokerPoints += calc.total;
    }
  }

  const byLeague = new Map<string, WeeklyLeagueStandingRow[]>();
  for (const row of standingMap.values()) {
    if (row.matchesPredicted <= 0) continue;
    if (!byLeague.has(row.leagueId)) byLeague.set(row.leagueId, []);
    byLeague.get(row.leagueId)!.push(row);
  }

  const result: WeeklyLeagueStandingRow[] = [];
  for (const rows of byLeague.values()) {
    const ranked = [...rows].sort((a, b) =>
      b.finalPoints - a.finalPoints ||
      b.exactHits - a.exactHits ||
      b.jokerPoints - a.jokerPoints ||
      a.userId - b.userId
    );
    ranked.forEach((row, index) => {
      row.finalRank = index + 1;
      result.push(row);
    });
  }

  return result;
}

async function buildWeeklyFinalizationReport(env: Env, scope: WeeklyScope) {
  const schema = await getSeasonSchemaSupport(env);
  const window = getWeekWindowUtc(scope.weekKey);
  const query = schema.matchesSeasonId
    ? env.DB.prepare(`
        SELECT
          m.match_id,
          m.status,
          r.match_id AS has_result
        FROM matches m
        LEFT JOIN results r ON r.day = m.day AND r.match_id = m.match_id
        WHERE m.is_pick = 1
          AND m.start_time >= ?
          AND m.start_time <= ?
          AND COALESCE(m.season_id, ?) = ?
      `).bind(window.startIso, window.endIso, scope.seasonId, scope.seasonId)
    : env.DB.prepare(`
        SELECT
          m.match_id,
          m.status,
          r.match_id AS has_result
        FROM matches m
        LEFT JOIN results r ON r.day = m.day AND r.match_id = m.match_id
        WHERE m.is_pick = 1
          AND m.start_time >= ?
          AND m.start_time <= ?
      `).bind(window.startIso, window.endIso);
  const res = await query.all();
  const rows = (res.results || []) as any[];
  const totalMatches = rows.length;
  if (totalMatches === 0) {
    return {
      seasonId: scope.seasonId,
      weekKey: scope.weekKey,
      totalMatches: 0,
      settledMatches: 0,
      unresolvedMatches: 0,
      ready: false,
      reason: 'NO_MATCHES',
      cutoffAt: window.cutoffMs,
    };
  }

  let settledMatches = 0;
  let unresolvedMatches = 0;
  for (const row of rows) {
    const status = String(row.status || '').toUpperCase();
    const hasResult = !!row.has_result;
    const settledByStatus = ['FINISHED', 'AWARDED', 'POSTPONED', 'CANCELLED'].includes(status);
    if (hasResult || settledByStatus) settledMatches += 1;
    else unresolvedMatches += 1;
  }

  const nowMs = Date.now();
  const weekEnded = nowMs >= window.endMs;
  const cutoffReached = nowMs >= window.cutoffMs;
  // Only finalize after the week has actually ended (Sunday 23:59 UTC)
  const ready = weekEnded && (unresolvedMatches === 0 || cutoffReached);
  return {
    seasonId: scope.seasonId,
    weekKey: scope.weekKey,
    totalMatches,
    settledMatches,
    unresolvedMatches,
    ready,
    reason: ready ? (unresolvedMatches === 0 ? null : 'CUTOFF_REACHED') : 'UNRESOLVED_MATCHES',
    cutoffAt: window.cutoffMs,
  };
}

async function replaceWeeklyLeagueSnapshots(
  env: Env,
  scope: WeeklyScope,
  rows: WeeklyLeagueStandingRow[]
) {
  const schema = await getQuestSchemaSupport(env);
  if (!schema.weeklyLeagueSnapshotTable) return;
  const now = Date.now();
  const statements: D1PreparedStatement[] = [
    env.DB.prepare(`
      DELETE FROM weekly_league_standings_snapshot
      WHERE season_id = ? AND week_key = ?
    `).bind(scope.seasonId, scope.weekKey),
  ];

  for (const row of rows) {
    statements.push(env.DB.prepare(`
      INSERT INTO weekly_league_standings_snapshot (
        season_id,
        week_key,
        league_id,
        user_id,
        final_rank,
        final_points,
        exact_hits,
        joker_points,
        matches_predicted,
        created_at
      )
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(
      scope.seasonId,
      scope.weekKey,
      row.leagueId,
      row.userId,
      row.finalRank,
      row.finalPoints,
      row.exactHits,
      row.jokerPoints,
      row.matchesPredicted,
      now
    ));
  }

  await runBatchedStatements(env, statements);
}

async function syncWeeklyRankingRewards(
  env: Env,
  scope: WeeklyScope,
  rows: WeeklyLeagueStandingRow[]
) {
  const defs = (await listWeeklyQuestDefinitions(env))
    .filter((def) => def.scope === 'league' && def.rankingBased);
  if (!defs.length) return;

  const grouped = new Map<string, WeeklyLeagueStandingRow[]>();
  for (const row of rows) {
    if (!grouped.has(row.leagueId)) grouped.set(row.leagueId, []);
    grouped.get(row.leagueId)!.push(row);
  }

  const qualifying = new Map<string, { userId: number; taskKey: string; instanceKey: string; stars: number }>();
  for (const [leagueId, leagueRows] of grouped.entries()) {
    for (const def of defs) {
      if (!hasEnoughLeagueRankingParticipants(leagueRows, def.threshold)) continue;
      for (const row of leagueRows) {
        if (row.finalRank <= def.threshold) {
          const instanceKey = getWeeklyLeagueInstanceKey(scope.weekKey, leagueId);
          qualifying.set(`${def.taskKey}:${instanceKey}:${row.userId}`, {
            userId: row.userId,
            taskKey: def.taskKey,
            instanceKey,
            stars: def.rewardStars,
          });
        }
      }
    }
  }

  const taskKeys = defs.map((def) => def.taskKey);
  const keyPlaceholders = taskKeys.map(() => '?').join(', ');
  const existingRes = await env.DB.prepare(`
    SELECT user_id, task_key, instance_key
    FROM user_task_progress
    WHERE season_id = ?
      AND task_key IN (${keyPlaceholders})
      AND instance_key LIKE ?
  `).bind(scope.seasonId, ...taskKeys, `week:${scope.weekKey}%`).all();

  for (const row of ((existingRes.results || []) as any[])) {
    const userId = Number(row.user_id);
    const taskKey = String(row.task_key);
    const instanceKey = String(row.instance_key);
    const compoundKey = `${taskKey}:${instanceKey}:${userId}`;
    if (qualifying.has(compoundKey)) continue;
    const def = defs.find((item) => item.taskKey === taskKey);
    if (!def) continue;
    await revokeStarsForTask(env, userId, scope.seasonId, taskKey, instanceKey, def.rewardStars);
    await env.DB.prepare(`
      DELETE FROM user_task_progress
      WHERE user_id = ? AND season_id = ? AND task_key = ? AND instance_key = ?
    `).bind(userId, scope.seasonId, taskKey, instanceKey).run();
  }

  for (const item of qualifying.values()) {
    await upsertTaskProgress(env, item.userId, scope.seasonId, item.taskKey, item.instanceKey, 1, { completed: true });
    const award = await awardStarsViaLedger(env, item.userId, scope.seasonId, item.taskKey, item.instanceKey, item.stars, 'weekly_task');
    if (award.awarded) {
      await markTaskRewardGranted(env, item.userId, scope.seasonId, item.taskKey, item.instanceKey);
    }
  }
}

async function finalizeWeeklyPeriod(env: Env, scope: WeeklyScope, opts?: { force?: boolean }) {
  const questSchema = await getQuestSchemaSupport(env);
  if (!questSchema.weeklyFinalizationsTable || !questSchema.weeklyLeagueSnapshotTable) {
    return { ok: false, reason: 'WEEKLY_SCHEMA_NOT_READY' as const };
  }

  const report = await buildWeeklyFinalizationReport(env, scope);
  if (!report.ready && !opts?.force) {
    return { ok: false, reason: report.reason, report };
  }

  const rows = await collectWeeklyLeagueStandingRows(env, scope);
  await replaceWeeklyLeagueSnapshots(env, scope, rows);
  await syncWeeklyRankingRewards(env, scope, rows);

  const window = getWeekWindowUtc(scope.weekKey);
  await env.DB.prepare(`
    INSERT INTO weekly_finalizations (season_id, week_key, week_start, week_end, cutoff_at, finalized_at, reason)
    VALUES (?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(season_id, week_key) DO UPDATE SET
      week_start = excluded.week_start,
      week_end = excluded.week_end,
      cutoff_at = excluded.cutoff_at,
      finalized_at = excluded.finalized_at,
      reason = excluded.reason
  `).bind(
    scope.seasonId,
    scope.weekKey,
    window.startIso,
    window.endIso,
    window.cutoffMs,
    Date.now(),
    report.reason
  ).run();

  return {
    ok: true,
    report,
    rows: rows.length,
  };
}

async function maybeFinalizeWeeklyForDay(env: Env, day: string) {
  const scopes = await getWeeklyScopesForDay(env, day);
  const results: any[] = [];
  for (const scope of scopes) {
    const report = await buildWeeklyFinalizationReport(env, scope);
    if (!report.ready) continue;
    results.push(await finalizeWeeklyPeriod(env, scope, { force: false }));
  }
  return results;
}

async function finalizeRecentWeeklyPeriods(env: Env) {
  const __t0 = Date.now(); const __runId = makeRunId(); let __status = "ok"; let __scopes = 0;
  try {
  const schema = await getSeasonSchemaSupport(env);
  const displaySeason = await getDisplaySeason(env);
  const fallbackSeasonId = displaySeason?.id ?? await getCurrentSeasonNumber(env);
  const since = new Date();
  since.setUTCDate(since.getUTCDate() - 21);
  const sinceIso = since.toISOString();
  const selectSeason = schema.matchesSeasonId ? `COALESCE(season_id, ${fallbackSeasonId})` : `${fallbackSeasonId}`;
  const res = await env.DB.prepare(`
    SELECT DISTINCT ${selectSeason} AS season_id, start_time
    FROM matches
    WHERE is_pick = 1
      AND start_time >= ?
  `).bind(sinceIso).all();

  const scopes = new Map<string, WeeklyScope>();
  for (const row of ((res.results || []) as any[])) {
    const weekKey = getWeekKeyFromStartTime(String(row.start_time));
    const seasonId = Number(row.season_id || fallbackSeasonId);
    scopes.set(`${seasonId}:${weekKey}`, { seasonId, weekKey });
  }

  __scopes = scopes.size;
  for (const scope of scopes.values()) {
    // Skip weeks that are already finalized. Without this guard the periodic
    // sweep re-ran the FULL weekly standings recompute (collectWeeklyLeague
    // StandingRows + replaceWeeklyLeagueSnapshots + syncWeeklyRankingRewards)
    // for every completed week on every 10-minute cron tick — a massive, useless
    // D1 rows-read drain (~the dominant source of daily usage). Legitimate
    // re-finalization after a result/manual correction is handled separately by
    // the day-level path (maybeFinalizeWeeklyForDay), so this sweep only needs to
    // catch weeks that became ready and were never finalized.
    if (await getWeeklyFinalizationRow(env, scope)) continue;
    const report = await buildWeeklyFinalizationReport(env, scope);
    if (report.ready) {
      await finalizeWeeklyPeriod(env, scope, { force: false });
    }
  }
  } catch (__e) { __status = "error"; throw __e; } finally { logEvent({ operation: "finalizeRecentWeeklyPeriods", trigger: "internal", run_id: __runId, status: __status, duration_ms: Date.now() - __t0, processed_periods: __scopes }); }
}

// ===========================================================================
// Stage 6 — Weekly Finalizer V2 (atomic-locked job model over existing finalize)
//
// Reuses finalizeWeeklyPeriod (idempotent via weekly_finalizations ON CONFLICT +
// replaceWeeklyLeagueSnapshots + syncWeeklyRankingRewards). V2 only adds a single
// owner lock + a dedicated cron + a GET gate. Default flag false = inert.
// ===========================================================================

// Discover RECENT weekly scopes that are READY to finalize (bounded window).
async function discoverReadyWeeklyScopes(env: Env, limit: number): Promise<WeeklyScopeRef[]> {
  const schema = await getSeasonSchemaSupport(env);
  const displaySeason = await getDisplaySeason(env);
  const fallbackSeasonId = displaySeason?.id ?? await getCurrentSeasonNumber(env);
  const since = new Date();
  since.setUTCDate(since.getUTCDate() - 21);
  const selectSeason = schema.matchesSeasonId ? `COALESCE(season_id, ${fallbackSeasonId})` : `${fallbackSeasonId}`;
  const res = await env.DB.prepare(`
    SELECT DISTINCT ${selectSeason} AS season_id, start_time
    FROM matches WHERE is_pick = 1 AND start_time >= ?
  `).bind(since.toISOString()).all();
  const scopeMap = new Map<string, WeeklyScopeRef>();
  for (const row of ((res.results || []) as any[])) {
    const weekKey = getWeekKeyFromStartTime(String(row.start_time));
    const seasonId = Number(row.season_id || fallbackSeasonId);
    scopeMap.set(`${seasonId}:${weekKey}`, { seasonId, weekKey });
  }
  const ready: WeeklyScopeRef[] = [];
  for (const scope of scopeMap.values()) {
    const report = await buildWeeklyFinalizationReport(env, scope);
    if (report.ready) ready.push(scope);
    if (ready.length >= limit) break;
  }
  return ready;
}

// Apply: claims per-period jobs and finalizes via the existing idempotent finalize.
async function runWeeklyFinalizerV2(env: Env, opts: { trigger: string }) {
  const params = resolveWeeklyParams(resolveEffectiveApiFlags(env));
  return runWeeklyFinalizerCore(env.DB, params, {
    trigger: opts.trigger,
    listReadyScopes: () => discoverReadyWeeklyScopes(env, params.maxPeriods),
    finalizeScope: async (scope) => {
      const result = await finalizeWeeklyPeriod(env, scope, { force: false });
      return { ...result, reason: result.reason ?? undefined };
    },
  });
}

// Read-only dry-run for one scope: readiness + estimated snapshot rows. No writes.
async function dryRunWeeklyFinalizer(env: Env, scope: WeeklyScopeRef) {
  const report = await buildWeeklyFinalizationReport(env, scope);
  let estimatedRows = 0;
  if (report.ready) {
    try { estimatedRows = (await collectWeeklyLeagueStandingRows(env, scope)).length; } catch { /* best-effort */ }
  }
  const alreadyFinalized = !!(await getWeeklyFinalizationRow(env, scope));
  logEvent({ operation: "weekly_finalizer_v2", trigger: "internal_dry_run", run_id: makeRunId(), job_key: buildWeeklyJobKey(scope.seasonId, scope.weekKey), status: "dry_run_completed", dry_run: true, reason_code: report.reason ?? undefined });
  return { ok: true, season_id: scope.seasonId, week_key: scope.weekKey, ready: report.ready, reason: report.reason ?? undefined, estimated_snapshot_rows: estimatedRows, already_finalized: alreadyFinalized };
}

// The previous (just-ended) week scope — the one the GET fallback would finalize.
export function previousWeeklyScope(currentScope: WeeklyScopeRef): WeeklyScopeRef {
  const prevWeekKey = getWeekKeyFromStartTime(new Date(Date.now() - 7 * 24 * 3600 * 1000).toISOString());
  return { seasonId: currentScope.seasonId, weekKey: prevWeekKey };
}

// GET /quests/weekly gate (Stage 6 §GET + Stage 7 read-skip). Returns whether to
// run legacy finalize. `userId` (Stage 7) enables a pure-read path for explicitly
// allowlisted test users while V2 is on; non-allowlist & V2-off keep Stage 6 behavior.
export async function weeklyGetShouldRunLegacy(
  env: Env,
  currentScope: WeeklyScopeRef,
  userId?: number
): Promise<boolean> {
  const flags = resolveEffectiveApiFlags(env);
  const t0 = Date.now();
  const target = previousWeeklyScope(currentScope);
  const jobKey = buildWeeklyJobKey(target.seasonId, target.weekKey);

  // Allowlist applies ONLY when V2 is enabled. Empty / invalid env → nobody affected.
  const skipUserIds = parseUserIdAllowlist(env.WEEKLY_GET_FALLBACK_SKIP_USER_IDS);
  const inAllowlist = flags.weeklyFinalizerV2 && userId != null && skipUserIds.has(userId);

  // Resolve the previous-week job state (only when V2 on). A read failure becomes
  // "read_error" so we never fabricate a completed status.
  let jobState: WeeklyJobState = "missing";
  let jobStatusLabel = "missing";
  if (flags.weeklyFinalizerV2) {
    try {
      const job = await getWeeklyJobStrict(env.DB, jobKey);
      const staleMs = flags.weeklyFinalizerStaleLockMinutes * 60_000;
      const decision = classifyWeeklyLock(
        job ? { status: job.status as any, run_id: job.run_id, heartbeat_at: job.heartbeat_at } : null,
        Date.now(),
        staleMs
      );
      jobState = weeklyJobStateOf(job, decision);
      jobStatusLabel = job?.status ?? "missing";
    } catch {
      jobState = "read_error";
      jobStatusLabel = "read_error";
    }
  }

  const d = decideWeeklyGetGate({
    v2Enabled: flags.weeklyFinalizerV2,
    inAllowlist,
    fallbackEnabled: flags.weeklyGetFallback,
    jobState,
  });

  // Logging (no initData / payloads — only minimal identifiers).
  if (d.operation === "weekly_get_reconcile_skipped") {
    logEvent({ operation: "weekly_get_reconcile_skipped", run_id: makeRunId(), user_id: userId, period_key: target.weekKey, job_status: jobStatusLabel, reason_code: d.reason, duration_ms: Date.now() - t0 });
  } else if (d.operation === "job_status_read_failed_fallback") {
    logEvent({ operation: "job_status_read_failed_fallback", run_id: makeRunId(), job_key: jobKey, user_id: userId, period_key: target.weekKey, job_status: "read_error", reason_code: d.reason, duration_ms: Date.now() - t0 });
  } else if (!(flags.weeklyFinalizerV2 === false && d.reason === "v2_off_legacy")) {
    // Preserve Stage 6 logs for non-allowlist V2-on paths (V2-off stays silent).
    logEvent({ operation: d.operation, run_id: makeRunId(), job_key: jobKey, period_key: target.weekKey, reason_code: d.reason });
  }

  if (d.propagateError) {
    // Non-allowlist read error → let the caller's try/catch handle it (no finalize), as in Stage 6.
    throw new Error("weekly_job_status_read_failed");
  }
  return d.runLegacy;
}

// Exported for the integration suite (weeklyTaskBalls.inttest.ts), same as
// checkDailyQuests — `export` only widens visibility, runtime behaviour is unchanged.
export async function checkWeeklyQuests(
  env: Env,
  userId: number,
  scope: WeeklyScope,
  phase: 'pick_saved' | 'scores_updated'
) {
  const __t0 = Date.now(); const __runId = makeRunId(); let __status = "ok";
  try {
  const defs = (await listWeeklyQuestDefinitions(env))
    .filter((def) => def.scope === 'global' && !def.rankingBased && def.phase === phase);
  if (!defs.length) return [];

  const [progress, activeDays] = await Promise.all([
    computeWeeklyGlobalProgress(env, userId, scope),
    listActiveDaysForWeeklyScope(env, scope),
  ]);
  const potentialDayCount = countWeeklyPotentialDays(scope, activeDays);
  const completed: string[] = [];
  const instanceKey = getWeeklyInstanceKey(scope.weekKey);

  for (const def of defs) {
    let value = 0;
    if (def.taskKey === 'weekly_active_days_3') value = progress.activeDaysPicked;
    else if (def.taskKey === 'weekly_points_days_3') value = progress.activeDaysWithPoints;
    else if (def.taskKey === 'global_double_exact_week') value = progress.exactHits;
    else continue;

    // Short weeks (international break, season start) cannot satisfy a hardcoded
    // "3 game days" target — clamp it to what the week actually offers.
    const threshold = resolveWeeklyThreshold(def.taskKey, def.threshold, potentialDayCount);
    const bounded = Math.min(value, threshold);
    const completedNow = value >= threshold;
    await upsertTaskProgress(env, userId, scope.seasonId, def.taskKey, instanceKey, bounded, { completed: completedNow });

    if (completedNow) {
      const award = await awardStarsViaLedger(env, userId, scope.seasonId, def.taskKey, instanceKey, def.rewardStars, 'weekly_task');
      if (award.awarded) {
        await markTaskRewardGranted(env, userId, scope.seasonId, def.taskKey, instanceKey);
        completed.push(def.taskKey); // only pushed when newly awarded (first completion)
      }
    } else {
      await revokeStarsForTask(env, userId, scope.seasonId, def.taskKey, instanceKey, def.rewardStars);
    }
  }

  await getWeeklyBonusCaseState(env, userId, scope);

  return completed;
  } catch (__e) { __status = "error"; throw __e; } finally { logEvent({ operation: "checkWeeklyQuests", trigger: phase, run_id: __runId, status: __status, duration_ms: Date.now() - __t0, processed_users: 1 }); }
}

async function getWeeklyFinalizationRow(env: Env, scope: WeeklyScope) {
  const schema = await getQuestSchemaSupport(env);
  if (!schema.weeklyFinalizationsTable) return null;
  return await env.DB.prepare(`
    SELECT season_id, week_key, finalized_at, reason
    FROM weekly_finalizations
    WHERE season_id = ? AND week_key = ?
    LIMIT 1
  `).bind(scope.seasonId, scope.weekKey).first() as any;
}

async function loadWeeklyLeagueStandingRows(
  env: Env,
  scope: WeeklyScope
): Promise<{ finalized: boolean; rows: WeeklyLeagueStandingRow[] }> {
  const questSchema = await getQuestSchemaSupport(env);
  const finalization = await getWeeklyFinalizationRow(env, scope);
  if (questSchema.weeklyLeagueSnapshotTable && finalization?.finalized_at) {
    const res = await env.DB.prepare(`
      SELECT
        league_id,
        user_id,
        final_rank,
        final_points,
        exact_hits,
        joker_points,
        matches_predicted
      FROM weekly_league_standings_snapshot
      WHERE season_id = ? AND week_key = ?
      ORDER BY league_id, final_rank ASC, user_id ASC
    `).bind(scope.seasonId, scope.weekKey).all();

    const rows = ((res.results || []) as any[]).map((row) => ({
      leagueId: String(row.league_id),
      userId: Number(row.user_id),
      finalRank: Number(row.final_rank || 0),
      finalPoints: Number(row.final_points || 0),
      exactHits: Number(row.exact_hits || 0),
      jokerPoints: Number(row.joker_points || 0),
      matchesPredicted: Number(row.matches_predicted || 0),
    }));
    return { finalized: true, rows };
  }

  return {
    finalized: false,
    rows: await collectWeeklyLeagueStandingRows(env, scope),
  };
}

async function listRelevantWeeklyLeaguesForUser(
  env: Env,
  userId: number,
  scope: WeeklyScope
): Promise<Array<{ id: string; name: string; type: 'private' | 'channel' }>> {
  const window = getWeekWindowUtc(scope.weekKey);
  const leagues = await listLeagueMetadataRows(env);
  const intervals = await listLeagueMembershipIntervals(env);
  const leagueMap = new Map<string, LeagueMetadataRow>(leagues.map((league) => [league.id, league]));
  const seen = new Map<string, { id: string; name: string; type: 'private' | 'channel' }>();

  for (const interval of intervals) {
    if (interval.userId !== userId) continue;
    const league = leagueMap.get(interval.leagueId);
    if (!league || !leagueExistsDuringWindow(league, window.startMs, window.endMs)) continue;

    const joinedAtMs = parseStoredDateTimeMs(interval.joinedAt) ?? parseStoredDateTimeMs(league.created_at) ?? Number.NEGATIVE_INFINITY;
    const leftAtMs = parseStoredDateTimeMs(interval.leftAt);
    const leagueCreatedAtMs = parseStoredDateTimeMs(league.created_at) ?? Number.NEGATIVE_INFINITY;
    const leagueDeletedAtMs = parseStoredDateTimeMs(league.deleted_at);
    const startMs = Math.max(joinedAtMs, leagueCreatedAtMs, window.startMs);
    const endMs = Math.min(
      leftAtMs ?? Number.POSITIVE_INFINITY,
      leagueDeletedAtMs ?? Number.POSITIVE_INFINITY,
      window.endMs
    );
    if (endMs < startMs) continue;

    seen.set(interval.leagueId, {
      id: interval.leagueId,
      name: league.name || `League ${interval.leagueId.slice(0, 8)}`,
      type: league.type,
    });
  }

  return [...seen.values()].sort((a, b) => a.name.localeCompare(b.name, 'ru', { sensitivity: 'base' }));
}

// Update scores_agg for a user

// Recalculate all user scores for a day after results are finalized
async function recalcDayScores(env: Env, day: string, results: Record<string, { home: number, away: number }>) {
  const __t0 = Date.now(); const __runId = makeRunId(); let __status = "ok";
  try {
  // Get all picks for this day
  const picksRes = await env.DB.prepare(`
    SELECT
      p.user_id,
      p.match_id,
      p.home,
      p.away,
      p.joker,
      p.double_chance,
      pba.answer AS advances_answer,
      COALESCE(mbq.is_enabled, 0) AS bonus_enabled,
      COALESCE(mbq.points_award, 1) AS bonus_points_award,
      mbq.correct_answer AS bonus_correct_answer,
      mbq.resolved_at AS bonus_resolved_at
    FROM picks p
    LEFT JOIN pick_bonus_answers pba
      ON pba.day = p.day
     AND pba.match_id = p.match_id
     AND pba.user_id = p.user_id
     AND pba.question_type = '${ADVANCES_TEAM_QUESTION}'
    LEFT JOIN match_bonus_questions mbq
      ON mbq.day = p.day
     AND mbq.match_id = p.match_id
     AND mbq.question_type = '${ADVANCES_TEAM_QUESTION}'
    WHERE p.day = ?
  `).bind(day).all();

  const picks = (picksRes.results || []) as any[];

  // Calculate points per user
  const userPoints: Record<number, number> = {};
  const activeUserIds = new Set<number>();

  for (const p of picks) {
    activeUserIds.add(Number(p.user_id));
    const r = results[String(p.match_id)];
    if (!r) continue;

    // Bonus questions (incl. advances_team) now reward STARS only, never day
    // points (2026-06-26). Day score = match-result points only (5/3/2/0, with
    // joker/double-chance). Star rewards are granted separately via
    // grantBonusQuestionRewards (reward_stars), independent of this aggregate.
    const baseCalc = calculateMatchPoints(p.home, p.away, r.home, r.away, p.joker, p.double_chance);
    const total = baseCalc.total;

    const uid = Number(p.user_id);
    userPoints[uid] = (userPoints[uid] || 0) + total;
  }

  // Daily per-match goalscorer scoring removed from runtime (2026-06-26).
  // This legacy feature awarded +2 day-score points for a correct match
  // goalscorer pick, which leaked into scores_agg / leaderboard / profile. The
  // goalscorer concept now lives only in the `user_goalscorer` bonus question
  // (star reward) and in the season-predictions mode. pick_goalscorers /
  // match_goalscorer_settings tables are kept for a possible Stage 2 drop.

  // Generic bonus-question day points removed (2026-06-26): all bonus questions
  // reward STARS only (granted via grantBonusQuestionRewards), never day points.

  if (activeUserIds.size === 0) return;

  const dayPeriod = `day:${day}`;
  const weekPeriod = `week:${getWeekKey(day)}`;
  const monthPeriod = `month:${day.slice(0, 7)}`;
  const seasonPeriod = await getSeasonPeriodForDay(env, day);

  // Bulk fetch existing day scores to calculate deltas
  const uids = Array.from(activeUserIds);
  const existingScoresMap = new Map<number, number>();
  const chunkSearch = 50;
  for (let i = 0; i < uids.length; i += chunkSearch) {
    const chunk = uids.slice(i, i + chunkSearch);
    const placeholders = chunk.map(() => '?').join(',');
    const res = await env.DB.prepare(`
      SELECT user_id, points FROM scores_agg WHERE period = ? AND user_id IN (${placeholders})
    `).bind(dayPeriod, ...chunk).all();
    (res.results || []).forEach((r: any) => existingScoresMap.set(Number(r.user_id), Number(r.points || 0)));
  }

  const batch: D1PreparedStatement[] = [];

  // Update scores_agg for each user
  for (const uid of uids) {
    const points = userPoints[uid] || 0;
    const oldPoints = existingScoresMap.get(uid) || 0;
    const delta = points - oldPoints;

    if (delta !== 0) {
      // Update day period (replace)
      batch.push(env.DB.prepare(`
        INSERT INTO scores_agg (user_id, period, points)
        VALUES (?, ?, ?)
        ON CONFLICT(user_id, period) DO UPDATE SET points = excluded.points
      `).bind(uid, dayPeriod, points));

      // Update week, month, season, all with delta
      for (const period of [weekPeriod, monthPeriod, seasonPeriod, "all"]) {
        batch.push(env.DB.prepare(`
          INSERT INTO scores_agg (user_id, period, points)
          VALUES (?, ?, ?)
          ON CONFLICT(user_id, period) DO UPDATE SET points = points + excluded.points
        `).bind(uid, period, delta));
      }
    }
  }

  if (batch.length > 0) {
    await runBatchedStatements(env, batch, 100);
  }

  // --- STATS & LEAGUES UPDATE ---
  // gameDays is global, fetch once and share across all users (was refetched per
  // user inside updateUserStats). Per-user work is independent, so run it with
  // bounded concurrency instead of strictly sequentially.
  const gameDays = await getGameDays(env);
  await mapWithConcurrency(Array.from(activeUserIds), 10, async (uid) => {
    await updateUserStats(env, uid, gameDays);
    await updateUserDayStats(env, uid, day);
  });

  // Leagues aggregate the per-user day stats above, so run them after the user loop.
  const impactedLeagueIds = await listActiveLeagueIdsForDay(env, day);
  await mapWithConcurrency(impactedLeagueIds, 8, (leagueId) => updateLeagueDayStats(env, leagueId, day));
  } catch (__e) { __status = "error"; throw __e; } finally { logEvent({ operation: "recalcDayScores", trigger: "internal", run_id: __runId, status: __status, duration_ms: Date.now() - __t0 }); }
}

async function getStoredResultsMapForDay(env: Env, day: string) {
  const dayResults = await env.DB.prepare(`
    SELECT match_id, home, away FROM results WHERE day = ?
  `).bind(day).all();
  const resultsMap: Record<string, { home: number; away: number }> = {};
  for (const r of (dayResults.results || []) as any[]) {
    resultsMap[String(r.match_id)] = { home: Number(r.home), away: Number(r.away) };
  }
  return resultsMap;
}

async function recalcDayAndMaybeResendSummary(
  env: Env,
  ctx: ExecutionContext,
  day: string,
  reasonLabel: string
) {
  const resultsMap = await getStoredResultsMapForDay(env, day);
  await resolveBonusQuestionsFromStoredResults(env, day, resultsMap);
  await resolveGoalscorersForDay(env, day);
  await recalcDayScores(env, day, resultsMap);
  await grantPendingBonusRewardsForDay(env, day);
  const finalize = await finalizeDay(env, day, { skipRecalc: true });
  const summaryAlreadySent = await wasSummaryAlreadySentForDay(env, day);
  const shouldResendSummary = finalize.ready || summaryAlreadySent;

  if (shouldResendSummary) {
    ctx.waitUntil(
      triggerBotSummaryResend(env, day)
        .then(() => console.log(`[${reasonLabel}] Queued immediate bot summary resend for day=${day} (ready=${finalize.ready}, alreadySent=${summaryAlreadySent})`))
        .catch(e => console.error(`[${reasonLabel}] Bot resend trigger failed:`, e))
    );
  } else {
    console.log(`[${reasonLabel}] Skip resend for day=${day}: finalize not ready (${finalize.reason}), summaryAlreadySent=${summaryAlreadySent}`);
  }

  return { finalize, summaryAlreadySent, resultsMap };
}

async function upsertResults(env: Env, day: string, rows: any[]) {
  const finished = rows.filter((r) => {
    // If strict normalized object represents a valid finished 90-min result
    if (r.normalized) {
      return r.normalized.isFinished && typeof r.normalized.home90 === 'number' && typeof r.normalized.away90 === 'number';
    }
    // Fallback logic
    const h = r.score?.home ?? r.homeScore ?? r.home;
    const a = r.score?.away ?? r.awayScore ?? r.away;
    const validScore = (typeof h === 'number' || /\d+/.test(String(h))) && (typeof a === 'number' || /\d+/.test(String(a)));
    const normalizedStatus = String(r.status || "").toUpperCase();
    const isFinished = ["FINISHED", "FT", "FULL_TIME"].includes(normalizedStatus);
    return isFinished && validScore;
  });

  if (finished.length === 0) return;
  const schema = await getSeasonSchemaSupport(env);
  const season = await getSeasonForDay(env, day);
  const seasonId = season?.id ?? null;

  const stmt = schema.resultsSeasonId
    ? env.DB.prepare(`
        INSERT INTO results (day, match_id, home, away, finalized_at, is_manual, season_id)
        VALUES (?, ?, ?, ?, ?, 0, ?)
        ON CONFLICT(day, match_id) DO UPDATE SET
          home=excluded.home,
          away=excluded.away,
          finalized_at=excluded.finalized_at,
          season_id=COALESCE(excluded.season_id, results.season_id)
        WHERE results.is_manual = 0 OR results.is_manual IS NULL
      `)
    : env.DB.prepare(`
        INSERT INTO results (day, match_id, home, away, finalized_at, is_manual)
        VALUES (?, ?, ?, ?, ?, 0)
        ON CONFLICT(day, match_id) DO UPDATE SET
          home=excluded.home,
          away=excluded.away,
          finalized_at=excluded.finalized_at
        WHERE results.is_manual = 0 OR results.is_manual IS NULL
      `);

  const now = Date.now();
  const batch = finished.map((r) => {
    const h = r.normalized ? r.normalized.home90 : Number(r.score?.home ?? r.homeScore ?? 0);
    const a = r.normalized ? r.normalized.away90 : Number(r.score?.away ?? r.awayScore ?? 0);

    // Safeguard
    if (!Number.isFinite(h) || !Number.isFinite(a)) return null;
    return schema.resultsSeasonId
      ? stmt.bind(day, r.match_id, h, a, now, seasonId)
      : stmt.bind(day, r.match_id, h, a, now);
  }).filter(Boolean);

  if (batch.length) await env.DB.batch(batch as any[]);
}

function isFinishedMatchStatus(status: unknown): boolean {
  const s = String(status || "").toUpperCase();
  return ["FINISHED", "FT", "FULL_TIME"].includes(s);
}

async function getFeaturedMatchesForDay(env: Env, day: string): Promise<any[]> {
  try {
    const featured = await env.DB.prepare(`
      SELECT fm.day, fm.match_id, fm.pos, m.status, m.start_time
      FROM featured_matches fm
      JOIN matches m ON m.day = fm.day AND m.match_id = fm.match_id
      WHERE fm.day = ?
      ORDER BY fm.pos ASC
      LIMIT 3
    `).bind(day).all();
    const rows = (featured.results || []) as any[];
    if (rows.length > 0) return rows;
  } catch {
    // Fallback below for installations without featured_matches table.
  }

  const legacy = await env.DB.prepare(`
    SELECT day, match_id, status, start_time
    FROM matches
    WHERE day = ? AND is_pick = 1
    ORDER BY start_time ASC
    LIMIT 3
  `).bind(day).all();

  return (legacy.results || []) as any[];
}

const ACTION_CONDITION_TYPES = new Set([
  "picks_total",
  "day_full_before_lock",
  "joker_use_total",
  "early_pick_event",
  "streak_days",
  "full_week_activity",
  "lock_discipline_streak",
  "league_join",
  "league_pick",
  "league_joker_use",
  "league_ontime_total",
  "league_streak"
]);

function isResultConditionType(conditionType: string): boolean {
  return !ACTION_CONDITION_TYPES.has(conditionType);
}

function periodContextDay(periodKey: string, fallbackDay: string): string {
  if (periodKey.startsWith("day:")) return periodKey.slice(4);
  if (periodKey.startsWith("week:")) return fallbackDay;
  if (periodKey.startsWith("month:")) return `${periodKey.slice(6)}-01`;
  return fallbackDay;
}

async function reconcileRevokedResultAchievements(env: Env, userId: number, day: string): Promise<number> {
  const achievementDefs = await listAchievementDefinitionsWithCatalogOverrides(env);
  const defMap = buildAchievementDefinitionMap(achievementDefs);
  const rowsRes = await env.DB.prepare(`
    SELECT
      ua.achievement_id,
      ua.scope_target_id,
      ua.period_key,
      ua.progress,
      a.condition_type,
      a.threshold
    FROM user_achievements ua
    JOIN achievements a ON a.id = ua.achievement_id
    WHERE ua.user_id = ? AND ua.state = 'confirmed'
  `).bind(userId).all();

  const rows = (rowsRes.results || []) as any[];
  let revoked = 0;

  for (const row of rows) {
    const conditionType = String(row.condition_type || "");
    const def = defMap.get(String(row.achievement_id || ''));
    const threshold = Number(def?.threshold ?? row.threshold ?? 1);
    if (!isResultConditionType(conditionType)) continue;

    const periodKey = String(row.period_key || "all");
    const scopeTargetId = String(row.scope_target_id || "");
    const refDay = periodContextDay(periodKey, day);

    const sCfgR = await getSeasonConfig(env);
    const progress = await calculateAchievementProgress(
      userId,
      conditionType,
      threshold,
      scopeTargetId,
      env,
      refDay,
      sCfgR.start
    );

    if (progress < threshold) {
      await env.DB.prepare(`
        UPDATE user_achievements
        SET
          state = 'revoked',
          unlocked_at = NULL,
          shown_at = COALESCE(shown_at, ?),
          progress = ?
        WHERE user_id = ? AND achievement_id = ? AND scope_target_id = ? AND period_key = ?
      `).bind(Date.now(), progress, userId, row.achievement_id, scopeTargetId, periodKey).run();
      revoked++;
    } else if (progress !== Number(row.progress || 0)) {
      await env.DB.prepare(`
        UPDATE user_achievements
        SET progress = ?
        WHERE user_id = ? AND achievement_id = ? AND scope_target_id = ? AND period_key = ?
      `).bind(progress, userId, row.achievement_id, scopeTargetId, periodKey).run();
    }
  }

  return revoked;
}

// Canonical fingerprint of a day's results: "match_id:home-away" pairs sorted by
// match_id, joined by '|'. Changes iff any result is added/removed/edited (incl.
// manual corrections), which is exactly when the day needs re-finalizing.
function computeDayResultsFingerprint(resultsMap: Record<string, { home: number; away: number }>): string {
  return Object.keys(resultsMap)
    .sort()
    .map((k) => `${k}:${resultsMap[k].home}-${resultsMap[k].away}`)
    .join('|');
}

// Read the stored fingerprint of an already-finalized day, or null if the day
// has no marker. Returns null on any error (e.g. the day_finalized table not yet
// migrated) so finalization degrades gracefully to the previous always-run behavior.
async function getDayFinalizedFingerprint(env: Env, day: string): Promise<string | null> {
  try {
    const row = await env.DB.prepare(`SELECT fingerprint FROM day_finalized WHERE day = ?`).bind(day).first() as any;
    return row ? String(row.fingerprint ?? '') : null;
  } catch {
    return null;
  }
}

// Record that a day has been finalized with the given results fingerprint.
// Best-effort: a failure here only means the next tick re-runs finalization.
async function markDayFinalized(env: Env, day: string, fingerprint: string): Promise<void> {
  try {
    await env.DB.prepare(`
      INSERT INTO day_finalized (day, fingerprint, finalized_at)
      VALUES (?, ?, ?)
      ON CONFLICT(day) DO UPDATE SET fingerprint = excluded.fingerprint, finalized_at = excluded.finalized_at
    `).bind(day, fingerprint, Date.now()).run();
  } catch (e) {
    console.error(`[finalizeDay] markDayFinalized failed day=${day}:`, e);
  }
}

// Bulk replacement for per-user `SELECT league_id FROM league_members WHERE
// user_id = ?` inside finalization loops: one chunked IN query returns the same
// data for all users at once. Users without leagues are simply absent from the map.
async function fetchLeagueIdsByUser(env: Env, userIds: number[]): Promise<Map<number, string[]>> {
  const map = new Map<number, string[]>();
  const chunkSize = 50;
  for (let i = 0; i < userIds.length; i += chunkSize) {
    const chunk = userIds.slice(i, i + chunkSize);
    const placeholders = chunk.map(() => '?').join(',');
    const res = await env.DB.prepare(
      `SELECT user_id, league_id FROM league_members WHERE user_id IN (${placeholders})`
    ).bind(...chunk).all();
    for (const r of (res.results || []) as any[]) {
      const uid = Number(r.user_id);
      const list = map.get(uid);
      if (list) list.push(String(r.league_id));
      else map.set(uid, [String(r.league_id)]);
    }
  }
  return map;
}

// Refund paid boosts stuck on POSTPONED/CANCELLED matches. The rules promise that
// such matches score no points for anyone, so a match-bound double_chance would
// otherwise burn silently after the lock. Only runs for days strictly BEFORE today
// (UTC): provider statuses can flap during the matchday itself (POSTPONED → LIVE
// for a delayed kickoff), but a match still POSTPONED after its day ended will not
// un-postpone. Idempotent: the boost_usage row is deleted in the same batch that
// returns the boost, so a re-run finds nothing. Only match-bound usages qualify
// (bu.match_id IS NOT NULL) — day-scoped extra_joker is out of scope by design.
export async function refundBoostsForPostponedMatches(env: Env, day: string): Promise<number> {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(day) || day >= todayKeyUTC()) return 0;
  const rowsRes = await env.DB.prepare(
    `SELECT bu.user_id, bu.boost_id, bu.boost_type, bu.match_id
     FROM boost_usage bu
     JOIN matches m ON m.day = bu.day AND m.match_id = bu.match_id
     WHERE bu.day = ? AND bu.match_id IS NOT NULL
       AND UPPER(COALESCE(m.status, '')) IN ('POSTPONED', 'CANCELLED')`
  ).bind(day).all();
  const rows = (rowsRes.results || []) as any[];
  let refunded = 0;
  for (const r of rows) {
    const userId = Number(r.user_id);
    const boostId = Number(r.boost_id);
    if (!Number.isFinite(userId) || !Number.isFinite(boostId)) continue;
    const stmts = [
      env.DB.prepare(
        `UPDATE user_boosts SET status = 'available', used_at = NULL, used_on_day = NULL, used_on_match_id = NULL
         WHERE id = ? AND user_id = ? AND status = 'used'`
      ).bind(boostId, userId),
      env.DB.prepare(`DELETE FROM boost_usage WHERE user_id = ? AND day = ?`).bind(userId, day),
    ];
    if (String(r.boost_type) === "double_chance") {
      stmts.unshift(
        env.DB.prepare(`UPDATE picks SET double_chance = NULL WHERE day = ? AND match_id = ? AND user_id = ?`)
          .bind(day, String(r.match_id), userId)
      );
    }
    await env.DB.batch(stmts);
    refunded += 1;
    if (env.TELEGRAM_BOT_TOKEN) {
      const label = String(r.boost_type) === "double_chance" ? "Двойной шанс" : "Дополнительный джокер";
      await telegramBotApi(env, "sendMessage", {
        chat_id: userId,
        text: `↩️ Матч, на который ты применил буст «${label}», перенесён или отменён. Буст возвращён в инвентарь — используй его в другой день.`,
      }).catch(() => {});
    }
  }
  if (refunded > 0) {
    console.log(`[BOOST_REFUND] day=${day} refunded=${refunded} postponed/cancelled boost usages`);
  }
  return refunded;
}

async function finalizeDay(env: Env, day: string, opts?: { force?: boolean; skipRecalc?: boolean }) {
  const __t0 = Date.now(); const __runId = makeRunId(); let __status = "ok";
  try {
  const force = !!opts?.force;
  const skipRecalc = !!opts?.skipRecalc;

  // Runs BEFORE the readiness guards: a POSTPONED featured match is exactly the
  // case where finishedCount never reaches featuredCount, so the early returns
  // below would otherwise keep the refund from ever happening.
  try {
    await refundBoostsForPostponedMatches(env, day);
  } catch (e: any) {
    console.error(`[BOOST_REFUND] sweep failed for ${day}:`, e?.message || e);
  }

  const featured = await getFeaturedMatchesForDay(env, day);
  const featuredCount = featured.length;
  const finishedCount = featured.filter((m) => isFinishedMatchStatus(m.status)).length;

  if (!force) {
    if (featuredCount === 0) {
      return {
        ok: true,
        day,
        ready: false,
        reason: "NO_FEATURED_MATCHES",
        featuredCount,
        finishedCount,
        confirmed: 0,
        revoked: 0,
        users: 0
      };
    }
    if (finishedCount !== featuredCount) {
      return {
        ok: true,
        day,
        ready: false,
        reason: "NOT_ALL_FEATURED_FINISHED",
        featuredCount,
        finishedCount,
        confirmed: 0,
        revoked: 0,
        users: 0
      };
    }
  }

  const dayResultsRes = await env.DB.prepare(`
    SELECT match_id, home, away
    FROM results
    WHERE day = ?
  `).bind(day).all();
  const dayResults = (dayResultsRes.results || []) as any[];

  const resultsMap: Record<string, { home: number; away: number }> = {};
  for (const r of dayResults) {
    resultsMap[String(r.match_id)] = { home: Number(r.home), away: Number(r.away) };
  }
  if (Object.keys(resultsMap).length === 0) {
    return {
      ok: true,
      day,
      ready: false,
      reason: "NO_RESULTS_FOR_DAY",
      featuredCount,
      finishedCount,
      confirmed: 0,
      revoked: 0,
      users: 0
    };
  }

  // Skip redundant re-finalization: if this day was already finalized and its
  // results are unchanged, none of the heavy per-user recompute below can produce
  // a different outcome, so return early. A manual correction changes the
  // fingerprint (and force bypasses this), so corrections still re-finalize.
  const resultsFingerprint = computeDayResultsFingerprint(resultsMap);
  if (!force) {
    const prevFingerprint = await getDayFinalizedFingerprint(env, day);
    if (prevFingerprint !== null && prevFingerprint === resultsFingerprint) {
      return {
        ok: true,
        day,
        ready: true,
        reason: "ALREADY_FINALIZED_UNCHANGED",
        featuredCount,
        finishedCount,
        confirmed: 0,
        revoked: 0,
        users: 0,
        skipped: true,
      };
    }
  }

  if (!skipRecalc) {
    // Idempotent score recomputation.
    await recalcDayScores(env, day, resultsMap);
  }

  const usersRes = await env.DB.prepare(`
    SELECT DISTINCT user_id
    FROM picks
    WHERE day = ?
  `).bind(day).all();
  const userIds = (usersRes.results || []).map((r: any) => Number(r.user_id)).filter((x: number) => Number.isFinite(x));

  let confirmed = 0;
  let revoked = 0;
  const daySeasonNumber = await getSeasonIdForDayOrDisplay(env, day);
  const weeklyScopes = await getWeeklyScopesForDay(env, day);

  // gameDays is global, fetch once and share; per-user work is independent.
  const gameDays = await getGameDays(env);
  await mapWithConcurrency(userIds, 10, async (uid) => {
    await updateUserStats(env, uid, gameDays);
    await updateUserDayStats(env, uid, day);
  });

  // Leagues aggregate the per-user day stats above, so run them after the user loop.
  const impactedLeagueIds = await listActiveLeagueIdsForDay(env, day);
  await mapWithConcurrency(impactedLeagueIds, 8, (leagueId) => updateLeagueDayStats(env, leagueId, day));

  // tasks_catalog is static within one finalization run — one read instead of a
  // per-achievement lookup inside the user loop.
  const ballRewardByTaskKey = new Map<string, number>();
  {
    const catalogRes = await env.DB.prepare(`SELECT task_key, reward_balls FROM tasks_catalog WHERE reward_balls > 0`).all();
    for (const r of (catalogRes.results || []) as any[]) ballRewardByTaskKey.set(String(r.task_key), Number(r.reward_balls));
  }

  const leagueIdsByUser = await fetchLeagueIdsByUser(env, userIds);
  for (const uid of userIds) {
    const leagueIds = leagueIdsByUser.get(uid) || [];

    const unlockedNow = await checkAchievements(env, uid, {
      phase: 'scores_updated',
      day,
      leagueIds
    });
    confirmed += unlockedNow.length;

    // Award stars for confirmed seasonal achievements via ledger
    try {
      for (const ach of unlockedNow) {
        if (ach.stars_reward && ach.stars_reward > 0) {
          await markTaskCompleted(env, uid, daySeasonNumber, ach.id || ach.achievement_id, 'season');
          await awardStarsViaLedger(env, uid, daySeasonNumber, ach.id || ach.achievement_id, 'season', ach.stars_reward, 'seasonal_task');
          await markTaskRewardGranted(env, uid, daySeasonNumber, ach.id || ach.achievement_id, 'season');
        }
        // Award balls
        const achKey = ach.id || ach.achievement_id;
        const rewardBalls = ballRewardByTaskKey.get(String(achKey)) ?? 0;
        if (rewardBalls > 0) {
          await awardBalls(env, uid, rewardBalls, daySeasonNumber, achKey, 'season', 'task_reward');
        }
      }
    } catch (starErr: any) {
      console.error(`[SCORES] star award error userId=${uid}:`, starErr?.message || starErr);
    }

    // Check daily quests (scores_updated phase). league_members was already read
    // above for checkAchievements — reuse it instead of an identical second query.
    try {
      await checkDailyQuests(env, uid, day, 'scores_updated', leagueIds);
      // Stage 4: quest shadow after scoring (default off → no-op).
      await maybeRunQuestShadow(env, "match_scored", uid, day, leagueIds).catch(() => {});
      // Stage 13: seasonal shadow after scoring (default off → no-op).
      await maybeRunSeasonalShadow(env, "prediction_scored", uid).catch(() => {});
      // Stage 14: seasonal event-driven apply for allowlisted users (default off → no-op).
      await maybeRunSeasonalApply(env, uid).catch(() => {});
    } catch (dqErr: any) {
      console.error(`[SCORES] daily quests error userId=${uid}:`, dqErr?.message || dqErr);
    }

    try {
      for (const weeklyScope of weeklyScopes) {
        await checkWeeklyQuests(env, uid, weeklyScope, 'scores_updated');
      }
    } catch (wqErr: any) {
      console.error(`[SCORES] weekly quests error userId=${uid}:`, wqErr?.message || wqErr);
    }

    revoked += await reconcileRevokedResultAchievements(env, uid, day);
  }

  let seasonFinalization: any = null;
  try {
    seasonFinalization = await maybeFinalizeSeasonForDay(env, day);
  } catch (seasonErr: any) {
    console.error(`[SEASON] finalize check failed day=${day}:`, seasonErr?.message || seasonErr);
  }

  let weeklyFinalization: any = null;
  try {
    weeklyFinalization = await maybeFinalizeWeeklyForDay(env, day);
  } catch (weeklyErr: any) {
    console.error(`[WEEKLY] finalize check failed day=${day}:`, weeklyErr?.message || weeklyErr);
  }

  // Record the finalized fingerprint so subsequent (non-force) ticks with the
  // same results skip the heavy recompute above.
  await markDayFinalized(env, day, resultsFingerprint);

  return {
    ok: true,
    day,
    ready: true,
    reason: null,
    featuredCount,
    finishedCount,
    confirmed,
    revoked,
    users: userIds.length,
    seasonFinalization,
    weeklyFinalization
  };
  } catch (__e) { __status = "error"; throw __e; } finally { logEvent({ operation: "finalizeDay", trigger: opts?.force ? "force" : "internal", run_id: __runId, status: __status, duration_ms: Date.now() - __t0 }); }
}

async function finalizeMatch(env: Env, matchId: string) {
  const match = await env.DB.prepare(`
    SELECT day, match_id, status
    FROM matches
    WHERE match_id = ?
    ORDER BY updated_at DESC
    LIMIT 1
  `).bind(matchId).first() as any;

  if (!match) {
    throw new Error("MATCH_NOT_FOUND");
  }

  if (!isFinishedMatchStatus(match.status)) {
    return {
      ok: true,
      day: String(match.day),
      ready: false,
      reason: "MATCH_NOT_FINISHED"
    };
  }

  const day = String(match.day);
  const dayResultsRes = await env.DB.prepare(`
    SELECT match_id, home, away
    FROM results
    WHERE day = ?
  `).bind(day).all();
  const dayResults = (dayResultsRes.results || []) as any[];
  const resultsMap: Record<string, { home: number; away: number }> = {};
  for (const r of dayResults) {
    resultsMap[String(r.match_id)] = { home: Number(r.home), away: Number(r.away) };
  }
  if (Object.keys(resultsMap).length > 0) {
    await recalcDayScores(env, day, resultsMap);
  }

  const finalize = await finalizeDay(env, day, { force: false, skipRecalc: true });
  return { ...finalize, match_id: matchId };
}

async function triggerBotSummaryResend(env: Env, day: string, replaceExisting: boolean = false): Promise<{ sent: number; edited: number; deleted: number; skipped: number; noMatches?: boolean }> {
  const botRes = await postToBotInternal(env, "/internal/resend-summary", { day, replaceExisting });

  if (!botRes.ok) {
    const err = await botRes.text().catch(() => `HTTP ${botRes.status}`);
    throw new Error(`Bot resend failed for ${day}: ${err}`);
  }

  const data = await botRes.json().catch(() => ({})) as any;
  return {
    sent: data.sent ?? 0,
    edited: data.edited ?? 0,
    deleted: data.deleted ?? 0,
    skipped: data.skipped ?? 0,
    noMatches: data.noMatches,
  };
}

async function revokeBallsForTask(
  env: Env,
  userId: number,
  seasonId: number,
  taskKey: string,
  instanceKey: string,
  balls: number
): Promise<void> {
  if (balls <= 0) return;
  const delRes = await env.DB.prepare(`
    DELETE FROM balls_ledger
    WHERE user_id = ? AND season_id = ? AND task_key = ? AND instance_key = ?
  `).bind(userId, seasonId, taskKey, instanceKey).run();

  if ((delRes.meta.changes ?? 0) > 0) {
    await env.DB.prepare(`
      UPDATE users
      SET balls = MAX(0, balls - ?)
      WHERE id = ?
    `).bind(balls, userId).run();
  }
}

async function postToBotInternal(env: Env, path: string, payload: unknown): Promise<Response> {
  const internalSecret = getInternalApiSecret(env);
  if (!env.BOT) {
    throw new Error("BOT service binding is not configured");
  }
  return env.BOT.fetch(new Request(`https://bot.internal${path}`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "x-internal-secret": internalSecret,
      "x-scoregame-internal-source": API_INTERNAL_SOURCE,
    },
    body: JSON.stringify(payload),
  }));
}

