// Run an async mapper over items with bounded concurrency. Used to parallelize
// independent per-user / per-league stat recomputations without firing every
// query at once. Order of side effects across items is not guaranteed; only use
// for work that is independent per item.
async function mapWithConcurrency<T>(items: T[], limit: number, fn: (item: T) => Promise<void>): Promise<void> {
  if (items.length === 0) return;
  const size = Math.max(1, limit);
  for (let i = 0; i < items.length; i += size) {
    await Promise.all(items.slice(i, i + size).map(fn));
  }
}

async function runBatchedStatements(env: Env, statements: D1PreparedStatement[], chunkSize: number = 50): Promise<void> {
  if (statements.length === 0) return;
  for (let i = 0; i < statements.length; i += chunkSize) {
    const chunk = statements.slice(i, i + chunkSize);
    try {
      await env.DB.batch(chunk);
    } catch (e) {
      console.error(`D1 batch failed [${i}-${i + chunk.length}]:`, e);
      // Fallback: run individually if batch fails (rare)
      for (const s of chunk) {
        try {
          await s.run();
        } catch (sErr) {
          console.error("D1 statement fallback failed:", sErr);
        }
      }
    }
  }
}

async function buildSeasonCompletionReport(env: Env, seasonId: number): Promise<SeasonCompletionReport> {
  await assertSeasonLifecycleSchemaReady(env);
  const season = await getSeasonById(env, seasonId);
  if (!season) throw new Error("SEASON_NOT_FOUND");

  const counts = await env.DB.prepare(`
    SELECT
      COUNT(*) AS total_matches,
      SUM(CASE WHEN status IN ('FINISHED', 'AWARDED', 'FULL_TIME', 'FT') THEN 1 ELSE 0 END) AS finished_matches,
      SUM(CASE WHEN status NOT IN ('FINISHED', 'AWARDED', 'FULL_TIME', 'FT') THEN 1 ELSE 0 END) AS unfinished_matches,
      SUM(CASE WHEN is_pick = 1 THEN 1 ELSE 0 END) AS total_pick_matches
    FROM matches
    WHERE season_id = ?
  `).bind(seasonId).first() as any;

  const missingResultsRow = await env.DB.prepare(`
    SELECT COUNT(*) AS c
    FROM matches m
    WHERE m.season_id = ?
      AND m.is_pick = 1
      AND m.status IN ('FINISHED', 'AWARDED', 'FULL_TIME', 'FT')
      AND NOT EXISTS (
        SELECT 1
        FROM results r
        WHERE r.day = m.day AND r.match_id = m.match_id
      )
  `).bind(seasonId).first() as any;

  const totalMatches = Number(counts?.total_matches || 0);
  const finishedMatches = Number(counts?.finished_matches || 0);
  const unfinishedMatches = Number(counts?.unfinished_matches || 0);
  const totalPickMatches = Number(counts?.total_pick_matches || 0);
  const missingResults = Number(missingResultsRow?.c || 0);

  let reason: string | null = null;
  if (totalMatches === 0) reason = "NO_MATCHES";
  else if (unfinishedMatches > 0) reason = "UNFINISHED_MATCHES";
  else if (missingResults > 0) reason = "MISSING_RESULTS";
  else if (season.status === 'active' && Date.now() < new Date(season.ends_at).getTime()) reason = "SEASON_RANGE_NOT_ENDED";

  return {
    season,
    totalMatches,
    finishedMatches,
    unfinishedMatches,
    totalPickMatches,
    missingResults,
    ready: reason === null,
    reason,
  };
}

type SeasonStandingRow = {
  userId: number;
  finalRank: number;
  finalPoints: number;
  exactHits: number;
  diffHits: number;
  outcomeHits: number;
  misses: number;
  jokerHits: number;
  doubleChanceSaves: number;
  matchesPredicted: number;
};

function makeEmptySeasonStandingRow(userId: number, finalPoints: number = 0): SeasonStandingRow {
  return {
    userId,
    finalRank: 0,
    finalPoints,
    exactHits: 0,
    diffHits: 0,
    outcomeHits: 0,
    misses: 0,
    jokerHits: 0,
    doubleChanceSaves: 0,
    matchesPredicted: 0,
  };
}

function buildSeasonStandingRowsFromPickResults(rawRows: any[]): SeasonStandingRow[] {
  const standings = new Map<number, SeasonStandingRow>();
  const ensure = (userId: number) => {
    if (!standings.has(userId)) {
      standings.set(userId, makeEmptySeasonStandingRow(userId, 0));
    }
    return standings.get(userId)!;
  };

  for (const row of rawRows) {
    const userId = Number(row.user_id);
    const item = ensure(userId);
    item.matchesPredicted += 1;

    if (row.result_home === null || row.result_away === null) continue;

    const baseCalc = calculateMatchPoints(
      row.pick_home,
      row.pick_away,
      row.result_home,
      row.result_away,
      row.joker,
      row.double_chance
    );
    const calc = applyMatchBonusPoints(baseCalc, row.advances_answer, getMatchBonusQuestionFromJoinedRow(row));

    item.finalPoints += calc.total;

    if (calc.reason === 'exact') item.exactHits += 1;
    else if (calc.reason === 'diff') item.diffHits += 1;
    else if (calc.reason === 'outcome') item.outcomeHits += 1;
    else if (calc.reason === 'double_chance') item.doubleChanceSaves += 1;
    else item.misses += 1;

    if (Number(row.joker) === 1 && calc.total > 0) {
      item.jokerHits += 1;
    }
  }

  const ranked = [...standings.values()].sort((a, b) =>
    b.finalPoints - a.finalPoints ||
    b.exactHits - a.exactHits ||
    b.diffHits - a.diffHits ||
    b.outcomeHits - a.outcomeHits ||
    a.userId - b.userId
  );

  ranked.forEach((row, index) => {
    row.finalRank = index + 1;
  });

  return ranked;
}

async function collectSeasonStandingRows(env: Env, seasonId: number): Promise<SeasonStandingRow[]> {
  const rowsRes = await env.DB.prepare(`
    SELECT
      p.user_id,
      p.home AS pick_home,
      p.away AS pick_away,
      p.joker,
      p.double_chance,
      pba.answer AS advances_answer,
      r.home AS result_home,
      r.away AS result_away,
      COALESCE(mbq.is_enabled, 0) AS bonus_enabled,
      COALESCE(mbq.points_award, 1) AS bonus_points_award,
      mbq.correct_answer AS bonus_correct_answer,
      mbq.resolved_at AS bonus_resolved_at
    FROM picks p
    JOIN matches m ON m.day = p.day AND m.match_id = p.match_id
    LEFT JOIN results r ON r.day = p.day AND r.match_id = p.match_id
    LEFT JOIN pick_bonus_answers pba
      ON pba.day = p.day
     AND pba.match_id = p.match_id
     AND pba.user_id = p.user_id
     AND pba.question_type = '${ADVANCES_TEAM_QUESTION}'
    LEFT JOIN match_bonus_questions mbq
      ON mbq.day = p.day
     AND mbq.match_id = p.match_id
     AND mbq.question_type = '${ADVANCES_TEAM_QUESTION}'
    WHERE COALESCE(p.season_id, m.season_id) = ?
    ORDER BY p.user_id, p.day, p.match_id
  `).bind(seasonId).all();

  return buildSeasonStandingRowsFromPickResults((rowsRes.results || []) as any[]);
}

